-- SQL Developer: ejecutar como script (F5), en conexion dedicada a esquema VACIO.
-- Privilegios/preparacion y limitaciones: LEEME_INSTALACION.md.
-- DDL tiene commits implicitos. Ante un fallo, conservar el destino y usar OTRO
-- esquema vacio; este script no elimina ni limpia objetos.
-- Secuencias e identity inician en 1; 02 consume los generadores mediante INSERT.
SET DEFINE OFF
SET SQLBLANKLINES ON
SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM USER_OBJECTS;
  IF v_count <> 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Instalacion cancelada: el esquema contiene objetos. Conectese a un esquema nuevo y vacio; no se creo ningun objeto.');
  END IF;
END;
