-- TABLE CLIENTE
CREATE TABLE "CLIENTE" 
   (	"ID_CLIENTE" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"NIT" VARCHAR2(20) NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(200) NOT NULL ENABLE, 
	"ID_CONDICION" NUMBER NOT NULL ENABLE, 
	"ESTADO" CHAR(1) DEFAULT 'A', 
	 CONSTRAINT "CK_CXC_CLIENTES_ESTADO" CHECK (ESTADO IN ('A','I')) ENABLE, 
	 CONSTRAINT "PK_CXC_CLIENTES" PRIMARY KEY ("ID_CLIENTE")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CXC_CLIENTES_NIT" UNIQUE ("NIT")
  USING INDEX  ENABLE
   );

-- TABLE CMP_ARTICULO
CREATE TABLE "CMP_ARTICULO" 
   (	"ART_CODIGO_ARTICULO" VARCHAR2(20) NOT NULL ENABLE, 
	"ART_DESCRIPCION" VARCHAR2(200) NOT NULL ENABLE, 
	"ART_ID_CATEGORIA" NUMBER NOT NULL ENABLE, 
	"ART_ID_MARCA" NUMBER NOT NULL ENABLE, 
	"ART_ID_UNIDAD_COMPRA" NUMBER NOT NULL ENABLE, 
	"ART_ID_UNIDAD_VENTA" NUMBER NOT NULL ENABLE, 
	"ART_ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"ART_MANEJA_LOTE" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE, 
	 CONSTRAINT "CK_CMP_ART_ACTIVO" CHECK (ART_ACTIVO IN (0, 1)) ENABLE, 
	 CONSTRAINT "CK_CMP_ART_LOTE" CHECK (ART_MANEJA_LOTE IN (0, 1)) ENABLE
   );

