  USING INDEX  ENABLE
   );

-- TABLE CXP_APLICACION
CREATE TABLE "CXP_APLICACION" 
   (	"ID_APLICACION" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_DOCUMENTO_DESTINO" NUMBER NOT NULL ENABLE, 
	"ID_PAGO" NUMBER, 
	"ID_DOCUMENTO_ORIGEN" NUMBER, 
	"ID_DOCUMENTO_CXC" NUMBER, 
	"TIPO_APLICACION" VARCHAR2(25) NOT NULL ENABLE, 
	"FECHA_APLICACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"MONTO_PRINCIPAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_DESCUENTO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_RETENCION" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"DIFERENCIA_CAMBIARIA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_TOTAL_APLICADO" NUMBER(18,2) NOT NULL ENABLE, 
	"SALDO_ANTERIOR" NUMBER(18,2), 
	"SALDO_POSTERIOR" NUMBER(18,2), 
	"ESTADO_CXC" VARCHAR2(25) DEFAULT 'NO_APLICA' NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"APLICADO_POR" NUMBER NOT NULL ENABLE, 
	"REVERTIDO_POR" NUMBER, 
	"FECHA_REVERSO" TIMESTAMP (6), 
	"MOTIVO_REVERSO" VARCHAR2(1000), 
	 CONSTRAINT "CK_CXP_APL_TIPO" CHECK (TIPO_APLICACION IN ('PAGO', 'ANTICIPO', 'NOTA_CREDITO',
                             'COMPENSACION_CXC', 'AJUSTE')) ENABLE, 
	 CONSTRAINT "CK_CXP_APL_FUENTE" CHECK (
        (TIPO_APLICACION IN ('PAGO', 'ANTICIPO')
         AND ID_PAGO IS NOT NULL AND ID_DOCUMENTO_ORIGEN IS NULL
         AND ID_DOCUMENTO_CXC IS NULL)
        OR
        (TIPO_APLICACION IN ('NOTA_CREDITO', 'AJUSTE')
         AND ID_PAGO IS NULL AND ID_DOCUMENTO_ORIGEN IS NOT NULL
         AND ID_DOCUMENTO_CXC IS NULL)
        OR
        (TIPO_APLICACION = 'COMPENSACION_CXC'
         AND ID_PAGO IS NULL AND ID_DOCUMENTO_ORIGEN IS NULL
         AND ID_DOCUMENTO_CXC IS NOT NULL)
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_APL_MONTOS" CHECK (
        MONTO_PRINCIPAL >= 0 AND MONTO_DESCUENTO >= 0
        AND MONTO_RETENCION >= 0 AND MONTO_TOTAL_APLICADO > 0
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_APL_CXC" CHECK (ESTADO_CXC IN ('NO_APLICA', 'PENDIENTE', 'CONFIRMADA', 'RECHAZADA')) ENABLE, 
	 CONSTRAINT "CK_CXP_APL_ESTADO" CHECK (ESTADO IN ('PENDIENTE', 'APLICADA', 'REVERTIDA', 'CANCELADA')) ENABLE, 
	 CONSTRAINT "CK_CXP_APL_REVERSO" CHECK (
        (ESTADO = 'REVERTIDA' AND REVERTIDO_POR IS NOT NULL
         AND FECHA_REVERSO IS NOT NULL AND MOTIVO_REVERSO IS NOT NULL)
        OR ESTADO <> 'REVERTIDA'
    ) ENABLE, 
	 CONSTRAINT "PK_CXP_APLICACION" PRIMARY KEY ("ID_APLICACION")
  USING INDEX  ENABLE
   );

-- TABLE CXP_APROBACION
CREATE TABLE "CXP_APROBACION" 
   (	"ID_APROBACION" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_REGLA" NUMBER, 
	"ID_DOCUMENTO" NUMBER, 
	"ID_PAGO" NUMBER, 
	"ID_LOTE" NUMBER, 
	"ID_CUENTA_BANCARIA" NUMBER, 
	"ID_COMPROMISO" NUMBER, 
	"ID_PERIODO" NUMBER, 
	"NIVEL" NUMBER(4,0) NOT NULL ENABLE, 
	"ID_ROL_APROBADOR" NUMBER NOT NULL ENABLE, 
	"ID_USUARIO_APROBADOR" NUMBER, 
	"DELEGADO_POR" NUMBER, 
	"ESTADO" VARCHAR2(20) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"ACCION" VARCHAR2(30), 
	"FECHA_SOLICITUD" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FECHA_DECISION" TIMESTAMP (6), 
	"OBSERVACION" VARCHAR2(1000), 
	 CONSTRAINT "CK_CXP_APR_ENTIDAD" CHECK (
        (CASE WHEN ID_DOCUMENTO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_PAGO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_LOTE IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_CUENTA_BANCARIA IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_COMPROMISO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_PERIODO IS NULL THEN 0 ELSE 1 END) = 1
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_APR_ESTADO" CHECK (ESTADO IN ('PENDIENTE', 'APROBADA', 'RECHAZADA',
                    'DELEGADA', 'CANCELADA')) ENABLE, 
	 CONSTRAINT "CK_CXP_APR_DECISION" CHECK (
        (ESTADO IN ('APROBADA', 'RECHAZADA')
         AND ID_USUARIO_APROBADOR IS NOT NULL AND FECHA_DECISION IS NOT NULL)
        OR ESTADO NOT IN ('APROBADA', 'RECHAZADA')
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_APR_NIVEL" CHECK (NIVEL > 0) ENABLE, 
	 CONSTRAINT "PK_CXP_APROBACION" PRIMARY KEY ("ID_APROBACION")
  USING INDEX  ENABLE
   );

-- TABLE CXP_ARCHIVO
CREATE TABLE "CXP_ARCHIVO" 
   (	"ID_ARCHIVO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_PROVEEDOR" NUMBER, 
	"ID_CUENTA_BANCARIA" NUMBER, 
	"ID_COMPROMISO" NUMBER, 
	"ID_DOCUMENTO" NUMBER, 
	"ID_LOTE" NUMBER, 
	"ID_PAGO" NUMBER, 
	"ID_APLICACION" NUMBER, 
	"ID_CONCILIACION_PROV" NUMBER, 
	"ID_EVENTO" NUMBER, 
	"CATEGORIA" VARCHAR2(40) NOT NULL ENABLE, 
	"NOMBRE_ARCHIVO" VARCHAR2(255) NOT NULL ENABLE, 
	"TIPO_MIME" VARCHAR2(120) NOT NULL ENABLE, 
	"TAMANO_BYTES" NUMBER(18,0) NOT NULL ENABLE, 
	"URI_ALMACENAMIENTO" VARCHAR2(1000) NOT NULL ENABLE, 
	"HASH_SHA256" VARCHAR2(64) NOT NULL ENABLE, 
	"VERSION_ARCHIVO" NUMBER(6,0) DEFAULT 1 NOT NULL ENABLE, 
	"ES_VERSION_ACTUAL" CHAR(1) DEFAULT 'S' NOT NULL ENABLE, 
	"CARGADO_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_CARGA" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_CXP_ARCH_ENTIDAD" CHECK (
        (CASE WHEN ID_PROVEEDOR IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_CUENTA_BANCARIA IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_COMPROMISO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_DOCUMENTO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_LOTE IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_PAGO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_APLICACION IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_CONCILIACION_PROV IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_EVENTO IS NULL THEN 0 ELSE 1 END) = 1
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_ARCH_TAMANO" CHECK (TAMANO_BYTES > 0 AND VERSION_ARCHIVO > 0) ENABLE, 
	 CONSTRAINT "CK_CXP_ARCH_ACTUAL" CHECK (ES_VERSION_ACTUAL IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_CXP_ARCH_HASH" CHECK (LENGTH(HASH_SHA256) = 64) ENABLE, 
	 CONSTRAINT "PK_CXP_ARCHIVO" PRIMARY KEY ("ID_ARCHIVO")
  USING INDEX  ENABLE
   );

-- TABLE CXP_COMPROMISO
CREATE TABLE "CXP_COMPROMISO" 
   (	"ID_COMPROMISO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_PROVEEDOR" NUMBER NOT NULL ENABLE, 
	"ID_SUCURSAL" NUMBER NOT NULL ENABLE, 
	"ID_DEPARTAMENTO" NUMBER, 
	"TIPO_COMPROMISO" VARCHAR2(25) NOT NULL ENABLE, 
	"NUMERO_REFERENCIA" VARCHAR2(80) NOT NULL ENABLE, 
	"DESCRIPCION" VARCHAR2(500) NOT NULL ENABLE, 
	"FECHA_INICIO" DATE NOT NULL ENABLE, 
	"FECHA_FIN" DATE, 
	"FRECUENCIA" VARCHAR2(20), 
	"NUMERO_CUOTAS" NUMBER(6,0), 
	"DIA_VENCIMIENTO" NUMBER(2,0), 
	"MONEDA" VARCHAR2(3) DEFAULT 'GTQ' NOT NULL ENABLE, 
	"MONTO_TOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"SALDO_CAPITAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"TASA_INTERES" NUMBER(9,6) DEFAULT 0 NOT NULL ENABLE, 
	"VALOR_CUOTA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"GARANTIA_DESCRIPCION" VARCHAR2(500), 
	"CUENTA_CONTABLE" VARCHAR2(50), 
	"CENTRO_COSTO" VARCHAR2(50), 
	"PROYECTO" VARCHAR2(100), 
	"RESPONSABLE_POR" NUMBER NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(25) DEFAULT 'ACTIVO' NOT NULL ENABLE, 
	"CREADO_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" TIMESTAMP (6), 
	 CONSTRAINT "CK_CXP_COMP_TIPO" CHECK (TIPO_COMPROMISO IN ('RECURRENTE', 'CONTRATO', 'PRESTAMO',
                             'ARRENDAMIENTO', 'FONDO_CAJA_CHICA',
                             'OBLIGACION_FISCAL', 'OTRO')) ENABLE, 
	 CONSTRAINT "CK_CXP_COMP_FECHAS" CHECK (FECHA_FIN IS NULL OR FECHA_FIN >= FECHA_INICIO) ENABLE, 
	 CONSTRAINT "CK_CXP_COMP_FREC" CHECK (FRECUENCIA IS NULL OR FRECUENCIA IN
            ('SEMANAL', 'QUINCENAL', 'MENSUAL', 'BIMESTRAL', 'TRIMESTRAL',
             'SEMESTRAL', 'ANUAL', 'VARIABLE')) ENABLE, 
	 CONSTRAINT "CK_CXP_COMP_DIA" CHECK (DIA_VENCIMIENTO IS NULL OR DIA_VENCIMIENTO BETWEEN 1 AND 31) ENABLE, 
	 CONSTRAINT "CK_CXP_COMP_MONTOS" CHECK (MONTO_TOTAL >= 0 AND SALDO_CAPITAL >= 0
         AND SALDO_CAPITAL <= MONTO_TOTAL AND TASA_INTERES >= 0
         AND VALOR_CUOTA >= 0 AND (NUMERO_CUOTAS IS NULL OR NUMERO_CUOTAS > 0)) ENABLE, 
	 CONSTRAINT "CK_CXP_COMP_ESTADO" CHECK (ESTADO IN ('BORRADOR', 'PENDIENTE_APROBACION', 'ACTIVO',
                    'SUSPENDIDO', 'FINALIZADO', 'ANULADO')) ENABLE, 
	 CONSTRAINT "PK_CXP_COMPROMISO" PRIMARY KEY ("ID_COMPROMISO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_COMP_REF" UNIQUE ("TIPO_COMPROMISO", "NUMERO_REFERENCIA")
  USING INDEX  ENABLE
   );

-- TABLE CXP_CONCILIACION_PAGO
CREATE TABLE "CXP_CONCILIACION_PAGO" 
   (	"ID_CONCILIACION_PAGO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_PAGO" NUMBER NOT NULL ENABLE, 
	"ID_CUENTA_BANCARIA" NUMBER NOT NULL ENABLE, 
	"REFERENCIA_MOVIMIENTO" VARCHAR2(150) NOT NULL ENABLE, 
	"FECHA_MOVIMIENTO" DATE NOT NULL ENABLE, 
	"MONTO_BANCO" NUMBER(18,2) NOT NULL ENABLE, 
	"MONTO_SISTEMA" NUMBER(18,2) NOT NULL ENABLE, 
	"DIFERENCIA_MONTO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"TIPO_COINCIDENCIA" VARCHAR2(25) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(30) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"CONCILIADO_POR" NUMBER, 
	"FECHA_CONCILIACION" TIMESTAMP (6), 
	"OBSERVACIONES" VARCHAR2(1000), 
	 CONSTRAINT "CK_CXP_CPAGO_MONTOS" CHECK (MONTO_BANCO >= 0 AND MONTO_SISTEMA >= 0) ENABLE, 
	 CONSTRAINT "CK_CXP_CPAGO_TIPO" CHECK (TIPO_COINCIDENCIA IN ('AUTOMATICA', 'MANUAL', 'TOLERANCIA', 'SIN_COINCIDENCIA')) ENABLE, 
	 CONSTRAINT "CK_CXP_CPAGO_ESTADO" CHECK (ESTADO IN ('PENDIENTE', 'CONCILIADO_AUTOMATICO',
                    'CONCILIADO_MANUAL', 'EN_REVISION', 'RECHAZADO')) ENABLE, 
	 CONSTRAINT "CK_CXP_CPAGO_CIERRE" CHECK (
        (ESTADO IN ('CONCILIADO_AUTOMATICO', 'CONCILIADO_MANUAL')
         AND CONCILIADO_POR IS NOT NULL AND FECHA_CONCILIACION IS NOT NULL)
        OR ESTADO NOT IN ('CONCILIADO_AUTOMATICO', 'CONCILIADO_MANUAL')
    ) ENABLE, 
	 CONSTRAINT "PK_CXP_CONC_PAGO" PRIMARY KEY ("ID_CONCILIACION_PAGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_CONC_MOV" UNIQUE ("ID_CUENTA_BANCARIA", "REFERENCIA_MOVIMIENTO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_CONC_PAGO" UNIQUE ("ID_PAGO")
  USING INDEX  ENABLE
   );

-- TABLE CXP_CONCILIACION_PROV_DET
CREATE TABLE "CXP_CONCILIACION_PROV_DET" 
   (	"ID_DET_CONCILIACION" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_CONCILIACION_PROV" NUMBER NOT NULL ENABLE, 
	"ID_DOCUMENTO" NUMBER, 
	"ID_PAGO" NUMBER, 
	"TIPO_REGISTRO" VARCHAR2(20) NOT NULL ENABLE, 
	"REFERENCIA_PROVEEDOR" VARCHAR2(120), 
	"FECHA_EMPRESA" DATE, 
	"FECHA_PROVEEDOR" DATE, 
	"MONTO_EMPRESA" NUMBER(18,2), 
	"MONTO_PROVEEDOR" NUMBER(18,2), 
	"DIFERENCIA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"RESULTADO" VARCHAR2(30) NOT NULL ENABLE, 
	"OBSERVACIONES" VARCHAR2(1000), 
	 CONSTRAINT "CK_CXP_CPD_TIPO" CHECK (TIPO_REGISTRO IN ('DOCUMENTO', 'PAGO', 'AJUSTE_EXTERNO')) ENABLE, 
	 CONSTRAINT "CK_CXP_CPD_ORIGEN" CHECK (
        (TIPO_REGISTRO = 'DOCUMENTO' AND ID_DOCUMENTO IS NOT NULL
         AND ID_PAGO IS NULL)
        OR (TIPO_REGISTRO = 'PAGO' AND ID_PAGO IS NOT NULL
            AND ID_DOCUMENTO IS NULL)
        OR (TIPO_REGISTRO = 'AJUSTE_EXTERNO' AND ID_DOCUMENTO IS NULL
            AND ID_PAGO IS NULL)
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_CPD_RESULT" CHECK (RESULTADO IN ('COINCIDE', 'DIFERENCIA_FECHA', 'DIFERENCIA_MONTO',
                       'NO_REGISTRADO_EMPRESA', 'NO_REGISTRADO_PROVEEDOR',
                       'EN_REVISION')) ENABLE, 
	 CONSTRAINT "PK_CXP_CONC_PROV_DET" PRIMARY KEY ("ID_DET_CONCILIACION")
  USING INDEX  ENABLE
   );

-- TABLE CXP_CONCILIACION_PROVEEDOR
CREATE TABLE "CXP_CONCILIACION_PROVEEDOR" 
   (	"ID_CONCILIACION_PROV" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_PROVEEDOR" NUMBER NOT NULL ENABLE, 
	"PERIODO_DESDE" DATE NOT NULL ENABLE, 
	"PERIODO_HASTA" DATE NOT NULL ENABLE, 
	"SALDO_EMPRESA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"SALDO_PROVEEDOR" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"DIFERENCIA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'BORRADOR' NOT NULL ENABLE, 
	"ELABORADA_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_ELABORACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"CERRADA_POR" NUMBER, 
	"FECHA_CIERRE" TIMESTAMP (6), 
	"OBSERVACIONES" VARCHAR2(1000), 
	 CONSTRAINT "CK_CXP_CPROV_FECHAS" CHECK (PERIODO_HASTA >= PERIODO_DESDE) ENABLE, 
	 CONSTRAINT "CK_CXP_CPROV_ESTADO" CHECK (ESTADO IN ('BORRADOR', 'EN_REVISION', 'CONCILIADA', 'CERRADA')) ENABLE, 
	 CONSTRAINT "CK_CXP_CPROV_CIERRE" CHECK (
        (ESTADO = 'CERRADA' AND CERRADA_POR IS NOT NULL
         AND FECHA_CIERRE IS NOT NULL)
        OR ESTADO <> 'CERRADA'
    ) ENABLE, 
	 CONSTRAINT "PK_CXP_CONC_PROV" PRIMARY KEY ("ID_CONCILIACION_PROV")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_CONC_PROV" UNIQUE ("ID_PROVEEDOR", "PERIODO_DESDE", "PERIODO_HASTA")
  USING INDEX  ENABLE
   );

-- TABLE CXP_CUENTA_BANCARIA
CREATE TABLE "CXP_CUENTA_BANCARIA" 
   (	"ID_CUENTA_BANCARIA" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"TIPO_TITULAR" VARCHAR2(12) NOT NULL ENABLE, 
	"ID_EMPRESA" NUMBER, 
	"ID_PROVEEDOR" NUMBER, 
	"BANCO_NOMBRE" VARCHAR2(120) NOT NULL ENABLE, 
	"CODIGO_BANCO" VARCHAR2(30), 
	"TITULAR" VARCHAR2(200) NOT NULL ENABLE, 
	"NUMERO_CUENTA" VARCHAR2(80) NOT NULL ENABLE, 
	"TIPO_CUENTA" VARCHAR2(20) NOT NULL ENABLE, 
	"MONEDA" VARCHAR2(3) DEFAULT 'GTQ' NOT NULL ENABLE, 
	"PAIS" VARCHAR2(80) DEFAULT 'GUATEMALA' NOT NULL ENABLE, 
	"CODIGO_SWIFT" VARCHAR2(20), 
	"CODIGO_IBAN" VARCHAR2(50), 
	"ES_PRINCIPAL" CHAR(1) DEFAULT 'N' NOT NULL ENABLE, 
	"TITULAR_COINCIDE" CHAR(1) DEFAULT 'N' NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'ACTIVA' NOT NULL ENABLE, 
	"ESTADO_APROBACION" VARCHAR2(25) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"MOTIVO_BLOQUEO" VARCHAR2(500), 
	"FECHA_VERIFICACION" TIMESTAMP (6), 
	"VERIFICADO_POR" NUMBER, 
	"CREADO_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" TIMESTAMP (6), 
	 CONSTRAINT "CK_CXP_CTA_DUENO" CHECK (
        (TIPO_TITULAR = 'EMPRESA' AND ID_EMPRESA IS NOT NULL
         AND ID_PROVEEDOR IS NULL)
        OR
        (TIPO_TITULAR = 'PROVEEDOR' AND ID_PROVEEDOR IS NOT NULL
         AND ID_EMPRESA IS NULL)
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_CTA_TIPO" CHECK (TIPO_CUENTA IN ('MONETARIA', 'AHORRO', 'TARJETA', 'OTRA')) ENABLE, 
	 CONSTRAINT "CK_CXP_CTA_MONEDA" CHECK (LENGTH(MONEDA) = 3) ENABLE, 
	 CONSTRAINT "CK_CXP_CTA_SINO" CHECK (ES_PRINCIPAL IN ('S', 'N') AND TITULAR_COINCIDE IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_CXP_CTA_ESTADO" CHECK (ESTADO IN ('ACTIVA', 'INACTIVA', 'BLOQUEADA')) ENABLE, 
	 CONSTRAINT "CK_CXP_CTA_APROB" CHECK (ESTADO_APROBACION IN ('PENDIENTE', 'APROBADA', 'RECHAZADA',
                               'REQUIERE_REVALIDACION')) ENABLE, 
	 CONSTRAINT "CK_CXP_CTA_VERIFICADA" CHECK (
        (ESTADO_APROBACION = 'APROBADA' AND FECHA_VERIFICACION IS NOT NULL
         AND VERIFICADO_POR IS NOT NULL AND TITULAR_COINCIDE = 'S')
        OR ESTADO_APROBACION <> 'APROBADA'
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_CTA_BLOQUEO" CHECK (ESTADO <> 'BLOQUEADA' OR MOTIVO_BLOQUEO IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_CXP_CUENTA_BANC" PRIMARY KEY ("ID_CUENTA_BANCARIA")
  USING INDEX  ENABLE
   );

-- TABLE CXP_CUENTA_USUARIO
CREATE TABLE "CXP_CUENTA_USUARIO" 
   (	"SEG_ID_USUARIO" NUMBER NOT NULL ENABLE, 
	"USU_ID_USUARIO" NUMBER NOT NULL ENABLE, 
	 CONSTRAINT "PK_CXP_CUENTA_USUARIO" PRIMARY KEY ("SEG_ID_USUARIO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CXP_CUENTA_USUARIO_OPERATIVO" UNIQUE ("USU_ID_USUARIO")
  USING INDEX  ENABLE
   );

-- TABLE CXP_DOCUMENTO
CREATE TABLE "CXP_DOCUMENTO" 
   (	"ID_DOCUMENTO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_PROVEEDOR" NUMBER, 
	"ID_SUCURSAL" NUMBER NOT NULL ENABLE, 
	"ID_CONDICION_CREDITO" NUMBER, 
	"ID_COMPROMISO" NUMBER, 
	"ID_DOCUMENTO_RELACIONADO" NUMBER, 
	"NO_FACTURA_COMPRA" VARCHAR2(50), 
	"NO_ORDEN_COMPRA" VARCHAR2(20), 
	"NO_RECEPCION" VARCHAR2(20), 
	"TIPO_DOCUMENTO" VARCHAR2(30) NOT NULL ENABLE, 
	"NATURALEZA" CHAR(1) DEFAULT 'D' NOT NULL ENABLE, 
	"ORIGEN_INGRESO" VARCHAR2(25) DEFAULT 'MANUAL' NOT NULL ENABLE, 
	"TIPO_REGISTRO" VARCHAR2(20) DEFAULT 'SIN_OC' NOT NULL ENABLE, 
	"SERIE" VARCHAR2(40), 
	"NUMERO_DOCUMENTO" VARCHAR2(80), 
	"UUID_FISCAL" VARCHAR2(100), 
	"NIT_EMISOR" VARCHAR2(20), 
	"REFERENCIA_EXTERNA" VARCHAR2(120), 
	"HASH_ORIGEN" VARCHAR2(128), 
	"FECHA_DOCUMENTO" DATE, 
	"FECHA_RECEPCION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FECHA_CONTABILIZACION" DATE, 
	"FECHA_VENCIMIENTO" DATE, 
	"DIAS_CREDITO" NUMBER(4,0) DEFAULT 0 NOT NULL ENABLE, 
	"MONEDA" VARCHAR2(3) DEFAULT 'GTQ' NOT NULL ENABLE, 
	"TIPO_CAMBIO" NUMBER(18,8) DEFAULT 1 NOT NULL ENABLE, 
	"FUENTE_TIPO_CAMBIO" VARCHAR2(100), 
	"FECHA_TIPO_CAMBIO" DATE, 
	"SUBTOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"DESCUENTO_TOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"IMPUESTO_TOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"RETENCION_TOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"RECARGO_TOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"GASTO_ADICIONAL_TOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"DIFERENCIA_REDONDEO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"TOTAL_BRUTO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"TOTAL_NETO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"TOTAL_LOCAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_APLICADO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"SALDO_PENDIENTE" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"ID_DEPARTAMENTO" NUMBER, 
	"CENTRO_COSTO" VARCHAR2(50), 
	"PROYECTO" VARCHAR2(100), 
	"CUENTA_CONTABLE" VARCHAR2(50), 
	"SOLICITADO_POR" NUMBER, 
	"RESPONSABLE_POR" NUMBER, 
	"JUSTIFICACION_SIN_OC" VARCHAR2(1000), 
	"NUMERO_CUOTA" NUMBER(6,0), 
	"CAPITAL_CUOTA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"INTERES_CUOTA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"COMISION_CUOTA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"RESULTADO_TRES_VIAS" VARCHAR2(30) DEFAULT 'NO_APLICA' NOT NULL ENABLE, 
	"DIFERENCIA_CANTIDAD" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE, 
	"DIFERENCIA_PRECIO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"DIFERENCIA_IMPUESTO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"DIFERENCIA_TOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"PRIORIDAD" VARCHAR2(10) DEFAULT 'NORMAL' NOT NULL ENABLE, 
	"ESTADO_CONTABLE" VARCHAR2(20) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"NUMERO_ASIENTO_EXT" VARCHAR2(80), 
	"ESTADO" VARCHAR2(30) DEFAULT 'RECIBIDO' NOT NULL ENABLE, 
	"POSIBLE_DUPLICADO" CHAR(1) DEFAULT 'N' NOT NULL ENABLE, 
	"MOTIVO_RECHAZO" VARCHAR2(1000), 
	"MOTIVO_BLOQUEO" VARCHAR2(1000), 
	"MOTIVO_ANULACION" VARCHAR2(1000), 
	"ANULADO_POR" NUMBER, 
	"FECHA_ANULACION" TIMESTAMP (6), 
	"OBSERVACIONES" VARCHAR2(1500), 
	"CREADO_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" TIMESTAMP (6), 
	 CONSTRAINT "CK_CXP_DOC_NAT" CHECK (NATURALEZA IN ('D', 'C')) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_ORIGEN" CHECK (ORIGEN_INGRESO IN ('MANUAL', 'ARCHIVO', 'CORREO', 'IMPORTACION',
                            'COMPRAS', 'CARGA_MASIVA', 'INTEGRACION',
                            'PORTAL_PROVEEDOR', 'FACTURACION_ELECTRONICA')) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_REGISTRO" CHECK (TIPO_REGISTRO IN ('CON_OC', 'SIN_OC', 'RECURRENTE',
                           'SALDO_INICIAL', 'IMPORTADO')) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_OC_REQ" CHECK (TIPO_REGISTRO <> 'CON_OC' OR NO_ORDEN_COMPRA IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_COMPRA_REQ" CHECK (ORIGEN_INGRESO <> 'COMPRAS' OR NO_FACTURA_COMPRA IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_MONEDA" CHECK (LENGTH(MONEDA) = 3 AND TIPO_CAMBIO > 0) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_MONTOS" CHECK (
        SUBTOTAL >= 0 AND DESCUENTO_TOTAL >= 0 AND IMPUESTO_TOTAL >= 0
        AND RETENCION_TOTAL >= 0 AND RECARGO_TOTAL >= 0
        AND GASTO_ADICIONAL_TOTAL >= 0 AND TOTAL_BRUTO >= 0
        AND TOTAL_NETO >= 0 AND TOTAL_LOCAL >= 0 AND MONTO_APLICADO >= 0
        AND SALDO_PENDIENTE >= 0 AND MONTO_APLICADO <= TOTAL_NETO
        AND CAPITAL_CUOTA >= 0 AND INTERES_CUOTA >= 0 AND COMISION_CUOTA >= 0
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_CALCULO" CHECK (
        TOTAL_BRUTO = ROUND(
            SUBTOTAL - DESCUENTO_TOTAL + IMPUESTO_TOTAL + RECARGO_TOTAL
            + GASTO_ADICIONAL_TOTAL + DIFERENCIA_REDONDEO,
            2
        )
        AND TOTAL_NETO = ROUND(TOTAL_BRUTO - RETENCION_TOTAL, 2)
        AND SALDO_PENDIENTE = ROUND(TOTAL_NETO - MONTO_APLICADO, 2)
        AND ABS(TOTAL_LOCAL - ROUND(TOTAL_NETO * TIPO_CAMBIO, 2)) <= 0.01
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_TRES_VIAS" CHECK (RESULTADO_TRES_VIAS IN ('NO_APLICA', 'COINCIDE', 'DENTRO_TOLERANCIA',
                                 'DIFERENCIA', 'DIF_PRECIO', 'DIF_CANTIDAD',
                                 'NO_RECIBIDO', 'SUPERA_ORDEN', 'SIN_RECEPCION',
                                 'ORDEN_CERRADA', 'ORDEN_ANULADA',
                                 'EN_INVESTIGACION', 'DIFERENCIA_APROBADA',
                                 'BLOQUEADO')) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_PRIORIDAD" CHECK (PRIORIDAD IN ('CRITICA', 'ALTA', 'NORMAL', 'BAJA')) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_CONTABLE" CHECK (ESTADO_CONTABLE IN ('PENDIENTE', 'ENVIADO', 'CONTABILIZADO',
                             'ERROR', 'REVERTIDO', 'NO_APLICA')) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_DUP" CHECK (POSIBLE_DUPLICADO IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_ESTADO" CHECK (ESTADO IN ('RECIBIDO', 'PENDIENTE_CLASIFICACION', 'BORRADOR',
                    'PENDIENTE_REVISION', 'EN_VALIDACION', 'DUPLICADO',
                    'CON_DIFERENCIAS', 'PENDIENTE_APROBACION', 'APROBADA',
                    'RECHAZADA', 'CONTABILIZADA', 'PENDIENTE_PAGO',
                    'PROGRAMADA_PAGO', 'PARCIALMENTE_PAGADA', 'PAGADA',
                    'VENCIDA', 'BLOQUEADA', 'EN_DISPUTA',
                    'PARCIALMENTE_APLICADA', 'APLICADA', 'ANULADA', 'CERRADA')) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_RECHAZO" CHECK (ESTADO <> 'RECHAZADA' OR MOTIVO_RECHAZO IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_BLOQUEO" CHECK (ESTADO <> 'BLOQUEADA' OR MOTIVO_BLOQUEO IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_ANULACION" CHECK (
        (ESTADO = 'ANULADA' AND MOTIVO_ANULACION IS NOT NULL
         AND ANULADO_POR IS NOT NULL AND FECHA_ANULACION IS NOT NULL)
        OR ESTADO <> 'ANULADA'
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_REL_DIST" CHECK (ID_DOCUMENTO_RELACIONADO IS NULL
         OR ID_DOCUMENTO_RELACIONADO <> ID_DOCUMENTO) ENABLE, 
	 CONSTRAINT "CK_CXP_DOC_TIPO" CHECK (TIPO_DOCUMENTO IN ('FACTURA', 'FACTURA_CAMBIARIA', 'NOTA_CREDITO',
                                'NOTA_DEBITO', 'RECIBO', 'REEMBOLSO',
                                'LIQUIDACION_VIATICO', 'GASTO_CAJA_CHICA',
                                'CUOTA_CONTRATO', 'CUOTA_PRESTAMO',
                                'OBLIGACION_FISCAL', 'SALDO_INICIAL',
                                'COMPROBANTE_SERVICIO', 'OTRO',
                                'FACTURA_ESPECIAL')) ENABLE, 
	 CONSTRAINT "PK_CXP_DOCUMENTO" PRIMARY KEY ("ID_DOCUMENTO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_DOC_UUID" UNIQUE ("UUID_FISCAL")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_DOC_HASH" UNIQUE ("HASH_ORIGEN")
  USING INDEX  ENABLE
   );

-- TABLE CXP_DOCUMENTO_DETALLE
CREATE TABLE "CXP_DOCUMENTO_DETALLE" 
   (	"ID_DETALLE" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_DOCUMENTO" NUMBER NOT NULL ENABLE, 
	"CODIGO_ARTICULO" VARCHAR2(20), 
	"ID_DETALLE_OC" NUMBER, 
	"ID_DETALLE_RECEPCION" NUMBER, 
	"NUMERO_LINEA" NUMBER(6,0) NOT NULL ENABLE, 
	"DESCRIPCION" VARCHAR2(500) NOT NULL ENABLE, 
	"CANTIDAD" NUMBER(18,4) NOT NULL ENABLE, 
	"UNIDAD_MEDIDA" VARCHAR2(30) DEFAULT 'UNIDAD' NOT NULL ENABLE, 
	"PRECIO_UNITARIO" NUMBER(18,6) NOT NULL ENABLE, 
	"DESCUENTO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"SUBTOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"IMPUESTO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"RETENCION" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"TOTAL_LINEA" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"CUENTA_CONTABLE" VARCHAR2(50), 
	"CENTRO_COSTO" VARCHAR2(50), 
	"ID_DEPARTAMENTO" NUMBER, 
	"PROYECTO" VARCHAR2(100), 
	"CANTIDAD_ORDENADA" NUMBER(18,4), 
	"CANTIDAD_RECIBIDA" NUMBER(18,4), 
	"CANTIDAD_FACTURADA" NUMBER(18,4), 
	"PRECIO_ORDENADO" NUMBER(18,6), 
	"PRECIO_FACTURADO" NUMBER(18,6), 
	"DIFERENCIA_CANTIDAD" NUMBER(18,4) DEFAULT 0 NOT NULL ENABLE, 
	"DIFERENCIA_PRECIO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"RESULTADO_TRES_VIAS" VARCHAR2(25) DEFAULT 'NO_APLICA' NOT NULL ENABLE, 
	 CONSTRAINT "CK_CXP_DDET_MONTOS" CHECK (
        CANTIDAD > 0 AND PRECIO_UNITARIO >= 0 AND DESCUENTO >= 0
        AND SUBTOTAL >= 0 AND IMPUESTO >= 0 AND RETENCION >= 0
        AND TOTAL_LINEA >= 0
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_DDET_TRES" CHECK (RESULTADO_TRES_VIAS IN ('NO_APLICA', 'COINCIDE',
                                 'DENTRO_TOLERANCIA', 'DIFERENCIA', 'BLOQUEADO')) ENABLE, 
	 CONSTRAINT "PK_CXP_DOC_DET" PRIMARY KEY ("ID_DETALLE")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_DOC_DET_LINEA" UNIQUE ("ID_DOCUMENTO", "NUMERO_LINEA")
  USING INDEX  ENABLE
   );

-- TABLE CXP_DOCUMENTO_TRIBUTO
CREATE TABLE "CXP_DOCUMENTO_TRIBUTO" 
   (	"ID_TRIBUTO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_DOCUMENTO" NUMBER NOT NULL ENABLE, 
	"ID_DETALLE" NUMBER, 
	"TIPO_TRIBUTO" VARCHAR2(15) NOT NULL ENABLE, 
	"CODIGO_TRIBUTO" VARCHAR2(30) NOT NULL ENABLE, 
	"NOMBRE_TRIBUTO" VARCHAR2(120) NOT NULL ENABLE, 
	"BASE_IMPONIBLE" NUMBER(18,2) NOT NULL ENABLE, 
	"PORCENTAJE" NUMBER(9,6) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO" NUMBER(18,2) NOT NULL ENABLE, 
	"MONTO_RECUPERABLE" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_NO_RECUPERABLE" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"INCLUIDO_PRECIO" CHAR(1) DEFAULT 'N' NOT NULL ENABLE, 
	"NUMERO_CONSTANCIA" VARCHAR2(80), 
	"PERIODO_FISCAL" VARCHAR2(20), 
	"FECHA_APLICACION" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'CALCULADO' NOT NULL ENABLE, 
	"GENERADO_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_GENERACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"ID_REGLA_TRIBUTARIA" NUMBER, 
	 CONSTRAINT "CK_CXP_TRIB_TIPO" CHECK (TIPO_TRIBUTO IN ('IMPUESTO', 'RETENCION', 'PERCEPCION')) ENABLE, 
	 CONSTRAINT "CK_CXP_TRIB_MONTOS" CHECK (BASE_IMPONIBLE >= 0 AND PORCENTAJE >= 0 AND MONTO >= 0
         AND MONTO_RECUPERABLE >= 0 AND MONTO_NO_RECUPERABLE >= 0) ENABLE, 
	 CONSTRAINT "CK_CXP_TRIB_PRECIO" CHECK (INCLUIDO_PRECIO IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_CXP_TRIB_ESTADO" CHECK (ESTADO IN ('CALCULADO', 'APLICADO', 'ANULADO')) ENABLE, 
	 CONSTRAINT "PK_CXP_DOC_TRIB" PRIMARY KEY ("ID_TRIBUTO")
  USING INDEX  ENABLE
   );

-- TABLE CXP_EVENTO
CREATE TABLE "CXP_EVENTO" 
   (	"ID_EVENTO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EVENTO_PADRE" NUMBER, 
	"ID_PROVEEDOR" NUMBER, 
	"ID_CUENTA_BANCARIA" NUMBER, 
	"ID_COMPROMISO" NUMBER, 
	"ID_DOCUMENTO" NUMBER, 
	"ID_LOTE" NUMBER, 
	"ID_PAGO" NUMBER, 
	"ID_APLICACION" NUMBER, 
	"ID_CONCILIACION_PROV" NUMBER, 
	"ID_PERIODO" NUMBER, 
	"TIPO_EVENTO" VARCHAR2(30) NOT NULL ENABLE, 
	"ASUNTO" VARCHAR2(250) NOT NULL ENABLE, 
	"DETALLE" VARCHAR2(2000), 
	"ESTADO_ANTERIOR" VARCHAR2(50), 
	"ESTADO_NUEVO" VARCHAR2(50), 
	"MONTO_RELACIONADO" NUMBER(18,2), 
	"CANAL" VARCHAR2(20), 
	"MENCIONES_JSON" CLOB, 
	"RESULTADO_JSON" CLOB, 
	"PRIORIDAD" VARCHAR2(10) DEFAULT 'NORMAL' NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'ABIERTO' NOT NULL ENABLE, 
	"USUARIO_ASIGNADO" NUMBER, 
	"FECHA_LIMITE" TIMESTAMP (6), 
	"USUARIO_EVENTO" NUMBER NOT NULL ENABLE, 
	"FECHA_EVENTO" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FECHA_CIERRE" TIMESTAMP (6), 
	 CONSTRAINT "CK_CXP_EVT_ENTIDAD" CHECK (
        (CASE WHEN ID_PROVEEDOR IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_CUENTA_BANCARIA IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_COMPROMISO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_DOCUMENTO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_LOTE IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_PAGO IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_APLICACION IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_CONCILIACION_PROV IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN ID_PERIODO IS NULL THEN 0 ELSE 1 END) = 1
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_EVT_PRIORIDAD" CHECK (PRIORIDAD IN ('CRITICA', 'ALTA', 'NORMAL', 'BAJA')) ENABLE, 
	 CONSTRAINT "CK_CXP_EVT_ESTADO" CHECK (ESTADO IN ('ABIERTO', 'EN_PROCESO', 'CERRADO', 'CANCELADO')) ENABLE, 
	 CONSTRAINT "CK_CXP_EVT_CIERRE" CHECK (ESTADO <> 'CERRADO' OR FECHA_CIERRE IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_CXP_EVENTO" PRIMARY KEY ("ID_EVENTO")
  USING INDEX  ENABLE
   );

-- TABLE CXP_FACTURA_ESPECIAL
CREATE TABLE "CXP_FACTURA_ESPECIAL" 
   (	"ID_FACTURA_ESPECIAL" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_DOCUMENTO" NUMBER NOT NULL ENABLE, 
	"PROVEEDOR_NOMBRE" VARCHAR2(200) NOT NULL ENABLE, 
	"PROVEEDOR_NIT" VARCHAR2(20), 
	"PROVEEDOR_CUI" VARCHAR2(20), 
	"PROVEEDOR_DIRECCION" VARCHAR2(300), 
	"DESCRIPCION_OPERACION" VARCHAR2(1000) NOT NULL ENABLE, 
	"REVISADO_POR" NUMBER, 
	"FECHA_REVISION" TIMESTAMP (6), 
	"OBSERVACION_REVISION" VARCHAR2(1000), 
	"ESTADO_EMISION" VARCHAR2(20) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"NUMERO_CONSTANCIA" VARCHAR2(40), 
	"FECHA_EMISION" TIMESTAMP (6), 
	"EMITIDO_POR" NUMBER, 
	"HASH_CONSTANCIA" VARCHAR2(64), 
	"CREADO_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_CXP_FESP_ID_FISCAL" CHECK (PROVEEDOR_NIT IS NOT NULL OR PROVEEDOR_CUI IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_FESP_ESTADO" CHECK (ESTADO_EMISION IN ('PENDIENTE', 'EMITIDA', 'ANULADA')) ENABLE, 
	 CONSTRAINT "CK_CXP_FESP_EMISION" CHECK (
                (ESTADO_EMISION = 'PENDIENTE' AND NUMERO_CONSTANCIA IS NULL AND FECHA_EMISION IS NULL)
                OR (ESTADO_EMISION = 'EMITIDA' AND NUMERO_CONSTANCIA IS NOT NULL AND FECHA_EMISION IS NOT NULL
                    AND EMITIDO_POR IS NOT NULL AND HASH_CONSTANCIA IS NOT NULL)
                OR ESTADO_EMISION = 'ANULADA'
            ) ENABLE, 
	 CONSTRAINT "CK_CXP_FESP_HASH" CHECK (HASH_CONSTANCIA IS NULL OR LENGTH(HASH_CONSTANCIA) = 64) ENABLE, 
	 CONSTRAINT "PK_CXP_FACTURA_ESP" PRIMARY KEY ("ID_FACTURA_ESPECIAL")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_FESP_DOC" UNIQUE ("ID_DOCUMENTO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_FESP_CONST" UNIQUE ("NUMERO_CONSTANCIA")
  USING INDEX  ENABLE
   );

-- TABLE CXP_LOTE_PAGO
CREATE TABLE "CXP_LOTE_PAGO" 
   (	"ID_LOTE" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_SUCURSAL" NUMBER NOT NULL ENABLE, 
	"ID_CUENTA_ORIGEN" NUMBER NOT NULL ENABLE, 
	"CODIGO_LOTE" VARCHAR2(40) NOT NULL ENABLE, 
	"TIPO_LOTE" VARCHAR2(30) DEFAULT 'PROVEEDORES' NOT NULL ENABLE, 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FECHA_EJECUCION" DATE NOT NULL ENABLE, 
	"MONEDA" VARCHAR2(3) DEFAULT 'GTQ' NOT NULL ENABLE, 
	"CANTIDAD_PAGOS" NUMBER(8,0) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_TOTAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(30) DEFAULT 'BORRADOR' NOT NULL ENABLE, 
	"CREADO_POR" NUMBER NOT NULL ENABLE, 
	"ENVIADO_POR" NUMBER, 
	"FECHA_ENVIO" TIMESTAMP (6), 
	"MOTIVO_RECHAZO" VARCHAR2(1000), 
	"MOTIVO_ANULACION" VARCHAR2(1000), 
	"OBSERVACIONES" VARCHAR2(1000), 
	 CONSTRAINT "CK_CXP_LOTE_TIPO" CHECK (TIPO_LOTE IN ('PROVEEDORES', 'IMPUESTOS', 'NOMINA',
                       'CAJA_CHICA', 'REEMBOLSOS', 'OTRO')) ENABLE, 
	 CONSTRAINT "CK_CXP_LOTE_MONEDA" CHECK (LENGTH(MONEDA) = 3) ENABLE, 
	 CONSTRAINT "CK_CXP_LOTE_MONTOS" CHECK (CANTIDAD_PAGOS >= 0 AND MONTO_TOTAL >= 0) ENABLE, 
	 CONSTRAINT "CK_CXP_LOTE_ESTADO" CHECK (ESTADO IN ('BORRADOR', 'PENDIENTE_APROBACION', 'APROBADO',
                    'ENVIADO', 'EN_PROCESO', 'EJECUTADO',
                    'PARCIAL', 'RECHAZADO', 'ANULADO')) ENABLE, 
	 CONSTRAINT "CK_CXP_LOTE_ENVIO" CHECK (
        (ESTADO IN ('ENVIADO', 'EN_PROCESO', 'EJECUTADO', 'PARCIAL')
         AND ENVIADO_POR IS NOT NULL AND FECHA_ENVIO IS NOT NULL)
        OR ESTADO NOT IN ('ENVIADO', 'EN_PROCESO', 'EJECUTADO', 'PARCIAL')
    ) ENABLE, 
	 CONSTRAINT "PK_CXP_LOTE_PAGO" PRIMARY KEY ("ID_LOTE")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_LOTE_COD" UNIQUE ("CODIGO_LOTE")
  USING INDEX  ENABLE
   );

-- TABLE CXP_PAGO
CREATE TABLE "CXP_PAGO" 
   (	"ID_PAGO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_LOTE" NUMBER, 
	"ID_PROVEEDOR" NUMBER NOT NULL ENABLE, 
	"ID_SUCURSAL" NUMBER NOT NULL ENABLE, 
	"ID_FORMA_PAGO" NUMBER NOT NULL ENABLE, 
	"ID_CUENTA_ORIGEN" NUMBER NOT NULL ENABLE, 
	"ID_CUENTA_DESTINO" NUMBER NOT NULL ENABLE, 
	"ID_PAGO_ORIGEN" NUMBER, 
	"CODIGO_PAGO" VARCHAR2(50) NOT NULL ENABLE, 
	"TIPO_PAGO" VARCHAR2(25) DEFAULT 'ORDINARIO' NOT NULL ENABLE, 
	"FECHA_PROGRAMADA" DATE NOT NULL ENABLE, 
	"FECHA_PAGO" TIMESTAMP (6), 
	"FECHA_EFECTIVA" DATE, 
	"MONEDA" VARCHAR2(3) DEFAULT 'GTQ' NOT NULL ENABLE, 
	"TIPO_CAMBIO" NUMBER(18,8) DEFAULT 1 NOT NULL ENABLE, 
	"FUENTE_TIPO_CAMBIO" VARCHAR2(100), 
	"FECHA_TIPO_CAMBIO" DATE, 
	"MONTO_OBLIGACION" NUMBER(18,2) NOT NULL ENABLE, 
	"MONTO_DESCUENTO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_RETENCION" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_COMISION" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_TRANSFERIDO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_APLICADO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_NO_APLICADO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"NUMERO_CHEQUE" VARCHAR2(80), 
	"NUMERO_TRANSFERENCIA" VARCHAR2(120), 
	"REFERENCIA_BANCARIA" VARCHAR2(120), 
	"CONCEPTO" VARCHAR2(500) NOT NULL ENABLE, 
	"RESPUESTA_BANCO" VARCHAR2(1000), 
	"ESTADO_CONTABLE" VARCHAR2(20) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"NUMERO_ASIENTO_EXT" VARCHAR2(80), 
	"CLAVE_IDEMPOTENCIA" VARCHAR2(100) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(30) DEFAULT 'BORRADOR' NOT NULL ENABLE, 
	"PROGRAMADO_POR" NUMBER NOT NULL ENABLE, 
	"EJECUTADO_POR" NUMBER, 
	"CONCILIADO_POR" NUMBER, 
	"MOTIVO_RECHAZO" VARCHAR2(1000), 
	"MOTIVO_DEVOLUCION" VARCHAR2(1000), 
	"MOTIVO_ANULACION" VARCHAR2(1000), 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FECHA_MODIFICACION" TIMESTAMP (6), 
	 CONSTRAINT "CK_CXP_PAGO_CUENTAS" CHECK (ID_CUENTA_ORIGEN <> ID_CUENTA_DESTINO) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_TIPO" CHECK (TIPO_PAGO IN ('ORDINARIO', 'ANTICIPO', 'REEMBOLSO',
                       'REPOSICION_CAJA', 'DEVOLUCION', 'REVERSO',
                       'COMPENSACION')) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_MONEDA" CHECK (LENGTH(MONEDA) = 3 AND TIPO_CAMBIO > 0) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_MONTOS" CHECK (
        MONTO_OBLIGACION > 0 AND MONTO_DESCUENTO >= 0
        AND MONTO_RETENCION >= 0 AND MONTO_COMISION >= 0
        AND MONTO_TRANSFERIDO >= 0 AND MONTO_APLICADO >= 0
        AND MONTO_NO_APLICADO >= 0 AND MONTO_APLICADO <= MONTO_OBLIGACION
        AND MONTO_TRANSFERIDO = ROUND(
            MONTO_OBLIGACION - MONTO_DESCUENTO - MONTO_RETENCION
            + MONTO_COMISION,
            2
        )
        AND MONTO_NO_APLICADO = ROUND(MONTO_OBLIGACION - MONTO_APLICADO, 2)
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_REVERSA" CHECK (TIPO_PAGO NOT IN ('DEVOLUCION', 'REVERSO') OR ID_PAGO_ORIGEN IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_CONTABLE" CHECK (ESTADO_CONTABLE IN ('PENDIENTE', 'ENVIADO', 'CONTABILIZADO',
                             'ERROR', 'REVERTIDO', 'NO_APLICA')) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_ESTADO" CHECK (ESTADO IN ('BORRADOR', 'PROGRAMADO', 'PENDIENTE_APROBACION',
                    'APROBADO', 'ENVIADO', 'EN_PROCESO', 'EJECUTADO',
                    'CONFIRMADO', 'PARCIALMENTE_APLICADO', 'APLICADO',
                    'CONCILIADO', 'RECHAZADO', 'DEVUELTO', 'ANULADO')) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_RECHAZO" CHECK (ESTADO <> 'RECHAZADO' OR MOTIVO_RECHAZO IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_DEV" CHECK (ESTADO <> 'DEVUELTO' OR MOTIVO_DEVOLUCION IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_ANUL" CHECK (ESTADO <> 'ANULADO' OR MOTIVO_ANULACION IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_SOD" CHECK (
        (EJECUTADO_POR IS NULL OR EJECUTADO_POR <> PROGRAMADO_POR)
        AND (CONCILIADO_POR IS NULL OR CONCILIADO_POR <> PROGRAMADO_POR)
        AND (CONCILIADO_POR IS NULL OR EJECUTADO_POR IS NULL
             OR CONCILIADO_POR <> EJECUTADO_POR)
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_ORIG_DIST" CHECK (ID_PAGO_ORIGEN IS NULL OR ID_PAGO_ORIGEN <> ID_PAGO) ENABLE, 
	 CONSTRAINT "CK_CXP_PAGO_EJEC" CHECK (
        (ESTADO IN ('EJECUTADO', 'CONFIRMADO', 'PARCIALMENTE_APLICADO',
                    'APLICADO', 'CONCILIADO')
         AND EJECUTADO_POR IS NOT NULL AND FECHA_PAGO IS NOT NULL)
        OR ESTADO NOT IN ('EJECUTADO', 'CONFIRMADO',
                          'PARCIALMENTE_APLICADO', 'APLICADO', 'CONCILIADO')
    ) ENABLE, 
	 CONSTRAINT "PK_CXP_PAGO" PRIMARY KEY ("ID_PAGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_PAGO_COD" UNIQUE ("CODIGO_PAGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_PAGO_IDEMP" UNIQUE ("CLAVE_IDEMPOTENCIA")
  USING INDEX  ENABLE
   );

-- TABLE CXP_PARAMETRO
CREATE TABLE "CXP_PARAMETRO" 
   (	"ID_PARAMETRO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"GRUPO_PARAMETRO" VARCHAR2(50) NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(60) NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(150) NOT NULL ENABLE, 
	"VALOR_TEXTO" VARCHAR2(500), 
	"VALOR_NUMERO" NUMBER(18,6), 
	"ACTIVO" CHAR(1) DEFAULT 'S' NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_CXP_PAR_ACTIVO" CHECK (ACTIVO IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_CXP_PAR_VALOR" CHECK (VALOR_TEXTO IS NOT NULL OR VALOR_NUMERO IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_CXP_PARAMETRO" PRIMARY KEY ("ID_PARAMETRO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_PARAMETRO" UNIQUE ("GRUPO_PARAMETRO", "CODIGO")
  USING INDEX  ENABLE
   );

-- TABLE CXP_PERIODO
CREATE TABLE "CXP_PERIODO" 
   (	"ID_PERIODO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_SUCURSAL" NUMBER NOT NULL ENABLE, 
	"ANIO" NUMBER(4,0) NOT NULL ENABLE, 
	"MES" NUMBER(2,0) NOT NULL ENABLE, 
	"FECHA_INICIO" DATE NOT NULL ENABLE, 
	"FECHA_FIN" DATE NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'ABIERTO' NOT NULL ENABLE, 
	"SALDO_INICIAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MOVIMIENTOS_DEBE" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MOVIMIENTOS_HABER" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"SALDO_FINAL" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"CERRADO_POR" NUMBER, 
	"FECHA_CIERRE" TIMESTAMP (6), 
	"REABIERTO_POR" NUMBER, 
	"FECHA_REAPERTURA" TIMESTAMP (6), 
	"MOTIVO_REAPERTURA" VARCHAR2(500), 
	"OBSERVACIONES" VARCHAR2(1000), 
	 CONSTRAINT "CK_CXP_PER_MES" CHECK (MES BETWEEN 1 AND 12) ENABLE, 
	 CONSTRAINT "CK_CXP_PER_FECHAS" CHECK (FECHA_FIN >= FECHA_INICIO) ENABLE, 
	 CONSTRAINT "CK_CXP_PER_ESTADO" CHECK (ESTADO IN ('ABIERTO', 'EN_CIERRE', 'CERRADO', 'REABIERTO')) ENABLE, 
	 CONSTRAINT "CK_CXP_PER_CIERRE" CHECK (
        (ESTADO = 'CERRADO' AND CERRADO_POR IS NOT NULL
         AND FECHA_CIERRE IS NOT NULL)
        OR ESTADO <> 'CERRADO'
    ) ENABLE, 
	 CONSTRAINT "CK_CXP_PER_REAP" CHECK (
        (ESTADO = 'REABIERTO' AND REABIERTO_POR IS NOT NULL
         AND FECHA_REAPERTURA IS NOT NULL AND MOTIVO_REAPERTURA IS NOT NULL)
        OR ESTADO <> 'REABIERTO'
    ) ENABLE, 
	 CONSTRAINT "PK_CXP_PERIODO" PRIMARY KEY ("ID_PERIODO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_PERIODO" UNIQUE ("ID_SUCURSAL", "ANIO", "MES")
  USING INDEX  ENABLE
   );

-- TABLE CXP_REGLA_APROBACION
CREATE TABLE "CXP_REGLA_APROBACION" 
   (	"ID_REGLA" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"TIPO_ENTIDAD" VARCHAR2(25) NOT NULL ENABLE, 
	"NOMBRE_REGLA" VARCHAR2(150) NOT NULL ENABLE, 
	"ID_PROVEEDOR" NUMBER, 
	"ID_DEPARTAMENTO" NUMBER, 
	"CENTRO_COSTO" VARCHAR2(50), 
	"PROYECTO" VARCHAR2(100), 
	"MONEDA" VARCHAR2(3), 
	"MONTO_DESDE" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_HASTA" NUMBER(18,2), 
	"REQUIERE_SIN_OC" CHAR(1), 
	"REQUIERE_DIFERENCIA" CHAR(1), 
	"NIVEL" NUMBER(4,0) NOT NULL ENABLE, 
	"ID_ROL_APROBADOR" NUMBER NOT NULL ENABLE, 
	"CANTIDAD_APROBADORES" NUMBER(3,0) DEFAULT 1 NOT NULL ENABLE, 
	"PERMITE_DELEGACION" CHAR(1) DEFAULT 'S' NOT NULL ENABLE, 
	"VIGENTE_DESDE" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"VIGENTE_HASTA" DATE, 
	"ACTIVA" CHAR(1) DEFAULT 'S' NOT NULL ENABLE, 
	"CREADA_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_CXP_REG_ENTIDAD" CHECK (TIPO_ENTIDAD IN ('DOCUMENTO', 'PAGO', 'LOTE', 'CUENTA_BANCARIA',
                          'COMPROMISO', 'PERIODO')) ENABLE, 
	 CONSTRAINT "CK_CXP_REG_MONTOS" CHECK (MONTO_DESDE >= 0 AND (MONTO_HASTA IS NULL OR MONTO_HASTA >= MONTO_DESDE)) ENABLE, 
	 CONSTRAINT "CK_CXP_REG_SINO" CHECK ((REQUIERE_SIN_OC IS NULL OR REQUIERE_SIN_OC IN ('S', 'N'))
         AND (REQUIERE_DIFERENCIA IS NULL OR REQUIERE_DIFERENCIA IN ('S', 'N'))
         AND PERMITE_DELEGACION IN ('S', 'N') AND ACTIVA IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_CXP_REG_VIGENCIA" CHECK (VIGENTE_HASTA IS NULL OR VIGENTE_HASTA >= VIGENTE_DESDE) ENABLE, 
	 CONSTRAINT "CK_CXP_REG_NIVEL" CHECK (NIVEL > 0 AND CANTIDAD_APROBADORES > 0) ENABLE, 
	 CONSTRAINT "PK_CXP_REGLA_APROB" PRIMARY KEY ("ID_REGLA")
  USING INDEX  ENABLE
   );

-- TABLE CXP_REGLA_TRIBUTARIA
CREATE TABLE "CXP_REGLA_TRIBUTARIA" 
   (	"ID_REGLA_TRIBUTARIA" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CODIGO_REGLA" VARCHAR2(30) NOT NULL ENABLE, 
	"VERSION_REGLA" NUMBER(6,0) DEFAULT 1 NOT NULL ENABLE, 
	"ID_REGLA_ANTERIOR" NUMBER, 
	"TIPO_DOCUMENTO" VARCHAR2(30) DEFAULT 'FACTURA_ESPECIAL' NOT NULL ENABLE, 
	"TIPO_TRIBUTO" VARCHAR2(15) NOT NULL ENABLE, 
	"CODIGO_TRIBUTO" VARCHAR2(30) NOT NULL ENABLE, 
	"NOMBRE_TRIBUTO" VARCHAR2(120) NOT NULL ENABLE, 
	"PORCENTAJE" NUMBER(9,6) DEFAULT 0 NOT NULL ENABLE, 
	"MONTO_FIJO" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"BASE_DESDE" NUMBER(18,2) DEFAULT 0 NOT NULL ENABLE, 
	"BASE_HASTA" NUMBER(18,2), 
	"SOBRE_EXCEDENTE" CHAR(1) DEFAULT 'N' NOT NULL ENABLE, 
	"MONEDA" VARCHAR2(3), 
	"VIGENTE_DESDE" DATE NOT NULL ENABLE, 
	"VIGENTE_HASTA" DATE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'VIGENTE' NOT NULL ENABLE, 
	"MOTIVO_CAMBIO" VARCHAR2(500), 
	"CREADA_POR" NUMBER NOT NULL ENABLE, 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"MODIFICADA_POR" NUMBER, 
	"FECHA_MODIFICACION" TIMESTAMP (6), 
	 CONSTRAINT "CK_CXP_RTRIB_TIPO" CHECK (TIPO_TRIBUTO IN ('IMPUESTO', 'RETENCION')) ENABLE, 
	 CONSTRAINT "CK_CXP_RTRIB_MONTOS" CHECK (PORCENTAJE >= 0 AND PORCENTAJE <= 100 AND MONTO_FIJO >= 0 AND BASE_DESDE >= 0
                 AND (BASE_HASTA IS NULL OR BASE_HASTA >= BASE_DESDE)) ENABLE, 
	 CONSTRAINT "CK_CXP_RTRIB_EXCED" CHECK (SOBRE_EXCEDENTE IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_CXP_RTRIB_MONEDA" CHECK (MONEDA IS NULL OR LENGTH(MONEDA) = 3) ENABLE, 
	 CONSTRAINT "CK_CXP_RTRIB_VIGENCIA" CHECK (VIGENTE_HASTA IS NULL OR VIGENTE_HASTA >= VIGENTE_DESDE) ENABLE, 
	 CONSTRAINT "CK_CXP_RTRIB_ESTADO" CHECK (ESTADO IN ('VIGENTE', 'REEMPLAZADA', 'FINALIZADA')) ENABLE, 
	 CONSTRAINT "CK_CXP_RTRIB_VERSION" CHECK (VERSION_REGLA > 0) ENABLE, 
	 CONSTRAINT "CK_CXP_RTRIB_CAMBIO" CHECK (VERSION_REGLA = 1 OR MOTIVO_CAMBIO IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_CXP_REGLA_TRIB" PRIMARY KEY ("ID_REGLA_TRIBUTARIA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_CXP_RTRIB_VERSION" UNIQUE ("CODIGO_REGLA", "VERSION_REGLA")
  USING INDEX  ENABLE
   );

-- TABLE DEPARTAMENTO
CREATE TABLE "DEPARTAMENTO" 
   (	"DEP_ID_DEPARTAMENTO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"DEP_NOMBRE_DEPARTAMENTO" VARCHAR2(100), 
	"DEP_PRESUPUESTO_DISPONIBLE" NUMBER(10,2) DEFAULT 0, 
	"DEP_ID_GERENTE" NUMBER, 
	"DEP_ACTIVO" NUMBER(1,0) DEFAULT 1, 
	 CONSTRAINT "PK_DEPARTAMENTO" PRIMARY KEY ("DEP_ID_DEPARTAMENTO")
  USING INDEX  ENABLE
   );

-- TABLE EMPLEADO
CREATE TABLE "EMPLEADO" 
   (	"ID_EMPLEADO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CODIGO_EMPLEADO" VARCHAR2(30), 
	"NOMBRE" VARCHAR2(120) NOT NULL ENABLE, 
	"APELLIDO" VARCHAR2(120), 
	"PUESTO" VARCHAR2(100), 
	"EMAIL" VARCHAR2(150), 
	"TELEFONO" VARCHAR2(30), 
	"ESTADO" CHAR(1) DEFAULT 'A' NOT NULL ENABLE, 
	"FOTO_URL" VARCHAR2(1000), 
	 CONSTRAINT "CK_CXC_EMPLEADOS_ESTADO" CHECK (ESTADO IN ('A','I')) ENABLE, 
	 CONSTRAINT "PK_CXC_EMPLEADOS" PRIMARY KEY ("ID_EMPLEADO")
  USING INDEX  ENABLE
   );

-- TABLE MB_AUDITORIA_BANCARIA
