	"RESULTADO" VARCHAR2(20) NOT NULL ENABLE, 
	"VALOR_ANTERIOR" CLOB, 
	"VALOR_NUEVO" CLOB, 
	"MODULO_ORIGEN" VARCHAR2(20) NOT NULL ENABLE, 
	"INFO_SESION" CLOB, 
	 CONSTRAINT "MB_CK_AUD_RESULTADO" CHECK (resultado IN ('EXITOSO','FALLIDO')) ENABLE, 
	 CONSTRAINT "MB_PK_AUDITORIA_BANCARIA" PRIMARY KEY ("AUDITORIA_ID")
  USING INDEX  ENABLE
   );

