-- TABLE MB_CATALOGO_BANCARIO
CREATE TABLE "MB_CATALOGO_BANCARIO" 
   (	"CATALOGO_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"GRUPO" VARCHAR2(30) NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(30) NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(80) NOT NULL ENABLE, 
	"DESCRIPCION" VARCHAR2(250), 
	"APLICA_A" VARCHAR2(30), 
	"NATURALEZA" CHAR(1), 
	"REQUIERE_COMENTARIO" CHAR(1) NOT NULL ENABLE, 
	"REQUIERE_EVIDENCIA" CHAR(1) NOT NULL ENABLE, 
	"PERMITE_REVERSION" CHAR(1) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(15) NOT NULL ENABLE, 
	 CONSTRAINT "MB_CK_CATALOGO_NAT" CHECK (naturaleza IN ('D','C') OR naturaleza IS NULL) ENABLE, 
	 CONSTRAINT "MB_CK_CATALOGO_FLAGS" CHECK (requiere_comentario IN ('S','N') AND requiere_evidencia IN ('S','N') AND permite_reversion IN ('S','N')) ENABLE, 
	 CONSTRAINT "MB_CK_CATALOGO_ESTADO" CHECK (estado IN ('ACTIVO','INACTIVO')) ENABLE, 
	 CONSTRAINT "MB_CK_CATALOGO_NAT_TIPO" CHECK (grupo <> 'TIPO_MOVIMIENTO' OR naturaleza IS NOT NULL) ENABLE, 
	 CONSTRAINT "MB_PK_CATALOGO_BANCARIO" PRIMARY KEY ("CATALOGO_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "MB_UQ_CATALOGO_GRUPO_CODIGO" UNIQUE ("GRUPO", "CODIGO")
  USING INDEX  ENABLE
   );

-- TABLE MB_CHEQUE
CREATE TABLE "MB_CHEQUE" 
   (	"CHEQUE_ID" NUMBER(19,0) NOT NULL ENABLE, 
