	 CONSTRAINT "MB_PK_CHEQUE" PRIMARY KEY ("CHEQUE_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "MB_UQ_CHEQUE_OP" UNIQUE ("OPERACION_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "MB_UQ_CHEQUE_MOV" UNIQUE ("MOVIMIENTO_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "MB_UQ_CHEQUE_NUM" UNIQUE ("CHEQUERA_ID", "NUMERO_CHEQUE")
  USING INDEX  ENABLE
   );

