-- TABLE MB_CUENTA_BANCARIA
CREATE TABLE "MB_CUENTA_BANCARIA" 
   (	"CUENTA_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"EMPRESA_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"BANCO_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"MONEDA_ID" NUMBER(5,0) NOT NULL ENABLE, 
	"TIPO_CUENTA_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"RESPONSABLE_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"CODIGO_CUENTA" VARCHAR2(20) NOT NULL ENABLE, 
	"NUMERO_CUENTA" VARCHAR2(20) NOT NULL ENABLE, 
	"NOMBRE_INTERNO" VARCHAR2(80) NOT NULL ENABLE, 
	"SALDO_INICIAL" NUMBER(18,2) NOT NULL ENABLE, 
	"FECHA_APERTURA" DATE NOT NULL ENABLE, 
	"USO_PRINCIPAL" VARCHAR2(15) NOT NULL ENABLE, 
	"PERMITE_COBROS" CHAR(1) NOT NULL ENABLE, 
	"PERMITE_PAGOS" CHAR(1) NOT NULL ENABLE, 
	"PERMITE_CHEQUES" CHAR(1) NOT NULL ENABLE, 
	"PERMITE_TRANSFERENCIAS" CHAR(1) NOT NULL ENABLE, 
	"FECHA_CIERRE" DATE, 
	"ESTADO" VARCHAR2(15) NOT NULL ENABLE, 
	"OBSERVACIONES" VARCHAR2(500), 
	"CREADO_POR" NUMBER(10,0) NOT NULL ENABLE, 
	"CREADO_EN" TIMESTAMP (6) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER(10,0), 
	"MODIFICADO_EN" TIMESTAMP (6), 
	 CONSTRAINT "MB_CK_CUENTA_NUMERO" CHECK (REGEXP_LIKE(numero_cuenta,'^[0-9]{6,20}$')) ENABLE, 
	 CONSTRAINT "MB_CK_CUENTA_USO" CHECK (uso_principal IN ('COBROS','PAGOS','AMBOS')) ENABLE, 
	 CONSTRAINT "MB_CK_CUENTA_FLAGS" CHECK (permite_cobros IN ('S','N') AND permite_pagos IN ('S','N') AND permite_cheques IN ('S','N') AND permite_transferencias IN ('S','N')) ENABLE, 
	 CONSTRAINT "MB_CK_CUENTA_ESTADO" CHECK (estado IN ('BORRADOR','ACTIVA','INACTIVA','CERRADA')) ENABLE, 
	 CONSTRAINT "MB_PK_CUENTA_BANCARIA" PRIMARY KEY ("CUENTA_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "MB_UQ_CUENTA_CODIGO" UNIQUE ("CODIGO_CUENTA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "MB_UQ_CUENTA_NUMERO" UNIQUE ("EMPRESA_ID", "BANCO_ID", "NUMERO_CUENTA")
  USING INDEX  ENABLE
   );

