	"CONFIRMADO_POR" NUMBER(10,0), 
	"CONFIRMADO_EN" TIMESTAMP (6), 
	 CONSTRAINT "MB_CK_DCON_MONTO" CHECK (monto_conciliado > 0) ENABLE, 
	 CONSTRAINT "MB_CK_DCON_TIPO" CHECK (tipo_relacion IN ('UNO_UNO','UNO_VARIOS','VARIOS_UNO')) ENABLE, 
	 CONSTRAINT "MB_CK_DCON_ESTADO" CHECK (estado IN ('SUGERIDA','CONFIRMADA','RECHAZADA')) ENABLE, 
	 CONSTRAINT "MB_PK_DET_CONC" PRIMARY KEY ("DETALLE_CONCILIACION_ID")
  USING INDEX  ENABLE, 
