   (	"DIFERENCIA_ID" NUMBER(19,0) NOT NULL ENABLE, 
	"CONCILIACION_ID" NUMBER(19,0) NOT NULL ENABLE, 
	"LINEA_ESTADO_ID" NUMBER(19,0), 
	"MOVIMIENTO_ID" NUMBER(19,0), 
	"TIPO_DIFERENCIA_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"TIPO_AJUSTE_ID" NUMBER(10,0), 
	"OPERACION_AJUSTE_ID" NUMBER(19,0), 
	"FECHA_DIFERENCIA" DATE NOT NULL ENABLE, 
	"MONTO" NUMBER(18,2) NOT NULL ENABLE, 
	"CONCEPTO" VARCHAR2(250) NOT NULL ENABLE, 
	"DESCRIPCION" VARCHAR2(500) NOT NULL ENABLE, 
	"RESPALDO_DOCUMENTO_ID" NUMBER(19,0), 
	"ENVIAR_REVISION" CHAR(1) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) NOT NULL ENABLE, 
	"OBSERVACIONES" VARCHAR2(500), 
	 CONSTRAINT "MB_CK_DIF_ORIGEN" CHECK (linea_estado_id IS NOT NULL OR movimiento_id IS NOT NULL) ENABLE, 
	 CONSTRAINT "MB_CK_DIF_AJUSTADA" CHECK (estado <> 'AJUSTADA' OR operacion_ajuste_id IS NOT NULL) ENABLE, 
	 CONSTRAINT "MB_CK_DIF_REV" CHECK (enviar_revision IN ('S','N')) ENABLE, 
	 CONSTRAINT "MB_CK_DIF_ESTADO" CHECK (estado IN ('PENDIENTE','EN_REVISION','AJUSTADA','RESUELTA')) ENABLE, 
	 CONSTRAINT "MB_PK_DIF_CONC" PRIMARY KEY ("DIFERENCIA_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "MB_UQ_DIF_OP" UNIQUE ("OPERACION_AJUSTE_ID")
  USING INDEX  ENABLE
   );

