	 CONSTRAINT "MB_CK_ESTCTA_PERIODO" CHECK (periodo_desde <= periodo_hasta) ENABLE, 
	 CONSTRAINT "MB_CK_ESTCTA_ESTADO" CHECK (estado IN ('CARGADO','VALIDADO','CON_ERRORES','PROCESADO')) ENABLE, 
	 CONSTRAINT "MB_PK_ESTADO_CUENTA" PRIMARY KEY ("ESTADO_CUENTA_ID")
