-- TABLE MB_REGLA_APROBACION_BANCARIA
CREATE TABLE "MB_REGLA_APROBACION_BANCARIA" 
   (	"REGLA_ID" NUMBER(19,0) NOT NULL ENABLE, 
	"EMPRESA_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"TIPO_OPERACION_ID" NUMBER(10,0) NOT NULL ENABLE, 
	"MONEDA_ID" NUMBER(5,0) NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(100) NOT NULL ENABLE, 
	"MONTO_MINIMO" NUMBER(18,2) NOT NULL ENABLE, 
	"MONTO_MAXIMO" NUMBER(18,2), 
	"CANTIDAD_APROBACIONES" NUMBER(3,0) NOT NULL ENABLE, 
	"DOBLE_APROBACION" CHAR(1) NOT NULL ENABLE, 
	"REQUIERE_EVIDENCIA" CHAR(1) NOT NULL ENABLE, 
	"PERMITE_REPROGRAMAR" CHAR(1) NOT NULL ENABLE, 
	"VIGENCIA_DESDE" DATE NOT NULL ENABLE, 
	"VIGENCIA_HASTA" DATE, 
	"VERSION" NUMBER(5,0) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(15) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER(10,0) NOT NULL ENABLE, 
	"CREADO_EN" TIMESTAMP (6) NOT NULL ENABLE, 
	 CONSTRAINT "MB_CK_RAB_MIN" CHECK (monto_minimo >= 0) ENABLE, 
	 CONSTRAINT "MB_CK_RAB_MAX" CHECK (monto_maximo IS NULL OR monto_maximo > monto_minimo) ENABLE, 
	 CONSTRAINT "MB_CK_RAB_FLAGS" CHECK (doble_aprobacion IN ('S','N') AND requiere_evidencia IN ('S','N') AND permite_reprogramar IN ('S','N')) ENABLE, 
	 CONSTRAINT "MB_CK_RAB_ESTADO" CHECK (estado IN ('BORRADOR','ACTIVA','INACTIVA')) ENABLE, 
	 CONSTRAINT "MB_PK_REGLA_APROB" PRIMARY KEY ("REGLA_ID")
  USING INDEX  ENABLE
   );

