	"MONTO_DESTINO" NUMBER(18,2) NOT NULL ENABLE, 
	"REFERENCIA_BANCARIA" VARCHAR2(60), 
	"CONCEPTO" VARCHAR2(250) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) NOT NULL ENABLE, 
	 CONSTRAINT "MB_CK_TRF_DESTINO" CHECK ((cuenta_destino_id IS NOT NULL AND cta_proveedor_id IS NULL) OR (cuenta_destino_id IS NULL AND cta_proveedor_id IS NOT NULL)) ENABLE, 
	 CONSTRAINT "MB_CK_TRF_CUENTAS" CHECK (cuenta_destino_id IS NULL OR cuenta_destino_id <> cuenta_origen_id) ENABLE, 
	 CONSTRAINT "MB_CK_TRF_ESTADO" CHECK (estado IN ('BORRADOR','PROGRAMADA','EJECUTADA','RECHAZADA','ANULADA')) ENABLE, 
	 CONSTRAINT "MB_PK_TRANSFERENCIA" PRIMARY KEY ("TRANSFERENCIA_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "MB_UQ_TRANSFERENCIA_OP" UNIQUE ("OPERACION_ID")
  USING INDEX  ENABLE
   );

