-- TABLE SEG_USUARIOS
CREATE TABLE "SEG_USUARIOS" 
   (	"ID_USUARIO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER, 
	"USERNAME" VARCHAR2(50) NOT NULL ENABLE, 
	"EMAIL" VARCHAR2(150), 
	"NOMBRE" VARCHAR2(120) NOT NULL ENABLE, 
	"PASSWORD_HASH" VARCHAR2(300) NOT NULL ENABLE, 
	"ROL" VARCHAR2(15) DEFAULT 'OPERADOR' NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(10) DEFAULT 'ACTIVO' NOT NULL ENABLE, 
	"INTENTOS_FALLIDOS" NUMBER(3,0) DEFAULT 0 NOT NULL ENABLE, 
	"BLOQUEADO_HASTA" TIMESTAMP (6), 
	"DEBE_CAMBIAR_CLAVE" CHAR(1) DEFAULT 'S' NOT NULL ENABLE, 
	"FECHA_CLAVE" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"ULTIMO_LOGIN" TIMESTAMP (6), 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_SEG_USU_ROL" CHECK (ROL IN ('ADMIN', 'OPERADOR', 'CONSULTA')) ENABLE, 
	 CONSTRAINT "CK_SEG_USU_ESTADO" CHECK (ESTADO IN ('ACTIVO', 'INACTIVO')) ENABLE, 
	 CONSTRAINT "CK_SEG_USU_DEBE_CLAVE" CHECK (DEBE_CAMBIAR_CLAVE IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_SEG_USU_INTENTOS" CHECK (INTENTOS_FALLIDOS >= 0) ENABLE, 
	 CONSTRAINT "PK_SEG_USUARIOS" PRIMARY KEY ("ID_USUARIO")
  USING INDEX  ENABLE
   );

-- TABLE USUARIO
CREATE TABLE "USUARIO" 
   (	"USU_ID_USUARIO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"USU_NOMBRE_COMPLETO" VARCHAR2(150), 
	"USU_ID_ROL" NUMBER, 
	"USU_ID_DEPARTAMENTO" NUMBER, 
	"USU_ID_JEFE_INMEDIATO" NUMBER, 
	"USU_ACTIVO" NUMBER(1,0) DEFAULT 1, 
	 CONSTRAINT "PK_USUARIO" PRIMARY KEY ("USU_ID_USUARIO")
  USING INDEX  ENABLE
   );

