-- VIEW MB_V_CXC_COBROS
CREATE OR REPLACE FORCE EDITIONABLE VIEW "MB_V_CXC_COBROS" ("ID_PAGO_ORIGEN", "MODULO_ORIGEN", "CLIENTE_ID", "CLIENTE_NOMBRE", "CLIENTE_NIT", "CLIENTE_ESTADO", "FORMA_PAGO_ID", "FORMA_PAGO_NOMBRE", "REQUIERE_REFERENCIA", "MONEDA_ID", "MONEDA_CODIGO", "MONEDA_NOMBRE", "BANCO_ID", "BANCO_CODIGO", "BANCO_NOMBRE", "FECHA_PAGO", "MONTO", "NUMERO_REFERENCIA", "ESTADO_ORIGEN", "ES_BANCARIO", "INTEGRACION_VALIDA", "MOTIVO_INTEGRACION") AS 
  SELECT
    p.id_pago                          AS id_pago_origen,
    'CXC'                              AS modulo_origen,

    p.id_cliente                       AS cliente_id,
    c.nombre                           AS cliente_nombre,
    c.nit                              AS cliente_nit,
    c.estado                           AS cliente_estado,

    p.id_forma_pago                    AS forma_pago_id,
    fp.nombre                          AS forma_pago_nombre,
    fp.requiere_referencia             AS requiere_referencia,

    p.id_moneda                        AS moneda_id,
    m.codigo                           AS moneda_codigo,
    m.nombre                           AS moneda_nombre,

    p.id_banco                         AS banco_id,
    b.codigo_banco                     AS banco_codigo,
    b.nombre                           AS banco_nombre,

    p.fecha_pago                       AS fecha_pago,
    p.monto                            AS monto,
    p.numero_referencia                AS numero_referencia,
    p.estado                           AS estado_origen,

    CASE
        WHEN UPPER(TRIM(fp.nombre)) IN (
            'DEPOSITO BANCARIO',
            'DEPÓSITO BANCARIO',
            'DEBITO AUTOMATICO',
            'DÉBITO AUTOMÁTICO',
            'PAGO EN LINEA',
            'TRANSFERENCIA BANCARIA',
            'CHEQUE',
            'TARJETA EMPRESARIAL',
            'TARJETA DEBIT',
            'TARJETA DE CRÉDITO/DÉBITO'
        )
        THEN 'S'
        ELSE 'N'
    END AS es_bancario,

    CASE
        WHEN c.id_cliente IS NULL
            THEN 'N'

        WHEN m.id_moneda IS NULL
            THEN 'N'

        WHEN fp.id_forma_pago IS NULL
            THEN 'N'

        WHEN UPPER(TRIM(fp.nombre)) IN (
            'DEPOSITO BANCARIO',
            'DEPÓSITO BANCARIO',
            'DEBITO AUTOMATICO',
            'DÉBITO AUTOMÁTICO',
            'PAGO EN LINEA',
            'TRANSFERENCIA BANCARIA',
            'CHEQUE',
            'TARJETA EMPRESARIAL',
            'TARJETA DEBIT',
            'TARJETA DE CRÉDITO/DÉBITO'
        )
        AND p.id_banco IS NULL
            THEN 'N'

        WHEN p.id_banco IS NOT NULL
         AND b.banco_id IS NULL
            THEN 'N'

        WHEN NVL(p.monto, 0) <= 0
            THEN 'N'

        ELSE 'S'
    END AS integracion_valida,

    CASE
        WHEN c.id_cliente IS NULL
            THEN 'El cliente indicado por CXC no existe'

        WHEN m.id_moneda IS NULL
            THEN 'La moneda indicada por CXC no existe'

        WHEN fp.id_forma_pago IS NULL
            THEN 'La forma de pago indicada por CXC no existe'

        WHEN UPPER(TRIM(fp.nombre)) IN (
            'DEPOSITO BANCARIO',
            'DEPÓSITO BANCARIO',
            'DEBITO AUTOMATICO',
            'DÉBITO AUTOMÁTICO',
            'PAGO EN LINEA',
            'TRANSFERENCIA BANCARIA',
            'CHEQUE',
            'TARJETA EMPRESARIAL',
            'TARJETA DEBIT',
            'TARJETA DE CRÉDITO/DÉBITO'
        )
        AND p.id_banco IS NULL
            THEN 'El medio de pago es bancario pero CXC no tiene banco asociado'

        WHEN p.id_banco IS NOT NULL
         AND b.banco_id IS NULL
            THEN 'El banco indicado por CXC no existe en MB_BANCO'

        WHEN NVL(p.monto, 0) <= 0
            THEN 'El pago CXC no tiene un monto valido'

        ELSE NULL
    END AS motivo_integracion

FROM CXC_PAGOS p

LEFT JOIN CLIENTE c
    ON c.id_cliente = p.id_cliente

LEFT JOIN CXC_FORMAS_PAGO fp
    ON fp.id_forma_pago = p.id_forma_pago

LEFT JOIN MONEDA m
    ON m.id_moneda = p.id_moneda

LEFT JOIN MB_BANCO b
    ON b.banco_id = p.id_banco;

-- VIEW MB_V_CXP_OBLIGACIONES
CREATE OR REPLACE FORCE EDITIONABLE VIEW "MB_V_CXP_OBLIGACIONES" ("ID_DOCUMENTO_ORIGEN", "MODULO_ORIGEN", "PROVEEDOR_ID", "PROVEEDOR_NOMBRE", "PROVEEDOR_NIT", "TIPO_DOCUMENTO", "SERIE", "NUMERO_DOCUMENTO", "NO_FACTURA_COMPRA", "MONEDA_CODIGO", "MONEDA_ID", "TOTAL_NETO", "MONTO_APLICADO", "SALDO_PENDIENTE", "FECHA_DOCUMENTO", "FECHA_VENCIMIENTO", "ESTADO_ORIGEN", "ES_PAGABLE", "MOTIVO_NO_PAGABLE") AS 
  SELECT
    d.id_documento                       AS id_documento_origen,
    'CXP'                                AS modulo_origen,

    d.id_proveedor                       AS proveedor_id,
    p.pro_nombre_entidad                 AS proveedor_nombre,
    p.pro_nit                            AS proveedor_nit,

    d.tipo_documento                     AS tipo_documento,
    d.serie                              AS serie,
    d.numero_documento                   AS numero_documento,
    d.no_factura_compra                  AS no_factura_compra,

    d.moneda                             AS moneda_codigo,
    m.id_moneda                          AS moneda_id,

    d.total_neto                         AS total_neto,
    d.monto_aplicado                     AS monto_aplicado,
    d.saldo_pendiente                    AS saldo_pendiente,

    d.fecha_documento                    AS fecha_documento,
    d.fecha_vencimiento                  AS fecha_vencimiento,

    d.estado                             AS estado_origen,

    CASE
        WHEN d.id_proveedor IS NULL THEN 'N'

        WHEN NVL(p.pro_activo, 0) <> 1 THEN 'N'

        WHEN m.id_moneda IS NULL THEN 'N'

        WHEN NVL(d.saldo_pendiente, 0) <= 0 THEN 'N'

        WHEN d.estado NOT IN (
            'APROBADA',
            'CONTABILIZADA',
            'PENDIENTE_PAGO',
            'PROGRAMADA_PAGO',
            'PARCIALMENTE_PAGADA',
            'VENCIDA'
        ) THEN 'N'

        ELSE 'S'
    END AS es_pagable,

    CASE
        WHEN d.id_proveedor IS NULL
            THEN 'El documento no tiene proveedor asociado'

        WHEN NVL(p.pro_activo, 0) <> 1
            THEN 'El proveedor no se encuentra activo'

        WHEN m.id_moneda IS NULL
            THEN 'La moneda del documento no existe en el catalogo MONEDA'

        WHEN NVL(d.saldo_pendiente, 0) <= 0
            THEN 'El documento no tiene saldo pendiente'

        WHEN d.estado NOT IN (
            'APROBADA',
            'CONTABILIZADA',
            'PENDIENTE_PAGO',
            'PROGRAMADA_PAGO',
            'PARCIALMENTE_PAGADA',
            'VENCIDA'
        )
            THEN 'El estado actual de CXP no permite preparar el pago'

        ELSE NULL
    END AS motivo_no_pagable

FROM CXP_DOCUMENTO d

LEFT JOIN PROVEEDOR p
    ON p.pro_id_proveedor = d.id_proveedor

LEFT JOIN MONEDA m
    ON UPPER(TRIM(m.codigo)) = UPPER(TRIM(d.moneda))
   AND m.estado = 'A'

WHERE d.naturaleza = 'D';

-- VIEW VW_CXP_ANTIGUEDAD_SALDOS
CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_CXP_ANTIGUEDAD_SALDOS" ("ID_DOCUMENTO", "ID_PROVEEDOR", "NIT_PROVEEDOR", "PROVEEDOR", "TIPO_DOCUMENTO", "SERIE", "NUMERO_DOCUMENTO", "FECHA_DOCUMENTO", "FECHA_VENCIMIENTO", "MONEDA", "TOTAL_NETO", "SALDO_PENDIENTE", "DIAS_VENCIDO", "RANGO_ANTIGUEDAD", "PRIORIDAD", "ESTADO") AS 
  SELECT
    D.ID_DOCUMENTO,
    D.ID_PROVEEDOR,
    D.NIT_EMISOR AS NIT_PROVEEDOR,
    CAST(NULL AS VARCHAR2(150)) AS PROVEEDOR,
    D.TIPO_DOCUMENTO,
    D.SERIE,
    D.NUMERO_DOCUMENTO,
    D.FECHA_DOCUMENTO,
    D.FECHA_VENCIMIENTO,
    D.MONEDA,
    D.TOTAL_NETO,
    D.SALDO_PENDIENTE,
    GREATEST(TRUNC(SYSDATE) - TRUNC(D.FECHA_VENCIMIENTO), 0)
        AS DIAS_VENCIDO,
    CASE
        WHEN D.FECHA_VENCIMIENTO >= TRUNC(SYSDATE) THEN 'POR_VENCER'
        WHEN TRUNC(SYSDATE) - TRUNC(D.FECHA_VENCIMIENTO) <= 30 THEN '1_30'
        WHEN TRUNC(SYSDATE) - TRUNC(D.FECHA_VENCIMIENTO) <= 60 THEN '31_60'
        WHEN TRUNC(SYSDATE) - TRUNC(D.FECHA_VENCIMIENTO) <= 90 THEN '61_90'
        ELSE 'MAS_90'
    END AS RANGO_ANTIGUEDAD,
    D.PRIORIDAD,
    D.ESTADO
FROM "CXP_DOCUMENTO" D
WHERE D.NATURALEZA = 'D'
  AND D.SALDO_PENDIENTE > 0
  AND D.FECHA_VENCIMIENTO IS NOT NULL
  AND D.ESTADO IN ('APROBADA', 'CONTABILIZADA', 'PENDIENTE_PAGO',
                   'PROGRAMADA_PAGO', 'PARCIALMENTE_PAGADA', 'VENCIDA',
                   'BLOQUEADA', 'EN_DISPUTA');

-- VIEW VW_CXP_CUENTAS_COMPARTIDAS
CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_CXP_CUENTAS_COMPARTIDAS" ("BANCO_NOMBRE", "NUMERO_CUENTA", "MONEDA", "CANTIDAD_PROVEEDORES", "IDS_PROVEEDORES") AS 
  SELECT
    C.BANCO_NOMBRE,
    C.NUMERO_CUENTA,
    C.MONEDA,
    COUNT(DISTINCT C.ID_PROVEEDOR) AS CANTIDAD_PROVEEDORES,
    LISTAGG(TO_CHAR(C.ID_PROVEEDOR), ', ')
        WITHIN GROUP (ORDER BY C.ID_PROVEEDOR) AS IDS_PROVEEDORES
FROM "CXP_CUENTA_BANCARIA" C
WHERE C.TIPO_TITULAR = 'PROVEEDOR'
  AND C.ESTADO = 'ACTIVA'
GROUP BY C.BANCO_NOMBRE, C.NUMERO_CUENTA, C.MONEDA
HAVING COUNT(DISTINCT C.ID_PROVEEDOR) > 1;

-- VIEW VW_CXP_DASHBOARD
CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_CXP_DASHBOARD" ("MONEDA", "TOTAL_PENDIENTE", "TOTAL_VENCIDO", "VENCE_EN_7_DIAS", "DOCUMENTOS_PEND_APROBACION", "DOCUMENTOS_EN_DISPUTA", "DOCUMENTOS_BLOQUEADOS", "PAGOS_PROGRAMADOS", "ANTICIPOS_SIN_APLICAR") AS 
  SELECT
    D.MONEDA,
    SUM(D.SALDO_PENDIENTE) AS TOTAL_PENDIENTE,
    SUM(CASE
            WHEN D.FECHA_VENCIMIENTO < TRUNC(SYSDATE)
            THEN D.SALDO_PENDIENTE ELSE 0
        END) AS TOTAL_VENCIDO,
    SUM(CASE
            WHEN D.FECHA_VENCIMIENTO BETWEEN TRUNC(SYSDATE)
                 AND TRUNC(SYSDATE) + 7
            THEN D.SALDO_PENDIENTE ELSE 0
        END) AS VENCE_EN_7_DIAS,
    SUM(CASE WHEN D.ESTADO = 'PENDIENTE_APROBACION' THEN 1 ELSE 0 END)
        AS DOCUMENTOS_PEND_APROBACION,
    SUM(CASE WHEN D.ESTADO = 'EN_DISPUTA' THEN 1 ELSE 0 END)
        AS DOCUMENTOS_EN_DISPUTA,
    SUM(CASE WHEN D.ESTADO = 'BLOQUEADA' THEN 1 ELSE 0 END)
        AS DOCUMENTOS_BLOQUEADOS,
    (SELECT NVL(SUM(P.MONTO_OBLIGACION), 0)
       FROM "CXP_PAGO" P
      WHERE P.MONEDA = D.MONEDA
        AND P.ESTADO IN ('PROGRAMADO', 'PENDIENTE_APROBACION', 'APROBADO'))
        AS PAGOS_PROGRAMADOS,
    (SELECT NVL(SUM(P.MONTO_NO_APLICADO), 0)
       FROM "CXP_PAGO" P
      WHERE P.MONEDA = D.MONEDA
        AND P.TIPO_PAGO = 'ANTICIPO'
        AND P.ESTADO NOT IN ('ANULADO', 'DEVUELTO', 'RECHAZADO'))
        AS ANTICIPOS_SIN_APLICAR
FROM "CXP_DOCUMENTO" D
WHERE D.NATURALEZA = 'D'
  AND D.ESTADO NOT IN ('DUPLICADO', 'RECHAZADA', 'ANULADA', 'CERRADA')
GROUP BY D.MONEDA;

-- VIEW VW_CXP_ESTADO_CUENTA
CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_CXP_ESTADO_CUENTA" ("ID_PROVEEDOR", "FECHA_MOVIMIENTO", "TIPO_MOVIMIENTO", "ID_ORIGEN", "REFERENCIA", "DEBITO", "CREDITO", "MONEDA", "ESTADO") AS 
  SELECT
    D.ID_PROVEEDOR,
    CAST(D.FECHA_DOCUMENTO AS TIMESTAMP) AS FECHA_MOVIMIENTO,
    D.TIPO_DOCUMENTO AS TIPO_MOVIMIENTO,
    D.ID_DOCUMENTO AS ID_ORIGEN,
    NVL(D.SERIE || '-', '') || D.NUMERO_DOCUMENTO AS REFERENCIA,
    CASE WHEN D.NATURALEZA = 'D' THEN D.TOTAL_NETO ELSE 0 END AS DEBITO,
    CASE WHEN D.NATURALEZA = 'C' THEN D.TOTAL_NETO ELSE 0 END AS CREDITO,
    D.MONEDA,
    D.ESTADO
FROM "CXP_DOCUMENTO" D
WHERE D.ID_PROVEEDOR IS NOT NULL
UNION ALL
SELECT
    P.ID_PROVEEDOR,
    NVL(P.FECHA_PAGO, CAST(P.FECHA_PROGRAMADA AS TIMESTAMP)),
    'PAGO_' || P.TIPO_PAGO,
    P.ID_PAGO,
    P.CODIGO_PAGO,
    0,
    P.MONTO_OBLIGACION,
    P.MONEDA,
    P.ESTADO
FROM "CXP_PAGO" P
WHERE P.ESTADO NOT IN ('BORRADOR', 'RECHAZADO', 'DEVUELTO', 'ANULADO');

-- VIEW VW_CXP_INTEGRACION_COMPRAS
CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_CXP_INTEGRACION_COMPRAS" ("ID_DOCUMENTO", "NO_FACTURA_COMPRA", "FAC_FECHA_FACTURA", "ID_PROVEEDOR", "PRO_NIT", "PRO_NOMBRE_ENTIDAD", "NO_ORDEN_COMPRA", "OCO_FECHA_EMISION", "NO_RECEPCION", "RBO_FECHA_RECEPCION", "TOTAL_COMPRAS", "TOTAL_CXP", "DIFERENCIA_INTEGRACION", "RESULTADO_TRES_VIAS", "ESTADO") AS 
  SELECT
    D.ID_DOCUMENTO,
    D.NO_FACTURA_COMPRA,
    F.FAC_FECHA_FACTURA,
    D.ID_PROVEEDOR,
    D.NIT_EMISOR AS PRO_NIT,
    CAST(NULL AS VARCHAR2(150)) AS PRO_NOMBRE_ENTIDAD,
    D.NO_ORDEN_COMPRA,
    O.OCO_FECHA_EMISION,
    D.NO_RECEPCION,
    R.RBO_FECHA_RECEPCION,
    F.FAC_TOTAL_FACTURA AS TOTAL_COMPRAS,
    D.TOTAL_BRUTO AS TOTAL_CXP,
    D.TOTAL_BRUTO - F.FAC_TOTAL_FACTURA AS DIFERENCIA_INTEGRACION,
    D.RESULTADO_TRES_VIAS,
    D.ESTADO
FROM "CXP_DOCUMENTO" D
JOIN "CMP_FACTURA_CXP" F
  ON F.FAC_NO_FACTURA = D.NO_FACTURA_COMPRA
LEFT JOIN "CMP_ORDEN_COMPRA" O
  ON O.OCO_NO_PO = D.NO_ORDEN_COMPRA
LEFT JOIN "CMP_RECEPCION_BODEGA" R
  ON R.RBO_NO_RECEPCION = D.NO_RECEPCION;

-- VIEW VW_CXP_VALIDACION_TRES_VIAS
CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_CXP_VALIDACION_TRES_VIAS" ("ID_DOCUMENTO", "NUMERO_DOCUMENTO", "NO_ORDEN_COMPRA", "NO_RECEPCION", "NUMERO_LINEA", "CODIGO_ARTICULO", "DESCRIPCION", "CANTIDAD_ORDENADA", "CANTIDAD_RECIBIDA", "CANTIDAD_FACTURADA", "PRECIO_ORDENADO", "PRECIO_FACTURADO", "DIFERENCIA_CANTIDAD", "DIFERENCIA_PRECIO", "RESULTADO_TRES_VIAS") AS 
  SELECT
    D.ID_DOCUMENTO,
    D.NUMERO_DOCUMENTO,
    D.NO_ORDEN_COMPRA,
    D.NO_RECEPCION,
    L.NUMERO_LINEA,
    L.CODIGO_ARTICULO,
    L.DESCRIPCION,
    L.CANTIDAD_ORDENADA,
    L.CANTIDAD_RECIBIDA,
    L.CANTIDAD_FACTURADA,
    L.PRECIO_ORDENADO,
    L.PRECIO_FACTURADO,
    L.DIFERENCIA_CANTIDAD,
    L.DIFERENCIA_PRECIO,
    L.RESULTADO_TRES_VIAS
FROM "CXP_DOCUMENTO" D
JOIN "CXP_DOCUMENTO_DETALLE" L
  ON L.ID_DOCUMENTO = D.ID_DOCUMENTO
WHERE D.TIPO_REGISTRO = 'CON_OC';

