-- PACKAGE MB_FONDOS
CREATE OR REPLACE PACKAGE "MB_FONDOS" AS

    /*
      Sprint 2 - Bancos
      Proceso 1: Cuentas y disponibilidad

      Regla general:
        saldo interno =
            saldo inicial
            + creditos aplicados
            - debitos aplicados

        disponibilidad =
            saldo interno
            - compromisos activos

      IMPORTANTE:
      Este package NO realiza COMMIT ni ROLLBACK.
      La transaccion debe ser controlada por el consumidor.
    */


    ------------------------------------------------------------------
    -- Calcula la disponibilidad actual de una cuenta.
    ------------------------------------------------------------------
    FUNCTION CALCULAR_DISPONIBILIDAD (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE
    )
    RETURN NUMBER;


    ------------------------------------------------------------------
    -- Devuelve el resumen financiero de una cuenta:
    -- saldo inicial, creditos, debitos, saldo interno,
    -- compromisos activos y disponibilidad.
    ------------------------------------------------------------------
    PROCEDURE OBTENER_RESUMEN (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,
        p_fecha_desde
            IN DATE DEFAULT NULL,
        p_fecha_hasta
            IN DATE DEFAULT NULL,
        p_resultado
            OUT SYS_REFCURSOR
    );


    ------------------------------------------------------------------
    -- Lista los movimientos bancarios de una cuenta por periodo.
    ------------------------------------------------------------------
    PROCEDURE LISTAR_MOVIMIENTOS (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,
        p_fecha_desde
            IN DATE DEFAULT NULL,
        p_fecha_hasta
            IN DATE DEFAULT NULL,
        p_resultado
            OUT SYS_REFCURSOR
    );


    ------------------------------------------------------------------
    -- Reserva fondos para una operacion bancaria.
    --
    -- La implementacion bloqueara la cuenta y recalculara la
    -- disponibilidad dentro de la misma transaccion.
    ------------------------------------------------------------------
    PROCEDURE RESERVAR (
        p_operacion_id
            IN MB_OPERACION_BANCARIA.operacion_id%TYPE,
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,
        p_monto
            IN MB_FONDO_COMPROMETIDO.monto%TYPE,
        p_compromiso_id
            OUT MB_FONDO_COMPROMETIDO.compromiso_id%TYPE
    );


    ------------------------------------------------------------------
    -- Marca un compromiso ACTIVO como CONSUMIDO.
    --
    -- El movimiento del pago se registra por el proceso que ejecuta
    -- la operacion. MB_FONDOS solo administra la reserva.
    ------------------------------------------------------------------
    PROCEDURE CONSUMIR (
        p_compromiso_id
            IN MB_FONDO_COMPROMETIDO.compromiso_id%TYPE
    );


    ------------------------------------------------------------------
    -- Libera un compromiso ACTIVO.
    ------------------------------------------------------------------
    PROCEDURE LIBERAR (
        p_compromiso_id
            IN MB_FONDO_COMPROMETIDO.compromiso_id%TYPE
    );


    ------------------------------------------------------------------
    -- Consulta un compromiso especifico.
    ------------------------------------------------------------------
    PROCEDURE OBTENER_COMPROMISO (
        p_compromiso_id
            IN MB_FONDO_COMPROMETIDO.compromiso_id%TYPE,
        p_resultado
            OUT SYS_REFCURSOR
    );


    ------------------------------------------------------------------
    -- Lista los compromisos de una cuenta.
    -- p_estado = NULL significa todos los estados.
    ------------------------------------------------------------------
    PROCEDURE LISTAR_COMPROMISOS (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,
        p_estado
            IN MB_FONDO_COMPROMETIDO.estado%TYPE DEFAULT NULL,
        p_resultado
            OUT SYS_REFCURSOR
    );

END MB_FONDOS;
/

-- PACKAGE MB_IMPORTACION
CREATE OR REPLACE PACKAGE "MB_IMPORTACION" AS

    /* =========================================================
       PROCESO DE IMPORTACION DE ESTADOS DE CUENTA
       ========================================================= */


    /* =========================================================
       PROCEDURE: registrar_documento

       Registra el archivo fisico asociado a una importacion
       bancaria.

       Node.js calcula previamente el SHA-256 del archivo y
       proporciona sus metadatos.

       Oracle:
         - Resuelve el tipo documental ESTADO_CUENTA.
         - Verifica que el hash no haya sido registrado.
         - Genera DOCUMENTO_ID.
         - Registra MB_DOCUMENTO_BANCARIO.

       La transaccion es controlada por el consumidor del
       package. Este procedimiento NO realiza COMMIT.

       Retorna:
         p_documento_id -> identificador generado.
       ========================================================= */

    PROCEDURE registrar_documento (
        p_numero_referencia IN VARCHAR2,
        p_fecha_documento   IN DATE,
        p_nombre_archivo    IN VARCHAR2,
        p_tipo_mime         IN VARCHAR2,
        p_tamano_bytes      IN NUMBER,
        p_ubicacion_archivo IN VARCHAR2,
        p_hash_sha256       IN VARCHAR2,
        p_descripcion       IN VARCHAR2,
        p_observaciones     IN VARCHAR2,
        p_cargado_por       IN NUMBER,
        p_documento_id      OUT NUMBER
    );


    /* =========================================================
       PROCEDURE: crear_estado_cuenta

       Crea la cabecera de una nueva importacion bancaria.

       Estado inicial:
         CARGADO

       Retorna:
         p_estado_cuenta_id -> identificador generado.
       ========================================================= */

    PROCEDURE crear_estado_cuenta (
        p_cuenta_id            IN NUMBER,
        p_formato_id           IN NUMBER,
        p_archivo_documento_id IN NUMBER,
        p_periodo_desde        IN DATE,
        p_periodo_hasta        IN DATE,
        p_saldo_inicial        IN NUMBER,
        p_saldo_final          IN NUMBER,
        p_importado_por        IN NUMBER,
        p_observaciones        IN VARCHAR2,
        p_estado_cuenta_id     OUT NUMBER
    );


    /* =========================================================
       PROCEDURE: registrar_linea

       Registra una linea del archivo bancario.

       Node.js realiza previamente el parsing del archivo.
       Oracle persiste y valida la informacion recibida.

       Estados de validacion:
         VALIDA
         ERROR
         DUPLICADA

       Retorna:
         p_linea_estado_id -> identificador generado.
       ========================================================= */

    PROCEDURE registrar_linea (
        p_estado_cuenta_id  IN NUMBER,
        p_numero_linea      IN NUMBER,
        p_fecha_bancaria    IN DATE,
        p_fecha_valor       IN DATE,
        p_referencia        IN VARCHAR2,
        p_descripcion       IN VARCHAR2,
        p_numero_cheque     IN VARCHAR2,
        p_naturaleza        IN CHAR,
        p_monto             IN NUMBER,
        p_saldo_linea       IN NUMBER,
        p_hash_linea        IN CHAR,
        p_estado_validacion IN VARCHAR2,
        p_detalle_error     IN VARCHAR2,
        p_linea_estado_id   OUT NUMBER
    );


    /* =========================================================
       PROCEDURE: finalizar_importacion

       Actualiza los contadores y el estado general de una
       importacion despues de procesar sus lineas.
       ========================================================= */

    PROCEDURE finalizar_importacion (
        p_estado_cuenta_id IN NUMBER
    );


    /* =========================================================
       PROCEDURE: obtener_estado_cuenta

       Obtiene la cabecera de una importacion.
       ========================================================= */

    PROCEDURE obtener_estado_cuenta (
        p_estado_cuenta_id IN NUMBER,
        p_resultado        OUT SYS_REFCURSOR
    );


    /* =========================================================
       PROCEDURE: listar_lineas

       Lista las lineas pertenecientes a una importacion.
       ========================================================= */

    PROCEDURE listar_lineas (
        p_estado_cuenta_id IN NUMBER,
        p_resultado        OUT SYS_REFCURSOR
    );

END MB_IMPORTACION;
/

-- PACKAGE MB_VERIFICACION
CREATE OR REPLACE PACKAGE "MB_VERIFICACION" AS

    ------------------------------------------------------------------
    -- Obtiene la ficha de revision de una cuenta de proveedor.
    ------------------------------------------------------------------
    PROCEDURE OBTENER_DETALLE (
        p_cta_proveedor_id
            IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE,
        p_resultado
            OUT SYS_REFCURSOR
