        p_resultado
            OUT SYS_REFCURSOR
    );


    ------------------------------------------------------------------
    -- Registra una decision formal sobre la cuenta del proveedor.
    --
    -- Decisiones permitidas:
    -- VERIFICAR
    -- RECHAZAR
    -- BLOQUEAR
    ------------------------------------------------------------------
    PROCEDURE REGISTRAR_DECISION (
