            IN MB_VERIFICACION_CTA_PROVEEDOR.comentario%TYPE,

        p_evidencia_documento_id
            IN MB_VERIFICACION_CTA_PROVEEDOR.evidencia_documento_id%TYPE,

        p_fecha_vigencia
            IN MB_VERIFICACION_CTA_PROVEEDOR.fecha_vigencia%TYPE,

        p_verificado_por
            IN MB_VERIFICACION_CTA_PROVEEDOR.verificado_por%TYPE,

        p_verificacion_id
            OUT MB_VERIFICACION_CTA_PROVEEDOR.verificacion_id%TYPE
    );

END MB_VERIFICACION;
/

-- PACKAGE PKG_MB_BANCOS
CREATE OR REPLACE PACKAGE "PKG_MB_BANCOS" AS

    -- ========================================================
    -- LISTAR TODOS LOS BANCOS
    -- ========================================================

    PROCEDURE LISTAR (
        p_resultado OUT SYS_REFCURSOR
    );

    -- ========================================================
    -- OBTENER BANCO POR ID
    -- ========================================================

    PROCEDURE OBTENER (
        p_banco_id  IN NUMBER,
        p_resultado OUT SYS_REFCURSOR
    );

    -- ========================================================
    -- CREAR BANCO
    -- ========================================================

    PROCEDURE CREAR (
        p_codigo_banco IN VARCHAR2,
        p_nombre       IN VARCHAR2,
        p_bic_swift    IN VARCHAR2,
        p_creado_por   IN NUMBER,
        p_banco_id     OUT NUMBER
    );

    -- ========================================================
    -- ACTUALIZAR BANCO
    -- ========================================================

    PROCEDURE ACTUALIZAR (
        p_banco_id     IN NUMBER,
        p_codigo_banco IN VARCHAR2,
        p_nombre       IN VARCHAR2,
        p_bic_swift    IN VARCHAR2
    );

    -- ========================================================
    -- CAMBIAR ESTADO DEL BANCO
    -- ========================================================

    PROCEDURE CAMBIAR_ESTADO (
        p_banco_id IN NUMBER,
        p_estado   IN VARCHAR2
    );

END PKG_MB_BANCOS;
/

-- PACKAGE PKG_MB_CATALOGOS
CREATE OR REPLACE PACKAGE "PKG_MB_CATALOGOS" AS


    -- ========================================================
    -- LISTAR TODOS LOS CATÁLOGOS
    -- ========================================================

    PROCEDURE LISTAR(
        p_resultado OUT SYS_REFCURSOR
    );


    -- ========================================================
    -- OBTENER CATÁLOGO POR ID
    -- ========================================================

    PROCEDURE OBTENER(
        p_catalogo_id IN NUMBER,
        p_resultado   OUT SYS_REFCURSOR
    );


    -- ========================================================
    -- LISTAR CATÁLOGOS ACTIVOS POR GRUPO
    --
    -- Utilizado por componentes reutilizables como CatalogSelect.
    -- ========================================================

    PROCEDURE LISTAR_POR_GRUPO(
        p_grupo     IN VARCHAR2,
        p_resultado OUT SYS_REFCURSOR
    );


    -- ========================================================
    -- CREAR CATÁLOGO
    --
    -- catalogo_id NO se recibe desde frontend/backend.
    -- Oracle lo genera con MB_SEQ_CATALOGO_BANCARIO.
    -- ========================================================

    PROCEDURE CREAR(
        p_grupo                 IN VARCHAR2,
        p_codigo                IN VARCHAR2,
        p_nombre                IN VARCHAR2,
        p_descripcion           IN VARCHAR2,
        p_aplica_a              IN VARCHAR2,
        p_naturaleza            IN CHAR,
        p_requiere_comentario   IN CHAR,
        p_requiere_evidencia    IN CHAR,
        p_permite_reversion     IN CHAR,
        p_estado                IN VARCHAR2,
        p_catalogo_id           OUT NUMBER
    );


    -- ========================================================
    -- ACTUALIZAR CATÁLOGO
    --
    -- grupo, codigo y estado no se modifican aquí.
    -- El estado se administra mediante CAMBIAR_ESTADO.
    -- ========================================================

    PROCEDURE ACTUALIZAR(
        p_catalogo_id           IN NUMBER,
        p_nombre                IN VARCHAR2,
        p_descripcion           IN VARCHAR2,
        p_aplica_a              IN VARCHAR2,
        p_naturaleza            IN CHAR,
        p_requiere_comentario   IN CHAR,
        p_requiere_evidencia    IN CHAR,
        p_permite_reversion     IN CHAR
    );


    -- ========================================================
    -- ACTIVAR / INACTIVAR CATÁLOGO
    -- ========================================================

    PROCEDURE CAMBIAR_ESTADO(
        p_catalogo_id IN NUMBER,
        p_estado      IN VARCHAR2
    );


END PKG_MB_CATALOGOS;
/

