-- PACKAGE PKG_MB_FORMATOS_IMPORTACION
CREATE OR REPLACE PACKAGE "PKG_MB_FORMATOS_IMPORTACION" AS

    /* =========================================================
       FORMATOS DE IMPORTACION
       ========================================================= */

    PROCEDURE listar_formatos (
        p_resultado OUT SYS_REFCURSOR
    );

    PROCEDURE obtener_formato (
        p_formato_id IN NUMBER,
        p_resultado  OUT SYS_REFCURSOR
    );

    PROCEDURE crear_formato (
        p_banco_id           IN NUMBER,
        p_nombre             IN VARCHAR2,
        p_version            IN NUMBER,
        p_tipo_archivo       IN VARCHAR2,
        p_delimitador        IN VARCHAR2,
        p_formato_fecha      IN VARCHAR2,
        p_fila_encabezado    IN NUMBER,
        p_archivo_ejemplo_id IN NUMBER,
        p_estado             IN VARCHAR2,
        p_formato_id         OUT NUMBER
    );

    PROCEDURE actualizar_formato (
        p_formato_id         IN NUMBER,
        p_banco_id           IN NUMBER,
        p_nombre             IN VARCHAR2,
        p_version            IN NUMBER,
        p_tipo_archivo       IN VARCHAR2,
        p_delimitador        IN VARCHAR2,
        p_formato_fecha      IN VARCHAR2,
        p_fila_encabezado    IN NUMBER,
        p_archivo_ejemplo_id IN NUMBER
    );

    PROCEDURE cambiar_estado_formato (
        p_formato_id IN NUMBER,
        p_estado     IN VARCHAR2
    );


    /* =========================================================
       MAPEO DE COLUMNAS
       ========================================================= */

    PROCEDURE listar_mapeos (
        p_formato_id IN NUMBER,
        p_resultado  OUT SYS_REFCURSOR
    );

    PROCEDURE crear_mapeo (
        p_formato_id     IN NUMBER,
        p_campo_sistema  IN VARCHAR2,
        p_nombre_columna IN VARCHAR2,
        p_numero_columna IN NUMBER,
        p_es_obligatorio IN CHAR,
        p_formato_valor  IN VARCHAR2,
        p_mapeo_id       OUT NUMBER
    );

    PROCEDURE actualizar_mapeo (
        p_mapeo_id       IN NUMBER,
        p_campo_sistema  IN VARCHAR2,
        p_nombre_columna IN VARCHAR2,
        p_numero_columna IN NUMBER,
        p_es_obligatorio IN CHAR,
        p_formato_valor  IN VARCHAR2
    );

    PROCEDURE eliminar_mapeo (
        p_mapeo_id IN NUMBER
    );

END PKG_MB_FORMATOS_IMPORTACION;
/

