    p_doble_aprobacion IN MB_REGLA_APROBACION_BANCARIA.doble_aprobacion%TYPE,
    p_requiere_evidencia IN MB_REGLA_APROBACION_BANCARIA.requiere_evidencia%TYPE,
    p_permite_reprogramar IN MB_REGLA_APROBACION_BANCARIA.permite_reprogramar%TYPE,
    p_vigencia_desde IN MB_REGLA_APROBACION_BANCARIA.vigencia_desde%TYPE,
    p_vigencia_hasta IN MB_REGLA_APROBACION_BANCARIA.vigencia_hasta%TYPE,
    p_version IN MB_REGLA_APROBACION_BANCARIA.version%TYPE,
    p_estado IN MB_REGLA_APROBACION_BANCARIA.estado%TYPE,
