    p_empresa_id IN MB_REGLA_APROBACION_BANCARIA.empresa_id%TYPE,
    p_tipo_operacion_id IN MB_REGLA_APROBACION_BANCARIA.tipo_operacion_id%TYPE,
    p_moneda_id IN MB_REGLA_APROBACION_BANCARIA.moneda_id%TYPE,
    p_nombre IN MB_REGLA_APROBACION_BANCARIA.nombre%TYPE,
    p_monto_minimo IN MB_REGLA_APROBACION_BANCARIA.monto_minimo%TYPE,
    p_monto_maximo IN MB_REGLA_APROBACION_BANCARIA.monto_maximo%TYPE,
    p_cantidad_aprobaciones IN MB_REGLA_APROBACION_BANCARIA.cantidad_aprobaciones%TYPE,
    p_doble_aprobacion IN MB_REGLA_APROBACION_BANCARIA.doble_aprobacion%TYPE,
    p_requiere_evidencia IN MB_REGLA_APROBACION_BANCARIA.requiere_evidencia%TYPE,
    p_permite_reprogramar IN MB_REGLA_APROBACION_BANCARIA.permite_reprogramar%TYPE,
    p_vigencia_desde IN MB_REGLA_APROBACION_BANCARIA.vigencia_desde%TYPE,
    p_vigencia_hasta IN MB_REGLA_APROBACION_BANCARIA.vigencia_hasta%TYPE,
    p_version IN MB_REGLA_APROBACION_BANCARIA.version%TYPE,
    p_estado IN MB_REGLA_APROBACION_BANCARIA.estado%TYPE);

  PROCEDURE CAMBIAR_ESTADO(p_id IN MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE, p_estado IN MB_REGLA_APROBACION_BANCARIA.estado%TYPE);

  PROCEDURE DESACTIVAR(p_id IN MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE);

  PROCEDURE RESOLVER_APLICABLE(p_empresa_id IN NUMBER, p_tipo_operacion_id IN NUMBER, p_moneda_id IN NUMBER, p_monto IN NUMBER, p_fecha IN DATE, p_resultado OUT SYS_REFCURSOR);

  PROCEDURE LISTAR_TIPOS(p_resultado OUT SYS_REFCURSOR);
  -- Returns NULL when no active configuration applies.
  FUNCTION OBTENER_ID_APLICABLE(p_empresa_id IN NUMBER, p_tipo_operacion_id IN NUMBER, p_moneda_id IN NUMBER, p_monto IN NUMBER, p_fecha IN DATE) RETURN MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE;
END PKG_MB_REGLAS_APROBACION;
/

PROMPT === PACKAGE_BODY ===

-- PACKAGE_BODY MB_CONCILIACION
CREATE OR REPLACE PACKAGE BODY "MB_CONCILIACION" AS

    ------------------------------------------------------------------
    -- INICIAR CONCILIACION
    ------------------------------------------------------------------
    PROCEDURE INICIAR_CONCILIACION (
        p_estado_cuenta_id IN MB_CONCILIACION_BANCARIA.estado_cuenta_id%TYPE,
        p_saldo_bancario   IN MB_CONCILIACION_BANCARIA.saldo_bancario%TYPE,
        p_saldo_interno    IN MB_CONCILIACION_BANCARIA.saldo_interno%TYPE,
        p_conciliacion_id  OUT MB_CONCILIACION_BANCARIA.conciliacion_id%TYPE
    ) IS
        v_existe NUMBER;
    BEGIN
        IF p_estado_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20100,
                'El estado de cuenta es obligatorio.'
            );
        END IF;

        IF p_saldo_bancario IS NULL OR p_saldo_interno IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20101,
                'Los saldos bancario e interno son obligatorios.'
            );
        END IF;

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_ESTADO_CUENTA
         WHERE estado_cuenta_id = p_estado_cuenta_id
           AND estado IN ('VALIDADO', 'CON_ERRORES');

        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20102,
                'El estado de cuenta no existe o no puede conciliarse.'
            );
        END IF;

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_CONCILIACION_BANCARIA
         WHERE estado_cuenta_id = p_estado_cuenta_id;

        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20103,
                'El estado de cuenta ya posee una conciliacion.'
            );
        END IF;

        p_conciliacion_id := SEQ_MB_CONCILIACION.NEXTVAL;

        INSERT INTO MB_CONCILIACION_BANCARIA (
            conciliacion_id,
            estado_cuenta_id,
            fecha_inicio,
            fecha_cierre,
            saldo_bancario,
            saldo_interno,
            observacion_final,
            estado,
            cerrado_por
        ) VALUES (
            p_conciliacion_id,
            p_estado_cuenta_id,
            SYSTIMESTAMP,
            NULL,
            p_saldo_bancario,
            p_saldo_interno,
            NULL,
            'ABIERTA',
            NULL
        );

    END INICIAR_CONCILIACION;


    ------------------------------------------------------------------
    -- GENERAR SUGERENCIAS AUTOMATICAS
    --
    -- Primera versión:
    --  * solo líneas VALIDAS
    --  * solo movimientos APLICADO + PENDIENTE
    --  * misma cuenta
    --  * tolerancia de fecha y monto según parámetros
    --  * referencia/concepto según configuración
    --  * si existe exactamente un candidato -> SUGERIDA
    --  * si existen varios candidatos -> no se sugiere automáticamente
    ------------------------------------------------------------------
    PROCEDURE GENERAR_SUGERENCIAS (
        p_conciliacion_id IN MB_CONCILIACION_BANCARIA.conciliacion_id%TYPE
    ) IS
        v_estado_cuenta_id MB_CONCILIACION_BANCARIA.estado_cuenta_id%TYPE;
        v_cuenta_id        MB_ESTADO_CUENTA.cuenta_id%TYPE;
        v_banco_id         MB_CUENTA_BANCARIA.banco_id%TYPE;

        v_tolerancia_dias  MB_PARAMETRO_CONCILIACION.tolerancia_dias%TYPE;
        v_tolerancia_monto MB_PARAMETRO_CONCILIACION.tolerancia_monto%TYPE;
        v_ref              MB_PARAMETRO_CONCILIACION.coincide_referencia%TYPE;
        v_concepto         MB_PARAMETRO_CONCILIACION.coincide_concepto%TYPE;

        v_candidatos       NUMBER;
        v_movimiento_id    MB_MOVIMIENTO_BANCARIO.movimiento_id%TYPE;
        v_monto            MB_MOVIMIENTO_BANCARIO.monto%TYPE;
        v_porcentaje       NUMBER;
        v_parametros       NUMBER;
    BEGIN
        ------------------------------------------------------------------
        -- Obtener conciliación y cuenta
        ------------------------------------------------------------------
        BEGIN
            SELECT
                cb.estado_cuenta_id,
                ec.cuenta_id,
                c.banco_id
            INTO
                v_estado_cuenta_id,
                v_cuenta_id,
                v_banco_id
            FROM MB_CONCILIACION_BANCARIA cb
            JOIN MB_ESTADO_CUENTA ec
              ON ec.estado_cuenta_id = cb.estado_cuenta_id
            JOIN MB_CUENTA_BANCARIA c
              ON c.cuenta_id = ec.cuenta_id
            WHERE cb.conciliacion_id = p_conciliacion_id
              AND cb.estado IN ('ABIERTA', 'EN_PROCESO', 'REABIERTA');
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20104,
                    'La conciliacion no existe o no admite procesamiento.'
                );
        END;

        ------------------------------------------------------------------
        -- Buscar política específica de cuenta.
        -- Si no existe, usar política general del banco.
        ------------------------------------------------------------------
        SELECT COUNT(*)
          INTO v_parametros
          FROM MB_PARAMETRO_CONCILIACION
         WHERE cuenta_id = v_cuenta_id
           AND estado = 'ACTIVO';

        IF v_parametros > 0 THEN

            SELECT
                tolerancia_dias,
                tolerancia_monto,
                coincide_referencia,
                coincide_concepto
            INTO
                v_tolerancia_dias,
                v_tolerancia_monto,
                v_ref,
                v_concepto
            FROM MB_PARAMETRO_CONCILIACION
            WHERE cuenta_id = v_cuenta_id
              AND estado = 'ACTIVO'
              AND ROWNUM = 1;

        ELSE

            BEGIN
                SELECT
                    tolerancia_dias,
                    tolerancia_monto,
                    coincide_referencia,
                    coincide_concepto
                INTO
                    v_tolerancia_dias,
                    v_tolerancia_monto,
                    v_ref,
                    v_concepto
                FROM MB_PARAMETRO_CONCILIACION
                WHERE banco_id = v_banco_id
                  AND cuenta_id IS NULL
                  AND estado = 'ACTIVO'
                  AND ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    RAISE_APPLICATION_ERROR(
                        -20105,
                        'No existe una politica activa de conciliacion.'
                    );
            END;

        END IF;

        ------------------------------------------------------------------
        -- Procesar cada línea bancaria válida que aún no tenga detalle.
        ------------------------------------------------------------------
        FOR r_linea IN (
            SELECT
                le.linea_estado_id,
                le.fecha_bancaria,
                le.referencia,
                le.descripcion,
                le.monto
            FROM MB_LINEA_ESTADO_CUENTA le
            WHERE le.estado_cuenta_id = v_estado_cuenta_id
              AND le.estado_validacion = 'VALIDA'
              AND NOT EXISTS (
                    SELECT 1
                    FROM MB_DETALLE_CONCILIACION dc
                    WHERE dc.linea_estado_id = le.linea_estado_id
                      AND dc.estado IN ('SUGERIDA', 'CONFIRMADA')
              )
            ORDER BY le.numero_linea
        ) LOOP

            v_candidatos    := 0;
            v_movimiento_id := NULL;
            v_monto         := NULL;

            ------------------------------------------------------------------
            -- Contar candidatos.
            ------------------------------------------------------------------
            SELECT COUNT(*)
              INTO v_candidatos
              FROM MB_MOVIMIENTO_BANCARIO mb
             WHERE mb.cuenta_id = v_cuenta_id
               AND mb.estado = 'APLICADO'
               AND mb.estado_conciliacion = 'PENDIENTE'
               AND ABS(
                    TRUNC(mb.fecha_operacion)
                    - TRUNC(r_linea.fecha_bancaria)
               ) <= NVL(v_tolerancia_dias, 0)
               AND ABS(mb.monto - r_linea.monto)
                    <= NVL(v_tolerancia_monto, 0)
               AND (
                    NVL(v_ref, 'N') <> 'S'
                    OR UPPER(TRIM(NVL(mb.referencia_bancaria, '#')))
                       = UPPER(TRIM(NVL(r_linea.referencia, '#')))
               )
               AND (
                    NVL(v_concepto, 'N') <> 'S'
                    OR UPPER(TRIM(NVL(mb.concepto, '#')))
                       = UPPER(TRIM(NVL(r_linea.descripcion, '#')))
               )
               AND NOT EXISTS (
                    SELECT 1
                    FROM MB_DETALLE_CONCILIACION dc
                    WHERE dc.movimiento_id = mb.movimiento_id
                      AND dc.estado IN ('SUGERIDA', 'CONFIRMADA')
               );

            ------------------------------------------------------------------
            -- Solo una coincidencia: generar sugerencia.
            ------------------------------------------------------------------
            IF v_candidatos = 1 THEN

                SELECT
                    mb.movimiento_id,
                    mb.monto
                INTO
                    v_movimiento_id,
                    v_monto
                FROM MB_MOVIMIENTO_BANCARIO mb
                WHERE mb.cuenta_id = v_cuenta_id
                  AND mb.estado = 'APLICADO'
                  AND mb.estado_conciliacion = 'PENDIENTE'
                  AND ABS(
                        TRUNC(mb.fecha_operacion)
                        - TRUNC(r_linea.fecha_bancaria)
                  ) <= NVL(v_tolerancia_dias, 0)
                  AND ABS(mb.monto - r_linea.monto)
                        <= NVL(v_tolerancia_monto, 0)
                  AND (
                        NVL(v_ref, 'N') <> 'S'
                        OR UPPER(TRIM(NVL(mb.referencia_bancaria, '#')))
                           = UPPER(TRIM(NVL(r_linea.referencia, '#')))
                  )
                  AND (
                        NVL(v_concepto, 'N') <> 'S'
                        OR UPPER(TRIM(NVL(mb.concepto, '#')))
                           = UPPER(TRIM(NVL(r_linea.descripcion, '#')))
                  )
                  AND NOT EXISTS (
                        SELECT 1
                        FROM MB_DETALLE_CONCILIACION dc
                        WHERE dc.movimiento_id = mb.movimiento_id
                          AND dc.estado IN ('SUGERIDA', 'CONFIRMADA')
                  );

                ------------------------------------------------------------------
                -- El match que supera todos los criterios configurados
                -- se considera coincidencia completa.
                ------------------------------------------------------------------
                v_porcentaje := 100;

                INSERT INTO MB_DETALLE_CONCILIACION (
                    detalle_conciliacion_id,
                    conciliacion_id,
                    movimiento_id,
                    linea_estado_id,
                    monto_conciliado,
                    tipo_relacion,
                    porcentaje_coincidencia,
                    estado,
                    comentario,
                    confirmado_por,
                    confirmado_en
                ) VALUES (
                    SEQ_MB_DETALLE_CONCILIACION.NEXTVAL,
                    p_conciliacion_id,
                    v_movimiento_id,
                    r_linea.linea_estado_id,
                    LEAST(v_monto, r_linea.monto),
                    'UNO_UNO',
                    v_porcentaje,
                    'SUGERIDA',
                    'Coincidencia automatica generada por politica de conciliacion.',
                    NULL,
                    NULL
                );

            END IF;

        END LOOP;

        UPDATE MB_CONCILIACION_BANCARIA
           SET estado = 'EN_PROCESO'
         WHERE conciliacion_id = p_conciliacion_id
           AND estado IN ('ABIERTA', 'REABIERTA');

    END GENERAR_SUGERENCIAS;


    ------------------------------------------------------------------
    -- CONFIRMAR SUGERENCIA
    ------------------------------------------------------------------
    PROCEDURE CONFIRMAR_SUGERENCIA (
        p_detalle_conciliacion_id
            IN MB_DETALLE_CONCILIACION.detalle_conciliacion_id%TYPE,
        p_confirmado_por
            IN MB_DETALLE_CONCILIACION.confirmado_por%TYPE,
        p_comentario
            IN MB_DETALLE_CONCILIACION.comentario%TYPE
    ) IS
        v_movimiento_id MB_DETALLE_CONCILIACION.movimiento_id%TYPE;
    BEGIN
        IF p_confirmado_por IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20106,
                'El usuario que confirma es obligatorio.'
            );
        END IF;

        BEGIN
            SELECT movimiento_id
              INTO v_movimiento_id
              FROM MB_DETALLE_CONCILIACION
             WHERE detalle_conciliacion_id = p_detalle_conciliacion_id
               AND estado = 'SUGERIDA'
             FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20107,
                    'La sugerencia no existe o ya fue procesada.'
                );
        END;

        UPDATE MB_DETALLE_CONCILIACION
           SET estado         = 'CONFIRMADA',
               comentario     = NVL(p_comentario, comentario),
               confirmado_por = p_confirmado_por,
               confirmado_en  = SYSTIMESTAMP
         WHERE detalle_conciliacion_id = p_detalle_conciliacion_id;

        UPDATE MB_MOVIMIENTO_BANCARIO
           SET estado_conciliacion = 'CONCILIADO'
         WHERE movimiento_id = v_movimiento_id;

    END CONFIRMAR_SUGERENCIA;


    ------------------------------------------------------------------
    -- RECHAZAR SUGERENCIA
    ------------------------------------------------------------------
    PROCEDURE RECHAZAR_SUGERENCIA (
        p_detalle_conciliacion_id
            IN MB_DETALLE_CONCILIACION.detalle_conciliacion_id%TYPE,
        p_confirmado_por
            IN MB_DETALLE_CONCILIACION.confirmado_por%TYPE,
        p_comentario
            IN MB_DETALLE_CONCILIACION.comentario%TYPE
    ) IS
        v_movimiento_id MB_DETALLE_CONCILIACION.movimiento_id%TYPE;
    BEGIN
        IF p_confirmado_por IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20108,
                'El usuario que rechaza es obligatorio.'
            );
        END IF;

        BEGIN
            SELECT movimiento_id
              INTO v_movimiento_id
              FROM MB_DETALLE_CONCILIACION
             WHERE detalle_conciliacion_id = p_detalle_conciliacion_id
               AND estado = 'SUGERIDA'
             FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20109,
                    'La sugerencia no existe o ya fue procesada.'
                );
        END;

        UPDATE MB_DETALLE_CONCILIACION
           SET estado         = 'RECHAZADA',
               comentario     = NVL(
                                    p_comentario,
                                    'Sugerencia rechazada manualmente.'
                                ),
               confirmado_por = p_confirmado_por,
               confirmado_en  = SYSTIMESTAMP
         WHERE detalle_conciliacion_id = p_detalle_conciliacion_id;

        UPDATE MB_MOVIMIENTO_BANCARIO
           SET estado_conciliacion = 'PENDIENTE'
         WHERE movimiento_id = v_movimiento_id;

    END RECHAZAR_SUGERENCIA;


    ------------------------------------------------------------------
    -- OBTENER CONCILIACION
    ------------------------------------------------------------------
    PROCEDURE OBTENER_CONCILIACION (
        p_conciliacion_id
            IN MB_CONCILIACION_BANCARIA.conciliacion_id%TYPE,
        p_resultado OUT SYS_REFCURSOR
    ) IS
    BEGIN
        OPEN p_resultado FOR
            SELECT
                cb.conciliacion_id,
                cb.estado_cuenta_id,
                ec.cuenta_id,
                cb.fecha_inicio,
                cb.fecha_cierre,
                cb.saldo_bancario,
                cb.saldo_interno,
                cb.saldo_bancario - cb.saldo_interno AS diferencia_saldos,
                cb.observacion_final,
                cb.estado,
                cb.cerrado_por
            FROM MB_CONCILIACION_BANCARIA cb
            JOIN MB_ESTADO_CUENTA ec
              ON ec.estado_cuenta_id = cb.estado_cuenta_id
            WHERE cb.conciliacion_id = p_conciliacion_id;

    END OBTENER_CONCILIACION;


    ------------------------------------------------------------------
    -- LISTAR SUGERENCIAS
    ------------------------------------------------------------------
    PROCEDURE LISTAR_SUGERENCIAS (
        p_conciliacion_id
            IN MB_CONCILIACION_BANCARIA.conciliacion_id%TYPE,
        p_resultado OUT SYS_REFCURSOR
    ) IS
    BEGIN
        OPEN p_resultado FOR
            SELECT
                dc.detalle_conciliacion_id,
                dc.conciliacion_id,
                dc.movimiento_id,
                dc.linea_estado_id,
                le.fecha_bancaria,
                le.referencia AS referencia_bancaria,
                le.descripcion AS descripcion_bancaria,
                le.monto AS monto_bancario,
                mb.fecha_operacion,
                mb.referencia_bancaria AS referencia_interna,
                mb.concepto AS concepto_interno,
                mb.monto AS monto_interno,
                dc.monto_conciliado,
                dc.tipo_relacion,
                dc.porcentaje_coincidencia,
                dc.estado,
                dc.comentario,
                dc.confirmado_por,
                dc.confirmado_en
            FROM MB_DETALLE_CONCILIACION dc
            JOIN MB_LINEA_ESTADO_CUENTA le
              ON le.linea_estado_id = dc.linea_estado_id
            JOIN MB_MOVIMIENTO_BANCARIO mb
              ON mb.movimiento_id = dc.movimiento_id
            WHERE dc.conciliacion_id = p_conciliacion_id
            ORDER BY dc.detalle_conciliacion_id;

    END LISTAR_SUGERENCIAS;


    ------------------------------------------------------------------
    -- LISTAR PENDIENTES
    --
    -- Devuelve las líneas válidas que todavía no tienen una
    -- conciliación confirmada o sugerida.
    ------------------------------------------------------------------
    PROCEDURE LISTAR_PENDIENTES (
        p_conciliacion_id
            IN MB_CONCILIACION_BANCARIA.conciliacion_id%TYPE,
        p_resultado OUT SYS_REFCURSOR
    ) IS
    BEGIN
        OPEN p_resultado FOR
            SELECT
                le.linea_estado_id,
                le.numero_linea,
                le.fecha_bancaria,
                le.referencia,
                le.descripcion,
                le.naturaleza,
                le.monto,
                le.estado_validacion
            FROM MB_CONCILIACION_BANCARIA cb
            JOIN MB_LINEA_ESTADO_CUENTA le
              ON le.estado_cuenta_id = cb.estado_cuenta_id
            WHERE cb.conciliacion_id = p_conciliacion_id
              AND le.estado_validacion = 'VALIDA'
              AND NOT EXISTS (
                    SELECT 1
                    FROM MB_DETALLE_CONCILIACION dc
                    WHERE dc.conciliacion_id = cb.conciliacion_id
                      AND dc.linea_estado_id = le.linea_estado_id
                      AND dc.estado IN ('SUGERIDA', 'CONFIRMADA')
              )
            ORDER BY le.numero_linea;

    END LISTAR_PENDIENTES;


    ------------------------------------------------------------------
    -- CERRAR CONCILIACION
    ------------------------------------------------------------------
    PROCEDURE CERRAR_CONCILIACION (
        p_conciliacion_id
            IN MB_CONCILIACION_BANCARIA.conciliacion_id%TYPE,
        p_cerrado_por
            IN MB_CONCILIACION_BANCARIA.cerrado_por%TYPE,
        p_observacion_final
            IN MB_CONCILIACION_BANCARIA.observacion_final%TYPE
    ) IS
        v_pendientes NUMBER;
        v_sugeridas  NUMBER;
    BEGIN
        IF p_cerrado_por IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20110,
                'El usuario de cierre es obligatorio.'
            );
        END IF;

        SELECT COUNT(*)
          INTO v_pendientes
          FROM MB_CONCILIACION_BANCARIA cb
          JOIN MB_LINEA_ESTADO_CUENTA le
            ON le.estado_cuenta_id = cb.estado_cuenta_id
         WHERE cb.conciliacion_id = p_conciliacion_id
           AND le.estado_validacion = 'VALIDA'
           AND NOT EXISTS (
                SELECT 1
                FROM MB_DETALLE_CONCILIACION dc
                WHERE dc.conciliacion_id = cb.conciliacion_id
                  AND dc.linea_estado_id = le.linea_estado_id
                  AND dc.estado = 'CONFIRMADA'
           );

        SELECT COUNT(*)
          INTO v_sugeridas
          FROM MB_DETALLE_CONCILIACION
         WHERE conciliacion_id = p_conciliacion_id
           AND estado = 'SUGERIDA';

        IF v_pendientes > 0 OR v_sugeridas > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20111,
                'No se puede cerrar la conciliacion mientras existan partidas pendientes.'
            );
        END IF;

        UPDATE MB_CONCILIACION_BANCARIA
           SET estado            = 'CERRADA',
               fecha_cierre      = SYSTIMESTAMP,
               cerrado_por       = p_cerrado_por,
               observacion_final = p_observacion_final
         WHERE conciliacion_id = p_conciliacion_id
           AND estado IN ('ABIERTA', 'EN_PROCESO', 'REABIERTA');

        IF SQL%ROWCOUNT = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20112,
                'La conciliacion no existe o no puede cerrarse.'
            );
        END IF;

    END CERRAR_CONCILIACION;

END MB_CONCILIACION;
/

-- PACKAGE_BODY MB_FONDOS
CREATE OR REPLACE PACKAGE BODY "MB_FONDOS" AS

    /*
      Sprint 2 - Bancos
      Proceso 1: Cuentas y disponibilidad

      Reglas centrales:

        saldo interno =
            saldo inicial
            + creditos APLICADOS
            - debitos APLICADOS

        disponibilidad =
            saldo interno
            - compromisos ACTIVO

      Principios:

        - Una sola fuente de verdad para disponibilidad.
        - Reserva protegida por bloqueo de cuenta.
        - Idempotencia para evitar doble afectacion.
        - No se realizan COMMIT ni ROLLBACK.
        - La transaccion pertenece al consumidor.
    */


    ------------------------------------------------------------------
    -- Codigos de error propios del package.
    ------------------------------------------------------------------
    C_ERR_CUENTA_REQUERIDA         CONSTANT PLS_INTEGER := -20101;
    C_ERR_CUENTA_NO_EXISTE         CONSTANT PLS_INTEGER := -20102;
    C_ERR_CUENTA_NO_ACTIVA         CONSTANT PLS_INTEGER := -20103;
    C_ERR_CUENTA_NO_PAGOS          CONSTANT PLS_INTEGER := -20104;
    C_ERR_FECHAS_INVALIDAS         CONSTANT PLS_INTEGER := -20105;
    C_ERR_MONTO_INVALIDO           CONSTANT PLS_INTEGER := -20106;
    C_ERR_OPERACION_REQUERIDA      CONSTANT PLS_INTEGER := -20107;
    C_ERR_OPERACION_NO_EXISTE      CONSTANT PLS_INTEGER := -20108;
    C_ERR_CUENTA_OPERACION         CONSTANT PLS_INTEGER := -20109;
    C_ERR_FONDOS_INSUFICIENTES     CONSTANT PLS_INTEGER := -20110;
    C_ERR_RESERVA_DUPLICADA        CONSTANT PLS_INTEGER := -20111;
    C_ERR_COMPROMISO_REQUERIDO     CONSTANT PLS_INTEGER := -20112;
    C_ERR_COMPROMISO_NO_EXISTE     CONSTANT PLS_INTEGER := -20113;
    C_ERR_ESTADO_COMPROMISO        CONSTANT PLS_INTEGER := -20114;
    C_ERR_RESERVA_CERRADA          CONSTANT PLS_INTEGER := -20115;
    C_ERR_RESERVA_INCONSISTENTE    CONSTANT PLS_INTEGER := -20116;


    ------------------------------------------------------------------
    -- Verifica que una cuenta exista.
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_CUENTA_EXISTE (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE
    ) AS

        v_total PLS_INTEGER;

    BEGIN

        IF p_cuenta_id IS NULL THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_CUENTA_REQUERIDA,
                'Debe indicar la cuenta bancaria.'
            );

        END IF;


        SELECT COUNT(*)
          INTO v_total
          FROM MB_CUENTA_BANCARIA
         WHERE cuenta_id = p_cuenta_id;


        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_CUENTA_NO_EXISTE,
                'La cuenta bancaria indicada no existe.'
            );

        END IF;

    END VALIDAR_CUENTA_EXISTE;


    ------------------------------------------------------------------
    -- Valida un rango de fechas.
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_RANGO_FECHAS (
        p_fecha_desde IN DATE,
        p_fecha_hasta IN DATE
    ) AS

    BEGIN

        IF p_fecha_desde IS NOT NULL
           AND p_fecha_hasta IS NOT NULL
           AND TRUNC(p_fecha_desde) > TRUNC(p_fecha_hasta) THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_FECHAS_INVALIDAS,
                'La fecha desde no puede ser posterior a la fecha hasta.'
            );

        END IF;

    END VALIDAR_RANGO_FECHAS;


    ------------------------------------------------------------------
    -- Calcula el saldo interno hasta una fecha de corte.
    --
    -- Si p_fecha_corte es NULL:
    --   toma todos los movimientos actualmente APLICADOS.
    --
    -- Solo afectan saldo:
    --   NATURALEZA C = suma
    --   NATURALEZA D = resta
    ------------------------------------------------------------------
    FUNCTION CALCULAR_SALDO_INTERNO (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,

        p_fecha_corte
            IN DATE
    )
    RETURN NUMBER AS

        v_saldo
            MB_CUENTA_BANCARIA.saldo_inicial%TYPE;

    BEGIN

        VALIDAR_CUENTA_EXISTE(
            p_cuenta_id
        );


        SELECT
            c.saldo_inicial
            +
            NVL(
                SUM(
                    CASE
                        WHEN cat.naturaleza = 'C'
                            THEN m.monto

                        WHEN cat.naturaleza = 'D'
                            THEN -m.monto

                        ELSE 0
                    END
                ),
                0
            )

        INTO
            v_saldo

        FROM
            MB_CUENTA_BANCARIA c

        LEFT JOIN
            MB_MOVIMIENTO_BANCARIO m

               ON m.cuenta_id =
                  c.cuenta_id

              AND m.estado =
                  'APLICADO'

              AND (
                    p_fecha_corte IS NULL
                    OR
                    m.fecha_operacion
                        < TRUNC(p_fecha_corte) + 1
                  )

        LEFT JOIN
            MB_CATALOGO_BANCARIO cat

               ON cat.catalogo_id =
                  m.tipo_movimiento_id

              AND cat.grupo =
                  'TIPO_MOVIMIENTO'

        WHERE
            c.cuenta_id =
            p_cuenta_id

        GROUP BY
            c.saldo_inicial;


        RETURN ROUND(
            v_saldo,
            2
        );

    END CALCULAR_SALDO_INTERNO;


    ------------------------------------------------------------------
    -- Disponibilidad operativa actual.
    --
    -- No depende de los filtros visuales del periodo.
    ------------------------------------------------------------------
    FUNCTION CALCULAR_DISPONIBILIDAD (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE
    )
    RETURN NUMBER AS

        v_saldo_interno
            NUMBER(18,2);

        v_comprometido
            NUMBER(18,2);

    BEGIN

        /*
          CALCULAR_SALDO_INTERNO ya valida
          la existencia de la cuenta.
        */
        v_saldo_interno :=
            CALCULAR_SALDO_INTERNO(
                p_cuenta_id,
                NULL
            );


        SELECT
            NVL(
                SUM(monto),
                0
            )

        INTO
            v_comprometido

        FROM
            MB_FONDO_COMPROMETIDO

        WHERE
            cuenta_id =
            p_cuenta_id

        AND estado =
            'ACTIVO';


        RETURN ROUND(
            v_saldo_interno
            - v_comprometido,
            2
        );

    END CALCULAR_DISPONIBILIDAD;


    ------------------------------------------------------------------
    -- Resumen financiero de una cuenta.
    --
    -- El periodo afecta:
    --   saldo de apertura
    --   creditos del periodo
    --   debitos del periodo
    --
    -- No altera:
    --   saldo interno operativo
    --   fondos comprometidos actuales
    --   disponibilidad actual
    ------------------------------------------------------------------
    PROCEDURE OBTENER_RESUMEN (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,

        p_fecha_desde
            IN DATE DEFAULT NULL,

        p_fecha_hasta
            IN DATE DEFAULT NULL,

        p_resultado
            OUT SYS_REFCURSOR
    ) AS

        v_fecha_hasta
            DATE;

        v_saldo_apertura
            NUMBER(18,2);

        v_creditos
            NUMBER(18,2);

        v_debitos
            NUMBER(18,2);

        v_saldo_interno
            NUMBER(18,2);

        v_comprometido
            NUMBER(18,2);

        v_disponible
            NUMBER(18,2);

        v_saldo_bancario
            NUMBER(18,2);

        v_fecha_saldo_banco
            DATE;

    BEGIN

        VALIDAR_CUENTA_EXISTE(
            p_cuenta_id
        );


        /*
          Si el consumidor no manda fecha final,
          el periodo visible termina hoy.
        */
        v_fecha_hasta :=
            NVL(
                TRUNC(p_fecha_hasta),
                TRUNC(SYSDATE)
            );


        /*
          Se valida contra la fecha efectiva,
          no solamente contra el parametro recibido.
        */
        VALIDAR_RANGO_FECHAS(
            p_fecha_desde,
            v_fecha_hasta
        );


        --------------------------------------------------------------
        -- Saldo de apertura del periodo.
        --
        -- Si no existe fecha inicial:
        --   saldo_apertura = saldo_inicial.
        --
        -- Si existe:
        --   saldo_apertura =
        --       saldo inicial
        --       + movimientos aplicados anteriores.
        --------------------------------------------------------------
        SELECT
            c.saldo_inicial
            +
            NVL(
                SUM(
                    CASE

                        WHEN cat.naturaleza = 'C'
                            THEN m.monto

                        WHEN cat.naturaleza = 'D'
                            THEN -m.monto

                        ELSE 0

                    END
                ),
                0
            )

        INTO
            v_saldo_apertura

        FROM
            MB_CUENTA_BANCARIA c

        LEFT JOIN
            MB_MOVIMIENTO_BANCARIO m

               ON m.cuenta_id =
                  c.cuenta_id

              AND m.estado =
                  'APLICADO'

              AND p_fecha_desde
                  IS NOT NULL

              AND m.fecha_operacion
                  < TRUNC(p_fecha_desde)

        LEFT JOIN
            MB_CATALOGO_BANCARIO cat

               ON cat.catalogo_id =
                  m.tipo_movimiento_id

              AND cat.grupo =
                  'TIPO_MOVIMIENTO'

        WHERE
            c.cuenta_id =
            p_cuenta_id

        GROUP BY
            c.saldo_inicial;


        --------------------------------------------------------------
        -- Creditos y debitos APLICADOS del periodo solicitado.
        --------------------------------------------------------------
        SELECT

            NVL(
                SUM(
                    CASE

                        WHEN cat.naturaleza = 'C'
                            THEN m.monto

                        ELSE 0

                    END
                ),
                0
            ),

            NVL(
                SUM(
                    CASE

                        WHEN cat.naturaleza = 'D'
                            THEN m.monto

                        ELSE 0

                    END
                ),
                0
            )

        INTO
            v_creditos,
            v_debitos

        FROM
            MB_MOVIMIENTO_BANCARIO m

        INNER JOIN
            MB_CATALOGO_BANCARIO cat

                ON cat.catalogo_id =
                   m.tipo_movimiento_id

               AND cat.grupo =
                   'TIPO_MOVIMIENTO'

        WHERE
            m.cuenta_id =
            p_cuenta_id

        AND m.estado =
            'APLICADO'

        AND (
                p_fecha_desde IS NULL
                OR
                m.fecha_operacion
                    >= TRUNC(p_fecha_desde)
            )

        AND m.fecha_operacion
            < TRUNC(v_fecha_hasta) + 1;


        --------------------------------------------------------------
        -- Posicion operativa actual.
        --
        -- No se limita por el periodo visual.
        --------------------------------------------------------------
        v_saldo_interno :=
            CALCULAR_SALDO_INTERNO(
                p_cuenta_id,
                NULL
            );


        --------------------------------------------------------------
        -- Compromisos activos actuales.
        --------------------------------------------------------------
        SELECT
            NVL(
                SUM(monto),
                0
            )

        INTO
            v_comprometido

        FROM
            MB_FONDO_COMPROMETIDO

        WHERE
            cuenta_id =
            p_cuenta_id

        AND estado =
            'ACTIVO';


        --------------------------------------------------------------
        -- Una sola fuente de verdad para disponibilidad.
        --------------------------------------------------------------
        v_disponible :=
            CALCULAR_DISPONIBILIDAD(
                p_cuenta_id
            );


        --------------------------------------------------------------
        -- Ultimo saldo bancario disponible.
        --
        -- Se mantiene separado del saldo interno.
        --
        -- No se inventan estados validos de MB_ESTADO_CUENTA:
        -- se toma el ultimo estado de cuenta registrado por periodo.
        --------------------------------------------------------------
        BEGIN

            SELECT
                saldo_final,
                periodo_hasta

            INTO
                v_saldo_bancario,
                v_fecha_saldo_banco

            FROM (
                SELECT
                    ec.saldo_final,
                    ec.periodo_hasta

                FROM
                    MB_ESTADO_CUENTA ec

                WHERE
                    ec.cuenta_id =
                    p_cuenta_id

                ORDER BY
                    ec.periodo_hasta DESC,
                    ec.estado_cuenta_id DESC
            )

            WHERE
                ROWNUM = 1;


        EXCEPTION

            WHEN NO_DATA_FOUND THEN

                v_saldo_bancario :=
                    NULL;

                v_fecha_saldo_banco :=
                    NULL;

        END;


        --------------------------------------------------------------
        -- Resultado del resumen.
        --------------------------------------------------------------
        OPEN p_resultado FOR

            SELECT

                c.cuenta_id,

                c.codigo_cuenta,

                c.numero_cuenta,

                c.nombre_interno,


                c.empresa_id,

                c.banco_id,

                b.codigo_banco,

                b.nombre
                    AS banco_nombre,


                c.moneda_id,

                c.tipo_cuenta_id,


                c.uso_principal,

                c.permite_cobros,

                c.permite_pagos,

                c.permite_cheques,

                c.permite_transferencias,


                c.estado,


                p_fecha_desde
                    AS fecha_desde,

                v_fecha_hasta
                    AS fecha_hasta,


                ROUND(
                    v_saldo_apertura,
                    2
                )
                    AS saldo_apertura,


                ROUND(
                    v_creditos,
                    2
                )
                    AS creditos_periodo,


                ROUND(
                    v_debitos,
                    2
                )
                    AS debitos_periodo,


                ROUND(
                    v_saldo_interno,
                    2
                )
                    AS saldo_interno,


                ROUND(
                    v_comprometido,
                    2
                )
                    AS fondos_comprometidos,


                ROUND(
                    v_disponible,
                    2
                )
                    AS disponible,


                v_saldo_bancario
                    AS ultimo_saldo_bancario,


                v_fecha_saldo_banco
                    AS fecha_saldo_bancario


            FROM
                MB_CUENTA_BANCARIA c

            INNER JOIN
                MB_BANCO b

                    ON b.banco_id =
                       c.banco_id

            WHERE
                c.cuenta_id =
                p_cuenta_id;


    END OBTENER_RESUMEN;


    ------------------------------------------------------------------
    -- Movimientos por cuenta y periodo.
    --
    -- Si fechaHasta es NULL:
    --   utiliza la fecha actual.
    --
    -- Se muestran todos los estados de movimiento para que la UI
    -- pueda diferenciar REGISTRADO/APLICADO/REVERSADO.
    --
    -- Solo los APLICADOS afectan los totales del resumen.
    ------------------------------------------------------------------
    PROCEDURE LISTAR_MOVIMIENTOS (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,

        p_fecha_desde
            IN DATE DEFAULT NULL,

        p_fecha_hasta
            IN DATE DEFAULT NULL,

        p_resultado
            OUT SYS_REFCURSOR
    ) AS

        v_fecha_hasta
            DATE;

    BEGIN

        VALIDAR_CUENTA_EXISTE(
            p_cuenta_id
        );


        v_fecha_hasta :=
            NVL(
                TRUNC(p_fecha_hasta),
                TRUNC(SYSDATE)
            );


        VALIDAR_RANGO_FECHAS(
            p_fecha_desde,
            v_fecha_hasta
        );


        OPEN p_resultado FOR

            SELECT

                TO_CHAR(
                    m.movimiento_id
                )
                    AS movimiento_id,


                TO_CHAR(
                    m.operacion_id
                )
                    AS operacion_id,


                m.cuenta_id,


                m.tipo_movimiento_id,

                cat.codigo
                    AS tipo_movimiento_codigo,

                cat.nombre
                    AS tipo_movimiento_nombre,

                cat.naturaleza,


                TO_CHAR(
                    m.movimiento_origen_id
                )
                    AS movimiento_origen_id,


                m.numero_movimiento,

                m.fecha_operacion,

                m.fecha_efectiva,

                m.referencia_bancaria,


                m.beneficiario_ordenante,

                m.concepto,


                m.monto,

                m.estado,

                m.estado_conciliacion


            FROM
                MB_MOVIMIENTO_BANCARIO m

            INNER JOIN
                MB_CATALOGO_BANCARIO cat

                    ON cat.catalogo_id =
                       m.tipo_movimiento_id

                   AND cat.grupo =
                       'TIPO_MOVIMIENTO'


            WHERE
                m.cuenta_id =
                p_cuenta_id

            AND (
                    p_fecha_desde IS NULL
                    OR
                    m.fecha_operacion
                        >= TRUNC(p_fecha_desde)
                )

            AND m.fecha_operacion
                < TRUNC(v_fecha_hasta) + 1


            ORDER BY
                m.fecha_operacion DESC,
                m.movimiento_id DESC;


    END LISTAR_MOVIMIENTOS;


    ------------------------------------------------------------------
    -- Reserva fondos.
    --
    -- Garantias:
    --
    -- 1. La cuenta se bloquea antes de calcular disponibilidad.
    -- 2. La cuenta debe estar asociada a la operacion.
    -- 3. Una operacion solo puede poseer un compromiso.
    -- 4. Un retry identico devuelve el compromiso ACTIVO existente.
    -- 5. Una operacion cerrada no vuelve a reservar.
    -- 6. La disponibilidad se recalcula dentro del lock.
    ------------------------------------------------------------------
    PROCEDURE RESERVAR (
        p_operacion_id
            IN MB_OPERACION_BANCARIA.operacion_id%TYPE,

        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,

        p_monto
            IN MB_FONDO_COMPROMETIDO.monto%TYPE,

        p_compromiso_id
            OUT MB_FONDO_COMPROMETIDO.compromiso_id%TYPE
    ) AS

        v_estado_cuenta
            MB_CUENTA_BANCARIA.estado%TYPE;

        v_permite_pagos
            MB_CUENTA_BANCARIA.permite_pagos%TYPE;

        v_cuenta_operacion
            MB_OPERACION_BANCARIA.cuenta_principal_id%TYPE;

        v_disponible
            NUMBER(18,2);

        v_total_compromisos
            PLS_INTEGER;

        v_compromiso_existente
            MB_FONDO_COMPROMETIDO.compromiso_id%TYPE;

        v_cuenta_existente
            MB_FONDO_COMPROMETIDO.cuenta_id%TYPE;

        v_monto_existente
            MB_FONDO_COMPROMETIDO.monto%TYPE;

        v_estado_existente
            MB_FONDO_COMPROMETIDO.estado%TYPE;

    BEGIN

        --------------------------------------------------------------
        -- Validaciones basicas.
        --------------------------------------------------------------
        IF p_operacion_id IS NULL THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_OPERACION_REQUERIDA,
                'Debe indicar la operacion bancaria.'
            );

        END IF;


        VALIDAR_CUENTA_EXISTE(
            p_cuenta_id
        );


        IF p_monto IS NULL
           OR p_monto <= 0 THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_MONTO_INVALIDO,
                'El monto a reservar debe ser mayor que cero.'
            );

        END IF;


        IF p_monto <> ROUND(p_monto, 2) THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_MONTO_INVALIDO,
                'El monto a reservar debe tener como maximo dos decimales.'
            );

        END IF;


        --------------------------------------------------------------
        -- Bloquear cuenta.
        --
        -- Toda reserva para una misma cuenta pasa por este lock.
        --------------------------------------------------------------
        SELECT
            estado,
            permite_pagos

        INTO
            v_estado_cuenta,
            v_permite_pagos

        FROM
            MB_CUENTA_BANCARIA

        WHERE
            cuenta_id =
            p_cuenta_id

        FOR UPDATE;


        --------------------------------------------------------------
        -- Validar la operacion.
        --------------------------------------------------------------
        BEGIN

            SELECT
                cuenta_principal_id

            INTO
                v_cuenta_operacion

            FROM
                MB_OPERACION_BANCARIA

            WHERE
                operacion_id =
                p_operacion_id;


        EXCEPTION

            WHEN NO_DATA_FOUND THEN

                RAISE_APPLICATION_ERROR(
                    C_ERR_OPERACION_NO_EXISTE,
                    'La operacion bancaria indicada no existe.'
                );

        END;


        --------------------------------------------------------------
        -- La operacion debe conocer su cuenta.
        --------------------------------------------------------------
        IF v_cuenta_operacion IS NULL THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_CUENTA_OPERACION,
                'La operacion bancaria no tiene una cuenta principal asignada.'
            );

        END IF;


        IF v_cuenta_operacion <> p_cuenta_id THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_CUENTA_OPERACION,
                'La cuenta indicada no coincide con la cuenta principal de la operacion.'
            );

        END IF;


        --------------------------------------------------------------
        -- Idempotencia fuerte.
        --
        -- Una operacion debe tener como maximo un compromiso.
        --------------------------------------------------------------
        SELECT
            COUNT(*)

        INTO
            v_total_compromisos

        FROM
            MB_FONDO_COMPROMETIDO

        WHERE
            operacion_id =
            p_operacion_id;


        --------------------------------------------------------------
        -- Mas de uno representa inconsistencia previa de datos.
        --------------------------------------------------------------
        IF v_total_compromisos > 1 THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_RESERVA_INCONSISTENTE,
                'La operacion posee multiples compromisos. Debe revisarse antes de continuar.'
            );

        END IF;


        --------------------------------------------------------------
        -- Existe un compromiso previo.
        --------------------------------------------------------------
        IF v_total_compromisos = 1 THEN

            SELECT
                compromiso_id,
                cuenta_id,
                monto,
                estado

            INTO
                v_compromiso_existente,
                v_cuenta_existente,
                v_monto_existente,
                v_estado_existente

            FROM
                MB_FONDO_COMPROMETIDO

            WHERE
                operacion_id =
                p_operacion_id;


            ----------------------------------------------------------
            -- Retry identico de una reserva todavia ACTIVA.
            ----------------------------------------------------------
            IF v_estado_existente = 'ACTIVO' THEN

                IF v_cuenta_existente = p_cuenta_id
                   AND v_monto_existente = p_monto THEN

                    p_compromiso_id :=
                        v_compromiso_existente;

                    RETURN;

                END IF;


                RAISE_APPLICATION_ERROR(
                    C_ERR_RESERVA_DUPLICADA,
                    'La operacion ya posee una reserva activa con una cuenta o monto diferente.'
                );

            END IF;


            ----------------------------------------------------------
            -- La operacion ya tuvo una reserva finalizada.
            --
            -- No se reutiliza la misma operacion para generar
            -- una segunda afectacion financiera.
            ----------------------------------------------------------
            IF v_estado_existente IN (
                'CONSUMIDO',
                'LIBERADO',
                'ANULADO'
            ) THEN

                RAISE_APPLICATION_ERROR(
                    C_ERR_RESERVA_CERRADA,
                    'La operacion ya posee un compromiso finalizado en estado '
                    || v_estado_existente
                    || '. No puede generar una nueva reserva.'
                );

            END IF;


            ----------------------------------------------------------
            -- Proteccion ante un estado inesperado.
            ----------------------------------------------------------
            RAISE_APPLICATION_ERROR(
                C_ERR_ESTADO_COMPROMISO,
                'El compromiso existente posee un estado no compatible con una nueva reserva.'
            );

        END IF;


        --------------------------------------------------------------
        -- Las siguientes reglas aplican solamente a una NUEVA reserva.
        --------------------------------------------------------------
        IF v_estado_cuenta <> 'ACTIVA' THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_CUENTA_NO_ACTIVA,
                'Solo se pueden reservar fondos en una cuenta ACTIVA.'
            );

        END IF;


        IF v_permite_pagos <> 'S' THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_CUENTA_NO_PAGOS,
                'La cuenta bancaria seleccionada no permite pagos.'
            );

        END IF;


        --------------------------------------------------------------
        -- Recalculo bajo bloqueo.
        --------------------------------------------------------------
        v_disponible :=
            CALCULAR_DISPONIBILIDAD(
                p_cuenta_id
            );


        IF v_disponible < p_monto THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_FONDOS_INSUFICIENTES,
                'Fondos insuficientes. Disponible: '
                || TO_CHAR(
                       v_disponible,
                       'FM9999999999990D00'
                   )
                || ', solicitado: '
                || TO_CHAR(
                       p_monto,
                       'FM9999999999990D00'
                   )
                || '.'
            );

        END IF;


        --------------------------------------------------------------
        -- Crear reserva.
        --------------------------------------------------------------
        SELECT
            SEQ_MB_FONDO_COMPROMETIDO.NEXTVAL

        INTO
            p_compromiso_id

        FROM
            dual;


        INSERT INTO MB_FONDO_COMPROMETIDO (
            compromiso_id,
            operacion_id,
            cuenta_id,
            monto,
            comprometido_en,
            liberado_en,
            estado
        )
        VALUES (
            p_compromiso_id,
            p_operacion_id,
            p_cuenta_id,
            p_monto,
            SYSTIMESTAMP,
            NULL,
            'ACTIVO'
        );


    EXCEPTION

        WHEN DUP_VAL_ON_INDEX THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_RESERVA_DUPLICADA,
                'No fue posible crear la reserva porque ya existe un registro equivalente.'
            );


    END RESERVAR;


    ------------------------------------------------------------------
    -- Consumir una reserva.
    --
    -- El egreso bancario es registrado por el proceso encargado
    -- de ejecutar el pago.
    --
    -- MB_FONDOS administra solamente el compromiso.
    ------------------------------------------------------------------
    PROCEDURE CONSUMIR (
        p_compromiso_id
            IN MB_FONDO_COMPROMETIDO.compromiso_id%TYPE
    ) AS

        v_cuenta_id
            MB_FONDO_COMPROMETIDO.cuenta_id%TYPE;

        v_estado
            MB_FONDO_COMPROMETIDO.estado%TYPE;

        v_dummy
            NUMBER;

    BEGIN

        IF p_compromiso_id IS NULL THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_COMPROMISO_REQUERIDO,
                'Debe indicar el compromiso.'
            );

        END IF;


        --------------------------------------------------------------
        -- Identificar la cuenta del compromiso.
        --------------------------------------------------------------
        BEGIN

            SELECT
                cuenta_id

            INTO
                v_cuenta_id

            FROM
                MB_FONDO_COMPROMETIDO

            WHERE
                compromiso_id =
                p_compromiso_id;


        EXCEPTION

            WHEN NO_DATA_FOUND THEN

                RAISE_APPLICATION_ERROR(
                    C_ERR_COMPROMISO_NO_EXISTE,
                    'El compromiso indicado no existe.'
                );

        END;


        --------------------------------------------------------------
        -- Orden de bloqueo:
        -- cuenta -> compromiso.
        --------------------------------------------------------------
        SELECT
            1

        INTO
            v_dummy

        FROM
            MB_CUENTA_BANCARIA

        WHERE
            cuenta_id =
            v_cuenta_id

        FOR UPDATE;


        SELECT
            estado

        INTO
            v_estado

        FROM
            MB_FONDO_COMPROMETIDO

        WHERE
            compromiso_id =
            p_compromiso_id

        FOR UPDATE;


        --------------------------------------------------------------
        -- Idempotencia.
        --------------------------------------------------------------
        IF v_estado = 'CONSUMIDO' THEN

            RETURN;

        END IF;


        IF v_estado <> 'ACTIVO' THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_ESTADO_COMPROMISO,
                'Solo un compromiso ACTIVO puede ser consumido. Estado actual: '
                || v_estado
                || '.'
            );

        END IF;


        UPDATE
            MB_FONDO_COMPROMETIDO

        SET
            estado =
            'CONSUMIDO'

        WHERE
            compromiso_id =
            p_compromiso_id;


    END CONSUMIR;


    ------------------------------------------------------------------
    -- Liberar una reserva.
    ------------------------------------------------------------------
    PROCEDURE LIBERAR (
        p_compromiso_id
            IN MB_FONDO_COMPROMETIDO.compromiso_id%TYPE
    ) AS

        v_cuenta_id
            MB_FONDO_COMPROMETIDO.cuenta_id%TYPE;

        v_estado
            MB_FONDO_COMPROMETIDO.estado%TYPE;

        v_dummy
            NUMBER;

    BEGIN

        IF p_compromiso_id IS NULL THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_COMPROMISO_REQUERIDO,
                'Debe indicar el compromiso.'
            );

        END IF;


        --------------------------------------------------------------
        -- Identificar cuenta.
        --------------------------------------------------------------
        BEGIN

            SELECT
                cuenta_id

            INTO
                v_cuenta_id

            FROM
                MB_FONDO_COMPROMETIDO

            WHERE
                compromiso_id =
                p_compromiso_id;


        EXCEPTION

            WHEN NO_DATA_FOUND THEN

                RAISE_APPLICATION_ERROR(
                    C_ERR_COMPROMISO_NO_EXISTE,
                    'El compromiso indicado no existe.'
                );

        END;


        --------------------------------------------------------------
        -- Mantener el mismo orden de bloqueo.
        -- cuenta -> compromiso.
        --------------------------------------------------------------
        SELECT
            1

        INTO
            v_dummy

        FROM
            MB_CUENTA_BANCARIA

        WHERE
            cuenta_id =
            v_cuenta_id

        FOR UPDATE;


        SELECT
            estado

        INTO
            v_estado

        FROM
            MB_FONDO_COMPROMETIDO

        WHERE
            compromiso_id =
            p_compromiso_id

        FOR UPDATE;


        --------------------------------------------------------------
        -- Retry de una liberacion ya realizada.
        --------------------------------------------------------------
        IF v_estado = 'LIBERADO' THEN

            RETURN;

        END IF;


        IF v_estado <> 'ACTIVO' THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_ESTADO_COMPROMISO,
                'Solo un compromiso ACTIVO puede ser liberado. Estado actual: '
                || v_estado
                || '.'
            );

        END IF;


        UPDATE
            MB_FONDO_COMPROMETIDO

        SET
            estado =
                'LIBERADO',

            liberado_en =
                SYSTIMESTAMP

        WHERE
            compromiso_id =
            p_compromiso_id;


    END LIBERAR;


    ------------------------------------------------------------------
    -- Obtener un compromiso especifico.
    ------------------------------------------------------------------
    PROCEDURE OBTENER_COMPROMISO (
        p_compromiso_id
            IN MB_FONDO_COMPROMETIDO.compromiso_id%TYPE,

        p_resultado
            OUT SYS_REFCURSOR
    ) AS

        v_total
            PLS_INTEGER;

    BEGIN

        IF p_compromiso_id IS NULL THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_COMPROMISO_REQUERIDO,
                'Debe indicar el compromiso.'
            );

        END IF;


        --------------------------------------------------------------
        -- Para detalle se devuelve un error entendible si no existe.
        --------------------------------------------------------------
        SELECT
            COUNT(*)

        INTO
            v_total

        FROM
            MB_FONDO_COMPROMETIDO

        WHERE
            compromiso_id =
            p_compromiso_id;


        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_COMPROMISO_NO_EXISTE,
                'El compromiso indicado no existe.'
            );

        END IF;


        OPEN p_resultado FOR

            SELECT

                TO_CHAR(
                    fc.compromiso_id
                )
                    AS compromiso_id,


                TO_CHAR(
                    fc.operacion_id
                )
                    AS operacion_id,


                fc.cuenta_id,

                c.codigo_cuenta,

                c.nombre_interno,


                fc.monto,

                fc.comprometido_en,

                fc.liberado_en,

                fc.estado,


                op.modulo_origen,

                op.estado
                    AS operacion_estado


            FROM
                MB_FONDO_COMPROMETIDO fc

            INNER JOIN
                MB_CUENTA_BANCARIA c

                    ON c.cuenta_id =
                       fc.cuenta_id

            INNER JOIN
                MB_OPERACION_BANCARIA op

                    ON op.operacion_id =
                       fc.operacion_id


            WHERE
                fc.compromiso_id =
                p_compromiso_id;


    END OBTENER_COMPROMISO;


    ------------------------------------------------------------------
    -- Lista compromisos de una cuenta.
    --
    -- p_estado NULL:
    --   todos.
    --
    -- Admite entrada en cualquier combinacion mayuscula/minuscula.
    ------------------------------------------------------------------
    PROCEDURE LISTAR_COMPROMISOS (
        p_cuenta_id
            IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,

        p_estado
            IN MB_FONDO_COMPROMETIDO.estado%TYPE DEFAULT NULL,

        p_resultado
            OUT SYS_REFCURSOR
    ) AS

        v_estado
            MB_FONDO_COMPROMETIDO.estado%TYPE;

    BEGIN

        VALIDAR_CUENTA_EXISTE(
            p_cuenta_id
        );


        v_estado :=
            CASE
                WHEN p_estado IS NULL
                    THEN NULL

                ELSE
                    UPPER(
                        TRIM(p_estado)
                    )
            END;


        IF v_estado IS NOT NULL
           AND v_estado NOT IN (
               'ACTIVO',
               'CONSUMIDO',
               'LIBERADO',
               'ANULADO'
           ) THEN

            RAISE_APPLICATION_ERROR(
                C_ERR_ESTADO_COMPROMISO,
                'Estado de compromiso no valido. Use ACTIVO, CONSUMIDO, LIBERADO o ANULADO.'
            );

        END IF;


        OPEN p_resultado FOR

            SELECT

                TO_CHAR(
                    fc.compromiso_id
                )
                    AS compromiso_id,


                TO_CHAR(
                    fc.operacion_id
                )
                    AS operacion_id,


                fc.cuenta_id,

                fc.monto,

                fc.comprometido_en,

                fc.liberado_en,

                fc.estado,


                op.modulo_origen,

                op.estado
                    AS operacion_estado


            FROM
                MB_FONDO_COMPROMETIDO fc

            INNER JOIN
                MB_OPERACION_BANCARIA op

                    ON op.operacion_id =
                       fc.operacion_id


            WHERE
                fc.cuenta_id =
                p_cuenta_id

            AND (
                    v_estado IS NULL
                    OR
                    fc.estado =
                    v_estado
                )


            ORDER BY
                fc.comprometido_en DESC,
                fc.compromiso_id DESC;


    END LISTAR_COMPROMISOS;


END MB_FONDOS;
/

-- PACKAGE_BODY MB_IMPORTACION
CREATE OR REPLACE PACKAGE BODY "MB_IMPORTACION" AS

    /* =========================================================
       PROCEDURE: registrar_documento

       Registra el documento bancario correspondiente al
       archivo CSV recibido por Node.js.

       El SHA-256 del archivo es calculado previamente en Node.

       Este procedimiento:
         - Resuelve el tipo documental ESTADO_CUENTA.
         - Valida los metadatos obligatorios.
         - Impide registrar nuevamente el mismo contenido.
         - Genera DOCUMENTO_ID mediante secuencia.
         - Registra MB_DOCUMENTO_BANCARIO.

       No realiza COMMIT.
       ========================================================= */

    PROCEDURE registrar_documento (
        p_numero_referencia IN VARCHAR2,
        p_fecha_documento   IN DATE,
        p_nombre_archivo    IN VARCHAR2,
        p_tipo_mime         IN VARCHAR2,
        p_tamano_bytes      IN NUMBER,
        p_ubicacion_archivo IN VARCHAR2,
        p_hash_sha256       IN VARCHAR2,
        p_descripcion       IN VARCHAR2,
        p_observaciones     IN VARCHAR2,
        p_cargado_por       IN NUMBER,
        p_documento_id      OUT NUMBER
    ) AS
        v_tipo_documento_id NUMBER;
        v_existe            NUMBER;
        v_hash              VARCHAR2(64);
    BEGIN

        /* -----------------------------------------------------
           Validaciones basicas
           ----------------------------------------------------- */

        IF p_fecha_documento IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20070,
                'La fecha del documento es obligatoria.'
            );
        END IF;

        IF p_nombre_archivo IS NULL
           OR LENGTH(TRIM(p_nombre_archivo)) = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20071,
                'El nombre del archivo es obligatorio.'
            );
        END IF;

        IF LENGTH(TRIM(p_nombre_archivo)) > 255 THEN
            RAISE_APPLICATION_ERROR(
                -20072,
                'El nombre del archivo no puede superar 255 caracteres.'
            );
        END IF;

        IF p_tipo_mime IS NULL
           OR LENGTH(TRIM(p_tipo_mime)) = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20073,
                'El tipo MIME del archivo es obligatorio.'
            );
        END IF;

        IF LENGTH(TRIM(p_tipo_mime)) > 100 THEN
            RAISE_APPLICATION_ERROR(
                -20074,
                'El tipo MIME no puede superar 100 caracteres.'
            );
        END IF;

        IF p_tamano_bytes IS NULL
           OR p_tamano_bytes <= 0 THEN

            RAISE_APPLICATION_ERROR(
                -20075,
                'El tamano del archivo debe ser mayor que cero.'
            );
        END IF;

        IF p_ubicacion_archivo IS NULL
           OR LENGTH(TRIM(p_ubicacion_archivo)) = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20076,
                'La ubicacion del archivo es obligatoria.'
            );
        END IF;

        IF LENGTH(TRIM(p_ubicacion_archivo)) > 500 THEN
            RAISE_APPLICATION_ERROR(
                -20077,
                'La ubicacion del archivo no puede superar 500 caracteres.'
            );
        END IF;

        IF p_hash_sha256 IS NULL
           OR LENGTH(TRIM(p_hash_sha256)) = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20078,
                'El hash SHA-256 del archivo es obligatorio.'
            );
        END IF;

        v_hash := UPPER(TRIM(p_hash_sha256));

        IF LENGTH(v_hash) <> 64
           OR REGEXP_LIKE(
               v_hash,
               '[^0-9A-F]'
           ) THEN

            RAISE_APPLICATION_ERROR(
                -20079,
                'El hash SHA-256 debe contener 64 caracteres hexadecimales.'
            );
        END IF;

        IF p_descripcion IS NULL
           OR LENGTH(TRIM(p_descripcion)) = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20080,
                'La descripcion del documento es obligatoria.'
            );
        END IF;

        IF LENGTH(TRIM(p_descripcion)) > 250 THEN
            RAISE_APPLICATION_ERROR(
                -20081,
                'La descripcion no puede superar 250 caracteres.'
            );
        END IF;

        IF p_observaciones IS NOT NULL
           AND LENGTH(TRIM(p_observaciones)) > 500 THEN

            RAISE_APPLICATION_ERROR(
                -20082,
                'Las observaciones no pueden superar 500 caracteres.'
            );
        END IF;

        IF p_numero_referencia IS NOT NULL
           AND LENGTH(TRIM(p_numero_referencia)) > 60 THEN

            RAISE_APPLICATION_ERROR(
                -20083,
                'El numero de referencia no puede superar 60 caracteres.'
            );
        END IF;

        IF p_cargado_por IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20084,
                'El usuario que carga el documento es obligatorio.'
            );
        END IF;


        /* -----------------------------------------------------
           Resolver tipo documental.

           No utilizamos CATALOGO_ID = 3 de forma fija.

           Se resuelve mediante:
             GRUPO    = TIPO_DOCUMENTO
             CODIGO   = ESTADO_CUENTA
             APLICA_A = DOCUMENTO_BANCARIO
             ESTADO   = ACTIVO
           ----------------------------------------------------- */

        BEGIN
            SELECT CATALOGO_ID
              INTO v_tipo_documento_id
              FROM MB_CATALOGO_BANCARIO
             WHERE GRUPO = 'TIPO_DOCUMENTO'
               AND CODIGO = 'ESTADO_CUENTA'
               AND APLICA_A = 'DOCUMENTO_BANCARIO'
               AND ESTADO = 'ACTIVO';

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20085,
                    'No existe una configuracion activa para el tipo documental ESTADO_CUENTA.'
                );

            WHEN TOO_MANY_ROWS THEN
                RAISE_APPLICATION_ERROR(
                    -20086,
                    'Existe mas de una configuracion activa para el tipo documental ESTADO_CUENTA.'
                );
        END;


        /* -----------------------------------------------------
           Evitar registrar nuevamente el mismo contenido.

           HASH_SHA256 posee ademas una restriccion UNIQUE,
           por lo que esta validacion proporciona un mensaje
           funcional y la restriccion protege concurrencia.
           ----------------------------------------------------- */

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_DOCUMENTO_BANCARIO
         WHERE HASH_SHA256 = v_hash;

        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20087,
                'El archivo ya fue registrado anteriormente.'
            );
        END IF;


        /* -----------------------------------------------------
           Generar identificador
           ----------------------------------------------------- */

        p_documento_id :=
            SEQ_MB_DOCUMENTO_BANCARIO.NEXTVAL;


        /* -----------------------------------------------------
           Registrar documento
           ----------------------------------------------------- */

        INSERT INTO MB_DOCUMENTO_BANCARIO (
            DOCUMENTO_ID,
            TIPO_DOCUMENTO_ID,
            NUMERO_REFERENCIA,
            FECHA_DOCUMENTO,
            NOMBRE_ARCHIVO,
            TIPO_MIME,
            TAMANO_BYTES,
            UBICACION_ARCHIVO,
            HASH_SHA256,
            DESCRIPCION,
            OBSERVACIONES,
            CARGADO_POR,
            CARGADO_EN
        )
        VALUES (
            p_documento_id,
            v_tipo_documento_id,
            TRIM(p_numero_referencia),
            p_fecha_documento,
            TRIM(p_nombre_archivo),
            TRIM(p_tipo_mime),
            p_tamano_bytes,
            TRIM(p_ubicacion_archivo),
            v_hash,
            TRIM(p_descripcion),
            TRIM(p_observaciones),
            p_cargado_por,
            SYSTIMESTAMP
        );

    EXCEPTION

        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20087,
                'El archivo ya fue registrado anteriormente.'
            );

        WHEN OTHERS THEN

            IF SQLCODE BETWEEN -20099 AND -20000 THEN
                RAISE;
            END IF;

            RAISE_APPLICATION_ERROR(
                -20088,
                'No fue posible registrar el documento bancario: '
                || SQLERRM
            );

    END registrar_documento;


    /* =========================================================
       PROCEDURE: crear_estado_cuenta
       Crea la cabecera de una importacion bancaria.
       ========================================================= */

    PROCEDURE crear_estado_cuenta (
        p_cuenta_id            IN NUMBER,
        p_formato_id           IN NUMBER,
        p_archivo_documento_id IN NUMBER,
        p_periodo_desde        IN DATE,
        p_periodo_hasta        IN DATE,
        p_saldo_inicial        IN NUMBER,
        p_saldo_final          IN NUMBER,
        p_importado_por        IN NUMBER,
        p_observaciones        IN VARCHAR2,
        p_estado_cuenta_id     OUT NUMBER
    ) AS
        v_existe NUMBER;
    BEGIN

        /* -----------------------------------------------------
           Validaciones basicas
           ----------------------------------------------------- */

        IF p_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20001,
                'La cuenta bancaria es obligatoria.'
            );
        END IF;

        IF p_formato_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20002,
                'El formato de importacion es obligatorio.'
            );
        END IF;

        IF p_archivo_documento_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20003,
                'El archivo de importacion es obligatorio.'
            );
        END IF;

        IF p_periodo_desde IS NULL
           OR p_periodo_hasta IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20004,
                'El periodo de importacion es obligatorio.'
            );
        END IF;

        IF p_periodo_desde > p_periodo_hasta THEN
            RAISE_APPLICATION_ERROR(
                -20005,
                'La fecha inicial del periodo no puede ser mayor que la fecha final.'
            );
        END IF;

        IF p_saldo_inicial IS NULL
           OR p_saldo_final IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20006,
                'Los saldos inicial y final son obligatorios.'
            );
        END IF;

        IF p_importado_por IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20007,
                'El usuario que realiza la importacion es obligatorio.'
            );
        END IF;


        /* -----------------------------------------------------
           Verificar que la cuenta bancaria exista
           ----------------------------------------------------- */

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_CUENTA_BANCARIA
         WHERE CUENTA_ID = p_cuenta_id;

        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20008,
                'La cuenta bancaria indicada no existe.'
            );
        END IF;


        /* -----------------------------------------------------
           Verificar que el formato exista
           ----------------------------------------------------- */

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_FORMATO_IMPORTACION_BANCO
         WHERE FORMATO_ID = p_formato_id;

        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20009,
                'El formato de importacion indicado no existe.'
            );
        END IF;


        /* -----------------------------------------------------
           Verificar que el documento exista
           ----------------------------------------------------- */

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_DOCUMENTO_BANCARIO
         WHERE DOCUMENTO_ID =
               p_archivo_documento_id;

        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20013,
                'El documento bancario indicado no existe.'
            );
        END IF;


        /* -----------------------------------------------------
           Evitar reprocesar la misma combinacion
           Cuenta + periodo + archivo
           ----------------------------------------------------- */

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_ESTADO_CUENTA
         WHERE CUENTA_ID = p_cuenta_id
           AND PERIODO_DESDE = p_periodo_desde
           AND PERIODO_HASTA = p_periodo_hasta
           AND ARCHIVO_DOCUMENTO_ID =
               p_archivo_documento_id;

        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20010,
                'El archivo ya fue importado para esta cuenta y periodo.'
            );
        END IF;


        /* -----------------------------------------------------
           Generar identificador
           ----------------------------------------------------- */

        p_estado_cuenta_id :=
            SEQ_MB_ESTADO_CUENTA.NEXTVAL;


        /* -----------------------------------------------------
           Crear cabecera
           ----------------------------------------------------- */

        INSERT INTO MB_ESTADO_CUENTA (
            ESTADO_CUENTA_ID,
            CUENTA_ID,
            FORMATO_ID,
            ARCHIVO_DOCUMENTO_ID,
            PERIODO_DESDE,
            PERIODO_HASTA,
            SALDO_INICIAL,
            SALDO_FINAL,
            REGISTROS_TOTALES,
            REGISTROS_VALIDOS,
            REGISTROS_ERROR,
            REGISTROS_DUPLICADOS,
            ESTADO,
            IMPORTADO_POR,
            IMPORTADO_EN,
            OBSERVACIONES
        )
        VALUES (
            p_estado_cuenta_id,
            p_cuenta_id,
            p_formato_id,
            p_archivo_documento_id,
            p_periodo_desde,
            p_periodo_hasta,
            p_saldo_inicial,
            p_saldo_final,
            0,
            0,
            0,
            0,
            'CARGADO',
            p_importado_por,
            SYSTIMESTAMP,
            p_observaciones
        );

    EXCEPTION

        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20011,
                'La importacion ya se encuentra registrada.'
            );

        WHEN OTHERS THEN

            IF SQLCODE BETWEEN -20099 AND -20000 THEN
                RAISE;
            END IF;

            RAISE_APPLICATION_ERROR(
                -20012,
                'No fue posible crear la importacion: '
                || SQLERRM
            );

    END crear_estado_cuenta;


    /* =========================================================
       PROCEDURE: registrar_linea
       Registra una linea del estado de cuenta.
       ========================================================= */

    PROCEDURE registrar_linea (
        p_estado_cuenta_id  IN NUMBER,
        p_numero_linea      IN NUMBER,
        p_fecha_bancaria    IN DATE,
        p_fecha_valor       IN DATE,
        p_referencia        IN VARCHAR2,
        p_descripcion       IN VARCHAR2,
        p_numero_cheque     IN VARCHAR2,
        p_naturaleza        IN CHAR,
        p_monto             IN NUMBER,
        p_saldo_linea       IN NUMBER,
        p_hash_linea        IN CHAR,
        p_estado_validacion IN VARCHAR2,
        p_detalle_error     IN VARCHAR2,
        p_linea_estado_id   OUT NUMBER
    ) AS
        v_existe            NUMBER;
        v_estado_validacion VARCHAR2(20);
    BEGIN

        /* -----------------------------------------------------
           Validaciones
           ----------------------------------------------------- */

        IF p_estado_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20020,
                'El estado de cuenta es obligatorio.'
            );
        END IF;

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_ESTADO_CUENTA
         WHERE ESTADO_CUENTA_ID =
               p_estado_cuenta_id;

        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20021,
                'La importacion indicada no existe.'
            );
        END IF;

        IF p_numero_linea IS NULL
           OR p_numero_linea <= 0 THEN

            RAISE_APPLICATION_ERROR(
                -20022,
                'El numero de linea debe ser mayor que cero.'
            );
        END IF;

        IF p_fecha_bancaria IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20023,
                'La fecha bancaria es obligatoria.'
            );
        END IF;

        IF p_naturaleza IS NULL
           OR UPPER(TRIM(p_naturaleza))
              NOT IN ('D', 'C') THEN

            RAISE_APPLICATION_ERROR(
                -20024,
                'La naturaleza debe ser D o C.'
            );
        END IF;

        IF p_monto IS NULL
           OR p_monto <= 0 THEN

            RAISE_APPLICATION_ERROR(
                -20025,
                'El monto debe ser mayor que cero.'
            );
        END IF;

        IF p_hash_linea IS NULL
           OR LENGTH(TRIM(p_hash_linea)) = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20026,
                'El hash de la linea es obligatorio.'
            );
        END IF;


        /* -----------------------------------------------------
           Evitar repetir numero de linea dentro del mismo
           estado de cuenta.
           ----------------------------------------------------- */

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_LINEA_ESTADO_CUENTA
         WHERE ESTADO_CUENTA_ID =
               p_estado_cuenta_id
           AND NUMERO_LINEA =
               p_numero_linea;

        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20027,
                'El numero de linea ya fue registrado en esta importacion.'
            );
        END IF;


        /* -----------------------------------------------------
           Determinar si la linea es duplicada por HASH.
           ----------------------------------------------------- */

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_LINEA_ESTADO_CUENTA
         WHERE ESTADO_CUENTA_ID =
               p_estado_cuenta_id
           AND HASH_LINEA =
               p_hash_linea;

        IF v_existe > 0 THEN
            v_estado_validacion :=
                'DUPLICADA';
        ELSE
            v_estado_validacion :=
                UPPER(
                    TRIM(
                        p_estado_validacion
                    )
                );
        END IF;


        IF v_estado_validacion NOT IN (
            'VALIDA',
            'ERROR',
            'DUPLICADA'
        ) THEN
            RAISE_APPLICATION_ERROR(
                -20028,
                'El estado de validacion debe ser VALIDA, ERROR o DUPLICADA.'
            );
        END IF;


        IF v_estado_validacion = 'ERROR'
           AND (
               p_detalle_error IS NULL
               OR LENGTH(
                   TRIM(p_detalle_error)
               ) = 0
           ) THEN

            RAISE_APPLICATION_ERROR(
                -20029,
                'Una linea con estado ERROR debe incluir el detalle del error.'
            );
        END IF;


        /* -----------------------------------------------------
           Generar identificador
           ----------------------------------------------------- */

        p_linea_estado_id :=
            SEQ_MB_LINEA_ESTADO_CUENTA.NEXTVAL;


        /* -----------------------------------------------------
           Insertar linea
           ----------------------------------------------------- */

        INSERT INTO MB_LINEA_ESTADO_CUENTA (
            LINEA_ESTADO_ID,
            ESTADO_CUENTA_ID,
            NUMERO_LINEA,
            FECHA_BANCARIA,
            FECHA_VALOR,
            REFERENCIA,
            DESCRIPCION,
            NUMERO_CHEQUE,
            NATURALEZA,
            MONTO,
            SALDO_LINEA,
            HASH_LINEA,
            ESTADO_VALIDACION,
            DETALLE_ERROR
        )
        VALUES (
            p_linea_estado_id,
            p_estado_cuenta_id,
            p_numero_linea,
            p_fecha_bancaria,
            p_fecha_valor,
            p_referencia,
            p_descripcion,
            p_numero_cheque,
            UPPER(
                TRIM(p_naturaleza)
            ),
            p_monto,
            p_saldo_linea,
            p_hash_linea,
            v_estado_validacion,
            CASE
                WHEN v_estado_validacion =
                     'DUPLICADA'
                THEN NVL(
                    p_detalle_error,
                    'Linea duplicada detectada por hash.'
                )
                ELSE p_detalle_error
            END
        );

    EXCEPTION

        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20030,
                'La linea ya se encuentra registrada.'
            );

        WHEN OTHERS THEN

            IF SQLCODE BETWEEN -20099 AND -20000 THEN
                RAISE;
            END IF;

            RAISE_APPLICATION_ERROR(
                -20031,
                'No fue posible registrar la linea: '
                || SQLERRM
            );

    END registrar_linea;


    /* =========================================================
       PROCEDURE: finalizar_importacion
       Calcula los contadores y establece el estado final.
       ========================================================= */

    PROCEDURE finalizar_importacion (
        p_estado_cuenta_id IN NUMBER
    ) AS
        v_existe     NUMBER;
        v_total      NUMBER;
        v_validos    NUMBER;
        v_errores    NUMBER;
        v_duplicados NUMBER;
        v_estado     VARCHAR2(20);
    BEGIN

        IF p_estado_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20040,
                'El estado de cuenta es obligatorio.'
            );
        END IF;


        SELECT COUNT(*)
          INTO v_existe
          FROM MB_ESTADO_CUENTA
         WHERE ESTADO_CUENTA_ID =
               p_estado_cuenta_id;

        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20041,
                'La importacion indicada no existe.'
            );
        END IF;


        SELECT
            COUNT(*),

            NVL(
                SUM(
                    CASE
                        WHEN ESTADO_VALIDACION =
                             'VALIDA'
                        THEN 1
                        ELSE 0
                    END
                ),
                0
            ),

            NVL(
                SUM(
                    CASE
                        WHEN ESTADO_VALIDACION =
                             'ERROR'
                        THEN 1
                        ELSE 0
                    END
                ),
                0
            ),

            NVL(
                SUM(
                    CASE
                        WHEN ESTADO_VALIDACION =
                             'DUPLICADA'
                        THEN 1
                        ELSE 0
                    END
                ),
                0
            )

        INTO
            v_total,
            v_validos,
            v_errores,
            v_duplicados

        FROM MB_LINEA_ESTADO_CUENTA
        WHERE ESTADO_CUENTA_ID =
              p_estado_cuenta_id;


        /* -----------------------------------------------------
           Si existen errores, la importacion queda
           CON_ERRORES.

           Si no existen errores, queda VALIDADO.

           Las lineas duplicadas se contabilizan por separado.
           ----------------------------------------------------- */

        IF v_errores > 0 THEN
            v_estado :=
                'CON_ERRORES';
        ELSE
            v_estado :=
                'VALIDADO';
        END IF;


        UPDATE MB_ESTADO_CUENTA
           SET REGISTROS_TOTALES =
                   v_total,

               REGISTROS_VALIDOS =
                   v_validos,

               REGISTROS_ERROR =
                   v_errores,

               REGISTROS_DUPLICADOS =
                   v_duplicados,

               ESTADO =
                   v_estado

         WHERE ESTADO_CUENTA_ID =
               p_estado_cuenta_id;

    EXCEPTION

        WHEN OTHERS THEN

            IF SQLCODE BETWEEN -20099 AND -20000 THEN
                RAISE;
            END IF;

            RAISE_APPLICATION_ERROR(
                -20042,
                'No fue posible finalizar la importacion: '
                || SQLERRM
            );

    END finalizar_importacion;


    /* =========================================================
       PROCEDURE: obtener_estado_cuenta
       Devuelve una importacion especifica.
       ========================================================= */

    PROCEDURE obtener_estado_cuenta (
        p_estado_cuenta_id IN NUMBER,
        p_resultado        OUT SYS_REFCURSOR
    ) AS
    BEGIN

        IF p_estado_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20050,
                'El estado de cuenta es obligatorio.'
            );
        END IF;


        OPEN p_resultado FOR

            SELECT
                ec.ESTADO_CUENTA_ID,
                ec.CUENTA_ID,
                cb.CODIGO_CUENTA,
                cb.NUMERO_CUENTA,
                cb.NOMBRE_INTERNO,
                ec.FORMATO_ID,
                ec.ARCHIVO_DOCUMENTO_ID,
                ec.PERIODO_DESDE,
                ec.PERIODO_HASTA,
                ec.SALDO_INICIAL,
                ec.SALDO_FINAL,
                ec.REGISTROS_TOTALES,
                ec.REGISTROS_VALIDOS,
                ec.REGISTROS_ERROR,
                ec.REGISTROS_DUPLICADOS,
                ec.ESTADO,
                ec.IMPORTADO_POR,
                ec.IMPORTADO_EN,
                ec.OBSERVACIONES

            FROM MB_ESTADO_CUENTA ec

            INNER JOIN MB_CUENTA_BANCARIA cb
                ON cb.CUENTA_ID =
                   ec.CUENTA_ID

            WHERE ec.ESTADO_CUENTA_ID =
                  p_estado_cuenta_id;

    END obtener_estado_cuenta;


    /* =========================================================
       PROCEDURE: listar_lineas
       Devuelve las lineas de una importacion.
       ========================================================= */

    PROCEDURE listar_lineas (
        p_estado_cuenta_id IN NUMBER,
        p_resultado        OUT SYS_REFCURSOR
    ) AS
    BEGIN

        IF p_estado_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20060,
                'El estado de cuenta es obligatorio.'
            );
        END IF;


        OPEN p_resultado FOR

            SELECT
                l.LINEA_ESTADO_ID,
                l.ESTADO_CUENTA_ID,
                l.NUMERO_LINEA,
                l.FECHA_BANCARIA,
                l.FECHA_VALOR,
                l.REFERENCIA,
                l.DESCRIPCION,
                l.NUMERO_CHEQUE,
                l.NATURALEZA,
                l.MONTO,
                l.SALDO_LINEA,
                l.HASH_LINEA,
                l.ESTADO_VALIDACION,
                l.DETALLE_ERROR

            FROM MB_LINEA_ESTADO_CUENTA l

            WHERE l.ESTADO_CUENTA_ID =
                  p_estado_cuenta_id

            ORDER BY
                l.NUMERO_LINEA;

    END listar_lineas;

END MB_IMPORTACION;
/

-- PACKAGE_BODY MB_VERIFICACION
CREATE OR REPLACE PACKAGE BODY "MB_VERIFICACION" AS

    ------------------------------------------------------------------
    -- Codigos de error propios del proceso.
    ------------------------------------------------------------------
    C_ERR_CUENTA_REQUERIDA      CONSTANT PLS_INTEGER := -20200;
    C_ERR_CUENTA_NO_EXISTE      CONSTANT PLS_INTEGER := -20201;
    C_ERR_DECISION_INVALIDA     CONSTANT PLS_INTEGER := -20202;
    C_ERR_COMENTARIO_REQUERIDO  CONSTANT PLS_INTEGER := -20203;
    C_ERR_EVIDENCIA_REQUERIDA   CONSTANT PLS_INTEGER := -20204;
    C_ERR_EVIDENCIA_NO_EXISTE   CONSTANT PLS_INTEGER := -20205;
    C_ERR_USUARIO_REQUERIDO     CONSTANT PLS_INTEGER := -20206;
    C_ERR_TRANSICION_INVALIDA   CONSTANT PLS_INTEGER := -20207;
    C_ERR_VIGENCIA_INVALIDA     CONSTANT PLS_INTEGER := -20208;
    C_ERR_ID_VERIFICACION       CONSTANT PLS_INTEGER := -20209;


    ------------------------------------------------------------------
    -- Valida que la cuenta de proveedor exista.
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_CUENTA (
        p_cta_proveedor_id
            IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE
    ) AS
        v_dummy NUMBER;
    BEGIN
        IF p_cta_proveedor_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_CUENTA_REQUERIDA,
                'Debe indicar la cuenta bancaria del proveedor.'
            );
        END IF;

        BEGIN
            SELECT 1
              INTO v_dummy
              FROM MB_CUENTA_BANCARIA_PROVEEDOR
             WHERE cta_proveedor_id = p_cta_proveedor_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    C_ERR_CUENTA_NO_EXISTE,
                    'La cuenta bancaria del proveedor indicada no existe.'
                );
        END;
    END VALIDAR_CUENTA;


    ------------------------------------------------------------------
    -- Valida la decision recibida.
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_DECISION (
        p_decision
            IN MB_VERIFICACION_CTA_PROVEEDOR.decision%TYPE
    ) AS
        v_decision MB_VERIFICACION_CTA_PROVEEDOR.decision%TYPE;
    BEGIN
        v_decision := UPPER(TRIM(p_decision));

        IF v_decision IS NULL
           OR v_decision NOT IN (
               'VERIFICAR',
               'RECHAZAR',
               'BLOQUEAR'
           )
        THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_DECISION_INVALIDA,
                'Decision invalida. Use VERIFICAR, RECHAZAR o BLOQUEAR.'
            );
        END IF;
    END VALIDAR_DECISION;


    ------------------------------------------------------------------
    -- Valida que el documento de evidencia exista.
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_EVIDENCIA (
        p_documento_id
            IN MB_DOCUMENTO_BANCARIO.documento_id%TYPE
    ) AS
        v_dummy NUMBER;
    BEGIN
        IF p_documento_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_EVIDENCIA_REQUERIDA,
                'Debe indicar un documento de evidencia.'
            );
        END IF;

        BEGIN
            SELECT 1
              INTO v_dummy
              FROM MB_DOCUMENTO_BANCARIO
             WHERE documento_id = p_documento_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    C_ERR_EVIDENCIA_NO_EXISTE,
                    'El documento de evidencia indicado no existe.'
                );
        END;
    END VALIDAR_EVIDENCIA;


    ------------------------------------------------------------------
    -- Ficha completa de revision.
    ------------------------------------------------------------------
    PROCEDURE OBTENER_DETALLE (
        p_cta_proveedor_id
            IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE,
        p_resultado
            OUT SYS_REFCURSOR
    ) AS
    BEGIN
        VALIDAR_CUENTA(p_cta_proveedor_id);

        OPEN p_resultado FOR
            SELECT
                TO_CHAR(cp.cta_proveedor_id)
                    AS cta_proveedor_id,

                cp.proveedor_id,

                cp.banco_id,
                b.codigo_banco,
                b.nombre
                    AS banco_nombre,

                cp.tipo_cuenta_id,
                tc.codigo
                    AS tipo_cuenta_codigo,
                tc.nombre
                    AS tipo_cuenta_nombre,

                cp.moneda_id,

                cp.titular,
                cp.numero_cuenta,

                TO_CHAR(cp.carta_solicitud_doc_id)
                    AS carta_solicitud_doc_id,

                carta.nombre_archivo
                    AS carta_solicitud_nombre,

                TO_CHAR(cp.constancia_banco_doc_id)
                    AS constancia_banco_doc_id,

                constancia.nombre_archivo
                    AS constancia_banco_nombre,

                TO_CHAR(cp.representante_doc_id)
                    AS representante_doc_id,

                representante.nombre_archivo
                    AS representante_nombre,

                cp.motivo_registro,
                cp.fecha_vigencia,
                cp.estado,
                cp.observaciones,
                cp.solicitado_por,
                cp.solicitado_en,

                TO_CHAR(v.verificacion_id)
                    AS ultima_verificacion_id,

                v.decision
                    AS ultima_decision,

                v.comentario
                    AS ultimo_comentario,

                TO_CHAR(v.evidencia_documento_id)
                    AS ultima_evidencia_documento_id,

                evidencia.nombre_archivo
                    AS ultima_evidencia_nombre,

                v.fecha_vigencia
                    AS ultima_fecha_vigencia,

                v.verificado_por
                    AS ultimo_verificado_por,

                v.verificado_en
                    AS ultimo_verificado_en,

                ------------------------------------------------------
                -- Regla explicita de elegibilidad.
                ------------------------------------------------------
                CASE
                    WHEN cp.estado = 'VERIFICADA'
                     AND v.decision = 'VERIFICAR'
                     AND v.evidencia_documento_id IS NOT NULL
                     AND (
                            cp.fecha_vigencia IS NULL
                            OR cp.fecha_vigencia >= TRUNC(SYSDATE)
                         )
                    THEN 'S'
                    ELSE 'N'
                END
                    AS elegible_transferencia,

                ------------------------------------------------------
                -- Explicacion para UX.
                ------------------------------------------------------
                CASE
                    WHEN cp.estado = 'VERIFICADA'
                     AND v.decision = 'VERIFICAR'
                     AND v.evidencia_documento_id IS NOT NULL
                     AND (
                            cp.fecha_vigencia IS NULL
                            OR cp.fecha_vigencia >= TRUNC(SYSDATE)
                         )
                    THEN
                        'Cuenta verificada y vigente.'

                    WHEN cp.estado = 'VERIFICADA'
                     AND cp.fecha_vigencia IS NOT NULL
                     AND cp.fecha_vigencia < TRUNC(SYSDATE)
                    THEN
                        'La vigencia de la verificacion esta vencida.'

                    WHEN cp.estado = 'VERIFICADA'
                     AND (
                            v.verificacion_id IS NULL
                            OR v.decision IS NULL
                            OR v.decision <> 'VERIFICAR'
                         )
                    THEN
                        'La cuenta no posee una verificacion formal valida.'

                    WHEN cp.estado = 'PENDIENTE'
                    THEN
                        'La cuenta esta pendiente de verificacion.'

                    WHEN cp.estado = 'EN_REVISION'
                    THEN
                        'La cuenta se encuentra en revision.'

                    WHEN cp.estado = 'RECHAZADA'
                    THEN
                        NVL(
                            v.comentario,
                            'La cuenta fue rechazada.'
                        )

                    WHEN cp.estado = 'BLOQUEADA'
                    THEN
                        NVL(
                            v.comentario,
                            'La cuenta se encuentra bloqueada.'
                        )

                    WHEN cp.estado = 'INACTIVA'
                    THEN
                        'La cuenta esta inactiva.'

                    ELSE
                        'La cuenta no es elegible para transferencia.'
                END
                    AS motivo_no_elegible

            FROM MB_CUENTA_BANCARIA_PROVEEDOR cp

            INNER JOIN MB_BANCO b
                    ON b.banco_id = cp.banco_id

            INNER JOIN MB_CATALOGO_BANCARIO tc
                    ON tc.catalogo_id = cp.tipo_cuenta_id

            LEFT JOIN MB_DOCUMENTO_BANCARIO carta
                   ON carta.documento_id =
                      cp.carta_solicitud_doc_id

            LEFT JOIN MB_DOCUMENTO_BANCARIO constancia
                   ON constancia.documento_id =
                      cp.constancia_banco_doc_id

            LEFT JOIN MB_DOCUMENTO_BANCARIO representante
                   ON representante.documento_id =
                      cp.representante_doc_id

            LEFT JOIN MB_VERIFICACION_CTA_PROVEEDOR v
                   ON v.verificacion_id = (
                        SELECT MAX(v2.verificacion_id)
                          FROM MB_VERIFICACION_CTA_PROVEEDOR v2
                         WHERE v2.cta_proveedor_id =
                               cp.cta_proveedor_id
                   )

            LEFT JOIN MB_DOCUMENTO_BANCARIO evidencia
                   ON evidencia.documento_id =
                      v.evidencia_documento_id

            WHERE cp.cta_proveedor_id =
                  p_cta_proveedor_id;

    END OBTENER_DETALLE;


    ------------------------------------------------------------------
    -- Historial completo de decisiones.
    ------------------------------------------------------------------
    PROCEDURE LISTAR_HISTORIAL (
        p_cta_proveedor_id
            IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE,
        p_resultado
            OUT SYS_REFCURSOR
    ) AS
    BEGIN
        VALIDAR_CUENTA(p_cta_proveedor_id);

        OPEN p_resultado FOR
            SELECT
                TO_CHAR(v.verificacion_id)
                    AS verificacion_id,

                TO_CHAR(v.cta_proveedor_id)
                    AS cta_proveedor_id,

                v.decision,
                v.comentario,

                TO_CHAR(v.evidencia_documento_id)
                    AS evidencia_documento_id,

                d.numero_referencia
                    AS evidencia_referencia,

                d.nombre_archivo
                    AS evidencia_nombre,

                d.descripcion
                    AS evidencia_descripcion,

                v.fecha_vigencia,
                v.verificado_por,
                v.verificado_en

            FROM MB_VERIFICACION_CTA_PROVEEDOR v

            INNER JOIN MB_DOCUMENTO_BANCARIO d
                    ON d.documento_id =
                       v.evidencia_documento_id

            WHERE v.cta_proveedor_id =
                  p_cta_proveedor_id

            ORDER BY
                v.verificado_en DESC,
                v.verificacion_id DESC;

    END LISTAR_HISTORIAL;


    ------------------------------------------------------------------
    -- Registra una decision formal.
    --
    -- IMPORTANTE:
    -- No realiza COMMIT ni ROLLBACK.
    -- La transaccion pertenece al consumidor del package.
    ------------------------------------------------------------------
    PROCEDURE REGISTRAR_DECISION (
        p_cta_proveedor_id
            IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE,

        p_decision
            IN MB_VERIFICACION_CTA_PROVEEDOR.decision%TYPE,

        p_comentario
            IN MB_VERIFICACION_CTA_PROVEEDOR.comentario%TYPE,

        p_evidencia_documento_id
            IN MB_VERIFICACION_CTA_PROVEEDOR.evidencia_documento_id%TYPE,

        p_fecha_vigencia
            IN MB_VERIFICACION_CTA_PROVEEDOR.fecha_vigencia%TYPE,

        p_verificado_por
            IN MB_VERIFICACION_CTA_PROVEEDOR.verificado_por%TYPE,

        p_verificacion_id
            OUT MB_VERIFICACION_CTA_PROVEEDOR.verificacion_id%TYPE
    ) AS

        v_estado_actual
            MB_CUENTA_BANCARIA_PROVEEDOR.estado%TYPE;

        v_decision
            MB_VERIFICACION_CTA_PROVEEDOR.decision%TYPE;

        v_estado_destino
            MB_CUENTA_BANCARIA_PROVEEDOR.estado%TYPE;

        v_fecha_vigencia
            MB_VERIFICACION_CTA_PROVEEDOR.fecha_vigencia%TYPE;

    BEGIN
        --------------------------------------------------------------
        -- Validaciones iniciales.
        --------------------------------------------------------------
        VALIDAR_CUENTA(p_cta_proveedor_id);

        v_decision := UPPER(TRIM(p_decision));

        VALIDAR_DECISION(v_decision);

        VALIDAR_EVIDENCIA(
            p_evidencia_documento_id
        );


        IF p_verificado_por IS NULL
           OR p_verificado_por <= 0
        THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_USUARIO_REQUERIDO,
                'Debe existir un usuario responsable de la decision.'
            );
        END IF;


        --------------------------------------------------------------
        -- Rechazo y bloqueo siempre requieren explicacion.
        --------------------------------------------------------------
        IF v_decision IN ('RECHAZAR', 'BLOQUEAR')
           AND TRIM(p_comentario) IS NULL
        THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_COMENTARIO_REQUERIDO,
                'Debe indicar un comentario al rechazar o bloquear.'
            );
        END IF;


        --------------------------------------------------------------
        -- Una verificacion no puede nacer vencida.
        --------------------------------------------------------------
        IF v_decision = 'VERIFICAR'
           AND p_fecha_vigencia IS NOT NULL
           AND TRUNC(p_fecha_vigencia) < TRUNC(SYSDATE)
        THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_VIGENCIA_INVALIDA,
                'La fecha de vigencia no puede estar vencida al verificar la cuenta.'
            );
        END IF;


        --------------------------------------------------------------
        -- Bloqueo de la cuenta.
        --
        -- Dos revisores no pueden decidir simultaneamente sobre
        -- la misma cuenta.
        --------------------------------------------------------------
        BEGIN
            SELECT estado
              INTO v_estado_actual
              FROM MB_CUENTA_BANCARIA_PROVEEDOR
             WHERE cta_proveedor_id = p_cta_proveedor_id
             FOR UPDATE;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    C_ERR_CUENTA_NO_EXISTE,
                    'La cuenta bancaria del proveedor indicada no existe.'
                );
        END;


        --------------------------------------------------------------
        -- Estados admitidos por el proceso.
        --------------------------------------------------------------
        IF v_estado_actual NOT IN (
            'PENDIENTE',
            'EN_REVISION',
            'VERIFICADA',
            'RECHAZADA',
            'BLOQUEADA',
            'INACTIVA'
        )
        THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_TRANSICION_INVALIDA,
                'El estado actual de la cuenta no permite realizar una decision de verificacion.'
            );
        END IF;


        --------------------------------------------------------------
        -- INACTIVA es terminal para este proceso.
        --------------------------------------------------------------
        IF v_estado_actual = 'INACTIVA' THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_TRANSICION_INVALIDA,
                'Una cuenta INACTIVA no puede ser verificada, rechazada ni bloqueada.'
            );
        END IF;


        --------------------------------------------------------------
        -- Determinar el nuevo estado.
        --------------------------------------------------------------
        CASE v_decision

            WHEN 'VERIFICAR' THEN
                v_estado_destino := 'VERIFICADA';
                v_fecha_vigencia := p_fecha_vigencia;

            WHEN 'RECHAZAR' THEN
                v_estado_destino := 'RECHAZADA';
                v_fecha_vigencia := NULL;

            WHEN 'BLOQUEAR' THEN
                v_estado_destino := 'BLOQUEADA';
                v_fecha_vigencia := NULL;

            ELSE
                RAISE_APPLICATION_ERROR(
                    C_ERR_DECISION_INVALIDA,
                    'Decision de verificacion no soportada.'
                );

        END CASE;


        --------------------------------------------------------------
        -- No existe secuencia propia para VERIFICACION_ID.
        --
        -- Se bloquea brevemente la tabla antes del MAX + 1 para
        -- impedir que dos sesiones generen el mismo identificador.
        --------------------------------------------------------------
        LOCK TABLE MB_VERIFICACION_CTA_PROVEEDOR
            IN SHARE ROW EXCLUSIVE MODE;


        SELECT NVL(MAX(verificacion_id), 0) + 1
          INTO p_verificacion_id
          FROM MB_VERIFICACION_CTA_PROVEEDOR;


        IF p_verificacion_id IS NULL
           OR p_verificacion_id <= 0
        THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_ID_VERIFICACION,
                'No fue posible generar el identificador de la verificacion.'
            );
        END IF;


        --------------------------------------------------------------
        -- Primero se conserva el historial.
        --
        -- Si este INSERT falla, la cuenta no llega a habilitarse.
        --------------------------------------------------------------
        INSERT INTO MB_VERIFICACION_CTA_PROVEEDOR (
            verificacion_id,
            cta_proveedor_id,
            decision,
            comentario,
            evidencia_documento_id,
            fecha_vigencia,
            verificado_por,
            verificado_en
        )
        VALUES (
            p_verificacion_id,
            p_cta_proveedor_id,
            v_decision,
            NULLIF(TRIM(p_comentario), ''),
            p_evidencia_documento_id,
            v_fecha_vigencia,
            p_verificado_por,
            SYSTIMESTAMP
        );


        --------------------------------------------------------------
        -- La cuenta cambia de condicion dentro de la MISMA
        -- transaccion que registra el historial.
        --------------------------------------------------------------
        UPDATE MB_CUENTA_BANCARIA_PROVEEDOR
           SET estado          = v_estado_destino,
               fecha_vigencia  = v_fecha_vigencia
         WHERE cta_proveedor_id =
               p_cta_proveedor_id;


    EXCEPTION

        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                C_ERR_ID_VERIFICACION,
                'No fue posible registrar la verificacion por un conflicto de identificador.'
            );

    END REGISTRAR_DECISION;


END MB_VERIFICACION;
/

-- PACKAGE_BODY PKG_MB_BANCOS
CREATE OR REPLACE PACKAGE BODY "PKG_MB_BANCOS" AS


    -- ========================================================
    -- LISTAR
    -- ========================================================

    PROCEDURE LISTAR (
        p_resultado OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR
            SELECT
                banco_id,
                codigo_banco,
                nombre,
                bic_swift,
                estado,
                creado_por,
                creado_en
            FROM MB_BANCO
            ORDER BY nombre;

    END LISTAR;


    -- ========================================================
    -- OBTENER
    -- ========================================================

    PROCEDURE OBTENER (
        p_banco_id  IN NUMBER,
        p_resultado OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR
            SELECT
                banco_id,
                codigo_banco,
                nombre,
                bic_swift,
                estado,
                creado_por,
                creado_en
            FROM MB_BANCO
            WHERE banco_id = p_banco_id;

    END OBTENER;


    -- ========================================================
    -- CREAR
    --
    -- El ID se genera dentro de Oracle.
    -- El banco se crea inicialmente con estado ACTIVO.
    -- ========================================================

    PROCEDURE CREAR (
        p_codigo_banco IN VARCHAR2,
        p_nombre       IN VARCHAR2,
        p_bic_swift    IN VARCHAR2,
        p_creado_por   IN NUMBER,
        p_banco_id     OUT NUMBER
    ) AS
    BEGIN

        p_banco_id := SEQ_MB_BANCO.NEXTVAL;

        INSERT INTO MB_BANCO (
            banco_id,
            codigo_banco,
            nombre,
            bic_swift,
            estado,
            creado_por,
            creado_en
        )
        VALUES (
            p_banco_id,
            p_codigo_banco,
            p_nombre,
            p_bic_swift,
            'ACTIVO',
            p_creado_por,
            SYSTIMESTAMP
        );

    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20023,
                'Ya existe un banco con el código indicado.'
            );

    END CREAR;


    -- ========================================================
    -- ACTUALIZAR
    --
    -- Reglas:
    -- - El banco debe existir.
    -- - Un banco INACTIVO no puede editarse.
    -- - No se permite duplicar codigo_banco.
    -- ========================================================

    PROCEDURE ACTUALIZAR (
        p_banco_id     IN NUMBER,
        p_codigo_banco IN VARCHAR2,
        p_nombre       IN VARCHAR2,
        p_bic_swift    IN VARCHAR2
    ) AS

        v_estado MB_BANCO.estado%TYPE;

    BEGIN

        -- Verificar existencia y obtener estado actual.
        BEGIN

            SELECT estado
              INTO v_estado
              FROM MB_BANCO
             WHERE banco_id = p_banco_id;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20021,
                    'El banco indicado no existe.'
                );
        END;


        -- Un banco inactivo conserva su informacion,
        -- pero no puede ser editado.
        IF v_estado = 'INACTIVO' THEN
            RAISE_APPLICATION_ERROR(
                -20022,
                'El banco indicado se encuentra inactivo y no puede editarse.'
            );
        END IF;


        UPDATE MB_BANCO
           SET codigo_banco = p_codigo_banco,
               nombre       = p_nombre,
               bic_swift    = p_bic_swift
         WHERE banco_id = p_banco_id;


    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20023,
                'Ya existe un banco con el código indicado.'
            );

    END ACTUALIZAR;

    -- ========================================================
    -- CAMBIAR ESTADO
    -- ========================================================

    PROCEDURE CAMBIAR_ESTADO (
        p_banco_id IN NUMBER,
        p_estado   IN VARCHAR2
    ) AS
    BEGIN

        IF p_estado NOT IN ('ACTIVO', 'INACTIVO') THEN
            RAISE_APPLICATION_ERROR(
                -20024,
                'El estado indicado no es válido.'
            );
        END IF;

        UPDATE MB_BANCO
           SET estado = p_estado
         WHERE banco_id = p_banco_id;

        IF SQL%ROWCOUNT = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20021,
                'El banco indicado no existe.'
            );
        END IF;

    END CAMBIAR_ESTADO;


END PKG_MB_BANCOS;
/

-- PACKAGE_BODY PKG_MB_CATALOGOS
CREATE OR REPLACE PACKAGE BODY "PKG_MB_CATALOGOS" AS


    -- ========================================================
    -- VALIDAR FLAGS
    --
    -- Valida los indicadores reutilizados por
    -- CREAR y ACTUALIZAR.
    -- ========================================================

    PROCEDURE VALIDAR_FLAGS(
        p_requiere_comentario IN CHAR,
        p_requiere_evidencia  IN CHAR,
        p_permite_reversion   IN CHAR
    ) AS
    BEGIN

        IF NVL(p_requiere_comentario, '?') NOT IN ('S', 'N')
           OR NVL(p_requiere_evidencia, '?') NOT IN ('S', 'N')
           OR NVL(p_permite_reversion, '?') NOT IN ('S', 'N') THEN

            RAISE_APPLICATION_ERROR(
                -20034,
                'Los indicadores deben contener únicamente S o N.'
            );

        END IF;

    END VALIDAR_FLAGS;


    -- ========================================================
    -- VALIDAR NATURALEZA
    --
    -- Reglas:
    -- - Solo se permiten D, C o NULL.
    -- - TIPO_MOVIMIENTO requiere naturaleza obligatoriamente.
    -- ========================================================

    PROCEDURE VALIDAR_NATURALEZA(
        p_grupo      IN VARCHAR2,
        p_naturaleza IN CHAR
    ) AS
    BEGIN

        IF p_naturaleza IS NOT NULL
           AND p_naturaleza NOT IN ('D', 'C') THEN

            RAISE_APPLICATION_ERROR(
                -20035,
                'La naturaleza debe ser D, C o estar vacía.'
            );

        END IF;


        IF p_grupo = 'TIPO_MOVIMIENTO'
           AND p_naturaleza IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20036,
                'Los catálogos de tipo movimiento requieren una naturaleza D o C.'
            );

        END IF;

    END VALIDAR_NATURALEZA;


    -- ========================================================
    -- VALIDAR ESTADO
    --
    -- Reglas:
    -- - El estado es obligatorio.
    -- - Solo se permiten ACTIVO e INACTIVO.
    -- ========================================================

    PROCEDURE VALIDAR_ESTADO(
        p_estado IN VARCHAR2
    ) AS
    BEGIN

        IF p_estado IS NULL
           OR p_estado NOT IN ('ACTIVO', 'INACTIVO') THEN

            RAISE_APPLICATION_ERROR(
                -20033,
                'El estado indicado no es válido.'
            );

        END IF;

    END VALIDAR_ESTADO;


    -- ========================================================
    -- LISTAR
    -- ========================================================

    PROCEDURE LISTAR(
        p_resultado OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR
            SELECT
                catalogo_id,
                grupo,
                codigo,
                nombre,
                descripcion,
                aplica_a,
                naturaleza,
                requiere_comentario,
                requiere_evidencia,
                permite_reversion,
                estado
            FROM MB_CATALOGO_BANCARIO
            ORDER BY grupo, codigo;

    END LISTAR;


    -- ========================================================
    -- OBTENER
    -- ========================================================

    PROCEDURE OBTENER(
        p_catalogo_id IN NUMBER,
        p_resultado   OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR
            SELECT
                catalogo_id,
                grupo,
                codigo,
                nombre,
                descripcion,
                aplica_a,
                naturaleza,
                requiere_comentario,
                requiere_evidencia,
                permite_reversion,
                estado
            FROM MB_CATALOGO_BANCARIO
            WHERE catalogo_id = p_catalogo_id;

    END OBTENER;


    -- ========================================================
    -- LISTAR POR GRUPO
    --
    -- Devuelve únicamente registros ACTIVO.
    -- ========================================================

    PROCEDURE LISTAR_POR_GRUPO(
        p_grupo     IN VARCHAR2,
        p_resultado OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR
            SELECT
                catalogo_id,
                codigo,
                nombre,
                descripcion,
                naturaleza
            FROM MB_CATALOGO_BANCARIO
            WHERE grupo = p_grupo
              AND estado = 'ACTIVO'
            ORDER BY nombre;

    END LISTAR_POR_GRUPO;


    -- ========================================================
    -- CREAR
    --
    -- Reglas:
    -- - El ID se genera dentro de Oracle.
    -- - No se recibe catalogo_id desde frontend ni backend.
    -- - Se validan flags, naturaleza y estado.
    -- - grupo + codigo no pueden duplicarse.
    -- ========================================================

    PROCEDURE CREAR(
        p_grupo                 IN VARCHAR2,
        p_codigo                IN VARCHAR2,
        p_nombre                IN VARCHAR2,
        p_descripcion           IN VARCHAR2,
        p_aplica_a              IN VARCHAR2,
        p_naturaleza            IN CHAR,
        p_requiere_comentario   IN CHAR,
        p_requiere_evidencia    IN CHAR,
        p_permite_reversion     IN CHAR,
        p_estado                IN VARCHAR2,
        p_catalogo_id           OUT NUMBER
    ) AS
    BEGIN

        VALIDAR_FLAGS(
            p_requiere_comentario,
            p_requiere_evidencia,
            p_permite_reversion
        );


        VALIDAR_NATURALEZA(
            p_grupo,
            p_naturaleza
        );


        VALIDAR_ESTADO(
            p_estado
        );


        p_catalogo_id :=
            MB_SEQ_CATALOGO_BANCARIO.NEXTVAL;


        INSERT INTO MB_CATALOGO_BANCARIO (
            catalogo_id,
            grupo,
            codigo,
            nombre,
            descripcion,
            aplica_a,
            naturaleza,
            requiere_comentario,
            requiere_evidencia,
            permite_reversion,
            estado
        )
        VALUES (
            p_catalogo_id,
            p_grupo,
            p_codigo,
            p_nombre,
            p_descripcion,
            p_aplica_a,
            p_naturaleza,
            p_requiere_comentario,
            p_requiere_evidencia,
            p_permite_reversion,
            p_estado
        );


    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN

            RAISE_APPLICATION_ERROR(
                -20031,
                'Ya existe un catálogo con el grupo y código indicados.'
            );

    END CREAR;


    -- ========================================================
    -- ACTUALIZAR
    --
    -- Reglas:
    -- - El catálogo debe existir.
    -- - grupo, codigo y estado no se modifican.
    -- - Se validan flags y naturaleza.
    -- ========================================================

    PROCEDURE ACTUALIZAR(
        p_catalogo_id           IN NUMBER,
        p_nombre                IN VARCHAR2,
        p_descripcion           IN VARCHAR2,
        p_aplica_a              IN VARCHAR2,
        p_naturaleza            IN CHAR,
        p_requiere_comentario   IN CHAR,
        p_requiere_evidencia    IN CHAR,
        p_permite_reversion     IN CHAR
    ) AS

        v_grupo MB_CATALOGO_BANCARIO.grupo%TYPE;

    BEGIN

        BEGIN

            SELECT grupo
              INTO v_grupo
              FROM MB_CATALOGO_BANCARIO
             WHERE catalogo_id = p_catalogo_id;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN

                RAISE_APPLICATION_ERROR(
                    -20032,
                    'El catálogo indicado no existe.'
                );

        END;


        VALIDAR_FLAGS(
            p_requiere_comentario,
            p_requiere_evidencia,
            p_permite_reversion
        );


        VALIDAR_NATURALEZA(
            v_grupo,
            p_naturaleza
        );


        UPDATE MB_CATALOGO_BANCARIO
           SET nombre               = p_nombre,
               descripcion          = p_descripcion,
               aplica_a             = p_aplica_a,
               naturaleza           = p_naturaleza,
               requiere_comentario  = p_requiere_comentario,
               requiere_evidencia   = p_requiere_evidencia,
               permite_reversion    = p_permite_reversion
         WHERE catalogo_id = p_catalogo_id;


        IF SQL%ROWCOUNT = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20032,
                'El catálogo indicado no existe.'
            );

        END IF;

    END ACTUALIZAR;


    -- ========================================================
    -- CAMBIAR ESTADO
    --
    -- Reglas:
    -- - Solo se permiten ACTIVO e INACTIVO.
    -- - El estado no puede ser NULL.
    -- - El catálogo debe existir.
    -- ========================================================

    PROCEDURE CAMBIAR_ESTADO(
        p_catalogo_id IN NUMBER,
        p_estado      IN VARCHAR2
    ) AS
    BEGIN

        VALIDAR_ESTADO(
            p_estado
        );


        UPDATE MB_CATALOGO_BANCARIO
           SET estado = p_estado
         WHERE catalogo_id = p_catalogo_id;


        IF SQL%ROWCOUNT = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20032,
                'El catálogo indicado no existe.'
            );

        END IF;

    END CAMBIAR_ESTADO;


END PKG_MB_CATALOGOS;
/

-- PACKAGE_BODY PKG_MB_CHEQUERAS
CREATE OR REPLACE PACKAGE BODY "PKG_MB_CHEQUERAS" AS

    ------------------------------------------------------------
    -- VALIDAR CUENTA
    ------------------------------------------------------------
    PROCEDURE VALIDAR_CUENTA(
        p_cuenta_id IN NUMBER
    ) IS
        v_estado  MB_CUENTA_BANCARIA.estado%TYPE;
        v_cheques MB_CUENTA_BANCARIA.permite_cheques%TYPE;
    BEGIN

        SELECT estado,
               permite_cheques
        INTO   v_estado,
               v_cheques
        FROM MB_CUENTA_BANCARIA
        WHERE cuenta_id = p_cuenta_id;

        IF v_estado <> 'ACTIVA' THEN
            RAISE_APPLICATION_ERROR(
                -20001,
                'La cuenta bancaria debe estar ACTIVA para utilizar chequeras.'
            );
        END IF;

        IF v_cheques <> 'S' THEN
            RAISE_APPLICATION_ERROR(
                -20002,
                'La cuenta bancaria seleccionada no permite cheques.'
            );
        END IF;

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR(
                -20003,
                'La cuenta bancaria indicada no existe.'
            );

    END VALIDAR_CUENTA;


    ------------------------------------------------------------
    -- VALIDAR RANGO
    ------------------------------------------------------------
    PROCEDURE VALIDAR_RANGO(
        p_cuenta_id      IN NUMBER,
        p_serie          IN VARCHAR2,
        p_numero_inicial IN NUMBER,
        p_numero_final   IN NUMBER,
        p_chequera_id    IN NUMBER DEFAULT NULL
    ) IS
        v_total NUMBER;
    BEGIN

        IF p_numero_inicial IS NULL
           OR p_numero_final IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20004,
                'El número inicial y el número final son obligatorios.'
            );

        END IF;

        IF p_numero_inicial > p_numero_final THEN

            RAISE_APPLICATION_ERROR(
                -20005,
                'El número inicial no puede ser mayor que el número final.'
            );

        END IF;

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CHEQUERA
        WHERE cuenta_id = p_cuenta_id

          AND NVL(
                UPPER(TRIM(serie)),
                '#SIN_SERIE#'
              )
              =
              NVL(
                UPPER(TRIM(p_serie)),
                '#SIN_SERIE#'
              )

          AND p_numero_inicial <= numero_final
          AND p_numero_final >= numero_inicial

          AND (
                p_chequera_id IS NULL
                OR chequera_id <> p_chequera_id
              );

        IF v_total > 0 THEN

            RAISE_APPLICATION_ERROR(
                -20006,
                'El rango de cheques se superpone con otra chequera de la misma cuenta y serie.'
            );

        END IF;

    END VALIDAR_RANGO;


    ------------------------------------------------------------
    -- VALIDAR ESTADO
    ------------------------------------------------------------
    PROCEDURE VALIDAR_ESTADO(
        p_estado IN VARCHAR2
    ) IS
        v_estado VARCHAR2(15);
    BEGIN

        v_estado := UPPER(TRIM(p_estado));

        IF v_estado IS NULL
           OR v_estado NOT IN (
                'BORRADOR',
                'ACTIVA',
                'AGOTADA',
                'INACTIVA'
           ) THEN

            RAISE_APPLICATION_ERROR(
                -20007,
                'Estado de chequera no válido.'
            );

        END IF;

    END VALIDAR_ESTADO;


    ------------------------------------------------------------
    -- LISTAR
    ------------------------------------------------------------
    PROCEDURE LISTAR(
        p_resultado OUT SYS_REFCURSOR
    ) IS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                ch.chequera_id,
                ch.cuenta_id,
                cb.codigo_cuenta,
                cb.numero_cuenta,
                cb.nombre_interno,
                b.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                ch.serie,
                ch.numero_inicial,
                ch.numero_final,
                ch.fecha_recepcion,
                ch.custodio_id,
                ch.ubicacion_fisica,
                ch.documento_recepcion_id,
                ch.estado,
                ch.observaciones

            FROM MB_CHEQUERA ch

            JOIN MB_CUENTA_BANCARIA cb
              ON cb.cuenta_id = ch.cuenta_id

            JOIN MB_BANCO b
              ON b.banco_id = cb.banco_id

            ORDER BY
                b.nombre,
                cb.nombre_interno,
                ch.serie,
                ch.numero_inicial;

    END LISTAR;


    ------------------------------------------------------------
    -- LISTAR POR CUENTA
    ------------------------------------------------------------
    PROCEDURE LISTAR_POR_CUENTA(
        p_cuenta_id IN NUMBER,
        p_resultado OUT SYS_REFCURSOR
    ) IS
        v_total NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CUENTA_BANCARIA
        WHERE cuenta_id = p_cuenta_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20008,
                'La cuenta bancaria indicada no existe.'
            );

        END IF;

        OPEN p_resultado FOR

            SELECT
                ch.chequera_id,
                ch.cuenta_id,
                cb.codigo_cuenta,
                cb.numero_cuenta,
                cb.nombre_interno,
                b.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                ch.serie,
                ch.numero_inicial,
                ch.numero_final,
                ch.fecha_recepcion,
                ch.custodio_id,
                ch.ubicacion_fisica,
                ch.documento_recepcion_id,
                ch.estado,
                ch.observaciones

            FROM MB_CHEQUERA ch

            JOIN MB_CUENTA_BANCARIA cb
              ON cb.cuenta_id = ch.cuenta_id

            JOIN MB_BANCO b
              ON b.banco_id = cb.banco_id

            WHERE ch.cuenta_id = p_cuenta_id

            ORDER BY
                ch.serie,
                ch.numero_inicial;

    END LISTAR_POR_CUENTA;


    ------------------------------------------------------------
    -- OBTENER
    ------------------------------------------------------------
    PROCEDURE OBTENER(
        p_chequera_id IN NUMBER,
        p_resultado OUT SYS_REFCURSOR
    ) IS
        v_total NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CHEQUERA
        WHERE chequera_id = p_chequera_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20009,
                'La chequera indicada no existe.'
            );

        END IF;

        OPEN p_resultado FOR

            SELECT
                ch.chequera_id,
                ch.cuenta_id,
                cb.codigo_cuenta,
                cb.numero_cuenta,
                cb.nombre_interno,
                b.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                ch.serie,
                ch.numero_inicial,
                ch.numero_final,
                ch.fecha_recepcion,
                ch.custodio_id,
                ch.ubicacion_fisica,
                ch.documento_recepcion_id,
                ch.estado,
                ch.observaciones

            FROM MB_CHEQUERA ch

            JOIN MB_CUENTA_BANCARIA cb
              ON cb.cuenta_id = ch.cuenta_id

            JOIN MB_BANCO b
              ON b.banco_id = cb.banco_id

            WHERE ch.chequera_id = p_chequera_id;

    END OBTENER;


    ------------------------------------------------------------
    -- CREAR
    ------------------------------------------------------------
    PROCEDURE CREAR(
        p_cuenta_id IN NUMBER,
        p_serie IN VARCHAR2,
        p_numero_inicial IN NUMBER,
        p_numero_final IN NUMBER,
        p_fecha_recepcion IN DATE,
        p_custodio_id IN NUMBER,
        p_ubicacion_fisica IN VARCHAR2,
        p_documento_recepcion_id IN NUMBER,
        p_estado IN VARCHAR2,
        p_observaciones IN VARCHAR2,
        p_chequera_id OUT NUMBER
    ) IS
    BEGIN

        VALIDAR_CUENTA(
            p_cuenta_id
        );

        VALIDAR_RANGO(
            p_cuenta_id,
            p_serie,
            p_numero_inicial,
            p_numero_final,
            NULL
        );

        VALIDAR_ESTADO(
            p_estado
        );

        IF p_fecha_recepcion IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20010,
                'La fecha de recepción es obligatoria.'
            );

        END IF;

        IF p_custodio_id IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20011,
                'El custodio de la chequera es obligatorio.'
            );

        END IF;

        SELECT SEQ_MB_CHEQUERA.NEXTVAL
        INTO p_chequera_id
        FROM DUAL;

        INSERT INTO MB_CHEQUERA(
            chequera_id,
            cuenta_id,
            serie,
            numero_inicial,
            numero_final,
            fecha_recepcion,
            custodio_id,
            ubicacion_fisica,
            documento_recepcion_id,
            estado,
            observaciones
        )
        VALUES(
            p_chequera_id,
            p_cuenta_id,
            UPPER(TRIM(p_serie)),
            p_numero_inicial,
            p_numero_final,
            p_fecha_recepcion,
            p_custodio_id,
            TRIM(p_ubicacion_fisica),
            p_documento_recepcion_id,
            UPPER(TRIM(p_estado)),
            TRIM(p_observaciones)
        );

    END CREAR;


    ------------------------------------------------------------
    -- ACTUALIZAR
    ------------------------------------------------------------
    PROCEDURE ACTUALIZAR(
        p_chequera_id IN NUMBER,
        p_cuenta_id IN NUMBER,
        p_serie IN VARCHAR2,
        p_numero_inicial IN NUMBER,
        p_numero_final IN NUMBER,
        p_fecha_recepcion IN DATE,
        p_custodio_id IN NUMBER,
        p_ubicacion_fisica IN VARCHAR2,
        p_documento_recepcion_id IN NUMBER,
        p_observaciones IN VARCHAR2
    ) IS
        v_total NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CHEQUERA
        WHERE chequera_id = p_chequera_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20012,
                'La chequera indicada no existe.'
            );

        END IF;

        VALIDAR_CUENTA(
            p_cuenta_id
        );

        VALIDAR_RANGO(
            p_cuenta_id,
            p_serie,
            p_numero_inicial,
            p_numero_final,
            p_chequera_id
        );

        IF p_fecha_recepcion IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20013,
                'La fecha de recepción es obligatoria.'
            );

        END IF;

        IF p_custodio_id IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20014,
                'El custodio de la chequera es obligatorio.'
            );

        END IF;

        UPDATE MB_CHEQUERA
        SET
            cuenta_id = p_cuenta_id,
            serie = UPPER(TRIM(p_serie)),
            numero_inicial = p_numero_inicial,
            numero_final = p_numero_final,
            fecha_recepcion = p_fecha_recepcion,
            custodio_id = p_custodio_id,
            ubicacion_fisica = TRIM(p_ubicacion_fisica),
            documento_recepcion_id = p_documento_recepcion_id,
            observaciones = TRIM(p_observaciones)

        WHERE chequera_id = p_chequera_id;

    END ACTUALIZAR;


    ------------------------------------------------------------
    -- CAMBIAR ESTADO
    ------------------------------------------------------------
    PROCEDURE CAMBIAR_ESTADO(
        p_chequera_id IN NUMBER,
        p_estado IN VARCHAR2
    ) IS
        v_total  NUMBER;
        v_cuenta NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CHEQUERA
        WHERE chequera_id = p_chequera_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20015,
                'La chequera indicada no existe.'
            );

        END IF;

        VALIDAR_ESTADO(
            p_estado
        );

        IF UPPER(TRIM(p_estado)) = 'ACTIVA' THEN

            SELECT cuenta_id
            INTO v_cuenta
            FROM MB_CHEQUERA
            WHERE chequera_id = p_chequera_id;

            VALIDAR_CUENTA(
                v_cuenta
            );

        END IF;

        UPDATE MB_CHEQUERA
        SET estado = UPPER(TRIM(p_estado))
        WHERE chequera_id = p_chequera_id;

    END CAMBIAR_ESTADO;


    ------------------------------------------------------------
    -- DELETE LÓGICO
    ------------------------------------------------------------
    PROCEDURE DESACTIVAR(
        p_chequera_id IN NUMBER
    ) IS
    BEGIN

        CAMBIAR_ESTADO(
            p_chequera_id => p_chequera_id,
            p_estado      => 'INACTIVA'
        );

    END DESACTIVAR;


END PKG_MB_CHEQUERAS;
/

-- PACKAGE_BODY PKG_MB_CUENTAS
CREATE OR REPLACE PACKAGE BODY "PKG_MB_CUENTAS" AS

    ------------------------------------------------------------------
    -- VALIDACIONES INTERNAS
    ------------------------------------------------------------------

    FUNCTION EXISTE_BANCO (
        p_banco_id IN MB_BANCO.banco_id%TYPE
    ) RETURN BOOLEAN AS
        v_total NUMBER;
    BEGIN
        SELECT COUNT(*)
        INTO v_total
        FROM MB_BANCO
        WHERE banco_id = p_banco_id;

        RETURN v_total > 0;
    END EXISTE_BANCO;


    FUNCTION BANCO_ESTA_ACTIVO (
        p_banco_id IN MB_BANCO.banco_id%TYPE
    ) RETURN BOOLEAN AS
        v_total NUMBER;
    BEGIN
        SELECT COUNT(*)
        INTO v_total
        FROM MB_BANCO
        WHERE banco_id = p_banco_id
          AND estado = 'ACTIVO';

        RETURN v_total > 0;
    END BANCO_ESTA_ACTIVO;


    FUNCTION EXISTE_TIPO_CUENTA (
        p_tipo_cuenta_id IN MB_CATALOGO_BANCARIO.catalogo_id%TYPE
    ) RETURN BOOLEAN AS
        v_total NUMBER;
    BEGIN
        SELECT COUNT(*)
        INTO v_total
        FROM MB_CATALOGO_BANCARIO
        WHERE catalogo_id = p_tipo_cuenta_id
          AND grupo = 'TIPO_CUENTA';

        RETURN v_total > 0;
    END EXISTE_TIPO_CUENTA;


    FUNCTION TIPO_CUENTA_ESTA_ACTIVO (
        p_tipo_cuenta_id IN MB_CATALOGO_BANCARIO.catalogo_id%TYPE
    ) RETURN BOOLEAN AS
        v_total NUMBER;
    BEGIN
        SELECT COUNT(*)
        INTO v_total
        FROM MB_CATALOGO_BANCARIO
        WHERE catalogo_id = p_tipo_cuenta_id
          AND grupo = 'TIPO_CUENTA'
          AND estado = 'ACTIVO';

        RETURN v_total > 0;
    END TIPO_CUENTA_ESTA_ACTIVO;


    FUNCTION EXISTE_CUENTA (
        p_cuenta_id IN MB_CUENTA_BANCARIA.cuenta_id%TYPE
    ) RETURN BOOLEAN AS
        v_total NUMBER;
    BEGIN
        SELECT COUNT(*)
        INTO v_total
        FROM MB_CUENTA_BANCARIA
        WHERE cuenta_id = p_cuenta_id;

        RETURN v_total > 0;
    END EXISTE_CUENTA;


    FUNCTION EXISTE_CUENTA_PROVEEDOR (
        p_cta_proveedor_id
            IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE
    ) RETURN BOOLEAN AS
        v_total NUMBER;
    BEGIN
        SELECT COUNT(*)
        INTO v_total
        FROM MB_CUENTA_BANCARIA_PROVEEDOR
        WHERE cta_proveedor_id = p_cta_proveedor_id;

        RETURN v_total > 0;
    END EXISTE_CUENTA_PROVEEDOR;


    PROCEDURE VALIDAR_ESTADO_CUENTA (
        p_estado IN MB_CUENTA_BANCARIA.estado%TYPE
    ) AS
    BEGIN
        IF p_estado IS NULL
           OR p_estado NOT IN (
                'BORRADOR',
                'ACTIVA',
                'INACTIVA',
                'CERRADA'
           ) THEN
            RAISE_APPLICATION_ERROR(
                -20001,
                'Estado de cuenta bancaria no valido.'
            );
        END IF;
    END VALIDAR_ESTADO_CUENTA;


    PROCEDURE VALIDAR_ESTADO_CUENTA_PROV (
        p_estado IN MB_CUENTA_BANCARIA_PROVEEDOR.estado%TYPE
    ) AS
    BEGIN
        IF p_estado IS NULL
           OR p_estado NOT IN (
                'PENDIENTE',
                'EN_REVISION',
                'VERIFICADA',
                'RECHAZADA',
                'BLOQUEADA',
                'INACTIVA'
           ) THEN
            RAISE_APPLICATION_ERROR(
                -20002,
                'Estado de cuenta bancaria de proveedor no valido.'
            );
        END IF;
    END VALIDAR_ESTADO_CUENTA_PROV;


    ------------------------------------------------------------------
    -- CUENTAS BANCARIAS EMPRESARIALES
    ------------------------------------------------------------------

    PROCEDURE LISTAR_CUENTAS (
        p_estado     IN MB_CUENTA_BANCARIA.estado%TYPE,
        p_banco_id   IN MB_CUENTA_BANCARIA.banco_id%TYPE,
        p_moneda_id  IN MB_CUENTA_BANCARIA.moneda_id%TYPE,
        p_resultado  OUT SYS_REFCURSOR
    ) AS
    BEGIN
        OPEN p_resultado FOR
            SELECT
                c.cuenta_id,
                c.empresa_id,
                c.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                c.moneda_id,
                c.tipo_cuenta_id,
                tc.codigo AS tipo_cuenta_codigo,
                tc.nombre AS tipo_cuenta_nombre,
                c.responsable_id,
                c.codigo_cuenta,
                c.numero_cuenta,
                c.nombre_interno,
                c.saldo_inicial,
                c.fecha_apertura,
                c.uso_principal,
                c.permite_cobros,
                c.permite_pagos,
                c.permite_cheques,
                c.permite_transferencias,
                c.fecha_cierre,
                c.estado,
                c.observaciones,
                c.creado_por,
                c.creado_en,
                c.modificado_por,
                c.modificado_en
            FROM MB_CUENTA_BANCARIA c
            INNER JOIN MB_BANCO b
                ON b.banco_id = c.banco_id
            INNER JOIN MB_CATALOGO_BANCARIO tc
                ON tc.catalogo_id = c.tipo_cuenta_id
            WHERE (p_estado IS NULL OR c.estado = p_estado)
              AND (p_banco_id IS NULL OR c.banco_id = p_banco_id)
              AND (p_moneda_id IS NULL OR c.moneda_id = p_moneda_id)
            ORDER BY c.nombre_interno, c.cuenta_id;
    END LISTAR_CUENTAS;


    PROCEDURE LISTAR_CUENTAS_ACTIVAS (
        p_banco_id   IN MB_CUENTA_BANCARIA.banco_id%TYPE,
        p_moneda_id  IN MB_CUENTA_BANCARIA.moneda_id%TYPE,
        p_resultado  OUT SYS_REFCURSOR
    ) AS
    BEGIN
        OPEN p_resultado FOR
            SELECT
                c.cuenta_id,
                c.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                c.moneda_id,
                c.tipo_cuenta_id,
                tc.codigo AS tipo_cuenta_codigo,
                tc.nombre AS tipo_cuenta_nombre,
                c.codigo_cuenta,
                c.numero_cuenta,
                c.nombre_interno,
                c.uso_principal,
                c.permite_cobros,
                c.permite_pagos,
                c.permite_cheques,
                c.permite_transferencias,
                c.estado
            FROM MB_CUENTA_BANCARIA c
            INNER JOIN MB_BANCO b
                ON b.banco_id = c.banco_id
            INNER JOIN MB_CATALOGO_BANCARIO tc
                ON tc.catalogo_id = c.tipo_cuenta_id
            WHERE c.estado = 'ACTIVA'
              AND (p_banco_id IS NULL OR c.banco_id = p_banco_id)
              AND (p_moneda_id IS NULL OR c.moneda_id = p_moneda_id)
            ORDER BY b.nombre, c.nombre_interno;
    END LISTAR_CUENTAS_ACTIVAS;


    PROCEDURE OBTENER_CUENTA (
        p_cuenta_id  IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,
        p_resultado  OUT SYS_REFCURSOR
    ) AS
    BEGIN
        IF p_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20003,
                'Debe indicar el identificador de la cuenta bancaria.'
            );
        END IF;

        IF NOT EXISTE_CUENTA(p_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20004,
                'La cuenta bancaria indicada no existe.'
            );
        END IF;

        OPEN p_resultado FOR
            SELECT
                c.cuenta_id,
                c.empresa_id,
                c.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                c.moneda_id,
                c.tipo_cuenta_id,
                tc.codigo AS tipo_cuenta_codigo,
                tc.nombre AS tipo_cuenta_nombre,
                c.responsable_id,
                c.codigo_cuenta,
                c.numero_cuenta,
                c.nombre_interno,
                c.saldo_inicial,
                c.fecha_apertura,
                c.uso_principal,
                c.permite_cobros,
                c.permite_pagos,
                c.permite_cheques,
                c.permite_transferencias,
                c.fecha_cierre,
                c.estado,
                c.observaciones,
                c.creado_por,
                c.creado_en,
                c.modificado_por,
                c.modificado_en
            FROM MB_CUENTA_BANCARIA c
            INNER JOIN MB_BANCO b
                ON b.banco_id = c.banco_id
            INNER JOIN MB_CATALOGO_BANCARIO tc
                ON tc.catalogo_id = c.tipo_cuenta_id
            WHERE c.cuenta_id = p_cuenta_id;
    END OBTENER_CUENTA;


    PROCEDURE CREAR_CUENTA (
        p_empresa_id              IN MB_CUENTA_BANCARIA.empresa_id%TYPE,
        p_banco_id                IN MB_CUENTA_BANCARIA.banco_id%TYPE,
        p_moneda_id               IN MB_CUENTA_BANCARIA.moneda_id%TYPE,
        p_tipo_cuenta_id          IN MB_CUENTA_BANCARIA.tipo_cuenta_id%TYPE,
        p_responsable_id          IN MB_CUENTA_BANCARIA.responsable_id%TYPE,
        p_numero_cuenta           IN MB_CUENTA_BANCARIA.numero_cuenta%TYPE,
        p_nombre_interno          IN MB_CUENTA_BANCARIA.nombre_interno%TYPE,
        p_saldo_inicial           IN MB_CUENTA_BANCARIA.saldo_inicial%TYPE,
        p_fecha_apertura          IN MB_CUENTA_BANCARIA.fecha_apertura%TYPE,
        p_uso_principal           IN MB_CUENTA_BANCARIA.uso_principal%TYPE,
        p_permite_cobros          IN MB_CUENTA_BANCARIA.permite_cobros%TYPE,
        p_permite_pagos           IN MB_CUENTA_BANCARIA.permite_pagos%TYPE,
        p_permite_cheques         IN MB_CUENTA_BANCARIA.permite_cheques%TYPE,
        p_permite_transferencias  IN MB_CUENTA_BANCARIA.permite_transferencias%TYPE,
        p_estado                  IN MB_CUENTA_BANCARIA.estado%TYPE,
        p_observaciones           IN MB_CUENTA_BANCARIA.observaciones%TYPE,
        p_creado_por              IN MB_CUENTA_BANCARIA.creado_por%TYPE,
        p_cuenta_id               OUT MB_CUENTA_BANCARIA.cuenta_id%TYPE
    ) AS
        v_total          NUMBER;
        v_codigo_cuenta  MB_CUENTA_BANCARIA.codigo_cuenta%TYPE;
    BEGIN

        IF p_banco_id IS NULL OR NOT EXISTE_BANCO(p_banco_id) THEN
            RAISE_APPLICATION_ERROR(-20007, 'El banco indicado no existe.');
        END IF;

        IF NOT BANCO_ESTA_ACTIVO(p_banco_id) THEN
            RAISE_APPLICATION_ERROR(
                -20042,
                'El banco indicado se encuentra inactivo y no puede asignarse a una cuenta nueva.'
            );
        END IF;

        IF p_tipo_cuenta_id IS NULL
           OR NOT EXISTE_TIPO_CUENTA(p_tipo_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20008,
                'El tipo de cuenta indicado no existe.'
            );
        END IF;

        IF NOT TIPO_CUENTA_ESTA_ACTIVO(p_tipo_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20054,
                'El tipo de cuenta indicado se encuentra inactivo y no puede asignarse a una cuenta nueva.'
            );
        END IF;

        VALIDAR_ESTADO_CUENTA(p_estado);

        IF p_estado NOT IN ('BORRADOR', 'ACTIVA') THEN
            RAISE_APPLICATION_ERROR(
                -20053,
                'El estado inicial de una cuenta bancaria solo puede ser BORRADOR o ACTIVA.'
            );
        END IF;

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CUENTA_BANCARIA
        WHERE empresa_id = p_empresa_id
          AND banco_id = p_banco_id
          AND numero_cuenta = p_numero_cuenta;

        IF v_total > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20010,
                'La cuenta bancaria ya se encuentra registrada para la empresa y banco indicados.'
            );
        END IF;

        p_cuenta_id := SEQ_MB_CUENTA_BANCARIA.NEXTVAL;

        v_codigo_cuenta := 'CTA-' || TO_CHAR(p_cuenta_id);

        INSERT INTO MB_CUENTA_BANCARIA (
            cuenta_id,
            empresa_id,
            banco_id,
            moneda_id,
            tipo_cuenta_id,
            responsable_id,
            codigo_cuenta,
            numero_cuenta,
            nombre_interno,
            saldo_inicial,
            fecha_apertura,
            uso_principal,
            permite_cobros,
            permite_pagos,
            permite_cheques,
            permite_transferencias,
            fecha_cierre,
            estado,
            observaciones,
            creado_por,
            creado_en
        )
        VALUES (
            p_cuenta_id,
            p_empresa_id,
            p_banco_id,
            p_moneda_id,
            p_tipo_cuenta_id,
            p_responsable_id,
            v_codigo_cuenta,
            p_numero_cuenta,
            p_nombre_interno,
            p_saldo_inicial,
            p_fecha_apertura,
            p_uso_principal,
            p_permite_cobros,
            p_permite_pagos,
            p_permite_cheques,
            p_permite_transferencias,
            NULL,
            p_estado,
            p_observaciones,
            p_creado_por,
            SYSTIMESTAMP
        );

    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20011,
                'No se pudo crear la cuenta porque existe un registro duplicado.'
            );

    END CREAR_CUENTA;


    PROCEDURE ACTUALIZAR_CUENTA (
        p_cuenta_id               IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,
        p_empresa_id              IN MB_CUENTA_BANCARIA.empresa_id%TYPE,
        p_banco_id                IN MB_CUENTA_BANCARIA.banco_id%TYPE,
        p_moneda_id               IN MB_CUENTA_BANCARIA.moneda_id%TYPE,
        p_tipo_cuenta_id          IN MB_CUENTA_BANCARIA.tipo_cuenta_id%TYPE,
        p_responsable_id          IN MB_CUENTA_BANCARIA.responsable_id%TYPE,
        p_codigo_cuenta           IN MB_CUENTA_BANCARIA.codigo_cuenta%TYPE,
        p_numero_cuenta           IN MB_CUENTA_BANCARIA.numero_cuenta%TYPE,
        p_nombre_interno          IN MB_CUENTA_BANCARIA.nombre_interno%TYPE,
        p_saldo_inicial           IN MB_CUENTA_BANCARIA.saldo_inicial%TYPE,
        p_fecha_apertura          IN MB_CUENTA_BANCARIA.fecha_apertura%TYPE,
        p_uso_principal           IN MB_CUENTA_BANCARIA.uso_principal%TYPE,
        p_permite_cobros          IN MB_CUENTA_BANCARIA.permite_cobros%TYPE,
        p_permite_pagos           IN MB_CUENTA_BANCARIA.permite_pagos%TYPE,
        p_permite_cheques         IN MB_CUENTA_BANCARIA.permite_cheques%TYPE,
        p_permite_transferencias  IN MB_CUENTA_BANCARIA.permite_transferencias%TYPE,
        p_fecha_cierre            IN MB_CUENTA_BANCARIA.fecha_cierre%TYPE,
        p_observaciones           IN MB_CUENTA_BANCARIA.observaciones%TYPE,
        p_modificado_por          IN MB_CUENTA_BANCARIA.modificado_por%TYPE
    ) AS
        v_total               NUMBER;
        v_estado_actual       MB_CUENTA_BANCARIA.estado%TYPE;
        v_banco_actual        MB_CUENTA_BANCARIA.banco_id%TYPE;
        v_moneda_actual       MB_CUENTA_BANCARIA.moneda_id%TYPE;
        v_numero_actual       MB_CUENTA_BANCARIA.numero_cuenta%TYPE;
        v_tipo_cuenta_actual  MB_CUENTA_BANCARIA.tipo_cuenta_id%TYPE;
    BEGIN

        IF p_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20012,
                'Debe indicar el identificador de la cuenta bancaria.'
            );
        END IF;

        IF NOT EXISTE_CUENTA(p_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20013,
                'La cuenta bancaria que desea actualizar no existe.'
            );
        END IF;

        SELECT
            estado,
            banco_id,
            moneda_id,
            numero_cuenta,
            tipo_cuenta_id
        INTO
            v_estado_actual,
            v_banco_actual,
            v_moneda_actual,
            v_numero_actual,
            v_tipo_cuenta_actual
        FROM MB_CUENTA_BANCARIA
        WHERE cuenta_id = p_cuenta_id
        FOR UPDATE;

        IF v_estado_actual IN ('INACTIVA', 'CERRADA') THEN
            RAISE_APPLICATION_ERROR(
                -20051,
                'Una cuenta bancaria INACTIVA o CERRADA no puede editarse.'
            );
        END IF;

        IF p_banco_id IS NULL OR NOT EXISTE_BANCO(p_banco_id) THEN
            RAISE_APPLICATION_ERROR(
                -20014,
                'El banco indicado no existe.'
            );
        END IF;

        IF p_tipo_cuenta_id IS NULL
           OR NOT EXISTE_TIPO_CUENTA(p_tipo_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20015,
                'El tipo de cuenta indicado no existe.'
            );
        END IF;

        IF NVL(v_tipo_cuenta_actual, -1) <> NVL(p_tipo_cuenta_id, -1)
           AND NOT TIPO_CUENTA_ESTA_ACTIVO(p_tipo_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20054,
                'El tipo de cuenta indicado se encuentra inactivo y no puede asignarse a la cuenta.'
            );
        END IF;

        SELECT COUNT(*)
        INTO v_total
        FROM MB_MOVIMIENTO_BANCARIO
        WHERE cuenta_id = p_cuenta_id;

        IF v_total > 0
           AND (
                NVL(v_banco_actual, -1) <> NVL(p_banco_id, -1)
                OR NVL(v_moneda_actual, -1) <> NVL(p_moneda_id, -1)
                OR NVL(v_numero_actual, '#NULL#')
                   <> NVL(p_numero_cuenta, '#NULL#')
           ) THEN
            RAISE_APPLICATION_ERROR(
                -20052,
                'No se puede cambiar banco, numero de cuenta o moneda despues del primer movimiento.'
            );
        END IF;

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CUENTA_BANCARIA
        WHERE codigo_cuenta = p_codigo_cuenta
          AND cuenta_id <> p_cuenta_id;

        IF v_total > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20016,
                'El codigo de cuenta bancaria ya pertenece a otra cuenta.'
            );
        END IF;

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CUENTA_BANCARIA
        WHERE empresa_id = p_empresa_id
          AND banco_id = p_banco_id
          AND numero_cuenta = p_numero_cuenta
          AND cuenta_id <> p_cuenta_id;

        IF v_total > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20017,
                'Ya existe otra cuenta con la misma empresa, banco y numero de cuenta.'
            );
        END IF;

        UPDATE MB_CUENTA_BANCARIA
        SET
            empresa_id = p_empresa_id,
            banco_id = p_banco_id,
            moneda_id = p_moneda_id,
            tipo_cuenta_id = p_tipo_cuenta_id,
            responsable_id = p_responsable_id,
            codigo_cuenta = p_codigo_cuenta,
            numero_cuenta = p_numero_cuenta,
            nombre_interno = p_nombre_interno,
            saldo_inicial = p_saldo_inicial,
            fecha_apertura = p_fecha_apertura,
            uso_principal = p_uso_principal,
            permite_cobros = p_permite_cobros,
            permite_pagos = p_permite_pagos,
            permite_cheques = p_permite_cheques,
            permite_transferencias = p_permite_transferencias,
            observaciones = p_observaciones,
            modificado_por = p_modificado_por,
            modificado_en = SYSTIMESTAMP
        WHERE cuenta_id = p_cuenta_id;

    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20018,
                'No se pudo actualizar la cuenta porque existe un registro duplicado.'
            );

    END ACTUALIZAR_CUENTA;


    PROCEDURE CAMBIAR_ESTADO_CUENTA (
        p_cuenta_id       IN MB_CUENTA_BANCARIA.cuenta_id%TYPE,
        p_estado          IN MB_CUENTA_BANCARIA.estado%TYPE,
        p_modificado_por  IN MB_CUENTA_BANCARIA.modificado_por%TYPE
    ) AS
        v_estado_actual MB_CUENTA_BANCARIA.estado%TYPE;
        v_total         NUMBER;
    BEGIN

        IF p_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20019,
                'Debe indicar el identificador de la cuenta bancaria.'
            );
        END IF;

        IF NOT EXISTE_CUENTA(p_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20020,
                'La cuenta bancaria indicada no existe.'
            );
        END IF;

        VALIDAR_ESTADO_CUENTA(p_estado);

        SELECT estado
        INTO v_estado_actual
        FROM MB_CUENTA_BANCARIA
        WHERE cuenta_id = p_cuenta_id
        FOR UPDATE;

        IF v_estado_actual = p_estado THEN
            RAISE_APPLICATION_ERROR(
                -20044,
                'La cuenta ya se encuentra en el estado indicado.'
            );
        END IF;

        IF NOT (
            (v_estado_actual = 'BORRADOR'
             AND p_estado IN ('ACTIVA', 'INACTIVA'))
            OR
            (v_estado_actual = 'ACTIVA'
             AND p_estado IN ('INACTIVA', 'CERRADA'))
            OR
            (v_estado_actual = 'INACTIVA'
             AND p_estado = 'ACTIVA')
        ) THEN
            RAISE_APPLICATION_ERROR(
                -20045,
                'La transicion de estado solicitada no esta permitida para esta cuenta.'
            );
        END IF;

        IF p_estado = 'CERRADA' THEN

            SELECT COUNT(*)
            INTO v_total
            FROM MB_FONDO_COMPROMETIDO
            WHERE cuenta_id = p_cuenta_id
              AND estado = 'ACTIVO';

            IF v_total > 0 THEN
                RAISE_APPLICATION_ERROR(
                    -20046,
                    'No se puede cerrar la cuenta porque tiene fondos comprometidos activos.'
                );
            END IF;

            SELECT COUNT(*)
            INTO v_total
            FROM MB_MOVIMIENTO_BANCARIO
            WHERE cuenta_id = p_cuenta_id
              AND estado = 'REGISTRADO';

            IF v_total > 0 THEN
                RAISE_APPLICATION_ERROR(
                    -20047,
                    'No se puede cerrar la cuenta porque tiene movimientos pendientes de aplicar.'
                );
            END IF;

            SELECT COUNT(*)
            INTO v_total
            FROM MB_TRANSFERENCIA_BANCARIA
            WHERE (
                    cuenta_origen_id = p_cuenta_id
                    OR cuenta_destino_id = p_cuenta_id
                  )
              AND estado IN (
                    'BORRADOR',
                    'PROGRAMADA'
              );

            IF v_total > 0 THEN
                RAISE_APPLICATION_ERROR(
                    -20050,
                    'No se puede cerrar la cuenta porque tiene transferencias pendientes.'
                );
            END IF;

            SELECT COUNT(*)
            INTO v_total
            FROM MB_CHEQUE ch
            INNER JOIN MB_CHEQUERA cq
                ON cq.chequera_id = ch.chequera_id
            WHERE cq.cuenta_id = p_cuenta_id
              AND ch.estado IN (
                    'RESERVADO',
                    'EMITIDO',
                    'IMPRESO',
                    'ENTREGADO',
                    'EXTRAVIADO'
              );

            IF v_total > 0 THEN
                RAISE_APPLICATION_ERROR(
                    -20048,
                    'No se puede cerrar la cuenta porque tiene cheques pendientes o en circulacion.'
                );
            END IF;

            SELECT COUNT(*)
            INTO v_total
            FROM MB_CONCILIACION_BANCARIA cb
            INNER JOIN MB_ESTADO_CUENTA ec
                ON ec.estado_cuenta_id = cb.estado_cuenta_id
            WHERE ec.cuenta_id = p_cuenta_id
              AND cb.estado IN (
                    'ABIERTA',
                    'EN_PROCESO',
                    'REABIERTA'
              );

            IF v_total > 0 THEN
                RAISE_APPLICATION_ERROR(
                    -20049,
                    'No se puede cerrar la cuenta porque tiene conciliaciones pendientes.'
                );
            END IF;

        END IF;

        UPDATE MB_CUENTA_BANCARIA
        SET
            estado = p_estado,
            fecha_cierre =
                CASE
                    WHEN p_estado = 'CERRADA'
                    THEN TRUNC(SYSDATE)
                    ELSE fecha_cierre
                END,
            modificado_por = p_modificado_por,
            modificado_en = SYSTIMESTAMP
        WHERE cuenta_id = p_cuenta_id;

    END CAMBIAR_ESTADO_CUENTA;


    ------------------------------------------------------------------
    -- CUENTAS BANCARIAS DE PROVEEDORES
    ------------------------------------------------------------------

    PROCEDURE LISTAR_CUENTAS_PROVEEDOR (
        p_proveedor_id  IN MB_CUENTA_BANCARIA_PROVEEDOR.proveedor_id%TYPE,
        p_estado        IN MB_CUENTA_BANCARIA_PROVEEDOR.estado%TYPE,
        p_banco_id      IN MB_CUENTA_BANCARIA_PROVEEDOR.banco_id%TYPE,
        p_moneda_id     IN MB_CUENTA_BANCARIA_PROVEEDOR.moneda_id%TYPE,
        p_resultado     OUT SYS_REFCURSOR
    ) AS
    BEGIN
        OPEN p_resultado FOR
            SELECT
                TO_CHAR(cp.cta_proveedor_id) AS cta_proveedor_id,
                cp.proveedor_id,
                cp.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                cp.tipo_cuenta_id,
                tc.codigo AS tipo_cuenta_codigo,
                tc.nombre AS tipo_cuenta_nombre,
                cp.moneda_id,
                TO_CHAR(cp.cuenta_anterior_id) AS cuenta_anterior_id,
                cp.titular,
                cp.numero_cuenta,
                TO_CHAR(cp.carta_solicitud_doc_id) AS carta_solicitud_doc_id,
                TO_CHAR(cp.constancia_banco_doc_id) AS constancia_banco_doc_id,
                TO_CHAR(cp.representante_doc_id) AS representante_doc_id,
                cp.motivo_registro,
                cp.fecha_vigencia,
                cp.estado,
                cp.observaciones,
                cp.solicitado_por,
                cp.solicitado_en
            FROM MB_CUENTA_BANCARIA_PROVEEDOR cp
            INNER JOIN MB_BANCO b
                ON b.banco_id = cp.banco_id
            INNER JOIN MB_CATALOGO_BANCARIO tc
                ON tc.catalogo_id = cp.tipo_cuenta_id
            WHERE (p_proveedor_id IS NULL
                   OR cp.proveedor_id = p_proveedor_id)
              AND (p_estado IS NULL
                   OR cp.estado = p_estado)
              AND (p_banco_id IS NULL
                   OR cp.banco_id = p_banco_id)
              AND (p_moneda_id IS NULL
                   OR cp.moneda_id = p_moneda_id)
            ORDER BY cp.solicitado_en DESC,
                     cp.cta_proveedor_id DESC;

    END LISTAR_CUENTAS_PROVEEDOR;


    PROCEDURE LISTAR_CUENTAS_PROV_VERIFICADAS (
        p_proveedor_id  IN MB_CUENTA_BANCARIA_PROVEEDOR.proveedor_id%TYPE,
        p_resultado     OUT SYS_REFCURSOR
    ) AS
    BEGIN
        IF p_proveedor_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20021,
                'Debe indicar el proveedor para consultar sus cuentas verificadas.'
            );
        END IF;

        OPEN p_resultado FOR
            SELECT
                TO_CHAR(cp.cta_proveedor_id) AS cta_proveedor_id,
                cp.proveedor_id,
                cp.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                cp.tipo_cuenta_id,
                tc.codigo AS tipo_cuenta_codigo,
                tc.nombre AS tipo_cuenta_nombre,
                cp.moneda_id,
                cp.titular,
                cp.numero_cuenta,
                cp.fecha_vigencia,
                cp.estado
            FROM MB_CUENTA_BANCARIA_PROVEEDOR cp
            INNER JOIN MB_BANCO b
                ON b.banco_id = cp.banco_id
            INNER JOIN MB_CATALOGO_BANCARIO tc
                ON tc.catalogo_id = cp.tipo_cuenta_id
            WHERE cp.proveedor_id = p_proveedor_id
              AND cp.estado = 'VERIFICADA'
            ORDER BY b.nombre,
                     cp.titular,
                     cp.cta_proveedor_id;

    END LISTAR_CUENTAS_PROV_VERIFICADAS;


    PROCEDURE OBTENER_CUENTA_PROVEEDOR (
        p_cta_proveedor_id
            IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE,
        p_resultado
            OUT SYS_REFCURSOR
    ) AS
    BEGIN
        IF p_cta_proveedor_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20022,
                'Debe indicar el identificador de la cuenta bancaria del proveedor.'
            );
        END IF;

        IF NOT EXISTE_CUENTA_PROVEEDOR(p_cta_proveedor_id) THEN
            RAISE_APPLICATION_ERROR(
                -20023,
                'La cuenta bancaria del proveedor indicada no existe.'
            );
        END IF;

        OPEN p_resultado FOR
            SELECT
                TO_CHAR(cp.cta_proveedor_id) AS cta_proveedor_id,
                cp.proveedor_id,
                cp.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,
                cp.tipo_cuenta_id,
                tc.codigo AS tipo_cuenta_codigo,
                tc.nombre AS tipo_cuenta_nombre,
                cp.moneda_id,
                TO_CHAR(cp.cuenta_anterior_id) AS cuenta_anterior_id,
                cp.titular,
                cp.numero_cuenta,
                TO_CHAR(cp.carta_solicitud_doc_id) AS carta_solicitud_doc_id,
                TO_CHAR(cp.constancia_banco_doc_id) AS constancia_banco_doc_id,
                TO_CHAR(cp.representante_doc_id) AS representante_doc_id,
                cp.motivo_registro,
                cp.fecha_vigencia,
                cp.estado,
                cp.observaciones,
                cp.solicitado_por,
                cp.solicitado_en
            FROM MB_CUENTA_BANCARIA_PROVEEDOR cp
            INNER JOIN MB_BANCO b
                ON b.banco_id = cp.banco_id
            INNER JOIN MB_CATALOGO_BANCARIO tc
                ON tc.catalogo_id = cp.tipo_cuenta_id
            WHERE cp.cta_proveedor_id = p_cta_proveedor_id;

    END OBTENER_CUENTA_PROVEEDOR;


    PROCEDURE CREAR_CUENTA_PROVEEDOR (
        p_proveedor_id             IN MB_CUENTA_BANCARIA_PROVEEDOR.proveedor_id%TYPE,
        p_banco_id                 IN MB_CUENTA_BANCARIA_PROVEEDOR.banco_id%TYPE,
        p_tipo_cuenta_id           IN MB_CUENTA_BANCARIA_PROVEEDOR.tipo_cuenta_id%TYPE,
        p_moneda_id                IN MB_CUENTA_BANCARIA_PROVEEDOR.moneda_id%TYPE,
        p_cuenta_anterior_id       IN MB_CUENTA_BANCARIA_PROVEEDOR.cuenta_anterior_id%TYPE,
        p_titular                  IN MB_CUENTA_BANCARIA_PROVEEDOR.titular%TYPE,
        p_numero_cuenta            IN MB_CUENTA_BANCARIA_PROVEEDOR.numero_cuenta%TYPE,
        p_carta_solicitud_doc_id   IN MB_CUENTA_BANCARIA_PROVEEDOR.carta_solicitud_doc_id%TYPE,
        p_constancia_banco_doc_id  IN MB_CUENTA_BANCARIA_PROVEEDOR.constancia_banco_doc_id%TYPE,
        p_representante_doc_id     IN MB_CUENTA_BANCARIA_PROVEEDOR.representante_doc_id%TYPE,
        p_motivo_registro          IN MB_CUENTA_BANCARIA_PROVEEDOR.motivo_registro%TYPE,
        p_fecha_vigencia           IN MB_CUENTA_BANCARIA_PROVEEDOR.fecha_vigencia%TYPE,
        p_estado                   IN MB_CUENTA_BANCARIA_PROVEEDOR.estado%TYPE,
        p_observaciones            IN MB_CUENTA_BANCARIA_PROVEEDOR.observaciones%TYPE,
        p_solicitado_por           IN MB_CUENTA_BANCARIA_PROVEEDOR.solicitado_por%TYPE,
        p_cta_proveedor_id         OUT MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE
    ) AS
        v_total NUMBER;

        e_fk_no_existe EXCEPTION;
        PRAGMA EXCEPTION_INIT(e_fk_no_existe, -2291);

    BEGIN

        IF p_banco_id IS NULL OR NOT EXISTE_BANCO(p_banco_id) THEN
            RAISE_APPLICATION_ERROR(
                -20026,
                'El banco indicado no existe.'
            );
        END IF;

        IF NOT BANCO_ESTA_ACTIVO(p_banco_id) THEN
            RAISE_APPLICATION_ERROR(
                -20043,
                'El banco indicado se encuentra inactivo y no puede asignarse a una cuenta nueva de proveedor.'
            );
        END IF;

        IF p_tipo_cuenta_id IS NULL
           OR NOT EXISTE_TIPO_CUENTA(p_tipo_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20027,
                'El tipo de cuenta indicado no existe.'
            );
        END IF;

        IF NOT TIPO_CUENTA_ESTA_ACTIVO(p_tipo_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20054,
                'El tipo de cuenta indicado se encuentra inactivo y no puede asignarse a una cuenta nueva de proveedor.'
            );
        END IF;

        IF p_cuenta_anterior_id IS NOT NULL
           AND NOT EXISTE_CUENTA_PROVEEDOR(p_cuenta_anterior_id) THEN
            RAISE_APPLICATION_ERROR(
                -20028,
                'La cuenta bancaria anterior indicada no existe.'
            );
        END IF;

        VALIDAR_ESTADO_CUENTA_PROV(p_estado);

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CUENTA_BANCARIA_PROVEEDOR
        WHERE proveedor_id = p_proveedor_id
          AND banco_id = p_banco_id
          AND numero_cuenta = p_numero_cuenta
          AND moneda_id = p_moneda_id;

        IF v_total > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20029,
                'La cuenta bancaria ya se encuentra registrada para este proveedor, banco y moneda.'
            );
        END IF;

        p_cta_proveedor_id :=
            SEQ_MB_CUENTA_PROVEEDOR.NEXTVAL;

        INSERT INTO MB_CUENTA_BANCARIA_PROVEEDOR (
            cta_proveedor_id,
            proveedor_id,
            banco_id,
            tipo_cuenta_id,
            moneda_id,
            cuenta_anterior_id,
            titular,
            numero_cuenta,
            carta_solicitud_doc_id,
            constancia_banco_doc_id,
            representante_doc_id,
            motivo_registro,
            fecha_vigencia,
            estado,
            observaciones,
            solicitado_por,
            solicitado_en
        )
        VALUES (
            p_cta_proveedor_id,
            p_proveedor_id,
            p_banco_id,
            p_tipo_cuenta_id,
            p_moneda_id,
            p_cuenta_anterior_id,
            p_titular,
            p_numero_cuenta,
            p_carta_solicitud_doc_id,
            p_constancia_banco_doc_id,
            p_representante_doc_id,
            p_motivo_registro,
            p_fecha_vigencia,
            p_estado,
            p_observaciones,
            p_solicitado_por,
            SYSTIMESTAMP
        );

    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20030,
                'No se pudo crear la cuenta bancaria del proveedor porque existe un registro duplicado.'
            );

        WHEN e_fk_no_existe THEN
            RAISE_APPLICATION_ERROR(
                -20031,
                'No se pudo crear la cuenta porque una referencia asociada no existe.'
            );

    END CREAR_CUENTA_PROVEEDOR;


    PROCEDURE ACTUALIZAR_CUENTA_PROVEEDOR (
        p_cta_proveedor_id         IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE,
        p_proveedor_id             IN MB_CUENTA_BANCARIA_PROVEEDOR.proveedor_id%TYPE,
        p_banco_id                 IN MB_CUENTA_BANCARIA_PROVEEDOR.banco_id%TYPE,
        p_tipo_cuenta_id           IN MB_CUENTA_BANCARIA_PROVEEDOR.tipo_cuenta_id%TYPE,
        p_moneda_id                IN MB_CUENTA_BANCARIA_PROVEEDOR.moneda_id%TYPE,
        p_cuenta_anterior_id       IN MB_CUENTA_BANCARIA_PROVEEDOR.cuenta_anterior_id%TYPE,
        p_titular                  IN MB_CUENTA_BANCARIA_PROVEEDOR.titular%TYPE,
        p_numero_cuenta            IN MB_CUENTA_BANCARIA_PROVEEDOR.numero_cuenta%TYPE,
        p_carta_solicitud_doc_id   IN MB_CUENTA_BANCARIA_PROVEEDOR.carta_solicitud_doc_id%TYPE,
        p_constancia_banco_doc_id  IN MB_CUENTA_BANCARIA_PROVEEDOR.constancia_banco_doc_id%TYPE,
        p_representante_doc_id     IN MB_CUENTA_BANCARIA_PROVEEDOR.representante_doc_id%TYPE,
        p_motivo_registro          IN MB_CUENTA_BANCARIA_PROVEEDOR.motivo_registro%TYPE,
        p_fecha_vigencia           IN MB_CUENTA_BANCARIA_PROVEEDOR.fecha_vigencia%TYPE,
        p_observaciones            IN MB_CUENTA_BANCARIA_PROVEEDOR.observaciones%TYPE
    ) AS
        v_total              NUMBER;
        v_tipo_cuenta_actual MB_CUENTA_BANCARIA_PROVEEDOR.tipo_cuenta_id%TYPE;

        e_fk_no_existe EXCEPTION;
        PRAGMA EXCEPTION_INIT(e_fk_no_existe, -2291);

    BEGIN

        IF p_cta_proveedor_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20032,
                'Debe indicar el identificador de la cuenta bancaria del proveedor.'
            );
        END IF;

        IF NOT EXISTE_CUENTA_PROVEEDOR(p_cta_proveedor_id) THEN
            RAISE_APPLICATION_ERROR(
                -20033,
                'La cuenta bancaria del proveedor que desea actualizar no existe.'
            );
        END IF;

        SELECT tipo_cuenta_id
        INTO v_tipo_cuenta_actual
        FROM MB_CUENTA_BANCARIA_PROVEEDOR
        WHERE cta_proveedor_id = p_cta_proveedor_id
        FOR UPDATE;

        IF p_banco_id IS NULL OR NOT EXISTE_BANCO(p_banco_id) THEN
            RAISE_APPLICATION_ERROR(
                -20034,
                'El banco indicado no existe.'
            );
        END IF;

        IF p_tipo_cuenta_id IS NULL
           OR NOT EXISTE_TIPO_CUENTA(p_tipo_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20035,
                'El tipo de cuenta indicado no existe.'
            );
        END IF;

        IF NVL(v_tipo_cuenta_actual, -1) <> NVL(p_tipo_cuenta_id, -1)
           AND NOT TIPO_CUENTA_ESTA_ACTIVO(p_tipo_cuenta_id) THEN
            RAISE_APPLICATION_ERROR(
                -20054,
                'El tipo de cuenta indicado se encuentra inactivo y no puede asignarse a la cuenta del proveedor.'
            );
        END IF;

        IF p_cuenta_anterior_id IS NOT NULL
           AND NOT EXISTE_CUENTA_PROVEEDOR(p_cuenta_anterior_id) THEN
            RAISE_APPLICATION_ERROR(
                -20036,
                'La cuenta bancaria anterior indicada no existe.'
            );
        END IF;

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CUENTA_BANCARIA_PROVEEDOR
        WHERE proveedor_id = p_proveedor_id
          AND banco_id = p_banco_id
          AND numero_cuenta = p_numero_cuenta
          AND moneda_id = p_moneda_id
          AND cta_proveedor_id <> p_cta_proveedor_id;

        IF v_total > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20037,
                'Ya existe otra cuenta bancaria con el mismo proveedor, banco, numero y moneda.'
            );
        END IF;

        UPDATE MB_CUENTA_BANCARIA_PROVEEDOR
        SET
            proveedor_id = p_proveedor_id,
            banco_id = p_banco_id,
            tipo_cuenta_id = p_tipo_cuenta_id,
            moneda_id = p_moneda_id,
            cuenta_anterior_id = p_cuenta_anterior_id,
            titular = p_titular,
            numero_cuenta = p_numero_cuenta,
            carta_solicitud_doc_id = p_carta_solicitud_doc_id,
            constancia_banco_doc_id = p_constancia_banco_doc_id,
            representante_doc_id = p_representante_doc_id,
            motivo_registro = p_motivo_registro,
            fecha_vigencia = p_fecha_vigencia,
            observaciones = p_observaciones
        WHERE cta_proveedor_id = p_cta_proveedor_id;

    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20038,
                'No se pudo actualizar la cuenta bancaria porque existe un registro duplicado.'
            );

        WHEN e_fk_no_existe THEN
            RAISE_APPLICATION_ERROR(
                -20039,
                'No se pudo actualizar la cuenta porque una referencia asociada no existe.'
            );

    END ACTUALIZAR_CUENTA_PROVEEDOR;


    PROCEDURE CAMBIAR_ESTADO_CUENTA_PROVEEDOR (
        p_cta_proveedor_id
            IN MB_CUENTA_BANCARIA_PROVEEDOR.cta_proveedor_id%TYPE,
        p_estado
            IN MB_CUENTA_BANCARIA_PROVEEDOR.estado%TYPE
    ) AS
    BEGIN

        IF p_cta_proveedor_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20040,
                'Debe indicar el identificador de la cuenta bancaria del proveedor.'
            );
        END IF;

        IF NOT EXISTE_CUENTA_PROVEEDOR(p_cta_proveedor_id) THEN
            RAISE_APPLICATION_ERROR(
                -20041,
                'La cuenta bancaria del proveedor indicada no existe.'
            );
        END IF;

        VALIDAR_ESTADO_CUENTA_PROV(p_estado);

        UPDATE MB_CUENTA_BANCARIA_PROVEEDOR
        SET estado = p_estado
        WHERE cta_proveedor_id = p_cta_proveedor_id;

    END CAMBIAR_ESTADO_CUENTA_PROVEEDOR;


END PKG_MB_CUENTAS;
/

-- PACKAGE_BODY PKG_MB_FORMATOS_IMPORTACION
CREATE OR REPLACE PACKAGE BODY "PKG_MB_FORMATOS_IMPORTACION" AS

    /* =========================================================
       LISTAR FORMATOS
       ========================================================= */

    PROCEDURE listar_formatos (
        p_resultado OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                f.formato_id,
                f.banco_id,
                b.nombre AS banco,
                f.nombre,
                f.version,
                f.tipo_archivo,
                f.delimitador,
                f.formato_fecha,
                f.fila_encabezado,
                f.archivo_ejemplo_id,
                f.estado

            FROM MB_FORMATO_IMPORTACION_BANCO f

            INNER JOIN MB_BANCO b
                ON b.banco_id = f.banco_id

            ORDER BY f.formato_id;

    END listar_formatos;


    /* =========================================================
       OBTENER FORMATO
       ========================================================= */

    PROCEDURE obtener_formato (
        p_formato_id IN NUMBER,
        p_resultado  OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                f.formato_id,
                f.banco_id,
                b.nombre AS banco,
                f.nombre,
                f.version,
                f.tipo_archivo,
                f.delimitador,
                f.formato_fecha,
                f.fila_encabezado,
                f.archivo_ejemplo_id,
                f.estado

            FROM MB_FORMATO_IMPORTACION_BANCO f

            INNER JOIN MB_BANCO b
                ON b.banco_id = f.banco_id

            WHERE f.formato_id = p_formato_id;

    END obtener_formato;


    /* =========================================================
       CREAR FORMATO
       ========================================================= */

    PROCEDURE crear_formato (
        p_banco_id           IN NUMBER,
        p_nombre             IN VARCHAR2,
        p_version            IN NUMBER,
        p_tipo_archivo       IN VARCHAR2,
        p_delimitador        IN VARCHAR2,
        p_formato_fecha      IN VARCHAR2,
        p_fila_encabezado    IN NUMBER,
        p_archivo_ejemplo_id IN NUMBER,
        p_estado             IN VARCHAR2,
        p_formato_id         OUT NUMBER
    ) AS
    BEGIN

        --------------------------------------------------------
        -- ID generado mediante secuencia Oracle
        --------------------------------------------------------

        p_formato_id :=
            SEQ_MB_FORMATO_IMPORTACION.NEXTVAL;


        INSERT INTO MB_FORMATO_IMPORTACION_BANCO (
            formato_id,
            banco_id,
            nombre,
            version,
            tipo_archivo,
            delimitador,
            formato_fecha,
            fila_encabezado,
            archivo_ejemplo_id,
            estado
        )
        VALUES (
            p_formato_id,
            p_banco_id,
            p_nombre,
            p_version,
            p_tipo_archivo,
            p_delimitador,
            p_formato_fecha,
            p_fila_encabezado,
            p_archivo_ejemplo_id,
            p_estado
        );

    END crear_formato;


    /* =========================================================
       ACTUALIZAR FORMATO
       ========================================================= */

    PROCEDURE actualizar_formato (
        p_formato_id         IN NUMBER,
        p_banco_id           IN NUMBER,
        p_nombre             IN VARCHAR2,
        p_version            IN NUMBER,
        p_tipo_archivo       IN VARCHAR2,
        p_delimitador        IN VARCHAR2,
        p_formato_fecha      IN VARCHAR2,
        p_fila_encabezado    IN NUMBER,
        p_archivo_ejemplo_id IN NUMBER
    ) AS
    BEGIN

        UPDATE MB_FORMATO_IMPORTACION_BANCO

        SET
            banco_id           = p_banco_id,
            nombre             = p_nombre,
            version            = p_version,
            tipo_archivo       = p_tipo_archivo,
            delimitador        = p_delimitador,
            formato_fecha      = p_formato_fecha,
            fila_encabezado    = p_fila_encabezado,
            archivo_ejemplo_id = p_archivo_ejemplo_id

        WHERE formato_id = p_formato_id;

    END actualizar_formato;


    /* =========================================================
       CAMBIAR ESTADO FORMATO
       ========================================================= */

    PROCEDURE cambiar_estado_formato (
        p_formato_id IN NUMBER,
        p_estado     IN VARCHAR2
    ) AS
    BEGIN

        UPDATE MB_FORMATO_IMPORTACION_BANCO

        SET estado = p_estado

        WHERE formato_id = p_formato_id;

    END cambiar_estado_formato;


    /* =========================================================
       LISTAR MAPEOS
       ========================================================= */

    PROCEDURE listar_mapeos (
        p_formato_id IN NUMBER,
        p_resultado  OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                m.mapeo_id,
                m.formato_id,
                m.campo_sistema,
                m.nombre_columna,
                m.numero_columna,
                m.es_obligatorio,
                m.formato_valor

            FROM MB_MAPEO_COLUMNA_FORMATO m

            WHERE m.formato_id = p_formato_id

            ORDER BY m.numero_columna;

    END listar_mapeos;


    /* =========================================================
       CREAR MAPEO
       ========================================================= */

    PROCEDURE crear_mapeo (
        p_formato_id     IN NUMBER,
        p_campo_sistema  IN VARCHAR2,
        p_nombre_columna IN VARCHAR2,
        p_numero_columna IN NUMBER,
        p_es_obligatorio IN CHAR,
        p_formato_valor  IN VARCHAR2,
        p_mapeo_id       OUT NUMBER
    ) AS
    BEGIN

        --------------------------------------------------------
        -- ID generado mediante secuencia Oracle
        --------------------------------------------------------

        p_mapeo_id :=
            SEQ_MB_MAPEO_COLUMNA_FORMATO.NEXTVAL;


        INSERT INTO MB_MAPEO_COLUMNA_FORMATO (
            mapeo_id,
            formato_id,
            campo_sistema,
            nombre_columna,
            numero_columna,
            es_obligatorio,
            formato_valor
        )
        VALUES (
            p_mapeo_id,
            p_formato_id,
            p_campo_sistema,
            p_nombre_columna,
            p_numero_columna,
            p_es_obligatorio,
            p_formato_valor
        );

    END crear_mapeo;


    /* =========================================================
       ACTUALIZAR MAPEO
       ========================================================= */

    PROCEDURE actualizar_mapeo (
        p_mapeo_id       IN NUMBER,
        p_campo_sistema  IN VARCHAR2,
        p_nombre_columna IN VARCHAR2,
        p_numero_columna IN NUMBER,
        p_es_obligatorio IN CHAR,
        p_formato_valor  IN VARCHAR2
    ) AS
    BEGIN

        UPDATE MB_MAPEO_COLUMNA_FORMATO

        SET
            campo_sistema  = p_campo_sistema,
            nombre_columna = p_nombre_columna,
            numero_columna = p_numero_columna,
            es_obligatorio = p_es_obligatorio,
            formato_valor  = p_formato_valor

        WHERE mapeo_id = p_mapeo_id;

    END actualizar_mapeo;


    /* =========================================================
       ELIMINAR MAPEO
       ========================================================= */

    PROCEDURE eliminar_mapeo (
        p_mapeo_id IN NUMBER
    ) AS
    BEGIN

        DELETE FROM MB_MAPEO_COLUMNA_FORMATO

        WHERE mapeo_id = p_mapeo_id;

    END eliminar_mapeo;


END PKG_MB_FORMATOS_IMPORTACION;
/

-- PACKAGE_BODY PKG_MB_INTEGRACION_CXC
CREATE OR REPLACE PACKAGE BODY "PKG_MB_INTEGRACION_CXC" AS

    ------------------------------------------------------------------
    -- LISTAR TODOS LOS COBROS
    ------------------------------------------------------------------
    PROCEDURE LISTAR_COBROS (
        p_cliente_id IN NUMBER DEFAULT NULL,
        p_estado_cxc IN VARCHAR2 DEFAULT NULL,
        p_resultado  OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                id_pago_origen,
                modulo_origen,
                cliente_id,
                cliente_nombre,
                cliente_nit,
                cliente_estado,
                forma_pago_id,
                forma_pago_nombre,
                requiere_referencia,
                moneda_id,
                moneda_codigo,
                moneda_nombre,
                banco_id,
                banco_codigo,
                banco_nombre,
                fecha_pago,
                monto,
                numero_referencia,
                estado_origen,
                es_bancario,
                integracion_valida,
                motivo_integracion
            FROM MB_V_CXC_COBROS
            WHERE (
                    p_cliente_id IS NULL
                    OR cliente_id = p_cliente_id
                  )
              AND (
                    p_estado_cxc IS NULL
                    OR estado_origen = UPPER(TRIM(p_estado_cxc))
                  )
            ORDER BY
                fecha_pago,
                id_pago_origen;

    END LISTAR_COBROS;


    ------------------------------------------------------------------
    -- LISTAR SOLO COBROS BANCARIOS VALIDOS
    ------------------------------------------------------------------
    PROCEDURE LISTAR_BANCARIOS_VALIDOS (
        p_cliente_id IN NUMBER DEFAULT NULL,
        p_banco_id   IN NUMBER DEFAULT NULL,
        p_moneda_id  IN NUMBER DEFAULT NULL,
        p_resultado  OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                id_pago_origen,
                modulo_origen,
                cliente_id,
                cliente_nombre,
                cliente_nit,
                cliente_estado,
                forma_pago_id,
                forma_pago_nombre,
                requiere_referencia,
                moneda_id,
                moneda_codigo,
                moneda_nombre,
                banco_id,
                banco_codigo,
                banco_nombre,
                fecha_pago,
                monto,
                numero_referencia,
                estado_origen,
                es_bancario,
                integracion_valida,
                motivo_integracion
            FROM MB_V_CXC_COBROS
            WHERE es_bancario = 'S'
              AND integracion_valida = 'S'
              AND (
                    p_cliente_id IS NULL
                    OR cliente_id = p_cliente_id
                  )
              AND (
                    p_banco_id IS NULL
                    OR banco_id = p_banco_id
                  )
              AND (
                    p_moneda_id IS NULL
                    OR moneda_id = p_moneda_id
                  )
            ORDER BY
                fecha_pago,
                id_pago_origen;

    END LISTAR_BANCARIOS_VALIDOS;


    ------------------------------------------------------------------
    -- OBTENER UN COBRO POR ID
    ------------------------------------------------------------------
    PROCEDURE OBTENER_COBRO (
        p_pago_origen_id IN NUMBER,
        p_resultado      OUT SYS_REFCURSOR
    ) AS

        v_existe NUMBER;

    BEGIN

        IF p_pago_origen_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20011,
                'El ID del pago CXC es obligatorio.'
            );
        END IF;

        SELECT COUNT(*)
        INTO v_existe
        FROM MB_V_CXC_COBROS
        WHERE id_pago_origen = p_pago_origen_id;

        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20012,
                'El cobro CXC indicado no existe o no esta disponible para Bancos.'
            );
        END IF;

        OPEN p_resultado FOR

            SELECT
                id_pago_origen,
                modulo_origen,
                cliente_id,
                cliente_nombre,
                cliente_nit,
                cliente_estado,
                forma_pago_id,
                forma_pago_nombre,
                requiere_referencia,
                moneda_id,
                moneda_codigo,
                moneda_nombre,
                banco_id,
                banco_codigo,
                banco_nombre,
                fecha_pago,
                monto,
                numero_referencia,
                estado_origen,
                es_bancario,
                integracion_valida,
                motivo_integracion
            FROM MB_V_CXC_COBROS
            WHERE id_pago_origen = p_pago_origen_id;

    END OBTENER_COBRO;

END PKG_MB_INTEGRACION_CXC;
/

-- PACKAGE_BODY PKG_MB_INTEGRACION_CXP
CREATE OR REPLACE PACKAGE BODY "PKG_MB_INTEGRACION_CXP" AS

    ------------------------------------------------------------------
    -- LISTAR TODAS LAS OBLIGACIONES
    ------------------------------------------------------------------
    PROCEDURE LISTAR_OBLIGACIONES (
        p_proveedor_id IN NUMBER DEFAULT NULL,
        p_estado_cxp   IN VARCHAR2 DEFAULT NULL,
        p_resultado    OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                id_documento_origen,
                modulo_origen,
                proveedor_id,
                proveedor_nombre,
                proveedor_nit,
                tipo_documento,
                serie,
                numero_documento,
                no_factura_compra,
                moneda_codigo,
                moneda_id,
                total_neto,
                monto_aplicado,
                saldo_pendiente,
                fecha_documento,
                fecha_vencimiento,
                estado_origen,
                es_pagable,
                motivo_no_pagable
            FROM MB_V_CXP_OBLIGACIONES
            WHERE (
                    p_proveedor_id IS NULL
                    OR proveedor_id = p_proveedor_id
                  )
              AND (
                    p_estado_cxp IS NULL
                    OR estado_origen = UPPER(TRIM(p_estado_cxp))
                  )
            ORDER BY
                fecha_vencimiento NULLS LAST,
                id_documento_origen;

    END LISTAR_OBLIGACIONES;


    ------------------------------------------------------------------
    -- LISTAR SOLO DOCUMENTOS QUE BANCOS PUEDE PREPARAR PARA PAGO
    ------------------------------------------------------------------
    PROCEDURE LISTAR_PAGABLES (
        p_proveedor_id IN NUMBER DEFAULT NULL,
        p_moneda_id    IN NUMBER DEFAULT NULL,
        p_resultado    OUT SYS_REFCURSOR
    ) AS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                id_documento_origen,
                modulo_origen,
                proveedor_id,
                proveedor_nombre,
                proveedor_nit,
                tipo_documento,
                serie,
                numero_documento,
                no_factura_compra,
                moneda_codigo,
                moneda_id,
                total_neto,
                monto_aplicado,
                saldo_pendiente,
                fecha_documento,
                fecha_vencimiento,
                estado_origen,
                es_pagable,
                motivo_no_pagable
            FROM MB_V_CXP_OBLIGACIONES
            WHERE es_pagable = 'S'
              AND (
                    p_proveedor_id IS NULL
                    OR proveedor_id = p_proveedor_id
                  )
              AND (
                    p_moneda_id IS NULL
                    OR moneda_id = p_moneda_id
                  )
            ORDER BY
                fecha_vencimiento NULLS LAST,
                id_documento_origen;

    END LISTAR_PAGABLES;


    ------------------------------------------------------------------
    -- OBTENER UNA OBLIGACION POR ID EXTERNO
    ------------------------------------------------------------------
    PROCEDURE OBTENER_OBLIGACION (
        p_documento_origen_id IN NUMBER,
        p_resultado           OUT SYS_REFCURSOR
    ) AS

        v_existe NUMBER;

    BEGIN

        IF p_documento_origen_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20001,
                'El ID del documento CXP es obligatorio.'
            );
        END IF;

        SELECT COUNT(*)
          INTO v_existe
          FROM MB_V_CXP_OBLIGACIONES
         WHERE id_documento_origen = p_documento_origen_id;

        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20002,
                'La obligacion CXP indicada no existe o no esta disponible para Bancos.'
            );
        END IF;

        OPEN p_resultado FOR

            SELECT
                id_documento_origen,
                modulo_origen,
                proveedor_id,
                proveedor_nombre,
                proveedor_nit,
                tipo_documento,
                serie,
                numero_documento,
                no_factura_compra,
                moneda_codigo,
                moneda_id,
                total_neto,
                monto_aplicado,
                saldo_pendiente,
                fecha_documento,
                fecha_vencimiento,
                estado_origen,
                es_pagable,
                motivo_no_pagable
            FROM MB_V_CXP_OBLIGACIONES
            WHERE id_documento_origen = p_documento_origen_id;

    END OBTENER_OBLIGACION;


END PKG_MB_INTEGRACION_CXP;
/

-- PACKAGE_BODY PKG_MB_OPERACIONES
CREATE OR REPLACE PACKAGE BODY "PKG_MB_OPERACIONES" AS

  PROCEDURE VALIDAR_CATALOGO(
    p_catalogo_id IN NUMBER,
    p_grupo       IN VARCHAR2
  ) AS
    v_grupo  MB_CATALOGO_BANCARIO.GRUPO%TYPE;
    v_estado MB_CATALOGO_BANCARIO.ESTADO%TYPE;
  BEGIN
    SELECT grupo, estado
      INTO v_grupo, v_estado
      FROM MB_CATALOGO_BANCARIO
     WHERE catalogo_id = p_catalogo_id;

    IF v_grupo <> p_grupo THEN
      RAISE_APPLICATION_ERROR(-20050, 'El catÃ¡logo no pertenece al grupo ' || p_grupo || '.');
    END IF;

    IF v_estado <> 'ACTIVO' THEN
      RAISE_APPLICATION_ERROR(-20051, 'El catÃ¡logo seleccionado estÃ¡ inactivo.');
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RAISE_APPLICATION_ERROR(-20052, 'No existe el catÃ¡logo solicitado.');
  END VALIDAR_CATALOGO;


  PROCEDURE LISTAR_MOVIMIENTOS(
    p_cuenta_id IN NUMBER DEFAULT NULL,
    p_estado    IN VARCHAR2 DEFAULT NULL,
    p_resultado OUT SYS_REFCURSOR
  ) AS
  BEGIN
    OPEN p_resultado FOR
      SELECT
        m.movimiento_id,
        m.operacion_id,
        m.cuenta_id,
        c.codigo_cuenta,
        c.numero_cuenta,
        c.nombre_interno AS nombre_cuenta,
        b.banco_id,
        b.codigo_banco,
        b.nombre AS banco_nombre,
        c.moneda_id,
        o.tipo_operacion_id,
        top.codigo AS tipo_operacion_codigo,
        top.nombre AS tipo_operacion_nombre,
        m.tipo_movimiento_id,
        tm.codigo AS tipo_movimiento_codigo,
        tm.nombre AS tipo_movimiento_nombre,
        tm.naturaleza,
        m.movimiento_origen_id,
        m.numero_movimiento,
        m.fecha_operacion,
        m.fecha_efectiva,
        m.referencia_bancaria,
        m.beneficiario_ordenante,
        m.concepto,
        m.monto,
        m.estado,
        m.estado_conciliacion,
        o.modulo_origen,
        o.documento_origen_id
      FROM MB_MOVIMIENTO_BANCARIO m
      JOIN MB_OPERACION_BANCARIA o
        ON o.operacion_id = m.operacion_id
      JOIN MB_CUENTA_BANCARIA c
        ON c.cuenta_id = m.cuenta_id
      JOIN MB_BANCO b
        ON b.banco_id = c.banco_id
      JOIN MB_CATALOGO_BANCARIO top
        ON top.catalogo_id = o.tipo_operacion_id
      JOIN MB_CATALOGO_BANCARIO tm
        ON tm.catalogo_id = m.tipo_movimiento_id
      WHERE (p_cuenta_id IS NULL OR m.cuenta_id = p_cuenta_id)
        AND (p_estado IS NULL OR m.estado = UPPER(TRIM(p_estado)))
      ORDER BY m.fecha_operacion DESC, m.movimiento_id DESC;
  END LISTAR_MOVIMIENTOS;


  PROCEDURE OBTENER_MOVIMIENTO(
    p_movimiento_id IN NUMBER,
    p_resultado     OUT SYS_REFCURSOR
  ) AS
  BEGIN
    OPEN p_resultado FOR
      SELECT
        m.movimiento_id,
        m.operacion_id,
        m.cuenta_id,
        c.codigo_cuenta,
        c.numero_cuenta,
        c.nombre_interno AS nombre_cuenta,
        b.banco_id,
        b.codigo_banco,
        b.nombre AS banco_nombre,
        c.moneda_id,
        o.tipo_operacion_id,
        top.codigo AS tipo_operacion_codigo,
        top.nombre AS tipo_operacion_nombre,
        m.tipo_movimiento_id,
        tm.codigo AS tipo_movimiento_codigo,
        tm.nombre AS tipo_movimiento_nombre,
        tm.naturaleza,
        m.movimiento_origen_id,
        m.numero_movimiento,
        m.fecha_operacion,
        m.fecha_efectiva,
        m.referencia_bancaria,
        m.beneficiario_ordenante,
        m.concepto,
        m.monto,
        m.estado,
        m.estado_conciliacion,
        o.modulo_origen,
        o.documento_origen_id
      FROM MB_MOVIMIENTO_BANCARIO m
      JOIN MB_OPERACION_BANCARIA o
        ON o.operacion_id = m.operacion_id
      JOIN MB_CUENTA_BANCARIA c
        ON c.cuenta_id = m.cuenta_id
      JOIN MB_BANCO b
        ON b.banco_id = c.banco_id
      JOIN MB_CATALOGO_BANCARIO top
        ON top.catalogo_id = o.tipo_operacion_id
      JOIN MB_CATALOGO_BANCARIO tm
        ON tm.catalogo_id = m.tipo_movimiento_id
      WHERE m.movimiento_id = p_movimiento_id;
  END OBTENER_MOVIMIENTO;


  PROCEDURE REGISTRAR_MOVIMIENTO(
    p_cuenta_id              IN NUMBER,
    p_tipo_operacion_id      IN NUMBER,
    p_tipo_movimiento_id     IN NUMBER,
    p_sucursal_id            IN NUMBER DEFAULT NULL,
    p_modulo_origen          IN VARCHAR2 DEFAULT 'BANCOS',
    p_documento_origen_id    IN NUMBER DEFAULT NULL,
    p_fecha_operacion        IN DATE,
    p_fecha_efectiva         IN DATE DEFAULT NULL,
    p_referencia_bancaria    IN VARCHAR2 DEFAULT NULL,
    p_beneficiario_ordenante IN VARCHAR2,
    p_concepto               IN VARCHAR2,
    p_monto                  IN NUMBER,
    p_usuario_id             IN NUMBER,
    p_operacion_id           OUT NUMBER,
    p_movimiento_id          OUT NUMBER,
    p_numero_movimiento      OUT VARCHAR2
  ) AS
    v_empresa_id     MB_CUENTA_BANCARIA.EMPRESA_ID%TYPE;
    v_estado_cuenta  MB_CUENTA_BANCARIA.ESTADO%TYPE;
    v_permite_cobros MB_CUENTA_BANCARIA.PERMITE_COBROS%TYPE;
    v_permite_pagos  MB_CUENTA_BANCARIA.PERMITE_PAGOS%TYPE;
    v_naturaleza     MB_CATALOGO_BANCARIO.NATURALEZA%TYPE;
    v_historial_id   NUMBER;
    v_modulo_origen  VARCHAR2(20);
  BEGIN
    IF p_usuario_id IS NULL OR p_usuario_id <= 0 THEN
      RAISE_APPLICATION_ERROR(-20053, 'El usuario de la operaciÃ³n es obligatorio.');
    END IF;

    IF p_monto IS NULL OR p_monto <= 0 THEN
      RAISE_APPLICATION_ERROR(-20054, 'El monto debe ser mayor que cero.');
    END IF;

    IF p_fecha_operacion IS NULL THEN
      RAISE_APPLICATION_ERROR(-20055, 'La fecha de operaciÃ³n es obligatoria.');
    END IF;

    IF LENGTH(TRIM(p_beneficiario_ordenante)) = 0 OR p_beneficiario_ordenante IS NULL THEN
      RAISE_APPLICATION_ERROR(-20056, 'El beneficiario u ordenante es obligatorio.');
    END IF;

    IF p_concepto IS NULL OR LENGTH(TRIM(p_concepto)) < 5 THEN
      RAISE_APPLICATION_ERROR(-20057, 'El concepto debe contener al menos 5 caracteres.');
    END IF;

    v_modulo_origen := UPPER(TRIM(NVL(p_modulo_origen, 'BANCOS')));
    IF v_modulo_origen NOT IN ('BANCOS', 'CXP', 'CXC') THEN
      RAISE_APPLICATION_ERROR(-20058, 'El mÃ³dulo de origen no es vÃ¡lido.');
    END IF;

    BEGIN
      SELECT empresa_id, estado, permite_cobros, permite_pagos
        INTO v_empresa_id, v_estado_cuenta, v_permite_cobros, v_permite_pagos
        FROM MB_CUENTA_BANCARIA
       WHERE cuenta_id = p_cuenta_id
       FOR UPDATE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20059, 'La cuenta bancaria no existe.');
    END;

    IF v_estado_cuenta <> 'ACTIVA' THEN
      RAISE_APPLICATION_ERROR(-20060, 'La cuenta bancaria debe estar activa.');
    END IF;

    VALIDAR_CATALOGO(p_tipo_operacion_id, 'TIPO_OPERACION');
    VALIDAR_CATALOGO(p_tipo_movimiento_id, 'TIPO_MOVIMIENTO');

    SELECT naturaleza
      INTO v_naturaleza
      FROM MB_CATALOGO_BANCARIO
     WHERE catalogo_id = p_tipo_movimiento_id;

    IF v_naturaleza = 'C' AND v_permite_cobros <> 'S' THEN
      RAISE_APPLICATION_ERROR(-20061, 'La cuenta seleccionada no permite movimientos de cobro/crÃ©dito.');
    END IF;

    IF v_naturaleza = 'D' AND v_permite_pagos <> 'S' THEN
      RAISE_APPLICATION_ERROR(-20062, 'La cuenta seleccionada no permite movimientos de pago/dÃ©bito.');
    END IF;

    p_operacion_id := SEQ_MB_OPERACION_BANCARIA.NEXTVAL;
    p_movimiento_id := SEQ_MB_MOVIMIENTO_BANCARIO.NEXTVAL;
    v_historial_id := SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL;
    p_numero_movimiento := 'MB-' || LPAD(TO_CHAR(p_movimiento_id), 10, '0');

    INSERT INTO MB_OPERACION_BANCARIA (
      operacion_id,
      empresa_id,
      sucursal_id,
      cuenta_principal_id,
      tipo_operacion_id,
      operacion_relacionada_id,
      modulo_origen,
      documento_origen_id,
      estado,
      creado_por,
      creado_en,
      modificado_por,
      modificado_en
    ) VALUES (
      p_operacion_id,
      v_empresa_id,
      p_sucursal_id,
      p_cuenta_id,
      p_tipo_operacion_id,
      NULL,
      v_modulo_origen,
      p_documento_origen_id,
      'REGISTRADA',
      p_usuario_id,
      SYSTIMESTAMP,
      NULL,
      NULL
    );

    INSERT INTO MB_MOVIMIENTO_BANCARIO (
      movimiento_id,
      operacion_id,
      cuenta_id,
      tipo_movimiento_id,
      movimiento_origen_id,
      numero_movimiento,
      fecha_operacion,
      fecha_efectiva,
      referencia_bancaria,
      beneficiario_ordenante,
      concepto,
      monto,
      estado,
      estado_conciliacion
    ) VALUES (
      p_movimiento_id,
      p_operacion_id,
      p_cuenta_id,
      p_tipo_movimiento_id,
      NULL,
      p_numero_movimiento,
      p_fecha_operacion,
      p_fecha_efectiva,
      TRIM(p_referencia_bancaria),
      TRIM(p_beneficiario_ordenante),
      TRIM(p_concepto),
      p_monto,
      'APLICADO',
      'PENDIENTE'
    );

    INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
      historial_id,
      operacion_id,
      estado_anterior,
      estado_nuevo,
      decision,
      motivo,
      usuario_id,
      registrado_en
    ) VALUES (
      v_historial_id,
      p_operacion_id,
      NULL,
      'REGISTRADA',
      'REGISTRAR',
      'Registro de movimiento bancario',
      p_usuario_id,
      SYSTIMESTAMP
    );
  END REGISTRAR_MOVIMIENTO;



  PROCEDURE REGISTRAR_MOVIMIENTO_OPERACION(
    p_operacion_id           IN NUMBER,
    p_tipo_movimiento_id     IN NUMBER,
    p_fecha_operacion        IN DATE,
    p_fecha_efectiva         IN DATE DEFAULT NULL,
    p_referencia_bancaria    IN VARCHAR2 DEFAULT NULL,
    p_beneficiario_ordenante IN VARCHAR2,
    p_concepto               IN VARCHAR2,
    p_monto                  IN NUMBER,
    p_usuario_id             IN NUMBER,
    p_movimiento_id          OUT NUMBER,
    p_numero_movimiento      OUT VARCHAR2
  ) AS
    v_cuenta_id       MB_OPERACION_BANCARIA.CUENTA_PRINCIPAL_ID%TYPE;
    v_estado_operacion MB_OPERACION_BANCARIA.ESTADO%TYPE;
    v_estado_cuenta   MB_CUENTA_BANCARIA.ESTADO%TYPE;
    v_permite_cobros  MB_CUENTA_BANCARIA.PERMITE_COBROS%TYPE;
    v_permite_pagos   MB_CUENTA_BANCARIA.PERMITE_PAGOS%TYPE;
    v_naturaleza      MB_CATALOGO_BANCARIO.NATURALEZA%TYPE;
    v_existentes      PLS_INTEGER;
  BEGIN
    IF p_operacion_id IS NULL OR p_operacion_id <= 0 THEN
      RAISE_APPLICATION_ERROR(-20072, 'La operacion bancaria es obligatoria.');
    END IF;

    IF p_usuario_id IS NULL OR p_usuario_id <= 0 THEN
      RAISE_APPLICATION_ERROR(-20073, 'El usuario de la operacion es obligatorio.');
    END IF;

    IF p_monto IS NULL OR p_monto <= 0 THEN
      RAISE_APPLICATION_ERROR(-20074, 'El monto debe ser mayor que cero.');
    END IF;

    IF p_fecha_operacion IS NULL THEN
      RAISE_APPLICATION_ERROR(-20075, 'La fecha de operacion es obligatoria.');
    END IF;

    IF p_beneficiario_ordenante IS NULL
       OR LENGTH(TRIM(p_beneficiario_ordenante)) = 0 THEN
      RAISE_APPLICATION_ERROR(-20076, 'El beneficiario u ordenante es obligatorio.');
    END IF;

    IF p_concepto IS NULL OR LENGTH(TRIM(p_concepto)) < 5 THEN
      RAISE_APPLICATION_ERROR(-20077, 'El concepto debe contener al menos 5 caracteres.');
    END IF;

    BEGIN
      SELECT cuenta_principal_id, estado
        INTO v_cuenta_id, v_estado_operacion
        FROM MB_OPERACION_BANCARIA
       WHERE operacion_id = p_operacion_id
       FOR UPDATE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20078, 'La operacion bancaria indicada no existe.');
    END;

    IF v_cuenta_id IS NULL THEN
      RAISE_APPLICATION_ERROR(-20079, 'La operacion no posee una cuenta bancaria principal.');
    END IF;

    IF v_estado_operacion IN ('ANULADA','RECHAZADA','REVERSADA') THEN
      RAISE_APPLICATION_ERROR(
        -20080,
        'La operacion no permite registrar movimientos en su estado actual: '
        || v_estado_operacion || '.'
      );
    END IF;

    BEGIN
      SELECT estado, permite_cobros, permite_pagos
        INTO v_estado_cuenta, v_permite_cobros, v_permite_pagos
        FROM MB_CUENTA_BANCARIA
       WHERE cuenta_id = v_cuenta_id
       FOR UPDATE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20081, 'La cuenta bancaria de la operacion no existe.');
    END;

    IF v_estado_cuenta <> 'ACTIVA' THEN
      RAISE_APPLICATION_ERROR(-20082, 'La cuenta bancaria debe estar activa.');
    END IF;

    VALIDAR_CATALOGO(p_tipo_movimiento_id, 'TIPO_MOVIMIENTO');

    SELECT naturaleza
      INTO v_naturaleza
      FROM MB_CATALOGO_BANCARIO
     WHERE catalogo_id = p_tipo_movimiento_id;

    IF v_naturaleza = 'C' AND v_permite_cobros <> 'S' THEN
      RAISE_APPLICATION_ERROR(-20083, 'La cuenta seleccionada no permite movimientos de credito.');
    END IF;

    IF v_naturaleza = 'D' AND v_permite_pagos <> 'S' THEN
      RAISE_APPLICATION_ERROR(-20084, 'La cuenta seleccionada no permite movimientos de debito.');
    END IF;

    SELECT COUNT(*)
      INTO v_existentes
      FROM MB_MOVIMIENTO_BANCARIO
     WHERE operacion_id = p_operacion_id;

    IF v_existentes > 0 THEN
      RAISE_APPLICATION_ERROR(-20085, 'La operacion ya posee un movimiento bancario registrado.');
    END IF;

    p_movimiento_id := SEQ_MB_MOVIMIENTO_BANCARIO.NEXTVAL;
    p_numero_movimiento := 'MB-' || LPAD(TO_CHAR(p_movimiento_id), 10, '0');

    INSERT INTO MB_MOVIMIENTO_BANCARIO (
      movimiento_id,
      operacion_id,
      cuenta_id,
      tipo_movimiento_id,
      movimiento_origen_id,
      numero_movimiento,
      fecha_operacion,
      fecha_efectiva,
      referencia_bancaria,
      beneficiario_ordenante,
      concepto,
      monto,
      estado,
      estado_conciliacion
    ) VALUES (
      p_movimiento_id,
      p_operacion_id,
      v_cuenta_id,
      p_tipo_movimiento_id,
      NULL,
      p_numero_movimiento,
      p_fecha_operacion,
      p_fecha_efectiva,
      TRIM(p_referencia_bancaria),
      TRIM(p_beneficiario_ordenante),
      TRIM(p_concepto),
      p_monto,
      'APLICADO',
      'PENDIENTE'
    );

  END REGISTRAR_MOVIMIENTO_OPERACION;

  PROCEDURE REVERSAR_MOVIMIENTO(
    p_movimiento_id              IN NUMBER,
    p_tipo_operacion_reverso_id  IN NUMBER,
    p_tipo_movimiento_reverso_id IN NUMBER,
    p_motivo                     IN VARCHAR2,
    p_usuario_id                 IN NUMBER,
    p_operacion_reverso_id       OUT NUMBER,
    p_movimiento_reverso_id      OUT NUMBER,
    p_numero_movimiento_reverso  OUT VARCHAR2
  ) AS
    v_operacion_id        NUMBER;
    v_cuenta_id           NUMBER;
    v_tipo_movimiento_id  NUMBER;
    v_movimiento_origen_id NUMBER;
    v_numero_original     VARCHAR2(30);
    v_beneficiario        VARCHAR2(150);
    v_concepto            VARCHAR2(250);
    v_monto               NUMBER(18,2);
    v_estado_mov          VARCHAR2(20);
    v_estado_conc         VARCHAR2(20);
    v_empresa_id          NUMBER;
    v_sucursal_id         NUMBER;
    v_estado_operacion    VARCHAR2(20);
    v_naturaleza_original CHAR(1);
    v_permite_reversion   CHAR(1);
    v_naturaleza_reverso  CHAR(1);
    v_reversos_existentes NUMBER;
    v_hist_original       NUMBER;
    v_hist_reverso        NUMBER;
  BEGIN
    IF p_usuario_id IS NULL OR p_usuario_id <= 0 THEN
      RAISE_APPLICATION_ERROR(-20063, 'El usuario de la reversiÃ³n es obligatorio.');
    END IF;

    IF p_motivo IS NULL OR LENGTH(TRIM(p_motivo)) < 5 THEN
      RAISE_APPLICATION_ERROR(-20064, 'Debe indicar un motivo de reversiÃ³n vÃ¡lido.');
    END IF;

    BEGIN
      SELECT
        operacion_id,
        cuenta_id,
        tipo_movimiento_id,
        movimiento_origen_id,
        numero_movimiento,
        beneficiario_ordenante,
        concepto,
        monto,
        estado,
        estado_conciliacion
      INTO
        v_operacion_id,
        v_cuenta_id,
        v_tipo_movimiento_id,
        v_movimiento_origen_id,
        v_numero_original,
        v_beneficiario,
        v_concepto,
        v_monto,
        v_estado_mov,
        v_estado_conc
      FROM MB_MOVIMIENTO_BANCARIO
      WHERE movimiento_id = p_movimiento_id
      FOR UPDATE;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20065, 'El movimiento original no existe.');
    END;

    IF v_estado_mov <> 'APLICADO' THEN
      RAISE_APPLICATION_ERROR(-20066, 'Solo se puede revertir un movimiento aplicado.');
    END IF;

    IF v_movimiento_origen_id IS NOT NULL THEN
      RAISE_APPLICATION_ERROR(-20071, 'Un movimiento compensatorio no puede revertirse desde esta accion.');
    END IF;

    IF v_estado_conc = 'CONCILIADO' THEN
      RAISE_APPLICATION_ERROR(-20067, 'Un movimiento conciliado no puede revertirse desde esta acciÃ³n.');
    END IF;

    SELECT naturaleza, permite_reversion
      INTO v_naturaleza_original, v_permite_reversion
      FROM MB_CATALOGO_BANCARIO
     WHERE catalogo_id = v_tipo_movimiento_id;

    IF v_permite_reversion <> 'S' THEN
      RAISE_APPLICATION_ERROR(-20068, 'El tipo de movimiento original no permite reversiÃ³n.');
    END IF;

    SELECT COUNT(*)
      INTO v_reversos_existentes
      FROM MB_MOVIMIENTO_BANCARIO
     WHERE movimiento_origen_id = p_movimiento_id;

    IF v_reversos_existentes > 0 THEN
      RAISE_APPLICATION_ERROR(-20069, 'El movimiento ya tiene un reverso registrado.');
    END IF;

    VALIDAR_CATALOGO(p_tipo_operacion_reverso_id, 'TIPO_OPERACION');
    VALIDAR_CATALOGO(p_tipo_movimiento_reverso_id, 'TIPO_MOVIMIENTO');

    SELECT naturaleza
      INTO v_naturaleza_reverso
      FROM MB_CATALOGO_BANCARIO
     WHERE catalogo_id = p_tipo_movimiento_reverso_id;

    IF v_naturaleza_reverso = v_naturaleza_original THEN
      RAISE_APPLICATION_ERROR(-20070, 'El movimiento de reverso debe tener naturaleza opuesta al original.');
    END IF;

    SELECT empresa_id, sucursal_id, estado
      INTO v_empresa_id, v_sucursal_id, v_estado_operacion
      FROM MB_OPERACION_BANCARIA
     WHERE operacion_id = v_operacion_id
     FOR UPDATE;

    p_operacion_reverso_id := SEQ_MB_OPERACION_BANCARIA.NEXTVAL;
    p_movimiento_reverso_id := SEQ_MB_MOVIMIENTO_BANCARIO.NEXTVAL;
    v_hist_original := SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL;
    v_hist_reverso := SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL;
    p_numero_movimiento_reverso := 'MBR-' || LPAD(TO_CHAR(p_movimiento_reverso_id), 9, '0');

    INSERT INTO MB_OPERACION_BANCARIA (
      operacion_id,
      empresa_id,
      sucursal_id,
      cuenta_principal_id,
      tipo_operacion_id,
      operacion_relacionada_id,
      modulo_origen,
      documento_origen_id,
      estado,
      creado_por,
      creado_en,
      modificado_por,
      modificado_en
    ) VALUES (
      p_operacion_reverso_id,
      v_empresa_id,
      v_sucursal_id,
      v_cuenta_id,
      p_tipo_operacion_reverso_id,
      v_operacion_id,
      'BANCOS',
      NULL,
      'REGISTRADA',
      p_usuario_id,
      SYSTIMESTAMP,
      NULL,
      NULL
    );

    INSERT INTO MB_MOVIMIENTO_BANCARIO (
      movimiento_id,
      operacion_id,
      cuenta_id,
      tipo_movimiento_id,
      movimiento_origen_id,
      numero_movimiento,
      fecha_operacion,
      fecha_efectiva,
      referencia_bancaria,
      beneficiario_ordenante,
      concepto,
      monto,
      estado,
      estado_conciliacion
    ) VALUES (
      p_movimiento_reverso_id,
      p_operacion_reverso_id,
      v_cuenta_id,
      p_tipo_movimiento_reverso_id,
      p_movimiento_id,
      p_numero_movimiento_reverso,
      TRUNC(CURRENT_DATE),
      TRUNC(CURRENT_DATE),
      SUBSTR('REV-' || v_numero_original, 1, 60),
      v_beneficiario,
      SUBSTR('REVERSO - ' || v_concepto, 1, 250),
      v_monto,
      'APLICADO',
      'PENDIENTE'
    );

    UPDATE MB_MOVIMIENTO_BANCARIO
       SET estado = 'REVERSADO'
     WHERE movimiento_id = p_movimiento_id;

    UPDATE MB_OPERACION_BANCARIA
       SET estado = 'REVERSADA',
           modificado_por = p_usuario_id,
           modificado_en = SYSTIMESTAMP
     WHERE operacion_id = v_operacion_id;

    INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
      historial_id,
      operacion_id,
      estado_anterior,
      estado_nuevo,
      decision,
      motivo,
      usuario_id,
      registrado_en
    ) VALUES (
      v_hist_original,
      v_operacion_id,
      v_estado_operacion,
      'REVERSADA',
      'REVERSAR',
      TRIM(p_motivo),
      p_usuario_id,
      SYSTIMESTAMP
    );

    INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
      historial_id,
      operacion_id,
      estado_anterior,
      estado_nuevo,
      decision,
      motivo,
      usuario_id,
      registrado_en
    ) VALUES (
      v_hist_reverso,
      p_operacion_reverso_id,
      NULL,
      'REGISTRADA',
      'REGISTRAR',
      'Movimiento compensatorio de ' || v_numero_original,
      p_usuario_id,
      SYSTIMESTAMP
    );
  END REVERSAR_MOVIMIENTO;

END PKG_MB_OPERACIONES;
/

-- PACKAGE_BODY PKG_MB_PAGOS
CREATE OR REPLACE PACKAGE BODY "PKG_MB_PAGOS" AS
    PROCEDURE PREPARAR_PAGO (
        p_documento_cxp_id IN NUMBER,
        p_cuenta_id        IN NUMBER,
        p_usuario_id       IN NUMBER,
        p_operacion_id     OUT NUMBER
    ) AS
        v_moneda_id          NUMBER;
        v_saldo_pendiente    NUMBER;
        v_es_pagable         VARCHAR2(1);
        v_empresa_id         NUMBER;
        v_cuenta_moneda_id   NUMBER;
        v_permite_pagos      VARCHAR2(1);
        v_estado_cuenta      VARCHAR2(20);
        v_tipo_operacion_id  NUMBER;
        v_existe             NUMBER;
    BEGIN
        IF p_documento_cxp_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20101, 'Debe indicar el documento CXP.');
        END IF;
        IF p_cuenta_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20102, 'Debe indicar la cuenta bancaria.');
        END IF;
        IF p_usuario_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20103, 'Debe indicar el usuario.');
        END IF;
        SELECT COUNT(*)
        INTO v_existe
        FROM USUARIO
        WHERE USU_ID_USUARIO = p_usuario_id
          AND USU_ACTIVO = 1;
        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20104,
                'El usuario indicado no existe o se encuentra inactivo.'
            );
        END IF;
        BEGIN
            SELECT
                moneda_id,
                saldo_pendiente,
                es_pagable
            INTO
                v_moneda_id,
                v_saldo_pendiente,
                v_es_pagable
            FROM MB_V_CXP_OBLIGACIONES
            WHERE id_documento_origen = p_documento_cxp_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20105,
                    'El documento CXP indicado no existe.'
                );
        END;
        IF v_es_pagable <> 'S' THEN
            RAISE_APPLICATION_ERROR(
                -20106,
                'El documento CXP no se encuentra disponible para pago.'
            );
        END IF;
        IF NVL(v_saldo_pendiente, 0) <= 0 THEN
            RAISE_APPLICATION_ERROR(
                -20107,
                'El documento CXP no tiene saldo pendiente.'
            );
        END IF;
        BEGIN
            SELECT
                empresa_id,
                moneda_id,
                permite_pagos,
                estado
            INTO
                v_empresa_id,
                v_cuenta_moneda_id,
                v_permite_pagos,
                v_estado_cuenta
            FROM MB_CUENTA_BANCARIA
            WHERE cuenta_id = p_cuenta_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20108,
                    'La cuenta bancaria indicada no existe.'
                );
        END;
        IF v_estado_cuenta <> 'ACTIVA' THEN
            RAISE_APPLICATION_ERROR(
                -20109,
                'La cuenta bancaria no se encuentra activa.'
            );
        END IF;
        IF v_permite_pagos <> 'S' THEN
            RAISE_APPLICATION_ERROR(
                -20110,
                'La cuenta bancaria no permite pagos.'
            );
        END IF;
        IF v_cuenta_moneda_id <> v_moneda_id THEN
            RAISE_APPLICATION_ERROR(
                -20111,
                'La moneda de la cuenta no coincide con la moneda del documento.'
            );
        END IF;
        BEGIN
            SELECT catalogo_id
            INTO v_tipo_operacion_id
            FROM MB_CATALOGO_BANCARIO
            WHERE grupo = 'TIPO_OPERACION'
              AND codigo = 'PAGO'
              AND estado = 'ACTIVO';
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20112,
                    'No existe un tipo de operacion PAGO activo.'
                );
            WHEN TOO_MANY_ROWS THEN
                RAISE_APPLICATION_ERROR(
                    -20114,
                    'Existe mas de un tipo de operacion PAGO activo.'
                );
        END;
        SELECT COUNT(*)
        INTO v_existe
        FROM MB_OPERACION_BANCARIA
        WHERE modulo_origen = 'CXP'
          AND documento_origen_id = p_documento_cxp_id
          AND estado NOT IN ('ANULADA', 'RECHAZADA');
        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20113,
                'Ya existe una operacion bancaria activa para este documento CXP.'
            );
        END IF;
        p_operacion_id := SEQ_MB_OPERACION_BANCARIA.NEXTVAL;
        INSERT INTO MB_OPERACION_BANCARIA (
            operacion_id,
            empresa_id,
            sucursal_id,
            cuenta_principal_id,
            tipo_operacion_id,
            operacion_relacionada_id,
            modulo_origen,
            documento_origen_id,
            estado,
            creado_por,
            creado_en,
            modificado_por,
            modificado_en
        )
        VALUES (
            p_operacion_id,
            v_empresa_id,
            NULL,
            p_cuenta_id,
            v_tipo_operacion_id,
            NULL,
            'CXP',
            p_documento_cxp_id,
            'PREPARADA',
            p_usuario_id,
            SYSTIMESTAMP,
            NULL,
            NULL
        );
        INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
            historial_id,
            operacion_id,
            estado_anterior,
            estado_nuevo,
            decision,
            motivo,
            usuario_id,
            registrado_en
        )
        VALUES (
            SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL,
            p_operacion_id,
            NULL,
            'PREPARADA',
            'CREACION',
            'Pago preparado desde documento CXP',
            p_usuario_id,
            SYSTIMESTAMP
        );
    END PREPARAR_PAGO;
    PROCEDURE OBTENER_PAGO (
        p_operacion_id IN NUMBER,
        p_resultado    OUT SYS_REFCURSOR
    ) AS
    BEGIN
        OPEN p_resultado FOR
            SELECT
                o.operacion_id,
                o.empresa_id,
                o.cuenta_principal_id,
                o.tipo_operacion_id,
                o.modulo_origen,
                o.documento_origen_id,
                o.estado,
                o.creado_por,
                o.creado_en,
                v.proveedor_id,
                v.proveedor_nombre,
                v.moneda_codigo,
                v.moneda_id,
                v.saldo_pendiente,
                v.estado_origen
            FROM MB_OPERACION_BANCARIA o
            LEFT JOIN MB_V_CXP_OBLIGACIONES v
              ON v.id_documento_origen = o.documento_origen_id
             AND o.modulo_origen = 'CXP'
            WHERE o.operacion_id = p_operacion_id;
    END OBTENER_PAGO;

    PROCEDURE LISTAR_PAGOS (
        p_estado    IN VARCHAR2,
        p_resultado OUT SYS_REFCURSOR
    ) AS
        v_estado VARCHAR2(30);
    BEGIN
        v_estado := UPPER(TRIM(p_estado));

        OPEN p_resultado FOR
            SELECT
                o.operacion_id,
                o.empresa_id,
                o.cuenta_principal_id,
                o.tipo_operacion_id,
                o.modulo_origen,
                o.documento_origen_id,
                o.estado,
                o.creado_por,
                o.creado_en,
                o.modificado_por,
                o.modificado_en,
                v.proveedor_id,
                v.proveedor_nombre,
                v.proveedor_nit,
                v.tipo_documento,
                v.serie,
                v.numero_documento,
                v.no_factura_compra,
                v.moneda_codigo,
                v.moneda_id,
                v.total_neto,
                v.monto_aplicado,
                v.saldo_pendiente,
                v.fecha_documento,
                v.fecha_vencimiento,
                v.estado_origen,
                c.codigo_cuenta,
                c.numero_cuenta,
                c.nombre_interno AS cuenta_nombre,
                CASE
                    WHEN ch.cheque_id IS NOT NULL THEN 'CHEQUE'
                    WHEN tr.transferencia_id IS NOT NULL THEN 'TRANSFERENCIA'
                    ELSE 'PENDIENTE'
                END AS medio_pago,
                ch.cheque_id,
                ch.numero_cheque,
                ch.monto AS monto_cheque,
                ch.estado AS estado_cheque,
                tr.transferencia_id,
                tr.cta_proveedor_id,
                tr.monto_origen AS monto_transferencia,
                tr.fecha_programada,
                tr.fecha_efectiva,
                tr.referencia_bancaria,
                tr.estado AS estado_transferencia,
                NVL(ch.monto, tr.monto_origen) AS monto_pago
            FROM MB_OPERACION_BANCARIA o
            LEFT JOIN MB_V_CXP_OBLIGACIONES v
              ON v.id_documento_origen = o.documento_origen_id
             AND o.modulo_origen = 'CXP'
            LEFT JOIN MB_CUENTA_BANCARIA c
              ON c.cuenta_id = o.cuenta_principal_id
            LEFT JOIN MB_CHEQUE ch
              ON ch.operacion_id = o.operacion_id
            LEFT JOIN MB_TRANSFERENCIA_BANCARIA tr
              ON tr.operacion_id = o.operacion_id
            WHERE o.modulo_origen = 'CXP'
              AND (
                    v_estado IS NULL
                    OR UPPER(o.estado) = v_estado
                  )
            ORDER BY o.creado_en DESC,
                     o.operacion_id DESC;

    END LISTAR_PAGOS;

    PROCEDURE DETERMINAR_MEDIO_PAGO (
        p_operacion_id IN NUMBER,
        p_medio_pago   OUT VARCHAR2,
        p_motivo       OUT VARCHAR2
    ) AS
        v_proveedor_id        NUMBER;
        v_moneda_id           NUMBER;
        v_cuenta_id           NUMBER;
        v_estado_operacion    VARCHAR2(20);
        v_codigo_banco        VARCHAR2(30);
        v_estado_cuenta       VARCHAR2(20);
        v_permite_pagos       VARCHAR2(1);
        v_permite_cheques     VARCHAR2(1);
        v_permite_transfer    VARCHAR2(1);
        v_moneda_cuenta       NUMBER;
        v_cuentas_verificadas NUMBER;
    BEGIN
        IF p_operacion_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20120,
                'Debe indicar la operacion bancaria.'
            );
        END IF;
        BEGIN
            SELECT
                v.proveedor_id,
                v.moneda_id,
                o.cuenta_principal_id,
                o.estado
            INTO
                v_proveedor_id,
                v_moneda_id,
                v_cuenta_id,
                v_estado_operacion
            FROM MB_OPERACION_BANCARIA o
            JOIN MB_V_CXP_OBLIGACIONES v
              ON v.id_documento_origen = o.documento_origen_id
            WHERE o.operacion_id = p_operacion_id
              AND o.modulo_origen = 'CXP';
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20121,
                    'La operacion indicada no corresponde a un pago CXP valido.'
                );
        END;
        IF v_estado_operacion <> 'PREPARADA' THEN
            RAISE_APPLICATION_ERROR(
                -20122,
                'El medio de pago solo puede determinarse para una operacion PREPARADA.'
            );
        END IF;
        BEGIN
            SELECT
                b.codigo_banco,
                c.estado,
                c.permite_pagos,
                c.permite_cheques,
                c.permite_transferencias,
                c.moneda_id
            INTO
                v_codigo_banco,
                v_estado_cuenta,
                v_permite_pagos,
                v_permite_cheques,
                v_permite_transfer,
                v_moneda_cuenta
            FROM MB_CUENTA_BANCARIA c
            JOIN MB_BANCO b
              ON b.banco_id = c.banco_id
            WHERE c.cuenta_id = v_cuenta_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20123,
                    'La cuenta origen de la operacion no existe.'
                );
        END;
        IF v_estado_cuenta <> 'ACTIVA' THEN
            p_medio_pago := 'NINGUNO';
            p_motivo := 'La cuenta bancaria origen no se encuentra activa.';
            RETURN;
        END IF;
        IF v_permite_pagos <> 'S' THEN
            p_medio_pago := 'NINGUNO';
            p_motivo := 'La cuenta bancaria origen no permite pagos.';
            RETURN;
        END IF;
        IF v_moneda_cuenta <> v_moneda_id THEN
            p_medio_pago := 'NINGUNO';
            p_motivo :=
                'La moneda de la cuenta origen no coincide con la moneda del documento.';
            RETURN;
        END IF;
        SELECT COUNT(*)
        INTO v_cuentas_verificadas
        FROM MB_CUENTA_BANCARIA_PROVEEDOR
        WHERE proveedor_id = v_proveedor_id
          AND moneda_id = v_moneda_id
          AND estado = 'VERIFICADA';
        IF v_cuentas_verificadas = 0 THEN
            IF v_permite_cheques = 'S' THEN
                p_medio_pago := 'CHEQUE';
                p_motivo :=
                    'El proveedor no posee una cuenta bancaria verificada compatible. Se propone pago por cheque.';
            ELSE
                p_medio_pago := 'NINGUNO';
                p_motivo :=
                    'El proveedor no posee una cuenta bancaria verificada y la cuenta origen no permite cheques.';
            END IF;
            RETURN;
        END IF;
        IF v_permite_transfer <> 'S' THEN
            p_medio_pago := 'NINGUNO';
            p_motivo :=
                'El proveedor posee una cuenta bancaria verificada, pero la cuenta origen no permite transferencias.';
            RETURN;
        END IF;
        IF UPPER(v_codigo_banco) NOT LIKE 'BAM%' THEN
            p_medio_pago := 'NINGUNO';
            p_motivo :=
                'El proveedor posee una cuenta bancaria verificada, pero la transferencia debe originarse desde una cuenta BAM habilitada.';
            RETURN;
        END IF;
        p_medio_pago := 'TRANSFERENCIA';
        p_motivo :=
            'El proveedor posee una cuenta bancaria verificada compatible y la cuenta origen BAM permite transferencias.';
    END DETERMINAR_MEDIO_PAGO;
    PROCEDURE RESERVAR_CHEQUE (
        p_operacion_id  IN NUMBER,
        p_chequera_id   IN NUMBER,
        p_monto         IN NUMBER,
        p_concepto      IN VARCHAR2,
        p_usuario_id    IN NUMBER,
        p_cheque_id     OUT NUMBER,
        p_numero_cheque OUT NUMBER
    ) AS
        v_cuenta_operacion     NUMBER;
        v_documento_origen_id  NUMBER;
        v_modulo_origen        VARCHAR2(20);
        v_estado_operacion     VARCHAR2(20);
        v_beneficiario         VARCHAR2(150);
        v_saldo_pendiente      NUMBER;
        v_es_pagable           VARCHAR2(1);
        v_cuenta_chequera      NUMBER;
        v_numero_inicial       NUMBER;
        v_numero_final         NUMBER;
        v_estado_chequera      VARCHAR2(15);
        v_medio_pago           VARCHAR2(30);
        v_motivo_medio         VARCHAR2(500);
        v_existe               NUMBER;
    BEGIN
        IF p_operacion_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20130, 'Debe indicar la operacion bancaria.');
        END IF;
        IF p_chequera_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20131, 'Debe indicar la chequera.');
        END IF;
        IF p_usuario_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20132, 'Debe indicar el usuario.');
        END IF;
        IF p_monto IS NULL OR p_monto <= 0 THEN
            RAISE_APPLICATION_ERROR(
                -20133,
                'El monto del cheque debe ser mayor que cero.'
            );
        END IF;
        IF p_monto <> ROUND(p_monto, 2) THEN
            RAISE_APPLICATION_ERROR(
                -20134,
                'El monto del cheque debe tener como maximo dos decimales.'
            );
        END IF;
        IF TRIM(p_concepto) IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20135,
                'Debe indicar el concepto del cheque.'
            );
        END IF;
        SELECT COUNT(*)
        INTO v_existe
        FROM USUARIO
        WHERE USU_ID_USUARIO = p_usuario_id
          AND USU_ACTIVO = 1;
        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20136,
                'El usuario indicado no existe o se encuentra inactivo.'
            );
        END IF;
        BEGIN
            SELECT
                cuenta_principal_id,
                documento_origen_id,
                modulo_origen,
                estado
            INTO
                v_cuenta_operacion,
                v_documento_origen_id,
                v_modulo_origen,
                v_estado_operacion
            FROM MB_OPERACION_BANCARIA
            WHERE operacion_id = p_operacion_id
            FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20137,
                    'La operacion bancaria indicada no existe.'
                );
        END;
        IF v_modulo_origen <> 'CXP' THEN
            RAISE_APPLICATION_ERROR(
                -20138,
                'La operacion indicada no corresponde a un pago de CXP.'
            );
        END IF;
        IF v_estado_operacion <> 'PREPARADA' THEN
            RAISE_APPLICATION_ERROR(
                -20139,
                'Solo una operacion PREPARADA puede reservar un cheque.'
            );
        END IF;
        BEGIN
            SELECT
                proveedor_nombre,
                saldo_pendiente,
                es_pagable
            INTO
                v_beneficiario,
                v_saldo_pendiente,
                v_es_pagable
            FROM MB_V_CXP_OBLIGACIONES
            WHERE id_documento_origen = v_documento_origen_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20140,
                    'No fue posible recuperar la obligacion CXP de la operacion.'
                );
        END;
        IF v_es_pagable <> 'S' THEN
            RAISE_APPLICATION_ERROR(
                -20141,
                'La obligacion CXP ya no se encuentra disponible para pago.'
            );
        END IF;
        IF p_monto > v_saldo_pendiente THEN
            RAISE_APPLICATION_ERROR(
                -20142,
                'El monto solicitado supera el saldo pendiente del documento.'
            );
        END IF;
        DETERMINAR_MEDIO_PAGO(
            p_operacion_id => p_operacion_id,
            p_medio_pago   => v_medio_pago,
            p_motivo       => v_motivo_medio
        );
        IF v_medio_pago <> 'CHEQUE' THEN
            RAISE_APPLICATION_ERROR(
                -20143,
                'La operacion no puede pagarse por cheque. ' ||
                v_motivo_medio
            );
        END IF;
        SELECT COUNT(*)
        INTO v_existe
        FROM MB_CHEQUE
        WHERE operacion_id = p_operacion_id;
        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20144,
                'La operacion ya posee un cheque asociado.'
            );
        END IF;
        SELECT COUNT(*)
        INTO v_existe
        FROM MB_TRANSFERENCIA_BANCARIA
        WHERE operacion_id = p_operacion_id;
        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20145,
                'La operacion ya posee una transferencia bancaria asociada.'
            );
        END IF;
        BEGIN
            SELECT
                cuenta_id,
                numero_inicial,
                numero_final,
                estado
            INTO
                v_cuenta_chequera,
                v_numero_inicial,
                v_numero_final,
                v_estado_chequera
            FROM MB_CHEQUERA
            WHERE chequera_id = p_chequera_id
            FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20146,
                    'La chequera indicada no existe.'
                );
        END;
        IF v_estado_chequera <> 'ACTIVA' THEN
            RAISE_APPLICATION_ERROR(
                -20147,
                'La chequera indicada no se encuentra ACTIVA.'
            );
        END IF;
        IF v_cuenta_chequera <> v_cuenta_operacion THEN
            RAISE_APPLICATION_ERROR(
                -20148,
                'La chequera no pertenece a la cuenta bancaria de la operacion.'
            );
        END IF;
        SELECT MIN(r.numero_cheque)
        INTO p_numero_cheque
        FROM (
            SELECT
                v_numero_inicial + LEVEL - 1 AS numero_cheque
            FROM DUAL
            CONNECT BY LEVEL <=
                (v_numero_final - v_numero_inicial + 1)
        ) r
        WHERE NOT EXISTS (
            SELECT 1
            FROM MB_CHEQUE c
            WHERE c.chequera_id = p_chequera_id
              AND c.numero_cheque = r.numero_cheque
        );
        IF p_numero_cheque IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20149,
                'La chequera no tiene numeros disponibles.'
            );
        END IF;
        p_cheque_id := SEQ_MB_CHEQUE.NEXTVAL;
        INSERT INTO MB_CHEQUE (
            cheque_id,
            operacion_id,
            pago_id,
            chequera_id,
            movimiento_id,
            numero_cheque,
            beneficiario,
            monto,
            fecha_emision,
            lugar_emision,
            concepto,
            estado
        )
        VALUES (
            p_cheque_id,
            p_operacion_id,
            NULL,
            p_chequera_id,
            NULL,
            p_numero_cheque,
            v_beneficiario,
            p_monto,
            SYSDATE,
            NULL,
            TRIM(p_concepto),
            'RESERVADO'
        );
        UPDATE MB_OPERACION_BANCARIA
        SET
            modificado_por = p_usuario_id,
            modificado_en  = SYSTIMESTAMP
        WHERE operacion_id = p_operacion_id;
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20150,
                'No fue posible reservar el cheque porque la operacion o el correlativo ya fue utilizado.'
            );
    END RESERVAR_CHEQUE;
    PROCEDURE CAMBIAR_ESTADO_CHEQUE (
        p_cheque_id    IN NUMBER,
        p_nuevo_estado IN VARCHAR2,
        p_usuario_id   IN NUMBER
    ) AS
        v_estado_actual    VARCHAR2(20);
        v_operacion_id     NUMBER;
        v_estado_operacion VARCHAR2(30);
        v_existe           NUMBER;
        v_nuevo_estado     VARCHAR2(20);
    BEGIN
        IF p_cheque_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20160, 'Debe indicar el cheque.');
        END IF;
        IF p_usuario_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20161, 'Debe indicar el usuario.');
        END IF;
        v_nuevo_estado := UPPER(TRIM(p_nuevo_estado));
        IF v_nuevo_estado IS NULL THEN
            RAISE_APPLICATION_ERROR(-20162, 'Debe indicar el nuevo estado.');
        END IF;
        SELECT COUNT(*)
          INTO v_existe
          FROM USUARIO
         WHERE USU_ID_USUARIO = p_usuario_id
           AND USU_ACTIVO = 1;
        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(-20163, 'El usuario indicado no existe o se encuentra inactivo.');
        END IF;
        IF v_nuevo_estado NOT IN (
            'RESERVADO','EMITIDO','IMPRESO','ENTREGADO',
            'COBRADO','ANULADO','EXTRAVIADO','REPUESTO'
        ) THEN
            RAISE_APPLICATION_ERROR(-20164, 'El estado indicado no es valido para un cheque.');
        END IF;
        BEGIN
            SELECT estado, operacion_id
              INTO v_estado_actual, v_operacion_id
              FROM MB_CHEQUE
             WHERE cheque_id = p_cheque_id
             FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(-20165, 'El cheque indicado no existe.');
        END;
        SELECT estado
          INTO v_estado_operacion
          FROM MB_OPERACION_BANCARIA
         WHERE operacion_id = v_operacion_id
         FOR UPDATE;
        IF v_estado_actual = v_nuevo_estado THEN
            RETURN;
        END IF;
        IF v_estado_actual = 'RESERVADO' AND v_nuevo_estado = 'EMITIDO' THEN
            RAISE_APPLICATION_ERROR(-20166, 'Use EJECUTAR_PAGO para emitir el cheque y registrar el egreso.');
        END IF;
        IF v_nuevo_estado = 'ANULADO' THEN
            RAISE_APPLICATION_ERROR(-20167, 'Use CANCELAR_PAGO para anular el pago y liberar fondos.');
        END IF;
        IF v_estado_operacion <> 'EJECUTADA' THEN
            RAISE_APPLICATION_ERROR(-20168, 'El seguimiento del cheque requiere una operacion de pago EJECUTADA.');
        END IF;
        IF NOT (
               (v_estado_actual = 'EMITIDO' AND v_nuevo_estado = 'IMPRESO')
            OR (v_estado_actual = 'IMPRESO' AND v_nuevo_estado = 'ENTREGADO')
            OR (v_estado_actual = 'ENTREGADO' AND v_nuevo_estado IN ('COBRADO','EXTRAVIADO'))
            OR (v_estado_actual = 'EXTRAVIADO' AND v_nuevo_estado = 'REPUESTO')
        ) THEN
            RAISE_APPLICATION_ERROR(-20169, 'La transicion de estado solicitada no esta permitida.');
        END IF;
        UPDATE MB_CHEQUE
           SET estado = v_nuevo_estado
         WHERE cheque_id = p_cheque_id;
        UPDATE MB_OPERACION_BANCARIA
           SET modificado_por = p_usuario_id,
               modificado_en = SYSTIMESTAMP
         WHERE operacion_id = v_operacion_id;
    END CAMBIAR_ESTADO_CHEQUE;
    PROCEDURE PREPARAR_TRANSFERENCIA (
        p_operacion_id      IN NUMBER,
        p_cta_proveedor_id  IN NUMBER,
        p_monto             IN NUMBER,
        p_fecha_programada  IN DATE,
        p_concepto          IN VARCHAR2,
        p_usuario_id        IN NUMBER,
        p_transferencia_id  OUT NUMBER
    ) AS
        v_cuenta_origen_id       NUMBER;
        v_documento_origen_id    NUMBER;
        v_modulo_origen          VARCHAR2(20);
        v_estado_operacion       VARCHAR2(20);
        v_proveedor_id           NUMBER;
        v_moneda_documento       NUMBER;
        v_saldo_pendiente        NUMBER;
        v_es_pagable             VARCHAR2(1);
        v_codigo_banco_origen    VARCHAR2(30);
        v_estado_cuenta_origen   VARCHAR2(20);
        v_permite_pagos          VARCHAR2(1);
        v_permite_transfer       VARCHAR2(1);
        v_moneda_origen          NUMBER;
        v_proveedor_destino      NUMBER;
        v_moneda_destino         NUMBER;
        v_estado_destino         VARCHAR2(20);
        v_medio_pago             VARCHAR2(30);
        v_motivo_medio           VARCHAR2(500);
        v_existe                 NUMBER;
    BEGIN
        IF p_operacion_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20170,
                'Debe indicar la operacion bancaria.'
            );
        END IF;
        IF p_cta_proveedor_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20171,
                'Debe indicar la cuenta bancaria del proveedor.'
            );
        END IF;
        IF p_usuario_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20172, 'Debe indicar el usuario.');
        END IF;
        IF p_monto IS NULL OR p_monto <= 0 THEN
            RAISE_APPLICATION_ERROR(
                -20173,
                'El monto de la transferencia debe ser mayor que cero.'
            );
        END IF;
        IF p_monto <> ROUND(p_monto, 2) THEN
            RAISE_APPLICATION_ERROR(
                -20174,
                'El monto de la transferencia debe tener como maximo dos decimales.'
            );
        END IF;
        IF p_fecha_programada IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20175,
                'Debe indicar la fecha programada.'
            );
        END IF;
        IF TRUNC(p_fecha_programada) < TRUNC(SYSDATE) THEN
            RAISE_APPLICATION_ERROR(
                -20176,
                'La fecha programada no puede ser anterior a la fecha actual.'
            );
        END IF;
        IF TRIM(p_concepto) IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20177,
                'Debe indicar el concepto de la transferencia.'
            );
        END IF;
        SELECT COUNT(*)
        INTO v_existe
        FROM USUARIO
        WHERE USU_ID_USUARIO = p_usuario_id
          AND USU_ACTIVO = 1;
        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20178,
                'El usuario indicado no existe o se encuentra inactivo.'
            );
        END IF;
        BEGIN
            SELECT
                cuenta_principal_id,
                documento_origen_id,
                modulo_origen,
                estado
            INTO
                v_cuenta_origen_id,
                v_documento_origen_id,
                v_modulo_origen,
                v_estado_operacion
            FROM MB_OPERACION_BANCARIA
            WHERE operacion_id = p_operacion_id
            FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20179,
                    'La operacion bancaria indicada no existe.'
                );
        END;
        IF v_modulo_origen <> 'CXP' THEN
            RAISE_APPLICATION_ERROR(
                -20180,
                'La operacion indicada no corresponde a un pago de CXP.'
            );
        END IF;
        IF v_estado_operacion <> 'PREPARADA' THEN
            RAISE_APPLICATION_ERROR(
                -20181,
                'Solo una operacion PREPARADA puede generar una transferencia.'
            );
        END IF;
        BEGIN
            SELECT
                proveedor_id,
                moneda_id,
                saldo_pendiente,
                es_pagable
            INTO
                v_proveedor_id,
                v_moneda_documento,
                v_saldo_pendiente,
                v_es_pagable
            FROM MB_V_CXP_OBLIGACIONES
            WHERE id_documento_origen = v_documento_origen_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20182,
                    'No fue posible recuperar la obligacion CXP.'
                );
        END;
        IF v_es_pagable <> 'S' THEN
            RAISE_APPLICATION_ERROR(
                -20183,
                'La obligacion CXP ya no se encuentra disponible para pago.'
            );
        END IF;
        IF p_monto > v_saldo_pendiente THEN
            RAISE_APPLICATION_ERROR(
                -20184,
                'El monto solicitado supera el saldo pendiente del documento.'
            );
        END IF;
        BEGIN
            SELECT
                b.codigo_banco,
                c.estado,
                c.permite_pagos,
                c.permite_transferencias,
                c.moneda_id
            INTO
                v_codigo_banco_origen,
                v_estado_cuenta_origen,
                v_permite_pagos,
                v_permite_transfer,
                v_moneda_origen
            FROM MB_CUENTA_BANCARIA c
            JOIN MB_BANCO b
              ON b.banco_id = c.banco_id
            WHERE c.cuenta_id = v_cuenta_origen_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20185,
                    'La cuenta bancaria origen no existe.'
                );
        END;
        IF v_estado_cuenta_origen <> 'ACTIVA' THEN
            RAISE_APPLICATION_ERROR(
                -20186,
                'La cuenta bancaria origen no se encuentra ACTIVA.'
            );
        END IF;
        IF v_permite_pagos <> 'S' THEN
            RAISE_APPLICATION_ERROR(
                -20187,
                'La cuenta bancaria origen no permite pagos.'
            );
        END IF;
        IF v_permite_transfer <> 'S' THEN
            RAISE_APPLICATION_ERROR(
                -20188,
                'La cuenta bancaria origen no permite transferencias.'
            );
        END IF;
        IF UPPER(v_codigo_banco_origen) NOT LIKE 'BAM%' THEN
            RAISE_APPLICATION_ERROR(
                -20189,
                'Las transferencias a proveedores deben originarse desde una cuenta BAM habilitada.'
            );
        END IF;
        IF v_moneda_origen <> v_moneda_documento THEN
            RAISE_APPLICATION_ERROR(
                -20190,
                'La moneda de la cuenta origen no coincide con la moneda del documento.'
            );
        END IF;
        BEGIN
            SELECT
                proveedor_id,
                moneda_id,
                estado
            INTO
                v_proveedor_destino,
                v_moneda_destino,
                v_estado_destino
            FROM MB_CUENTA_BANCARIA_PROVEEDOR
            WHERE cta_proveedor_id = p_cta_proveedor_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20191,
                    'La cuenta bancaria del proveedor indicada no existe.'
                );
        END;
        IF v_proveedor_destino <> v_proveedor_id THEN
            RAISE_APPLICATION_ERROR(
                -20192,
                'La cuenta bancaria indicada no pertenece al proveedor del documento CXP.'
            );
        END IF;
        IF v_estado_destino <> 'VERIFICADA' THEN
            RAISE_APPLICATION_ERROR(
                -20193,
                'La cuenta bancaria del proveedor no se encuentra VERIFICADA.'
            );
        END IF;
        IF v_moneda_destino <> v_moneda_documento THEN
            RAISE_APPLICATION_ERROR(
                -20194,
                'La moneda de la cuenta del proveedor no coincide con la moneda del documento.'
            );
        END IF;
        DETERMINAR_MEDIO_PAGO(
            p_operacion_id => p_operacion_id,
            p_medio_pago   => v_medio_pago,
            p_motivo       => v_motivo_medio
        );
        IF v_medio_pago <> 'TRANSFERENCIA' THEN
            RAISE_APPLICATION_ERROR(
                -20195,
                'La operacion no puede pagarse por transferencia. ' ||
                v_motivo_medio
            );
        END IF;
        SELECT COUNT(*)
        INTO v_existe
        FROM MB_TRANSFERENCIA_BANCARIA
        WHERE operacion_id = p_operacion_id;
        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20196,
                'La operacion ya posee una transferencia bancaria asociada.'
            );
        END IF;
        SELECT COUNT(*)
        INTO v_existe
        FROM MB_CHEQUE
        WHERE operacion_id = p_operacion_id;
        IF v_existe > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20197,
                'La operacion ya posee un cheque asociado.'
            );
        END IF;
        p_transferencia_id :=
            SEQ_MB_TRANSFERENCIA_BANCARIA.NEXTVAL;
        INSERT INTO MB_TRANSFERENCIA_BANCARIA (
            transferencia_id,
            operacion_id,
            pago_id,
            cuenta_origen_id,
            cuenta_destino_id,
            cta_proveedor_id,
            fecha_programada,
            fecha_efectiva,
            monto_origen,
            tipo_cambio,
            monto_destino,
            referencia_bancaria,
            concepto,
            estado
        )
        VALUES (
            p_transferencia_id,
            p_operacion_id,
            NULL,
            v_cuenta_origen_id,
            NULL,
            p_cta_proveedor_id,
            p_fecha_programada,
            NULL,
            p_monto,
            1,
            p_monto,
            NULL,
            TRIM(p_concepto),
            'BORRADOR'
        );
        UPDATE MB_OPERACION_BANCARIA
        SET
            modificado_por = p_usuario_id,
            modificado_en  = SYSTIMESTAMP
        WHERE operacion_id = p_operacion_id;
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN
            RAISE_APPLICATION_ERROR(
                -20198,
                'La operacion ya posee una transferencia bancaria asociada.'
            );
    END PREPARAR_TRANSFERENCIA;
    PROCEDURE CAMBIAR_ESTADO_TRANSFERENCIA (
        p_transferencia_id    IN NUMBER,
        p_nuevo_estado        IN VARCHAR2,
        p_referencia_bancaria IN VARCHAR2,
        p_usuario_id          IN NUMBER
    ) AS
        v_estado_actual      VARCHAR2(20);
        v_operacion_id       NUMBER;
        v_estado_operacion   VARCHAR2(30);
        v_nuevo_estado       VARCHAR2(20);
        v_existe             NUMBER;
        v_compromiso_id      NUMBER;
        v_compromisos        NUMBER;
    BEGIN
        IF p_transferencia_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20200, 'Debe indicar la transferencia bancaria.');
        END IF;
        IF p_usuario_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20201, 'Debe indicar el usuario.');
        END IF;
        v_nuevo_estado := UPPER(TRIM(p_nuevo_estado));
        IF v_nuevo_estado IS NULL THEN
            RAISE_APPLICATION_ERROR(-20202, 'Debe indicar el nuevo estado de la transferencia.');
        END IF;
        SELECT COUNT(*)
          INTO v_existe
          FROM USUARIO
         WHERE USU_ID_USUARIO = p_usuario_id
           AND USU_ACTIVO = 1;
        IF v_existe = 0 THEN
            RAISE_APPLICATION_ERROR(-20203, 'El usuario indicado no existe o se encuentra inactivo.');
        END IF;
        IF v_nuevo_estado NOT IN ('BORRADOR','PROGRAMADA','EJECUTADA','RECHAZADA','ANULADA') THEN
            RAISE_APPLICATION_ERROR(-20204, 'El estado indicado no es valido para una transferencia bancaria.');
        END IF;
        BEGIN
            SELECT estado, operacion_id
              INTO v_estado_actual, v_operacion_id
              FROM MB_TRANSFERENCIA_BANCARIA
             WHERE transferencia_id = p_transferencia_id
             FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(-20205, 'La transferencia bancaria indicada no existe.');
        END;
        SELECT estado
          INTO v_estado_operacion
          FROM MB_OPERACION_BANCARIA
         WHERE operacion_id = v_operacion_id
         FOR UPDATE;
        IF v_estado_actual = v_nuevo_estado THEN
            RETURN;
        END IF;
        IF v_nuevo_estado = 'EJECUTADA' THEN
            RAISE_APPLICATION_ERROR(-20206, 'Use EJECUTAR_PAGO para ejecutar la transferencia y registrar el egreso.');
        END IF;
        IF v_nuevo_estado = 'ANULADA' THEN
            RAISE_APPLICATION_ERROR(-20207, 'Use CANCELAR_PAGO para anular la transferencia y liberar fondos.');
        END IF;
        IF v_estado_actual = 'BORRADOR' AND v_nuevo_estado = 'PROGRAMADA' THEN
            IF v_estado_operacion <> 'AUTORIZADA' THEN
                RAISE_APPLICATION_ERROR(-20208, 'La transferencia solo puede programarse cuando el pago esta AUTORIZADO.');
            END IF;
            UPDATE MB_TRANSFERENCIA_BANCARIA
               SET estado = 'PROGRAMADA'
             WHERE transferencia_id = p_transferencia_id;
            UPDATE MB_OPERACION_BANCARIA
               SET modificado_por = p_usuario_id,
                   modificado_en = SYSTIMESTAMP
             WHERE operacion_id = v_operacion_id;
            RETURN;
        END IF;
        IF v_estado_actual = 'PROGRAMADA' AND v_nuevo_estado = 'RECHAZADA' THEN
            IF v_estado_operacion <> 'AUTORIZADA' THEN
                RAISE_APPLICATION_ERROR(-20209, 'Solo una transferencia de un pago AUTORIZADO puede registrarse como RECHAZADA.');
            END IF;
            SELECT COUNT(*), MAX(compromiso_id)
              INTO v_compromisos, v_compromiso_id
              FROM MB_FONDO_COMPROMETIDO
             WHERE operacion_id = v_operacion_id
               AND estado = 'ACTIVO';
            IF v_compromisos > 1 THEN
                RAISE_APPLICATION_ERROR(-20210, 'La operacion posee multiples compromisos activos y requiere revision.');
            ELSIF v_compromisos = 1 THEN
                MB_FONDOS.LIBERAR(v_compromiso_id);
            END IF;
            UPDATE MB_TRANSFERENCIA_BANCARIA
               SET estado = 'RECHAZADA'
             WHERE transferencia_id = p_transferencia_id;
            UPDATE MB_OPERACION_BANCARIA
               SET estado = 'RECHAZADA',
                   modificado_por = p_usuario_id,
                   modificado_en = SYSTIMESTAMP
             WHERE operacion_id = v_operacion_id;
            INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
                historial_id, operacion_id, estado_anterior, estado_nuevo,
                decision, motivo, usuario_id, registrado_en
            ) VALUES (
                SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL,
                v_operacion_id,
                'AUTORIZADA',
                'RECHAZADA',
                'RECHAZAR',
                'Transferencia rechazada por el banco.',
                p_usuario_id,
                SYSTIMESTAMP
            );
            RETURN;
        END IF;
        RAISE_APPLICATION_ERROR(-20211, 'La transicion solicitada no esta permitida.');
    END CAMBIAR_ESTADO_TRANSFERENCIA;
    PROCEDURE AUTORIZAR_PAGO (
        p_operacion_id    IN NUMBER,
        p_usuario_id      IN NUMBER,
        p_motivo          IN VARCHAR2,
        p_regla_id        OUT NUMBER,
        p_compromiso_id   OUT NUMBER,
        p_estado_final    OUT VARCHAR2
    ) AS
        v_empresa_id              NUMBER;
        v_tipo_operacion_id       NUMBER;
        v_cuenta_id               NUMBER;
        v_estado_operacion        VARCHAR2(30);
        v_moneda_id               NUMBER;
        v_monto                   NUMBER(18,2);
        v_cantidad_aprobaciones   NUMBER;
        v_doble_aprobacion        CHAR(1);
        v_requiere_evidencia      CHAR(1);
        v_aprobaciones_actuales   NUMBER;
        v_aprobacion_usuario      NUMBER;
        v_evidencias              NUMBER;
        v_cheques                 NUMBER;
        v_transferencias          NUMBER;
        v_usuario_valido          NUMBER;
        v_estado_anterior         VARCHAR2(30);
    BEGIN
        p_regla_id      := NULL;
        p_compromiso_id := NULL;
        p_estado_final  := NULL;
        IF p_operacion_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20220,
                'Debe indicar la operacion bancaria.'
            );
        END IF;
        IF p_usuario_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20221,
                'Debe indicar el usuario que autoriza.'
            );
        END IF;
        IF TRIM(p_motivo) IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20222,
                'Debe indicar el motivo o comentario de la autorizacion.'
            );
        END IF;
        SELECT COUNT(*)
        INTO v_usuario_valido
        FROM USUARIO
        WHERE USU_ID_USUARIO = p_usuario_id
          AND USU_ACTIVO = 1;
        IF v_usuario_valido = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20223,
                'El usuario indicado no existe o se encuentra inactivo.'
            );
        END IF;
        BEGIN
            SELECT
                empresa_id,
                tipo_operacion_id,
                cuenta_principal_id,
                estado
            INTO
                v_empresa_id,
                v_tipo_operacion_id,
                v_cuenta_id,
                v_estado_operacion
            FROM MB_OPERACION_BANCARIA
            WHERE operacion_id = p_operacion_id
              AND modulo_origen = 'CXP'
            FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20224,
                    'La operacion indicada no corresponde a un pago CXP valido.'
                );
        END;
        IF v_estado_operacion NOT IN (
            'PREPARADA',
            'PENDIENTE_APROBACION'
        ) THEN
            RAISE_APPLICATION_ERROR(
                -20225,
                'La operacion no se encuentra disponible para autorizacion. Estado actual: '
                || v_estado_operacion
                || '.'
            );
        END IF;
        v_estado_anterior := v_estado_operacion;
        BEGIN
            SELECT moneda_id
            INTO v_moneda_id
            FROM MB_CUENTA_BANCARIA
            WHERE cuenta_id = v_cuenta_id;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20226,
                    'La cuenta principal de la operacion no existe.'
                );
        END;
        SELECT
            COUNT(*),
            NVL(MAX(monto), 0)
        INTO
            v_cheques,
            v_monto
        FROM MB_CHEQUE
        WHERE operacion_id = p_operacion_id
          AND estado NOT IN ('ANULADO', 'REPUESTO');
        SELECT COUNT(*)
        INTO v_transferencias
        FROM MB_TRANSFERENCIA_BANCARIA
        WHERE operacion_id = p_operacion_id
          AND estado <> 'ANULADA';
        IF v_cheques > 0 AND v_transferencias > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20227,
                'La operacion posee simultaneamente cheque y transferencia. Debe revisarse.'
            );
        END IF;
        IF v_cheques = 0 AND v_transferencias = 0 THEN
            RAISE_APPLICATION_ERROR(
                -20228,
                'La operacion aun no posee un cheque o transferencia preparado para autorizar.'
            );
        END IF;
        IF v_transferencias > 0 THEN
            SELECT monto_origen
            INTO v_monto
            FROM MB_TRANSFERENCIA_BANCARIA
            WHERE operacion_id = p_operacion_id
              AND estado <> 'ANULADA';
        END IF;
        IF NVL(v_monto, 0) <= 0 THEN
            RAISE_APPLICATION_ERROR(
                -20229,
                'No fue posible determinar un monto valido para autorizar.'
            );
        END IF;
        p_regla_id :=
            PKG_MB_REGLAS_APROBACION.OBTENER_ID_APLICABLE(
                p_empresa_id         => v_empresa_id,
                p_tipo_operacion_id  => v_tipo_operacion_id,
                p_moneda_id          => v_moneda_id,
                p_monto              => v_monto,
                p_fecha              => SYSDATE
            );
        IF p_regla_id IS NULL THEN
            RAISE_APPLICATION_ERROR(
                -20230,
                'No existe una regla de aprobacion vigente aplicable al pago.'
            );
        END IF;
        BEGIN
            SELECT
                cantidad_aprobaciones,
                doble_aprobacion,
                requiere_evidencia
            INTO
                v_cantidad_aprobaciones,
                v_doble_aprobacion,
                v_requiere_evidencia
            FROM MB_REGLA_APROBACION_BANCARIA
            WHERE regla_id = p_regla_id
              AND estado = 'ACTIVA';
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20231,
                    'La regla de aprobacion resuelta ya no se encuentra activa.'
                );
        END;
        IF v_requiere_evidencia = 'S' THEN
            SELECT COUNT(*)
            INTO v_evidencias
            FROM MB_DOCUMENTO_OPERACION
            WHERE operacion_id = p_operacion_id
              AND proposito IN (
                    'EVIDENCIA',
                    'RESPALDO',
                    'COMPROBANTE'
              );
            IF v_evidencias = 0 THEN
                RAISE_APPLICATION_ERROR(
                    -20232,
                    'La regla de aprobacion exige evidencia y la operacion no posee documentos asociados.'
                );
            END IF;
        END IF;
        SELECT COUNT(*)
        INTO v_aprobacion_usuario
        FROM MB_HISTORIAL_ESTADO_OPERACION
        WHERE operacion_id = p_operacion_id
          AND decision = 'APROBAR'
          AND usuario_id = p_usuario_id;
        IF v_aprobacion_usuario > 0 THEN
            RAISE_APPLICATION_ERROR(
                -20233,
                'El usuario ya registro una aprobacion para esta operacion.'
            );
        END IF;
        SELECT COUNT(DISTINCT usuario_id)
        INTO v_aprobaciones_actuales
        FROM MB_HISTORIAL_ESTADO_OPERACION
        WHERE operacion_id = p_operacion_id
          AND decision = 'APROBAR';
        IF v_aprobaciones_actuales + 1
           < v_cantidad_aprobaciones THEN
            UPDATE MB_OPERACION_BANCARIA
            SET
                estado = 'PENDIENTE_APROBACION',
                modificado_por = p_usuario_id,
                modificado_en = SYSTIMESTAMP
            WHERE operacion_id = p_operacion_id;
            INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
                historial_id,
                operacion_id,
                estado_anterior,
                estado_nuevo,
                decision,
                motivo,
                usuario_id,
                registrado_en
            )
            VALUES (
                SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL,
                p_operacion_id,
                v_estado_anterior,
                'PENDIENTE_APROBACION',
                'APROBAR',
                'Regla '
                    || p_regla_id
                    || '. '
                    || TRIM(p_motivo),
                p_usuario_id,
                SYSTIMESTAMP
            );
            p_estado_final :=
                'PENDIENTE_APROBACION';
            RETURN;
        END IF;
        MB_FONDOS.RESERVAR(
            p_operacion_id   => p_operacion_id,
            p_cuenta_id      => v_cuenta_id,
            p_monto          => v_monto,
            p_compromiso_id  => p_compromiso_id
        );
        UPDATE MB_OPERACION_BANCARIA
        SET
            estado = 'AUTORIZADA',
            modificado_por = p_usuario_id,
            modificado_en = SYSTIMESTAMP
        WHERE operacion_id = p_operacion_id;
        INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
            historial_id,
            operacion_id,
            estado_anterior,
            estado_nuevo,
            decision,
            motivo,
            usuario_id,
            registrado_en
        )
        VALUES (
            SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL,
            p_operacion_id,
            v_estado_anterior,
            'AUTORIZADA',
            'APROBAR',
            'Regla '
                || p_regla_id
                || '. '
                || TRIM(p_motivo),
            p_usuario_id,
            SYSTIMESTAMP
        );
        p_estado_final :=
            'AUTORIZADA';
    END AUTORIZAR_PAGO;
    PROCEDURE CANCELAR_PAGO (
        p_operacion_id IN NUMBER,
        p_motivo       IN VARCHAR2,
        p_usuario_id   IN NUMBER
    ) AS
        v_estado_operacion  MB_OPERACION_BANCARIA.estado%TYPE;
        v_usuario_valido    PLS_INTEGER;
        v_movimientos       PLS_INTEGER;
        v_compromisos       PLS_INTEGER;
        v_compromiso_id     MB_FONDO_COMPROMETIDO.compromiso_id%TYPE;
        v_cheque_id         MB_CHEQUE.cheque_id%TYPE;
        v_cheque_estado     MB_CHEQUE.estado%TYPE;
        v_trf_id            MB_TRANSFERENCIA_BANCARIA.transferencia_id%TYPE;
        v_trf_estado        MB_TRANSFERENCIA_BANCARIA.estado%TYPE;
    BEGIN
        IF p_operacion_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20240, 'Debe indicar la operacion bancaria.');
        END IF;
        IF p_usuario_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20241, 'Debe indicar el usuario.');
        END IF;
        IF TRIM(p_motivo) IS NULL THEN
            RAISE_APPLICATION_ERROR(-20242, 'Debe indicar el motivo de cancelacion.');
        END IF;
        SELECT COUNT(*)
          INTO v_usuario_valido
          FROM USUARIO
         WHERE USU_ID_USUARIO = p_usuario_id
           AND USU_ACTIVO = 1;
        IF v_usuario_valido = 0 THEN
            RAISE_APPLICATION_ERROR(-20243, 'El usuario indicado no existe o se encuentra inactivo.');
        END IF;
        BEGIN
            SELECT estado
              INTO v_estado_operacion
              FROM MB_OPERACION_BANCARIA
             WHERE operacion_id = p_operacion_id
               AND modulo_origen = 'CXP'
             FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(-20244, 'La operacion indicada no corresponde a un pago CXP valido.');
        END;
        IF v_estado_operacion = 'ANULADA' THEN
            RETURN;
        END IF;
        IF v_estado_operacion IN ('EJECUTADA','REVERSADA') THEN
            RAISE_APPLICATION_ERROR(-20245, 'Una operacion ejecutada no puede cancelarse; debe utilizarse el proceso de reverso cuando corresponda.');
        END IF;
        IF v_estado_operacion NOT IN ('PREPARADA','PENDIENTE_APROBACION','AUTORIZADA') THEN
            RAISE_APPLICATION_ERROR(-20246, 'La operacion no puede cancelarse desde el estado ' || v_estado_operacion || '.');
        END IF;
        SELECT COUNT(*)
          INTO v_movimientos
          FROM MB_MOVIMIENTO_BANCARIO
         WHERE operacion_id = p_operacion_id;
        IF v_movimientos > 0 THEN
            RAISE_APPLICATION_ERROR(-20247, 'La operacion ya posee un movimiento bancario y no puede cancelarse como preparacion.');
        END IF;
        BEGIN
            SELECT cheque_id, estado
              INTO v_cheque_id, v_cheque_estado
              FROM MB_CHEQUE
             WHERE operacion_id = p_operacion_id
             FOR UPDATE;
            IF v_cheque_estado IN ('ENTREGADO','COBRADO','EXTRAVIADO','REPUESTO') THEN
                RAISE_APPLICATION_ERROR(-20248, 'El cheque ya se encuentra en un estado que requiere tratamiento de incidencia o reverso.');
            END IF;
            IF v_cheque_estado <> 'ANULADO' THEN
                UPDATE MB_CHEQUE
                   SET estado = 'ANULADO'
                 WHERE cheque_id = v_cheque_id;
            END IF;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;
        BEGIN
            SELECT transferencia_id, estado
              INTO v_trf_id, v_trf_estado
              FROM MB_TRANSFERENCIA_BANCARIA
             WHERE operacion_id = p_operacion_id
             FOR UPDATE;
            IF v_trf_estado = 'EJECUTADA' THEN
                RAISE_APPLICATION_ERROR(-20249, 'La transferencia ya fue ejecutada y no puede anularse localmente.');
            END IF;
            IF v_trf_estado <> 'ANULADA' THEN
                UPDATE MB_TRANSFERENCIA_BANCARIA
                   SET estado = 'ANULADA'
                 WHERE transferencia_id = v_trf_id;
            END IF;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;
        SELECT COUNT(*), MAX(compromiso_id)
          INTO v_compromisos, v_compromiso_id
          FROM MB_FONDO_COMPROMETIDO
         WHERE operacion_id = p_operacion_id
           AND estado = 'ACTIVO';
        IF v_compromisos > 1 THEN
            RAISE_APPLICATION_ERROR(-20250, 'La operacion posee multiples compromisos activos y requiere revision.');
        ELSIF v_compromisos = 1 THEN
            MB_FONDOS.LIBERAR(v_compromiso_id);
        END IF;
        UPDATE MB_OPERACION_BANCARIA
           SET estado = 'ANULADA',
               modificado_por = p_usuario_id,
               modificado_en = SYSTIMESTAMP
         WHERE operacion_id = p_operacion_id;
        INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
            historial_id, operacion_id, estado_anterior, estado_nuevo,
            decision, motivo, usuario_id, registrado_en
        ) VALUES (
            SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL,
            p_operacion_id,
            v_estado_operacion,
            'ANULADA',
            'CANCELAR',
            TRIM(p_motivo),
            p_usuario_id,
            SYSTIMESTAMP
        );
    END CANCELAR_PAGO;
    PROCEDURE EJECUTAR_PAGO (
        p_operacion_id          IN NUMBER,
        p_referencia_bancaria   IN VARCHAR2,
        p_usuario_id            IN NUMBER,
        p_movimiento_id         OUT NUMBER,
        p_numero_movimiento     OUT VARCHAR2
    ) AS
        v_estado_operacion    MB_OPERACION_BANCARIA.estado%TYPE;
        v_tipo_operacion_id   MB_OPERACION_BANCARIA.tipo_operacion_id%TYPE;
        v_cuenta_id           MB_OPERACION_BANCARIA.cuenta_principal_id%TYPE;
        v_documento_cxp_id    MB_OPERACION_BANCARIA.documento_origen_id%TYPE;
        v_sucursal_id         MB_OPERACION_BANCARIA.sucursal_id%TYPE;
        v_usuario_valido      PLS_INTEGER;
        v_compromisos         PLS_INTEGER;
        v_compromiso_id       MB_FONDO_COMPROMETIDO.compromiso_id%TYPE;
        v_estado_compromiso   MB_FONDO_COMPROMETIDO.estado%TYPE;
        v_cheques             PLS_INTEGER;
        v_transferencias      PLS_INTEGER;
        v_cheque_id           MB_CHEQUE.cheque_id%TYPE;
        v_cheque_estado       MB_CHEQUE.estado%TYPE;
        v_beneficiario        MB_CHEQUE.beneficiario%TYPE;
        v_monto               NUMBER(18,2);
        v_concepto            VARCHAR2(250);
        v_trf_id              MB_TRANSFERENCIA_BANCARIA.transferencia_id%TYPE;
        v_trf_estado          MB_TRANSFERENCIA_BANCARIA.estado%TYPE;
        v_tipo_movimiento_id  MB_CATALOGO_BANCARIO.catalogo_id%TYPE;
        v_tipo_mov_count      PLS_INTEGER;
        v_mov_existente       PLS_INTEGER;
    BEGIN
        p_movimiento_id := NULL;
        p_numero_movimiento := NULL;
        IF p_operacion_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20260, 'Debe indicar la operacion bancaria.');
        END IF;
        IF p_usuario_id IS NULL THEN
            RAISE_APPLICATION_ERROR(-20261, 'Debe indicar el usuario.');
        END IF;
        SELECT COUNT(*)
          INTO v_usuario_valido
          FROM USUARIO
         WHERE USU_ID_USUARIO = p_usuario_id
           AND USU_ACTIVO = 1;
        IF v_usuario_valido = 0 THEN
            RAISE_APPLICATION_ERROR(-20262, 'El usuario indicado no existe o se encuentra inactivo.');
        END IF;
        BEGIN
            SELECT estado,
                   tipo_operacion_id,
                   cuenta_principal_id,
                   documento_origen_id,
                   sucursal_id
              INTO v_estado_operacion,
                   v_tipo_operacion_id,
                   v_cuenta_id,
                   v_documento_cxp_id,
                   v_sucursal_id
              FROM MB_OPERACION_BANCARIA
             WHERE operacion_id = p_operacion_id
               AND modulo_origen = 'CXP'
             FOR UPDATE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(-20263, 'La operacion indicada no corresponde a un pago CXP valido.');
        END;
        IF v_estado_operacion = 'EJECUTADA' THEN
            SELECT COUNT(*), MAX(movimiento_id), MAX(numero_movimiento)
              INTO v_mov_existente, p_movimiento_id, p_numero_movimiento
              FROM MB_MOVIMIENTO_BANCARIO
             WHERE operacion_id = p_operacion_id;
            IF v_mov_existente = 1 THEN
                RETURN;
            END IF;
            RAISE_APPLICATION_ERROR(-20264, 'La operacion figura EJECUTADA pero no posee exactamente un movimiento bancario.');
        END IF;
        IF v_estado_operacion <> 'AUTORIZADA' THEN
            RAISE_APPLICATION_ERROR(-20265, 'Solo un pago AUTORIZADO puede ejecutarse. Estado actual: ' || v_estado_operacion || '.');
        END IF;
        SELECT COUNT(*), MAX(compromiso_id), MAX(estado)
          INTO v_compromisos, v_compromiso_id, v_estado_compromiso
          FROM MB_FONDO_COMPROMETIDO
         WHERE operacion_id = p_operacion_id;
        IF v_compromisos <> 1 THEN
            RAISE_APPLICATION_ERROR(-20266, 'El pago autorizado debe poseer exactamente un compromiso de fondos.');
        END IF;
        IF v_estado_compromiso NOT IN ('ACTIVO','CONSUMIDO') THEN
            RAISE_APPLICATION_ERROR(-20267, 'El compromiso del pago no se encuentra disponible para ejecucion. Estado: ' || v_estado_compromiso || '.');
        END IF;
        SELECT COUNT(*)
          INTO v_cheques
          FROM MB_CHEQUE
         WHERE operacion_id = p_operacion_id
           AND estado <> 'ANULADO';
        SELECT COUNT(*)
          INTO v_transferencias
          FROM MB_TRANSFERENCIA_BANCARIA
         WHERE operacion_id = p_operacion_id
           AND estado <> 'ANULADA';
        IF v_cheques + v_transferencias <> 1 THEN
            RAISE_APPLICATION_ERROR(-20268, 'La operacion debe poseer exactamente un medio de pago activo.');
        END IF;
        SELECT COUNT(*), MAX(catalogo_id)
          INTO v_tipo_mov_count, v_tipo_movimiento_id
          FROM MB_CATALOGO_BANCARIO
         WHERE grupo = 'TIPO_MOVIMIENTO'
           AND naturaleza = 'D'
           AND estado = 'ACTIVO';
        IF v_tipo_mov_count <> 1 THEN
            RAISE_APPLICATION_ERROR(-20269, 'Debe existir exactamente un tipo de movimiento DEBITO activo para ejecutar pagos.');
        END IF;
        IF v_cheques = 1 THEN
            SELECT cheque_id, estado, beneficiario, monto, concepto
              INTO v_cheque_id, v_cheque_estado, v_beneficiario, v_monto, v_concepto
              FROM MB_CHEQUE
             WHERE operacion_id = p_operacion_id
               AND estado <> 'ANULADO'
             FOR UPDATE;
            IF v_cheque_estado <> 'RESERVADO' THEN
                RAISE_APPLICATION_ERROR(-20270, 'El cheque debe encontrarse RESERVADO para ejecutar el pago. Estado actual: ' || v_cheque_estado || '.');
            END IF;
        ELSE
            SELECT t.transferencia_id,
                   t.estado,
                   t.monto_origen,
                   t.concepto,
                   v.proveedor_nombre
              INTO v_trf_id,
                   v_trf_estado,
                   v_monto,
                   v_concepto,
                   v_beneficiario
              FROM MB_TRANSFERENCIA_BANCARIA t
              JOIN MB_OPERACION_BANCARIA o
                ON o.operacion_id = t.operacion_id
              JOIN MB_V_CXP_OBLIGACIONES v
                ON v.id_documento_origen = o.documento_origen_id
             WHERE t.operacion_id = p_operacion_id
               AND t.estado <> 'ANULADA'
             FOR UPDATE OF t.estado;
            IF v_trf_estado <> 'PROGRAMADA' THEN
                RAISE_APPLICATION_ERROR(-20271, 'La transferencia debe encontrarse PROGRAMADA para ejecutar el pago. Estado actual: ' || v_trf_estado || '.');
            END IF;
            IF TRIM(p_referencia_bancaria) IS NULL THEN
                RAISE_APPLICATION_ERROR(-20272, 'La transferencia ejecutada requiere referencia bancaria.');
            END IF;
        END IF;
        PKG_MB_OPERACIONES.REGISTRAR_MOVIMIENTO_OPERACION(
            p_operacion_id            => p_operacion_id,
            p_tipo_movimiento_id      => v_tipo_movimiento_id,
            p_fecha_operacion         => TRUNC(CURRENT_DATE),
            p_fecha_efectiva          => TRUNC(CURRENT_DATE),
            p_referencia_bancaria     => CASE WHEN v_transferencias = 1 THEN TRIM(p_referencia_bancaria) ELSE NULL END,
            p_beneficiario_ordenante  => v_beneficiario,
            p_concepto                => v_concepto,
            p_monto                   => v_monto,
            p_usuario_id              => p_usuario_id,
            p_movimiento_id           => p_movimiento_id,
            p_numero_movimiento       => p_numero_movimiento
        );
        MB_FONDOS.CONSUMIR(v_compromiso_id);
        IF v_cheques = 1 THEN
            UPDATE MB_CHEQUE
               SET estado = 'EMITIDO',
                   movimiento_id = p_movimiento_id
             WHERE cheque_id = v_cheque_id;
        ELSE
            UPDATE MB_TRANSFERENCIA_BANCARIA
               SET estado = 'EJECUTADA',
                   fecha_efectiva = SYSDATE,
                   referencia_bancaria = TRIM(p_referencia_bancaria)
             WHERE transferencia_id = v_trf_id;
        END IF;
        UPDATE MB_OPERACION_BANCARIA
           SET estado = 'EJECUTADA',
               modificado_por = p_usuario_id,
               modificado_en = SYSTIMESTAMP
         WHERE operacion_id = p_operacion_id;
        INSERT INTO MB_HISTORIAL_ESTADO_OPERACION (
            historial_id, operacion_id, estado_anterior, estado_nuevo,
            decision, motivo, usuario_id, registrado_en
        ) VALUES (
            SEQ_MB_HISTORIAL_ESTADO_OPERACION.NEXTVAL,
            p_operacion_id,
            'AUTORIZADA',
            'EJECUTADA',
            'EJECUTAR',
            CASE
                WHEN v_cheques = 1 THEN 'Pago ejecutado por cheque; egreso reconocido al emitir.'
                ELSE 'Transferencia bancaria ejecutada y confirmada.'
            END,
            p_usuario_id,
            SYSTIMESTAMP
        );
    END EJECUTAR_PAGO;
END PKG_MB_PAGOS;
/

-- PACKAGE_BODY PKG_MB_PARAMETROS_CONCILIACION
CREATE OR REPLACE PACKAGE BODY "PKG_MB_PARAMETROS_CONCILIACION" AS
  -- No COMMIT/ROLLBACK aqui: la API (o el consumidor PL/SQL) controla la transaccion.
  -- Bloqueo de catalogo de bajo volumen para serializar las comprobaciones de
  -- duplicados/superposiciones incluso entre sesiones concurrentes del package.
  PROCEDURE validar(r IN MB_PARAMETRO_CONCILIACION%ROWTYPE) IS
    n PLS_INTEGER;
  BEGIN
    IF r.estado IS NULL OR r.estado NOT IN ('ACTIVO','INACTIVO') THEN
      RAISE_APPLICATION_ERROR(-20001, 'Estado no permitido.');
    END IF;
    IF r.coincide_referencia IS NULL OR r.coincide_referencia NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_referencia debe ser S o N.'); END IF;
    IF r.coincide_cheque IS NULL OR r.coincide_cheque NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_cheque debe ser S o N.'); END IF;
    IF r.coincide_beneficiario IS NULL OR r.coincide_beneficiario NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_beneficiario debe ser S o N.'); END IF;
    IF r.coincide_concepto IS NULL OR r.coincide_concepto NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_concepto debe ser S o N.'); END IF;
    IF r.revision_manual IS NULL OR r.revision_manual NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'revision_manual debe ser S o N.'); END IF;
    IF r.banco_id IS NULL OR r.banco_id < 1 OR r.banco_id > 9999999999 OR r.banco_id <> ROUND(r.banco_id,0) THEN
      RAISE_APPLICATION_ERROR(-20001, 'banco_id: valor fuera de rango o precision invalida.');
    END IF;
    IF r.tolerancia_dias IS NULL OR r.tolerancia_dias < 0 OR r.tolerancia_dias > 999 OR r.tolerancia_dias <> ROUND(r.tolerancia_dias,0) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tolerancia_dias: valor fuera de rango o precision invalida.');
    END IF;
    IF r.tolerancia_monto IS NULL OR r.tolerancia_monto < 0 OR r.tolerancia_monto > 9999999999999999.99 OR r.tolerancia_monto <> ROUND(r.tolerancia_monto,2) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tolerancia_monto: valor fuera de rango o precision invalida.');
    END IF;
    IF r.porcentaje_minimo IS NULL OR r.porcentaje_minimo < 0 OR r.porcentaje_minimo > 100 OR r.porcentaje_minimo <> ROUND(r.porcentaje_minimo,2) THEN
      RAISE_APPLICATION_ERROR(-20001, 'porcentaje_minimo: valor fuera de rango o precision invalida.');
    END IF;
    SELECT COUNT(*) INTO n FROM MB_BANCO
      WHERE banco_id = r.banco_id AND (r.estado = 'INACTIVO' OR estado = 'ACTIVO');
    IF n = 0 THEN RAISE_APPLICATION_ERROR(-20001, 'El banco no existe o no esta activo.'); END IF;
    IF r.cuenta_id IS NOT NULL THEN
      SELECT COUNT(*) INTO n FROM MB_CUENTA_BANCARIA
       WHERE cuenta_id = r.cuenta_id AND banco_id = r.banco_id
         AND (r.estado = 'INACTIVO' OR estado = 'ACTIVA');
      IF n = 0 THEN RAISE_APPLICATION_ERROR(-20001, 'La cuenta no pertenece al banco o no esta activa.'); END IF;
    END IF;
    SELECT COUNT(*) INTO n FROM MB_PARAMETRO_CONCILIACION
      WHERE banco_id = r.banco_id AND (cuenta_id = r.cuenta_id OR (cuenta_id IS NULL AND r.cuenta_id IS NULL))
        AND (r.parametro_id IS NULL OR parametro_id <> r.parametro_id);
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20002, 'Ya existe una configuracion para este banco y cuenta. Edite o reactive la existente.'); END IF;
  END validar;

  PROCEDURE LISTAR(p_resultado OUT SYS_REFCURSOR) IS
  BEGIN
    OPEN p_resultado FOR SELECT TO_CHAR(t.parametro_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS parametro_id,
        TO_CHAR(t.banco_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS banco_id,
        TO_CHAR(t.cuenta_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS cuenta_id,
        TO_CHAR(t.tolerancia_dias, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tolerancia_dias,
        TO_CHAR(t.tolerancia_monto, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tolerancia_monto,
        t.coincide_referencia,
        t.coincide_cheque,
        t.coincide_beneficiario,
        t.coincide_concepto,
        TO_CHAR(t.porcentaje_minimo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS porcentaje_minimo,
        t.revision_manual,
        t.estado,
        b.nombre AS banco_nombre,
        c.nombre_interno AS cuenta_nombre FROM MB_PARAMETRO_CONCILIACION t JOIN MB_BANCO b ON b.banco_id = t.banco_id LEFT JOIN MB_CUENTA_BANCARIA c ON c.cuenta_id = t.cuenta_id ORDER BY t.parametro_id DESC;
  END LISTAR;

  PROCEDURE OBTENER(p_id IN MB_PARAMETRO_CONCILIACION.parametro_id%TYPE, p_resultado OUT SYS_REFCURSOR) IS
  BEGIN
    OPEN p_resultado FOR SELECT TO_CHAR(t.parametro_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS parametro_id,
        TO_CHAR(t.banco_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS banco_id,
        TO_CHAR(t.cuenta_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS cuenta_id,
        TO_CHAR(t.tolerancia_dias, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tolerancia_dias,
        TO_CHAR(t.tolerancia_monto, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tolerancia_monto,
        t.coincide_referencia,
        t.coincide_cheque,
        t.coincide_beneficiario,
        t.coincide_concepto,
        TO_CHAR(t.porcentaje_minimo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS porcentaje_minimo,
        t.revision_manual,
        t.estado,
        b.nombre AS banco_nombre,
        c.nombre_interno AS cuenta_nombre FROM MB_PARAMETRO_CONCILIACION t JOIN MB_BANCO b ON b.banco_id = t.banco_id LEFT JOIN MB_CUENTA_BANCARIA c ON c.cuenta_id = t.cuenta_id WHERE t.parametro_id = p_id;
  END OBTENER;

  PROCEDURE CREAR(p_banco_id IN MB_PARAMETRO_CONCILIACION.banco_id%TYPE,
    p_cuenta_id IN MB_PARAMETRO_CONCILIACION.cuenta_id%TYPE,
    p_tolerancia_dias IN MB_PARAMETRO_CONCILIACION.tolerancia_dias%TYPE,
    p_tolerancia_monto IN MB_PARAMETRO_CONCILIACION.tolerancia_monto%TYPE,
    p_coincide_referencia IN MB_PARAMETRO_CONCILIACION.coincide_referencia%TYPE,
    p_coincide_cheque IN MB_PARAMETRO_CONCILIACION.coincide_cheque%TYPE,
    p_coincide_beneficiario IN MB_PARAMETRO_CONCILIACION.coincide_beneficiario%TYPE,
    p_coincide_concepto IN MB_PARAMETRO_CONCILIACION.coincide_concepto%TYPE,
    p_porcentaje_minimo IN MB_PARAMETRO_CONCILIACION.porcentaje_minimo%TYPE,
    p_revision_manual IN MB_PARAMETRO_CONCILIACION.revision_manual%TYPE,
    p_estado IN MB_PARAMETRO_CONCILIACION.estado%TYPE,
    p_id OUT MB_PARAMETRO_CONCILIACION.parametro_id%TYPE) IS
    r MB_PARAMETRO_CONCILIACION%ROWTYPE;
  BEGIN
    LOCK TABLE MB_PARAMETRO_CONCILIACION IN SHARE ROW EXCLUSIVE MODE WAIT 5;
    IF p_banco_id IS NOT NULL AND (p_banco_id <> ROUND(p_banco_id, 0) OR ABS(p_banco_id) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'banco_id: precision o rango invalido.');
    END IF;
    IF p_cuenta_id IS NOT NULL AND (p_cuenta_id <> ROUND(p_cuenta_id, 0) OR ABS(p_cuenta_id) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'cuenta_id: precision o rango invalido.');
    END IF;
    IF p_tolerancia_dias IS NOT NULL AND (p_tolerancia_dias <> ROUND(p_tolerancia_dias, 0) OR ABS(p_tolerancia_dias) > 999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tolerancia_dias: precision o rango invalido.');
    END IF;
    IF p_tolerancia_monto IS NOT NULL AND (p_tolerancia_monto <> ROUND(p_tolerancia_monto, 2) OR ABS(p_tolerancia_monto) > 9999999999999999.99) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tolerancia_monto: precision o rango invalido.');
    END IF;
    IF p_coincide_referencia IS NULL OR p_coincide_referencia NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_referencia debe ser S o N.'); END IF;
    IF p_coincide_cheque IS NULL OR p_coincide_cheque NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_cheque debe ser S o N.'); END IF;
    IF p_coincide_beneficiario IS NULL OR p_coincide_beneficiario NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_beneficiario debe ser S o N.'); END IF;
    IF p_coincide_concepto IS NULL OR p_coincide_concepto NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_concepto debe ser S o N.'); END IF;
    IF p_porcentaje_minimo IS NOT NULL AND (p_porcentaje_minimo <> ROUND(p_porcentaje_minimo, 2) OR ABS(p_porcentaje_minimo) > 100) THEN
      RAISE_APPLICATION_ERROR(-20001, 'porcentaje_minimo: precision o rango invalido.');
    END IF;
    IF p_revision_manual IS NULL OR p_revision_manual NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'revision_manual debe ser S o N.'); END IF;
    IF p_estado IS NULL OR p_estado NOT IN ('ACTIVO','INACTIVO') THEN RAISE_APPLICATION_ERROR(-20001, 'Estado no permitido.'); END IF;
    r.banco_id := p_banco_id;
    r.cuenta_id := p_cuenta_id;
    r.tolerancia_dias := p_tolerancia_dias;
    r.tolerancia_monto := p_tolerancia_monto;
    r.coincide_referencia := p_coincide_referencia;
    r.coincide_cheque := p_coincide_cheque;
    r.coincide_beneficiario := p_coincide_beneficiario;
    r.coincide_concepto := p_coincide_concepto;
    r.porcentaje_minimo := p_porcentaje_minimo;
    r.revision_manual := p_revision_manual;
    r.estado := p_estado;
    validar(r);
    r.parametro_id := MB_P5_SEQ_PARAM.NEXTVAL;
    INSERT INTO MB_PARAMETRO_CONCILIACION (parametro_id, banco_id, cuenta_id, tolerancia_dias, tolerancia_monto, coincide_referencia, coincide_cheque, coincide_beneficiario, coincide_concepto, porcentaje_minimo, revision_manual, estado)
      VALUES (r.parametro_id, r.banco_id, r.cuenta_id, r.tolerancia_dias, r.tolerancia_monto, r.coincide_referencia, r.coincide_cheque, r.coincide_beneficiario, r.coincide_concepto, r.porcentaje_minimo, r.revision_manual, r.estado);
    p_id := r.parametro_id;
  END CREAR;

  PROCEDURE ACTUALIZAR(p_id IN MB_PARAMETRO_CONCILIACION.parametro_id%TYPE,
    p_banco_id IN MB_PARAMETRO_CONCILIACION.banco_id%TYPE,
    p_cuenta_id IN MB_PARAMETRO_CONCILIACION.cuenta_id%TYPE,
    p_tolerancia_dias IN MB_PARAMETRO_CONCILIACION.tolerancia_dias%TYPE,
    p_tolerancia_monto IN MB_PARAMETRO_CONCILIACION.tolerancia_monto%TYPE,
    p_coincide_referencia IN MB_PARAMETRO_CONCILIACION.coincide_referencia%TYPE,
    p_coincide_cheque IN MB_PARAMETRO_CONCILIACION.coincide_cheque%TYPE,
    p_coincide_beneficiario IN MB_PARAMETRO_CONCILIACION.coincide_beneficiario%TYPE,
    p_coincide_concepto IN MB_PARAMETRO_CONCILIACION.coincide_concepto%TYPE,
    p_porcentaje_minimo IN MB_PARAMETRO_CONCILIACION.porcentaje_minimo%TYPE,
    p_revision_manual IN MB_PARAMETRO_CONCILIACION.revision_manual%TYPE,
    p_estado IN MB_PARAMETRO_CONCILIACION.estado%TYPE) IS
    r MB_PARAMETRO_CONCILIACION%ROWTYPE;
  BEGIN
    LOCK TABLE MB_PARAMETRO_CONCILIACION IN SHARE ROW EXCLUSIVE MODE WAIT 5;
    SELECT * INTO r FROM MB_PARAMETRO_CONCILIACION WHERE parametro_id = p_id;
    IF p_banco_id IS NOT NULL AND (p_banco_id <> ROUND(p_banco_id, 0) OR ABS(p_banco_id) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'banco_id: precision o rango invalido.');
    END IF;
    IF p_cuenta_id IS NOT NULL AND (p_cuenta_id <> ROUND(p_cuenta_id, 0) OR ABS(p_cuenta_id) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'cuenta_id: precision o rango invalido.');
    END IF;
    IF p_tolerancia_dias IS NOT NULL AND (p_tolerancia_dias <> ROUND(p_tolerancia_dias, 0) OR ABS(p_tolerancia_dias) > 999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tolerancia_dias: precision o rango invalido.');
    END IF;
    IF p_tolerancia_monto IS NOT NULL AND (p_tolerancia_monto <> ROUND(p_tolerancia_monto, 2) OR ABS(p_tolerancia_monto) > 9999999999999999.99) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tolerancia_monto: precision o rango invalido.');
    END IF;
    IF p_coincide_referencia IS NULL OR p_coincide_referencia NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_referencia debe ser S o N.'); END IF;
    IF p_coincide_cheque IS NULL OR p_coincide_cheque NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_cheque debe ser S o N.'); END IF;
    IF p_coincide_beneficiario IS NULL OR p_coincide_beneficiario NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_beneficiario debe ser S o N.'); END IF;
    IF p_coincide_concepto IS NULL OR p_coincide_concepto NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'coincide_concepto debe ser S o N.'); END IF;
    IF p_porcentaje_minimo IS NOT NULL AND (p_porcentaje_minimo <> ROUND(p_porcentaje_minimo, 2) OR ABS(p_porcentaje_minimo) > 100) THEN
      RAISE_APPLICATION_ERROR(-20001, 'porcentaje_minimo: precision o rango invalido.');
    END IF;
    IF p_revision_manual IS NULL OR p_revision_manual NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'revision_manual debe ser S o N.'); END IF;
    IF p_estado IS NULL OR p_estado NOT IN ('ACTIVO','INACTIVO') THEN RAISE_APPLICATION_ERROR(-20001, 'Estado no permitido.'); END IF;
    r.banco_id := p_banco_id;
    r.cuenta_id := p_cuenta_id;
    r.tolerancia_dias := p_tolerancia_dias;
    r.tolerancia_monto := p_tolerancia_monto;
    r.coincide_referencia := p_coincide_referencia;
    r.coincide_cheque := p_coincide_cheque;
    r.coincide_beneficiario := p_coincide_beneficiario;
    r.coincide_concepto := p_coincide_concepto;
    r.porcentaje_minimo := p_porcentaje_minimo;
    r.revision_manual := p_revision_manual;
    r.estado := p_estado;
    validar(r);
    UPDATE MB_PARAMETRO_CONCILIACION SET banco_id = r.banco_id,
      cuenta_id = r.cuenta_id,
      tolerancia_dias = r.tolerancia_dias,
      tolerancia_monto = r.tolerancia_monto,
      coincide_referencia = r.coincide_referencia,
      coincide_cheque = r.coincide_cheque,
      coincide_beneficiario = r.coincide_beneficiario,
      coincide_concepto = r.coincide_concepto,
      porcentaje_minimo = r.porcentaje_minimo,
      revision_manual = r.revision_manual,
      estado = r.estado
      WHERE parametro_id = p_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN RAISE_APPLICATION_ERROR(-20004, 'Registro no encontrado.');
  END ACTUALIZAR;

  PROCEDURE CAMBIAR_ESTADO(p_id IN MB_PARAMETRO_CONCILIACION.parametro_id%TYPE, p_estado IN MB_PARAMETRO_CONCILIACION.estado%TYPE) IS
    r MB_PARAMETRO_CONCILIACION%ROWTYPE;
  BEGIN
    IF p_estado IS NULL OR p_estado NOT IN ('ACTIVO','INACTIVO') THEN RAISE_APPLICATION_ERROR(-20001, 'Estado no permitido.'); END IF;
    LOCK TABLE MB_PARAMETRO_CONCILIACION IN SHARE ROW EXCLUSIVE MODE WAIT 5;
    SELECT * INTO r FROM MB_PARAMETRO_CONCILIACION WHERE parametro_id = p_id;
    r.estado := p_estado;
    validar(r);
    UPDATE MB_PARAMETRO_CONCILIACION SET estado = p_estado WHERE parametro_id = p_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN RAISE_APPLICATION_ERROR(-20004, 'Registro no encontrado.');
  END CAMBIAR_ESTADO;

  PROCEDURE DESACTIVAR(p_id IN MB_PARAMETRO_CONCILIACION.parametro_id%TYPE) IS
  BEGIN
    CAMBIAR_ESTADO(p_id, 'INACTIVO');
  END DESACTIVAR;

  PROCEDURE LISTAR_BANCOS(p_resultado OUT SYS_REFCURSOR) IS
  BEGIN
    OPEN p_resultado FOR SELECT TO_CHAR(banco_id) AS id, codigo_banco || ' - ' || nombre AS nombre, estado FROM MB_BANCO ORDER BY nombre;
  END;
  PROCEDURE LISTAR_CUENTAS(p_resultado OUT SYS_REFCURSOR) IS
  BEGIN
    OPEN p_resultado FOR SELECT TO_CHAR(cuenta_id) AS id, TO_CHAR(banco_id) AS banco_id,
      codigo_cuenta || ' - ' || nombre_interno AS nombre, estado FROM MB_CUENTA_BANCARIA ORDER BY nombre_interno;
  END;
  FUNCTION OBTENER_ID_APLICABLE(p_banco_id IN NUMBER, p_cuenta_id IN NUMBER) RETURN MB_PARAMETRO_CONCILIACION.parametro_id%TYPE IS
    n PLS_INTEGER;
    v_id MB_PARAMETRO_CONCILIACION.parametro_id%TYPE;
  BEGIN
    IF p_banco_id IS NULL OR (p_banco_id IS NOT NULL AND (p_banco_id < 1 OR p_banco_id > 9999999999 OR p_banco_id <> ROUND(p_banco_id, 0))) THEN
      RAISE_APPLICATION_ERROR(-20001, 'banco_id: valor invalido.');
    END IF;
    IF (p_cuenta_id IS NOT NULL AND (p_cuenta_id < 1 OR p_cuenta_id > 9999999999 OR p_cuenta_id <> ROUND(p_cuenta_id, 0))) THEN
      RAISE_APPLICATION_ERROR(-20001, 'cuenta_id: valor invalido.');
    END IF;
    IF p_banco_id IS NULL THEN RAISE_APPLICATION_ERROR(-20001, 'Banco obligatorio.'); END IF;
    IF p_cuenta_id IS NOT NULL THEN
      SELECT COUNT(*) INTO n FROM MB_CUENTA_BANCARIA WHERE cuenta_id = p_cuenta_id AND banco_id = p_banco_id AND estado = 'ACTIVA';
      IF n = 0 THEN RAISE_APPLICATION_ERROR(-20001, 'Cuenta invalida para este banco o inactiva.'); END IF;
    END IF;
    SELECT COUNT(*) INTO n FROM MB_PARAMETRO_CONCILIACION
      WHERE estado = 'ACTIVO' AND banco_id = p_banco_id AND cuenta_id IS NULL;
    IF n > 1 THEN RAISE_APPLICATION_ERROR(-20002, 'Existen parametros generales activos duplicados; corrija los datos heredados.'); END IF;
    SELECT t.parametro_id INTO v_id FROM MB_PARAMETRO_CONCILIACION t JOIN MB_BANCO b ON b.banco_id = t.banco_id LEFT JOIN MB_CUENTA_BANCARIA c ON c.cuenta_id = t.cuenta_id
      WHERE t.banco_id = p_banco_id AND t.estado = 'ACTIVO' AND b.estado = 'ACTIVO'
        AND (t.cuenta_id = p_cuenta_id OR t.cuenta_id IS NULL)
      ORDER BY CASE WHEN t.cuenta_id IS NOT NULL THEN 0 ELSE 1 END
      FETCH FIRST 1 ROW ONLY;
    RETURN v_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN NULL;
  END OBTENER_ID_APLICABLE;

  PROCEDURE RESOLVER_APLICABLE(p_banco_id IN NUMBER, p_cuenta_id IN NUMBER, p_resultado OUT SYS_REFCURSOR) IS
    v_id MB_PARAMETRO_CONCILIACION.parametro_id%TYPE;
  BEGIN
    v_id := OBTENER_ID_APLICABLE(p_banco_id, p_cuenta_id);
    OPEN p_resultado FOR SELECT TO_CHAR(t.parametro_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS parametro_id,
        TO_CHAR(t.banco_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS banco_id,
        TO_CHAR(t.cuenta_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS cuenta_id,
        TO_CHAR(t.tolerancia_dias, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tolerancia_dias,
        TO_CHAR(t.tolerancia_monto, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tolerancia_monto,
        t.coincide_referencia,
        t.coincide_cheque,
        t.coincide_beneficiario,
        t.coincide_concepto,
        TO_CHAR(t.porcentaje_minimo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS porcentaje_minimo,
        t.revision_manual,
        t.estado,
        b.nombre AS banco_nombre,
        c.nombre_interno AS cuenta_nombre FROM MB_PARAMETRO_CONCILIACION t JOIN MB_BANCO b ON b.banco_id = t.banco_id LEFT JOIN MB_CUENTA_BANCARIA c ON c.cuenta_id = t.cuenta_id
      WHERE t.parametro_id = v_id;
  END RESOLVER_APLICABLE;
END PKG_MB_PARAMETROS_CONCILIACION;
/

-- PACKAGE_BODY PKG_MB_PLANTILLAS_CHEQUE
CREATE OR REPLACE PACKAGE BODY "PKG_MB_PLANTILLAS_CHEQUE" AS

    ------------------------------------------------------------------
    -- VALIDAR QUE EL BANCO EXISTA
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_BANCO(
        p_banco_id        IN NUMBER,
        p_requiere_activo IN BOOLEAN DEFAULT TRUE
    ) IS
        v_estado MB_BANCO.estado%TYPE;
    BEGIN

        SELECT estado
        INTO v_estado
        FROM MB_BANCO
        WHERE banco_id = p_banco_id;

        IF p_requiere_activo
           AND v_estado <> 'ACTIVO' THEN

            RAISE_APPLICATION_ERROR(
                -20101,
                'El banco debe estar ACTIVO.'
            );

        END IF;

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR(
                -20102,
                'El banco indicado no existe.'
            );

    END VALIDAR_BANCO;


    ------------------------------------------------------------------
    -- VALIDAR TIPO DE CUENTA
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_TIPO_CUENTA(
        p_tipo_cuenta_id IN NUMBER
    ) IS
        v_total NUMBER;
    BEGIN

        IF p_tipo_cuenta_id IS NULL THEN
            RETURN;
        END IF;

        SELECT COUNT(*)
        INTO v_total
        FROM MB_CATALOGO_BANCARIO
        WHERE catalogo_id = p_tipo_cuenta_id
          AND grupo = 'TIPO_CUENTA';

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20103,
                'El tipo de cuenta indicado no existe o no pertenece al grupo TIPO_CUENTA.'
            );

        END IF;

    END VALIDAR_TIPO_CUENTA;


    ------------------------------------------------------------------
    -- VALIDAR DOCUMENTO DE FONDO
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_ARCHIVO_FONDO(
        p_archivo_fondo_id IN NUMBER
    ) IS
        v_total NUMBER;
    BEGIN

        IF p_archivo_fondo_id IS NULL THEN
            RETURN;
        END IF;

        SELECT COUNT(*)
        INTO v_total
        FROM MB_DOCUMENTO_BANCARIO
        WHERE documento_id = p_archivo_fondo_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20104,
                'El archivo de fondo indicado no existe.'
            );

        END IF;

    END VALIDAR_ARCHIVO_FONDO;


    ------------------------------------------------------------------
    -- VALIDAR ORIENTACIÓN
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_ORIENTACION(
        p_orientacion IN VARCHAR2
    ) IS
        v_orientacion VARCHAR2(15);
    BEGIN

        v_orientacion := UPPER(TRIM(p_orientacion));

        IF v_orientacion IS NULL
           OR v_orientacion NOT IN (
                'HORIZONTAL',
                'VERTICAL'
           ) THEN

            RAISE_APPLICATION_ERROR(
                -20105,
                'La orientación debe ser HORIZONTAL o VERTICAL.'
            );

        END IF;

    END VALIDAR_ORIENTACION;


    ------------------------------------------------------------------
    -- VALIDAR ESTADO DE PLANTILLA
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_ESTADO_PLANTILLA(
        p_estado IN VARCHAR2
    ) IS
        v_estado VARCHAR2(15);
    BEGIN

        v_estado := UPPER(TRIM(p_estado));

        IF v_estado IS NULL
           OR v_estado NOT IN (
                'ACTIVA',
                'INACTIVA'
           ) THEN

            RAISE_APPLICATION_ERROR(
                -20106,
                'El estado de la plantilla debe ser ACTIVA o INACTIVA.'
            );

        END IF;

    END VALIDAR_ESTADO_PLANTILLA;


    ------------------------------------------------------------------
    -- VALIDAR DATOS GENERALES DE LA PLANTILLA
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_DATOS_PLANTILLA(
        p_nombre              IN VARCHAR2,
        p_tamano_papel        IN VARCHAR2,
        p_margen_superior_mm  IN NUMBER,
        p_margen_inferior_mm  IN NUMBER,
        p_margen_izquierdo_mm IN NUMBER,
        p_margen_derecho_mm   IN NUMBER
    ) IS
    BEGIN

        IF TRIM(p_nombre) IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20107,
                'El nombre de la plantilla es obligatorio.'
            );

        END IF;

        IF TRIM(p_tamano_papel) IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20108,
                'El tamaño de papel es obligatorio.'
            );

        END IF;

        IF p_margen_superior_mm IS NULL
           OR p_margen_inferior_mm IS NULL
           OR p_margen_izquierdo_mm IS NULL
           OR p_margen_derecho_mm IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20109,
                'Todos los márgenes son obligatorios.'
            );

        END IF;

        IF p_margen_superior_mm < 0
           OR p_margen_inferior_mm < 0
           OR p_margen_izquierdo_mm < 0
           OR p_margen_derecho_mm < 0 THEN

            RAISE_APPLICATION_ERROR(
                -20110,
                'Los márgenes no pueden ser negativos.'
            );

        END IF;

    END VALIDAR_DATOS_PLANTILLA;


    ------------------------------------------------------------------
    -- VALIDAR CÓDIGO DE CAMPO
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_CODIGO_CAMPO(
        p_codigo_campo IN VARCHAR2
    ) IS
        v_codigo VARCHAR2(30);
    BEGIN

        v_codigo := UPPER(TRIM(p_codigo_campo));

        IF v_codigo IS NULL
           OR v_codigo NOT IN (
                'FECHA',
                'BENEFICIARIO',
                'MONTO_NUM',
                'MONTO_LETRAS',
                'CONCEPTO'
           ) THEN

            RAISE_APPLICATION_ERROR(
                -20111,
                'Código de campo de cheque no válido.'
            );

        END IF;

    END VALIDAR_CODIGO_CAMPO;


    ------------------------------------------------------------------
    -- VALIDAR ALINEACIÓN
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_ALINEACION(
        p_alineacion IN VARCHAR2
    ) IS
        v_alineacion VARCHAR2(15);
    BEGIN

        v_alineacion := UPPER(TRIM(p_alineacion));

        IF v_alineacion IS NULL
           OR v_alineacion NOT IN (
                'IZQUIERDA',
                'CENTRO',
                'DERECHA'
           ) THEN

            RAISE_APPLICATION_ERROR(
                -20112,
                'La alineación debe ser IZQUIERDA, CENTRO o DERECHA.'
            );

        END IF;

    END VALIDAR_ALINEACION;


    ------------------------------------------------------------------
    -- VALIDAR ESTADO DE CAMPO
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_ESTADO_CAMPO(
        p_estado IN VARCHAR2
    ) IS
        v_estado VARCHAR2(15);
    BEGIN

        v_estado := UPPER(TRIM(p_estado));

        IF v_estado IS NULL
           OR v_estado NOT IN (
                'ACTIVO',
                'INACTIVO'
           ) THEN

            RAISE_APPLICATION_ERROR(
                -20113,
                'El estado del campo debe ser ACTIVO o INACTIVO.'
            );

        END IF;

    END VALIDAR_ESTADO_CAMPO;


    ------------------------------------------------------------------
    -- VALIDAR MEDIDAS DEL CAMPO
    ------------------------------------------------------------------
    PROCEDURE VALIDAR_MEDIDAS_CAMPO(
        p_posicion_x_mm IN NUMBER,
        p_posicion_y_mm IN NUMBER,
        p_ancho_mm      IN NUMBER,
        p_alto_mm       IN NUMBER,
        p_tamano_fuente IN NUMBER
    ) IS
    BEGIN

        IF p_posicion_x_mm IS NULL
           OR p_posicion_y_mm IS NULL
           OR p_ancho_mm IS NULL
           OR p_alto_mm IS NULL
           OR p_tamano_fuente IS NULL THEN

            RAISE_APPLICATION_ERROR(
                -20114,
                'Las posiciones, dimensiones y tamaño de fuente son obligatorios.'
            );

        END IF;

        IF p_posicion_x_mm < 0
           OR p_posicion_y_mm < 0
           OR p_ancho_mm <= 0
           OR p_alto_mm <= 0
           OR p_tamano_fuente <= 0 THEN

            RAISE_APPLICATION_ERROR(
                -20115,
                'Las posiciones no pueden ser negativas y las dimensiones deben ser mayores que cero.'
            );

        END IF;

    END VALIDAR_MEDIDAS_CAMPO;


    ------------------------------------------------------------------
    -- LISTAR
    ------------------------------------------------------------------
    PROCEDURE LISTAR(
        p_resultado OUT SYS_REFCURSOR
    ) IS
    BEGIN

        OPEN p_resultado FOR

            SELECT
                pc.plantilla_id,
                pc.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,

                pc.tipo_cuenta_id,
                cb.codigo AS tipo_cuenta_codigo,
                cb.nombre AS tipo_cuenta_nombre,

                pc.nombre,
                pc.tamano_papel,
                pc.orientacion,
                pc.margen_superior_mm,
                pc.margen_inferior_mm,
                pc.margen_izquierdo_mm,
                pc.margen_derecho_mm,
                pc.archivo_fondo_id,
                pc.estado

            FROM MB_PLANTILLA_CHEQUE pc

            JOIN MB_BANCO b
              ON b.banco_id = pc.banco_id

            LEFT JOIN MB_CATALOGO_BANCARIO cb
              ON cb.catalogo_id = pc.tipo_cuenta_id

            ORDER BY
                b.nombre,
                pc.nombre;

    END LISTAR;


    ------------------------------------------------------------------
    -- LISTAR POR BANCO
    ------------------------------------------------------------------
    PROCEDURE LISTAR_POR_BANCO(
        p_banco_id  IN NUMBER,
        p_resultado OUT SYS_REFCURSOR
    ) IS
    BEGIN

        VALIDAR_BANCO(
            p_banco_id        => p_banco_id,
            p_requiere_activo => FALSE
        );

        OPEN p_resultado FOR

            SELECT
                pc.plantilla_id,
                pc.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,

                pc.tipo_cuenta_id,
                cb.codigo AS tipo_cuenta_codigo,
                cb.nombre AS tipo_cuenta_nombre,

                pc.nombre,
                pc.tamano_papel,
                pc.orientacion,
                pc.margen_superior_mm,
                pc.margen_inferior_mm,
                pc.margen_izquierdo_mm,
                pc.margen_derecho_mm,
                pc.archivo_fondo_id,
                pc.estado

            FROM MB_PLANTILLA_CHEQUE pc

            JOIN MB_BANCO b
              ON b.banco_id = pc.banco_id

            LEFT JOIN MB_CATALOGO_BANCARIO cb
              ON cb.catalogo_id = pc.tipo_cuenta_id

            WHERE pc.banco_id = p_banco_id

            ORDER BY pc.nombre;

    END LISTAR_POR_BANCO;


    ------------------------------------------------------------------
    -- OBTENER
    ------------------------------------------------------------------
    PROCEDURE OBTENER(
        p_plantilla_id IN NUMBER,
        p_resultado    OUT SYS_REFCURSOR
    ) IS
        v_total NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CHEQUE
        WHERE plantilla_id = p_plantilla_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20116,
                'La plantilla indicada no existe.'
            );

        END IF;

        OPEN p_resultado FOR

            SELECT
                pc.plantilla_id,
                pc.banco_id,
                b.codigo_banco,
                b.nombre AS banco_nombre,

                pc.tipo_cuenta_id,
                cb.codigo AS tipo_cuenta_codigo,
                cb.nombre AS tipo_cuenta_nombre,

                pc.nombre,
                pc.tamano_papel,
                pc.orientacion,
                pc.margen_superior_mm,
                pc.margen_inferior_mm,
                pc.margen_izquierdo_mm,
                pc.margen_derecho_mm,
                pc.archivo_fondo_id,
                pc.estado

            FROM MB_PLANTILLA_CHEQUE pc

            JOIN MB_BANCO b
              ON b.banco_id = pc.banco_id

            LEFT JOIN MB_CATALOGO_BANCARIO cb
              ON cb.catalogo_id = pc.tipo_cuenta_id

            WHERE pc.plantilla_id = p_plantilla_id;

    END OBTENER;


    ------------------------------------------------------------------
    -- CREAR
    ------------------------------------------------------------------
    PROCEDURE CREAR(
        p_banco_id             IN NUMBER,
        p_tipo_cuenta_id       IN NUMBER,
        p_nombre               IN VARCHAR2,
        p_tamano_papel         IN VARCHAR2,
        p_orientacion          IN VARCHAR2,
        p_margen_superior_mm   IN NUMBER,
        p_margen_inferior_mm   IN NUMBER,
        p_margen_izquierdo_mm  IN NUMBER,
        p_margen_derecho_mm    IN NUMBER,
        p_archivo_fondo_id     IN NUMBER,
        p_estado               IN VARCHAR2,
        p_plantilla_id         OUT NUMBER
    ) IS
        v_total NUMBER;
    BEGIN

        VALIDAR_BANCO(p_banco_id);
        VALIDAR_TIPO_CUENTA(p_tipo_cuenta_id);
        VALIDAR_ARCHIVO_FONDO(p_archivo_fondo_id);
        VALIDAR_ORIENTACION(p_orientacion);
        VALIDAR_ESTADO_PLANTILLA(p_estado);

        VALIDAR_DATOS_PLANTILLA(
            p_nombre,
            p_tamano_papel,
            p_margen_superior_mm,
            p_margen_inferior_mm,
            p_margen_izquierdo_mm,
            p_margen_derecho_mm
        );

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CHEQUE
        WHERE banco_id = p_banco_id
          AND UPPER(TRIM(nombre)) = UPPER(TRIM(p_nombre));

        IF v_total > 0 THEN

            RAISE_APPLICATION_ERROR(
                -20117,
                'Ya existe una plantilla con ese nombre para el banco seleccionado.'
            );

        END IF;

        SELECT SEQ_MB_PLANTILLA_CHEQUE.NEXTVAL
        INTO p_plantilla_id
        FROM DUAL;

        INSERT INTO MB_PLANTILLA_CHEQUE(
            plantilla_id,
            banco_id,
            tipo_cuenta_id,
            nombre,
            tamano_papel,
            orientacion,
            margen_superior_mm,
            margen_inferior_mm,
            margen_izquierdo_mm,
            margen_derecho_mm,
            archivo_fondo_id,
            estado
        )
        VALUES(
            p_plantilla_id,
            p_banco_id,
            p_tipo_cuenta_id,
            TRIM(p_nombre),
            UPPER(TRIM(p_tamano_papel)),
            UPPER(TRIM(p_orientacion)),
            p_margen_superior_mm,
            p_margen_inferior_mm,
            p_margen_izquierdo_mm,
            p_margen_derecho_mm,
            p_archivo_fondo_id,
            UPPER(TRIM(p_estado))
        );

    END CREAR;


    ------------------------------------------------------------------
    -- ACTUALIZAR
    ------------------------------------------------------------------
    PROCEDURE ACTUALIZAR(
        p_plantilla_id         IN NUMBER,
        p_banco_id             IN NUMBER,
        p_tipo_cuenta_id       IN NUMBER,
        p_nombre               IN VARCHAR2,
        p_tamano_papel         IN VARCHAR2,
        p_orientacion          IN VARCHAR2,
        p_margen_superior_mm   IN NUMBER,
        p_margen_inferior_mm   IN NUMBER,
        p_margen_izquierdo_mm  IN NUMBER,
        p_margen_derecho_mm    IN NUMBER,
        p_archivo_fondo_id     IN NUMBER
    ) IS
        v_total NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CHEQUE
        WHERE plantilla_id = p_plantilla_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20118,
                'La plantilla indicada no existe.'
            );

        END IF;

        VALIDAR_BANCO(p_banco_id);
        VALIDAR_TIPO_CUENTA(p_tipo_cuenta_id);
        VALIDAR_ARCHIVO_FONDO(p_archivo_fondo_id);
        VALIDAR_ORIENTACION(p_orientacion);

        VALIDAR_DATOS_PLANTILLA(
            p_nombre,
            p_tamano_papel,
            p_margen_superior_mm,
            p_margen_inferior_mm,
            p_margen_izquierdo_mm,
            p_margen_derecho_mm
        );

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CHEQUE
        WHERE banco_id = p_banco_id
          AND UPPER(TRIM(nombre)) = UPPER(TRIM(p_nombre))
          AND plantilla_id <> p_plantilla_id;

        IF v_total > 0 THEN

            RAISE_APPLICATION_ERROR(
                -20119,
                'Ya existe otra plantilla con ese nombre para el banco seleccionado.'
            );

        END IF;

        UPDATE MB_PLANTILLA_CHEQUE
        SET
            banco_id            = p_banco_id,
            tipo_cuenta_id      = p_tipo_cuenta_id,
            nombre              = TRIM(p_nombre),
            tamano_papel        = UPPER(TRIM(p_tamano_papel)),
            orientacion         = UPPER(TRIM(p_orientacion)),
            margen_superior_mm  = p_margen_superior_mm,
            margen_inferior_mm  = p_margen_inferior_mm,
            margen_izquierdo_mm = p_margen_izquierdo_mm,
            margen_derecho_mm   = p_margen_derecho_mm,
            archivo_fondo_id    = p_archivo_fondo_id

        WHERE plantilla_id = p_plantilla_id;

    END ACTUALIZAR;


    ------------------------------------------------------------------
    -- CAMBIAR ESTADO
    ------------------------------------------------------------------
    PROCEDURE CAMBIAR_ESTADO(
        p_plantilla_id IN NUMBER,
        p_estado       IN VARCHAR2
    ) IS
        v_total    NUMBER;
        v_banco_id NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CHEQUE
        WHERE plantilla_id = p_plantilla_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20120,
                'La plantilla indicada no existe.'
            );

        END IF;

        VALIDAR_ESTADO_PLANTILLA(p_estado);

        IF UPPER(TRIM(p_estado)) = 'ACTIVA' THEN

            SELECT banco_id
            INTO v_banco_id
            FROM MB_PLANTILLA_CHEQUE
            WHERE plantilla_id = p_plantilla_id;

            VALIDAR_BANCO(v_banco_id);

        END IF;

        UPDATE MB_PLANTILLA_CHEQUE
        SET estado = UPPER(TRIM(p_estado))
        WHERE plantilla_id = p_plantilla_id;

    END CAMBIAR_ESTADO;


    ------------------------------------------------------------------
    -- DELETE LÓGICO DE PLANTILLA
    ------------------------------------------------------------------
    PROCEDURE DESACTIVAR(
        p_plantilla_id IN NUMBER
    ) IS
    BEGIN

        CAMBIAR_ESTADO(
            p_plantilla_id => p_plantilla_id,
            p_estado       => 'INACTIVA'
        );

    END DESACTIVAR;


    ------------------------------------------------------------------
    -- LISTAR CAMPOS
    ------------------------------------------------------------------
    PROCEDURE LISTAR_CAMPOS(
        p_plantilla_id IN NUMBER,
        p_resultado    OUT SYS_REFCURSOR
    ) IS
        v_total NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CHEQUE
        WHERE plantilla_id = p_plantilla_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20121,
                'La plantilla indicada no existe.'
            );

        END IF;

        OPEN p_resultado FOR

            SELECT
                campo_plantilla_id,
                plantilla_id,
                codigo_campo,
                posicion_x_mm,
                posicion_y_mm,
                ancho_mm,
                alto_mm,
                tamano_fuente,
                alineacion,
                estado

            FROM MB_PLANTILLA_CAMPO_CHEQUE

            WHERE plantilla_id = p_plantilla_id

            ORDER BY codigo_campo;

    END LISTAR_CAMPOS;


    ------------------------------------------------------------------
    -- CREAR CAMPO
    ------------------------------------------------------------------
    PROCEDURE CREAR_CAMPO(
        p_plantilla_id       IN NUMBER,
        p_codigo_campo       IN VARCHAR2,
        p_posicion_x_mm      IN NUMBER,
        p_posicion_y_mm      IN NUMBER,
        p_ancho_mm           IN NUMBER,
        p_alto_mm            IN NUMBER,
        p_tamano_fuente      IN NUMBER,
        p_alineacion         IN VARCHAR2,
        p_estado             IN VARCHAR2,
        p_campo_plantilla_id OUT NUMBER
    ) IS
        v_total NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CHEQUE
        WHERE plantilla_id = p_plantilla_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20122,
                'La plantilla indicada no existe.'
            );

        END IF;

        VALIDAR_CODIGO_CAMPO(p_codigo_campo);
        VALIDAR_ALINEACION(p_alineacion);
        VALIDAR_ESTADO_CAMPO(p_estado);

        VALIDAR_MEDIDAS_CAMPO(
            p_posicion_x_mm,
            p_posicion_y_mm,
            p_ancho_mm,
            p_alto_mm,
            p_tamano_fuente
        );

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CAMPO_CHEQUE
        WHERE plantilla_id = p_plantilla_id
          AND codigo_campo = UPPER(TRIM(p_codigo_campo));

        IF v_total > 0 THEN

            RAISE_APPLICATION_ERROR(
                -20123,
                'Ese campo ya está definido para la plantilla.'
            );

        END IF;

        SELECT SEQ_MB_PLANTILLA_CAMPO_CHEQUE.NEXTVAL
        INTO p_campo_plantilla_id
        FROM DUAL;

        INSERT INTO MB_PLANTILLA_CAMPO_CHEQUE(
            campo_plantilla_id,
            plantilla_id,
            codigo_campo,
            posicion_x_mm,
            posicion_y_mm,
            ancho_mm,
            alto_mm,
            tamano_fuente,
            alineacion,
            estado
        )
        VALUES(
            p_campo_plantilla_id,
            p_plantilla_id,
            UPPER(TRIM(p_codigo_campo)),
            p_posicion_x_mm,
            p_posicion_y_mm,
            p_ancho_mm,
            p_alto_mm,
            p_tamano_fuente,
            UPPER(TRIM(p_alineacion)),
            UPPER(TRIM(p_estado))
        );

    END CREAR_CAMPO;


    ------------------------------------------------------------------
    -- ACTUALIZAR CAMPO
    ------------------------------------------------------------------
    PROCEDURE ACTUALIZAR_CAMPO(
        p_campo_plantilla_id IN NUMBER,
        p_codigo_campo       IN VARCHAR2,
        p_posicion_x_mm      IN NUMBER,
        p_posicion_y_mm      IN NUMBER,
        p_ancho_mm           IN NUMBER,
        p_alto_mm            IN NUMBER,
        p_tamano_fuente      IN NUMBER,
        p_alineacion         IN VARCHAR2,
        p_estado             IN VARCHAR2
    ) IS
        v_total        NUMBER;
        v_plantilla_id NUMBER;
    BEGIN

        BEGIN

            SELECT plantilla_id
            INTO v_plantilla_id
            FROM MB_PLANTILLA_CAMPO_CHEQUE
            WHERE campo_plantilla_id = p_campo_plantilla_id;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN

                RAISE_APPLICATION_ERROR(
                    -20124,
                    'El campo de plantilla indicado no existe.'
                );

        END;

        VALIDAR_CODIGO_CAMPO(p_codigo_campo);
        VALIDAR_ALINEACION(p_alineacion);
        VALIDAR_ESTADO_CAMPO(p_estado);

        VALIDAR_MEDIDAS_CAMPO(
            p_posicion_x_mm,
            p_posicion_y_mm,
            p_ancho_mm,
            p_alto_mm,
            p_tamano_fuente
        );

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CAMPO_CHEQUE
        WHERE plantilla_id = v_plantilla_id
          AND codigo_campo = UPPER(TRIM(p_codigo_campo))
          AND campo_plantilla_id <> p_campo_plantilla_id;

        IF v_total > 0 THEN

            RAISE_APPLICATION_ERROR(
                -20125,
                'Ya existe otro campo con ese código en la plantilla.'
            );

        END IF;

        UPDATE MB_PLANTILLA_CAMPO_CHEQUE
        SET
            codigo_campo  = UPPER(TRIM(p_codigo_campo)),
            posicion_x_mm = p_posicion_x_mm,
            posicion_y_mm = p_posicion_y_mm,
            ancho_mm      = p_ancho_mm,
            alto_mm       = p_alto_mm,
            tamano_fuente = p_tamano_fuente,
            alineacion    = UPPER(TRIM(p_alineacion)),
            estado        = UPPER(TRIM(p_estado))

        WHERE campo_plantilla_id = p_campo_plantilla_id;

    END ACTUALIZAR_CAMPO;


    ------------------------------------------------------------------
    -- DELETE LÓGICO DEL CAMPO
    ------------------------------------------------------------------
    PROCEDURE ELIMINAR_CAMPO(
        p_campo_plantilla_id IN NUMBER
    ) IS
        v_total NUMBER;
    BEGIN

        SELECT COUNT(*)
        INTO v_total
        FROM MB_PLANTILLA_CAMPO_CHEQUE
        WHERE campo_plantilla_id = p_campo_plantilla_id;

        IF v_total = 0 THEN

            RAISE_APPLICATION_ERROR(
                -20126,
                'El campo de plantilla indicado no existe.'
            );

        END IF;

        UPDATE MB_PLANTILLA_CAMPO_CHEQUE
        SET estado = 'INACTIVO'
        WHERE campo_plantilla_id = p_campo_plantilla_id;

    END ELIMINAR_CAMPO;


END PKG_MB_PLANTILLAS_CHEQUE;
/

-- PACKAGE_BODY PKG_MB_REGLAS_APROBACION
CREATE OR REPLACE PACKAGE BODY "PKG_MB_REGLAS_APROBACION" AS
  -- No COMMIT/ROLLBACK aqui: la API (o el consumidor PL/SQL) controla la transaccion.
  -- Bloqueo de catalogo de bajo volumen para serializar las comprobaciones de
  -- duplicados/superposiciones incluso entre sesiones concurrentes del package.
  PROCEDURE validar(r IN MB_REGLA_APROBACION_BANCARIA%ROWTYPE) IS
    n PLS_INTEGER;
  BEGIN
    IF r.estado IS NULL OR r.estado NOT IN ('BORRADOR','ACTIVA','INACTIVA') THEN
      RAISE_APPLICATION_ERROR(-20001, 'Estado no permitido.');
    END IF;
    IF r.doble_aprobacion IS NULL OR r.doble_aprobacion NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'doble_aprobacion debe ser S o N.'); END IF;
    IF r.requiere_evidencia IS NULL OR r.requiere_evidencia NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'requiere_evidencia debe ser S o N.'); END IF;
    IF r.permite_reprogramar IS NULL OR r.permite_reprogramar NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'permite_reprogramar debe ser S o N.'); END IF;
    IF r.empresa_id IS NULL OR r.empresa_id < 1 OR r.empresa_id > 9999999999 OR r.empresa_id <> ROUND(r.empresa_id,0) THEN
      RAISE_APPLICATION_ERROR(-20001, 'empresa_id: valor fuera de rango o precision invalida.');
    END IF;
    IF r.tipo_operacion_id IS NULL OR r.tipo_operacion_id < 1 OR r.tipo_operacion_id > 9999999999 OR r.tipo_operacion_id <> ROUND(r.tipo_operacion_id,0) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tipo_operacion_id: valor fuera de rango o precision invalida.');
    END IF;
    IF r.creado_por IS NULL OR r.creado_por < 1 OR r.creado_por > 9999999999 OR r.creado_por <> ROUND(r.creado_por,0) THEN
      RAISE_APPLICATION_ERROR(-20001, 'creado_por: valor fuera de rango o precision invalida.');
    END IF;
    IF r.moneda_id IS NULL OR r.moneda_id < 1 OR r.moneda_id > 99999 OR r.moneda_id <> ROUND(r.moneda_id,0) THEN
      RAISE_APPLICATION_ERROR(-20001, 'moneda_id: valor fuera de rango o precision invalida.');
    END IF;
    IF r.cantidad_aprobaciones IS NULL OR r.cantidad_aprobaciones < 1 OR r.cantidad_aprobaciones > 999 OR r.cantidad_aprobaciones <> ROUND(r.cantidad_aprobaciones,0) THEN
      RAISE_APPLICATION_ERROR(-20001, 'cantidad_aprobaciones: valor fuera de rango o precision invalida.');
    END IF;
    IF r.version IS NULL OR r.version < 1 OR r.version > 99999 OR r.version <> ROUND(r.version,0) THEN
      RAISE_APPLICATION_ERROR(-20001, 'version: valor fuera de rango o precision invalida.');
    END IF;
    IF r.monto_minimo IS NULL OR r.monto_minimo < 0 OR r.monto_minimo > 9999999999999999.99 OR r.monto_minimo <> ROUND(r.monto_minimo,2) THEN
      RAISE_APPLICATION_ERROR(-20001, 'monto_minimo: valor fuera de rango o precision invalida.');
    END IF;
    IF r.nombre IS NULL OR TRIM(r.nombre) IS NULL OR LENGTHB(r.nombre) > 100 THEN
      RAISE_APPLICATION_ERROR(-20001, 'Nombre obligatorio: maximo 100 bytes.');
    END IF;
    IF r.monto_maximo IS NOT NULL AND
      (r.monto_maximo <= r.monto_minimo OR r.monto_maximo > 9999999999999999.99 OR r.monto_maximo <> ROUND(r.monto_maximo, 2)) THEN
      RAISE_APPLICATION_ERROR(-20001, 'El monto maximo debe superar al minimo y tener hasta dos decimales.');
    END IF;
    IF r.vigencia_desde IS NULL OR (r.vigencia_hasta IS NOT NULL AND TRUNC(r.vigencia_hasta) < TRUNC(r.vigencia_desde)) THEN
      RAISE_APPLICATION_ERROR(-20001, 'Vigencia invalida.');
    END IF;
    IF r.doble_aprobacion = 'S' AND r.cantidad_aprobaciones < 2 THEN
      RAISE_APPLICATION_ERROR(-20001, 'Doble aprobacion requiere al menos dos aprobaciones.');
    END IF;
    SELECT COUNT(*) INTO n FROM MB_CATALOGO_BANCARIO
      WHERE catalogo_id = r.tipo_operacion_id AND grupo = 'TIPO_OPERACION'
        AND (r.estado <> 'ACTIVA' OR estado = 'ACTIVO');
    IF n = 0 THEN RAISE_APPLICATION_ERROR(-20001, 'Seleccione un catalogo TIPO_OPERACION valido y activo al activar la regla.'); END IF;
    IF r.estado = 'ACTIVA' THEN
      SELECT COUNT(*) INTO n FROM MB_REGLA_APROBACION_BANCARIA t
       WHERE t.estado = 'ACTIVA' AND t.empresa_id = r.empresa_id
         AND t.tipo_operacion_id = r.tipo_operacion_id AND t.moneda_id = r.moneda_id
         AND (r.regla_id IS NULL OR t.regla_id <> r.regla_id)
         AND (r.monto_maximo IS NULL OR t.monto_minimo <= r.monto_maximo)
         AND (t.monto_maximo IS NULL OR r.monto_minimo <= t.monto_maximo)
         AND (r.vigencia_hasta IS NULL OR TRUNC(t.vigencia_desde) <= TRUNC(r.vigencia_hasta))
         AND (t.vigencia_hasta IS NULL OR TRUNC(r.vigencia_desde) <= TRUNC(t.vigencia_hasta));
      IF n > 0 THEN RAISE_APPLICATION_ERROR(-20002, 'El rango de monto y vigencia se superpone con otra regla activa.'); END IF;
    END IF;
  END validar;

  PROCEDURE LISTAR(p_resultado OUT SYS_REFCURSOR) IS
  BEGIN
    OPEN p_resultado FOR SELECT TO_CHAR(t.regla_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS regla_id,
        TO_CHAR(t.empresa_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS empresa_id,
        TO_CHAR(t.tipo_operacion_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tipo_operacion_id,
        TO_CHAR(t.moneda_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS moneda_id,
        t.nombre,
        TO_CHAR(t.monto_minimo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS monto_minimo,
        TO_CHAR(t.monto_maximo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS monto_maximo,
        TO_CHAR(t.cantidad_aprobaciones, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS cantidad_aprobaciones,
        t.doble_aprobacion,
        t.requiere_evidencia,
        t.permite_reprogramar,
        TO_CHAR(t.vigencia_desde, 'YYYY-MM-DD') AS vigencia_desde,
        TO_CHAR(t.vigencia_hasta, 'YYYY-MM-DD') AS vigencia_hasta,
        TO_CHAR(t.version, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS version,
        t.estado,
        TO_CHAR(t.creado_por, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS creado_por,
        TO_CHAR(t.creado_en, 'YYYY-MM-DD"T"HH24:MI:SS') AS creado_en,
        c.nombre AS tipo_operacion_nombre FROM MB_REGLA_APROBACION_BANCARIA t JOIN MB_CATALOGO_BANCARIO c ON c.catalogo_id = t.tipo_operacion_id ORDER BY t.regla_id DESC;
  END LISTAR;

  PROCEDURE OBTENER(p_id IN MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE, p_resultado OUT SYS_REFCURSOR) IS
  BEGIN
    OPEN p_resultado FOR SELECT TO_CHAR(t.regla_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS regla_id,
        TO_CHAR(t.empresa_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS empresa_id,
        TO_CHAR(t.tipo_operacion_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tipo_operacion_id,
        TO_CHAR(t.moneda_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS moneda_id,
        t.nombre,
        TO_CHAR(t.monto_minimo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS monto_minimo,
        TO_CHAR(t.monto_maximo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS monto_maximo,
        TO_CHAR(t.cantidad_aprobaciones, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS cantidad_aprobaciones,
        t.doble_aprobacion,
        t.requiere_evidencia,
        t.permite_reprogramar,
        TO_CHAR(t.vigencia_desde, 'YYYY-MM-DD') AS vigencia_desde,
        TO_CHAR(t.vigencia_hasta, 'YYYY-MM-DD') AS vigencia_hasta,
        TO_CHAR(t.version, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS version,
        t.estado,
        TO_CHAR(t.creado_por, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS creado_por,
        TO_CHAR(t.creado_en, 'YYYY-MM-DD"T"HH24:MI:SS') AS creado_en,
        c.nombre AS tipo_operacion_nombre FROM MB_REGLA_APROBACION_BANCARIA t JOIN MB_CATALOGO_BANCARIO c ON c.catalogo_id = t.tipo_operacion_id WHERE t.regla_id = p_id;
  END OBTENER;

  PROCEDURE CREAR(p_empresa_id IN MB_REGLA_APROBACION_BANCARIA.empresa_id%TYPE,
    p_tipo_operacion_id IN MB_REGLA_APROBACION_BANCARIA.tipo_operacion_id%TYPE,
    p_moneda_id IN MB_REGLA_APROBACION_BANCARIA.moneda_id%TYPE,
    p_nombre IN MB_REGLA_APROBACION_BANCARIA.nombre%TYPE,
    p_monto_minimo IN MB_REGLA_APROBACION_BANCARIA.monto_minimo%TYPE,
    p_monto_maximo IN MB_REGLA_APROBACION_BANCARIA.monto_maximo%TYPE,
    p_cantidad_aprobaciones IN MB_REGLA_APROBACION_BANCARIA.cantidad_aprobaciones%TYPE,
    p_doble_aprobacion IN MB_REGLA_APROBACION_BANCARIA.doble_aprobacion%TYPE,
    p_requiere_evidencia IN MB_REGLA_APROBACION_BANCARIA.requiere_evidencia%TYPE,
    p_permite_reprogramar IN MB_REGLA_APROBACION_BANCARIA.permite_reprogramar%TYPE,
    p_vigencia_desde IN MB_REGLA_APROBACION_BANCARIA.vigencia_desde%TYPE,
    p_vigencia_hasta IN MB_REGLA_APROBACION_BANCARIA.vigencia_hasta%TYPE,
    p_version IN MB_REGLA_APROBACION_BANCARIA.version%TYPE,
    p_estado IN MB_REGLA_APROBACION_BANCARIA.estado%TYPE,
    p_creado_por IN MB_REGLA_APROBACION_BANCARIA.creado_por%TYPE,
    p_id OUT MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE) IS
    r MB_REGLA_APROBACION_BANCARIA%ROWTYPE;
  BEGIN
    LOCK TABLE MB_REGLA_APROBACION_BANCARIA IN SHARE ROW EXCLUSIVE MODE WAIT 5;
    IF p_empresa_id IS NOT NULL AND (p_empresa_id <> ROUND(p_empresa_id, 0) OR ABS(p_empresa_id) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'empresa_id: precision o rango invalido.');
    END IF;
    IF p_tipo_operacion_id IS NOT NULL AND (p_tipo_operacion_id <> ROUND(p_tipo_operacion_id, 0) OR ABS(p_tipo_operacion_id) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tipo_operacion_id: precision o rango invalido.');
    END IF;
    IF p_moneda_id IS NOT NULL AND (p_moneda_id <> ROUND(p_moneda_id, 0) OR ABS(p_moneda_id) > 99999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'moneda_id: precision o rango invalido.');
    END IF;
    IF p_nombre IS NULL OR TRIM(p_nombre) IS NULL OR LENGTHB(p_nombre) > 100 THEN RAISE_APPLICATION_ERROR(-20001, 'Nombre obligatorio: maximo 100 bytes.'); END IF;
    IF p_monto_minimo IS NOT NULL AND (p_monto_minimo <> ROUND(p_monto_minimo, 2) OR ABS(p_monto_minimo) > 9999999999999999.99) THEN
      RAISE_APPLICATION_ERROR(-20001, 'monto_minimo: precision o rango invalido.');
    END IF;
    IF p_monto_maximo IS NOT NULL AND (p_monto_maximo <> ROUND(p_monto_maximo, 2) OR ABS(p_monto_maximo) > 9999999999999999.99) THEN
      RAISE_APPLICATION_ERROR(-20001, 'monto_maximo: precision o rango invalido.');
    END IF;
    IF p_cantidad_aprobaciones IS NOT NULL AND (p_cantidad_aprobaciones <> ROUND(p_cantidad_aprobaciones, 0) OR ABS(p_cantidad_aprobaciones) > 999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'cantidad_aprobaciones: precision o rango invalido.');
    END IF;
    IF p_doble_aprobacion IS NULL OR p_doble_aprobacion NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'doble_aprobacion debe ser S o N.'); END IF;
    IF p_requiere_evidencia IS NULL OR p_requiere_evidencia NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'requiere_evidencia debe ser S o N.'); END IF;
    IF p_permite_reprogramar IS NULL OR p_permite_reprogramar NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'permite_reprogramar debe ser S o N.'); END IF;
    IF p_version IS NOT NULL AND (p_version <> ROUND(p_version, 0) OR ABS(p_version) > 99999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'version: precision o rango invalido.');
    END IF;
    IF p_estado IS NULL OR p_estado NOT IN ('BORRADOR','ACTIVA','INACTIVA') THEN RAISE_APPLICATION_ERROR(-20001, 'Estado no permitido.'); END IF;
    IF p_creado_por IS NOT NULL AND (p_creado_por <> ROUND(p_creado_por, 0) OR ABS(p_creado_por) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'creado_por: precision o rango invalido.');
    END IF;
    r.empresa_id := p_empresa_id;
    r.tipo_operacion_id := p_tipo_operacion_id;
    r.moneda_id := p_moneda_id;
    r.nombre := p_nombre;
    r.monto_minimo := p_monto_minimo;
    r.monto_maximo := p_monto_maximo;
    r.cantidad_aprobaciones := p_cantidad_aprobaciones;
    r.doble_aprobacion := p_doble_aprobacion;
    r.requiere_evidencia := p_requiere_evidencia;
    r.permite_reprogramar := p_permite_reprogramar;
    r.vigencia_desde := TRUNC(p_vigencia_desde);
    r.vigencia_hasta := TRUNC(p_vigencia_hasta);
    r.version := p_version;
    r.estado := p_estado;
    r.creado_por := p_creado_por;
    r.creado_en := SYSTIMESTAMP;
    validar(r);
    r.regla_id := MB_P5_SEQ_REGLA.NEXTVAL;
    INSERT INTO MB_REGLA_APROBACION_BANCARIA (regla_id, empresa_id, tipo_operacion_id, moneda_id, nombre, monto_minimo, monto_maximo, cantidad_aprobaciones, doble_aprobacion, requiere_evidencia, permite_reprogramar, vigencia_desde, vigencia_hasta, version, estado, creado_por, creado_en)
      VALUES (r.regla_id, r.empresa_id, r.tipo_operacion_id, r.moneda_id, r.nombre, r.monto_minimo, r.monto_maximo, r.cantidad_aprobaciones, r.doble_aprobacion, r.requiere_evidencia, r.permite_reprogramar, r.vigencia_desde, r.vigencia_hasta, r.version, r.estado, r.creado_por, r.creado_en);
    p_id := r.regla_id;
  END CREAR;

  PROCEDURE ACTUALIZAR(p_id IN MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE,
    p_empresa_id IN MB_REGLA_APROBACION_BANCARIA.empresa_id%TYPE,
    p_tipo_operacion_id IN MB_REGLA_APROBACION_BANCARIA.tipo_operacion_id%TYPE,
    p_moneda_id IN MB_REGLA_APROBACION_BANCARIA.moneda_id%TYPE,
    p_nombre IN MB_REGLA_APROBACION_BANCARIA.nombre%TYPE,
    p_monto_minimo IN MB_REGLA_APROBACION_BANCARIA.monto_minimo%TYPE,
    p_monto_maximo IN MB_REGLA_APROBACION_BANCARIA.monto_maximo%TYPE,
    p_cantidad_aprobaciones IN MB_REGLA_APROBACION_BANCARIA.cantidad_aprobaciones%TYPE,
    p_doble_aprobacion IN MB_REGLA_APROBACION_BANCARIA.doble_aprobacion%TYPE,
    p_requiere_evidencia IN MB_REGLA_APROBACION_BANCARIA.requiere_evidencia%TYPE,
    p_permite_reprogramar IN MB_REGLA_APROBACION_BANCARIA.permite_reprogramar%TYPE,
    p_vigencia_desde IN MB_REGLA_APROBACION_BANCARIA.vigencia_desde%TYPE,
    p_vigencia_hasta IN MB_REGLA_APROBACION_BANCARIA.vigencia_hasta%TYPE,
    p_version IN MB_REGLA_APROBACION_BANCARIA.version%TYPE,
    p_estado IN MB_REGLA_APROBACION_BANCARIA.estado%TYPE) IS
    r MB_REGLA_APROBACION_BANCARIA%ROWTYPE;
  BEGIN
    LOCK TABLE MB_REGLA_APROBACION_BANCARIA IN SHARE ROW EXCLUSIVE MODE WAIT 5;
    SELECT * INTO r FROM MB_REGLA_APROBACION_BANCARIA WHERE regla_id = p_id;
    IF p_empresa_id IS NOT NULL AND (p_empresa_id <> ROUND(p_empresa_id, 0) OR ABS(p_empresa_id) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'empresa_id: precision o rango invalido.');
    END IF;
    IF p_tipo_operacion_id IS NOT NULL AND (p_tipo_operacion_id <> ROUND(p_tipo_operacion_id, 0) OR ABS(p_tipo_operacion_id) > 9999999999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tipo_operacion_id: precision o rango invalido.');
    END IF;
    IF p_moneda_id IS NOT NULL AND (p_moneda_id <> ROUND(p_moneda_id, 0) OR ABS(p_moneda_id) > 99999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'moneda_id: precision o rango invalido.');
    END IF;
    IF p_nombre IS NULL OR TRIM(p_nombre) IS NULL OR LENGTHB(p_nombre) > 100 THEN RAISE_APPLICATION_ERROR(-20001, 'Nombre obligatorio: maximo 100 bytes.'); END IF;
    IF p_monto_minimo IS NOT NULL AND (p_monto_minimo <> ROUND(p_monto_minimo, 2) OR ABS(p_monto_minimo) > 9999999999999999.99) THEN
      RAISE_APPLICATION_ERROR(-20001, 'monto_minimo: precision o rango invalido.');
    END IF;
    IF p_monto_maximo IS NOT NULL AND (p_monto_maximo <> ROUND(p_monto_maximo, 2) OR ABS(p_monto_maximo) > 9999999999999999.99) THEN
      RAISE_APPLICATION_ERROR(-20001, 'monto_maximo: precision o rango invalido.');
    END IF;
    IF p_cantidad_aprobaciones IS NOT NULL AND (p_cantidad_aprobaciones <> ROUND(p_cantidad_aprobaciones, 0) OR ABS(p_cantidad_aprobaciones) > 999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'cantidad_aprobaciones: precision o rango invalido.');
    END IF;
    IF p_doble_aprobacion IS NULL OR p_doble_aprobacion NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'doble_aprobacion debe ser S o N.'); END IF;
    IF p_requiere_evidencia IS NULL OR p_requiere_evidencia NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'requiere_evidencia debe ser S o N.'); END IF;
    IF p_permite_reprogramar IS NULL OR p_permite_reprogramar NOT IN ('S','N') THEN RAISE_APPLICATION_ERROR(-20001, 'permite_reprogramar debe ser S o N.'); END IF;
    IF p_version IS NOT NULL AND (p_version <> ROUND(p_version, 0) OR ABS(p_version) > 99999) THEN
      RAISE_APPLICATION_ERROR(-20001, 'version: precision o rango invalido.');
    END IF;
    IF p_estado IS NULL OR p_estado NOT IN ('BORRADOR','ACTIVA','INACTIVA') THEN RAISE_APPLICATION_ERROR(-20001, 'Estado no permitido.'); END IF;
    r.empresa_id := p_empresa_id;
    r.tipo_operacion_id := p_tipo_operacion_id;
    r.moneda_id := p_moneda_id;
    r.nombre := p_nombre;
    r.monto_minimo := p_monto_minimo;
    r.monto_maximo := p_monto_maximo;
    r.cantidad_aprobaciones := p_cantidad_aprobaciones;
    r.doble_aprobacion := p_doble_aprobacion;
    r.requiere_evidencia := p_requiere_evidencia;
    r.permite_reprogramar := p_permite_reprogramar;
    r.vigencia_desde := TRUNC(p_vigencia_desde);
    r.vigencia_hasta := TRUNC(p_vigencia_hasta);
    r.version := p_version;
    r.estado := p_estado;
    validar(r);
    UPDATE MB_REGLA_APROBACION_BANCARIA SET empresa_id = r.empresa_id,
      tipo_operacion_id = r.tipo_operacion_id,
      moneda_id = r.moneda_id,
      nombre = r.nombre,
      monto_minimo = r.monto_minimo,
      monto_maximo = r.monto_maximo,
      cantidad_aprobaciones = r.cantidad_aprobaciones,
      doble_aprobacion = r.doble_aprobacion,
      requiere_evidencia = r.requiere_evidencia,
      permite_reprogramar = r.permite_reprogramar,
      vigencia_desde = r.vigencia_desde,
      vigencia_hasta = r.vigencia_hasta,
      version = r.version,
      estado = r.estado
      WHERE regla_id = p_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN RAISE_APPLICATION_ERROR(-20004, 'Registro no encontrado.');
  END ACTUALIZAR;

  PROCEDURE CAMBIAR_ESTADO(p_id IN MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE, p_estado IN MB_REGLA_APROBACION_BANCARIA.estado%TYPE) IS
    r MB_REGLA_APROBACION_BANCARIA%ROWTYPE;
  BEGIN
    IF p_estado IS NULL OR p_estado NOT IN ('BORRADOR','ACTIVA','INACTIVA') THEN RAISE_APPLICATION_ERROR(-20001, 'Estado no permitido.'); END IF;
    LOCK TABLE MB_REGLA_APROBACION_BANCARIA IN SHARE ROW EXCLUSIVE MODE WAIT 5;
    SELECT * INTO r FROM MB_REGLA_APROBACION_BANCARIA WHERE regla_id = p_id;
    r.estado := p_estado;
    validar(r);
    UPDATE MB_REGLA_APROBACION_BANCARIA SET estado = p_estado WHERE regla_id = p_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN RAISE_APPLICATION_ERROR(-20004, 'Registro no encontrado.');
  END CAMBIAR_ESTADO;

  PROCEDURE DESACTIVAR(p_id IN MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE) IS
  BEGIN
    CAMBIAR_ESTADO(p_id, 'INACTIVA');
  END DESACTIVAR;

  PROCEDURE LISTAR_TIPOS(p_resultado OUT SYS_REFCURSOR) IS
  BEGIN
    OPEN p_resultado FOR SELECT TO_CHAR(catalogo_id) AS id, codigo || ' - ' || nombre AS nombre, estado
      FROM MB_CATALOGO_BANCARIO WHERE grupo = 'TIPO_OPERACION' ORDER BY nombre;
  END;
  FUNCTION OBTENER_ID_APLICABLE(p_empresa_id IN NUMBER, p_tipo_operacion_id IN NUMBER, p_moneda_id IN NUMBER, p_monto IN NUMBER, p_fecha IN DATE) RETURN MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE IS
    n PLS_INTEGER;
    v_id MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE;
  BEGIN
    IF p_empresa_id IS NULL OR (p_empresa_id IS NOT NULL AND (p_empresa_id < 1 OR p_empresa_id > 9999999999 OR p_empresa_id <> ROUND(p_empresa_id, 0))) THEN
      RAISE_APPLICATION_ERROR(-20001, 'empresa_id: valor invalido.');
    END IF;
    IF p_tipo_operacion_id IS NULL OR (p_tipo_operacion_id IS NOT NULL AND (p_tipo_operacion_id < 1 OR p_tipo_operacion_id > 9999999999 OR p_tipo_operacion_id <> ROUND(p_tipo_operacion_id, 0))) THEN
      RAISE_APPLICATION_ERROR(-20001, 'tipo_operacion_id: valor invalido.');
    END IF;
    IF p_moneda_id IS NULL OR (p_moneda_id IS NOT NULL AND (p_moneda_id < 1 OR p_moneda_id > 99999 OR p_moneda_id <> ROUND(p_moneda_id, 0))) THEN
      RAISE_APPLICATION_ERROR(-20001, 'moneda_id: valor invalido.');
    END IF;
    IF p_monto IS NULL OR (p_monto IS NOT NULL AND (p_monto < 0 OR p_monto > 9999999999999999.99 OR p_monto <> ROUND(p_monto, 2))) THEN
      RAISE_APPLICATION_ERROR(-20001, 'monto: valor invalido.');
    END IF;
    IF p_empresa_id IS NULL OR p_tipo_operacion_id IS NULL OR p_moneda_id IS NULL OR p_monto IS NULL OR p_monto < 0 OR p_monto <> ROUND(p_monto, 2) OR p_fecha IS NULL THEN
      RAISE_APPLICATION_ERROR(-20001, 'Empresa, operacion, moneda, monto y fecha validos son obligatorios.');
    END IF;
    SELECT COUNT(*) INTO n FROM MB_REGLA_APROBACION_BANCARIA t
      WHERE t.estado = 'ACTIVA' AND t.empresa_id = p_empresa_id AND t.tipo_operacion_id = p_tipo_operacion_id AND t.moneda_id = p_moneda_id
        AND p_monto >= t.monto_minimo AND (t.monto_maximo IS NULL OR p_monto <= t.monto_maximo)
        AND TRUNC(p_fecha) >= TRUNC(t.vigencia_desde) AND (t.vigencia_hasta IS NULL OR TRUNC(p_fecha) <= TRUNC(t.vigencia_hasta));
    IF n > 1 THEN RAISE_APPLICATION_ERROR(-20002, 'Existen reglas activas superpuestas heredadas; corrijalas antes de resolver.'); END IF;
    SELECT t.regla_id INTO v_id FROM MB_REGLA_APROBACION_BANCARIA t JOIN MB_CATALOGO_BANCARIO c ON c.catalogo_id = t.tipo_operacion_id
      WHERE t.estado = 'ACTIVA' AND c.estado = 'ACTIVO' AND c.grupo = 'TIPO_OPERACION'
        AND t.empresa_id = p_empresa_id AND t.tipo_operacion_id = p_tipo_operacion_id AND t.moneda_id = p_moneda_id
        AND p_monto >= t.monto_minimo AND (t.monto_maximo IS NULL OR p_monto <= t.monto_maximo)
        AND TRUNC(p_fecha) >= TRUNC(t.vigencia_desde) AND (t.vigencia_hasta IS NULL OR TRUNC(p_fecha) <= TRUNC(t.vigencia_hasta));
    RETURN v_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN NULL;
  END OBTENER_ID_APLICABLE;

  PROCEDURE RESOLVER_APLICABLE(p_empresa_id IN NUMBER, p_tipo_operacion_id IN NUMBER, p_moneda_id IN NUMBER, p_monto IN NUMBER, p_fecha IN DATE, p_resultado OUT SYS_REFCURSOR) IS
    v_id MB_REGLA_APROBACION_BANCARIA.regla_id%TYPE;
  BEGIN
    v_id := OBTENER_ID_APLICABLE(p_empresa_id, p_tipo_operacion_id, p_moneda_id, p_monto, p_fecha);
    OPEN p_resultado FOR SELECT TO_CHAR(t.regla_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS regla_id,
        TO_CHAR(t.empresa_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS empresa_id,
        TO_CHAR(t.tipo_operacion_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS tipo_operacion_id,
        TO_CHAR(t.moneda_id, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS moneda_id,
        t.nombre,
        TO_CHAR(t.monto_minimo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS monto_minimo,
        TO_CHAR(t.monto_maximo, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS monto_maximo,
        TO_CHAR(t.cantidad_aprobaciones, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS cantidad_aprobaciones,
        t.doble_aprobacion,
        t.requiere_evidencia,
        t.permite_reprogramar,
        TO_CHAR(t.vigencia_desde, 'YYYY-MM-DD') AS vigencia_desde,
        TO_CHAR(t.vigencia_hasta, 'YYYY-MM-DD') AS vigencia_hasta,
        TO_CHAR(t.version, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS version,
        t.estado,
        TO_CHAR(t.creado_por, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') AS creado_por,
        TO_CHAR(t.creado_en, 'YYYY-MM-DD"T"HH24:MI:SS') AS creado_en,
        c.nombre AS tipo_operacion_nombre FROM MB_REGLA_APROBACION_BANCARIA t JOIN MB_CATALOGO_BANCARIO c ON c.catalogo_id = t.tipo_operacion_id
      WHERE t.regla_id = v_id;
  END RESOLVER_APLICABLE;
END PKG_MB_REGLAS_APROBACION;
/

PROMPT === Verificacion final de compilacion ===
DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM USER_OBJECTS WHERE STATUS = 'INVALID';
  IF v_count > 0 THEN
    FOR e IN (SELECT NAME,TYPE,LINE,POSITION,TEXT FROM USER_ERRORS ORDER BY NAME,TYPE,SEQUENCE) LOOP
      DBMS_OUTPUT.PUT_LINE(e.NAME || ' ' || e.TYPE || ' linea ' || e.LINE || ':' || e.POSITION || ' ' || e.TEXT);
    END LOOP;
    RAISE_APPLICATION_ERROR(-20005,'Hay objetos INVALID. Revisar USER_OBJECTS y USER_ERRORS antes de cargar datos; ver limitaciones documentadas.');
  END IF;
  DBMS_OUTPUT.PUT_LINE('Estructura creada y todos los objetos VALID. Ejecutar 02_datos_demo.sql.');
END;
/
